INSERT INTO public.curriculum_standards (standard_code, learning_area, strand_no, strand_name, description) VALUES
  ('ว 1.1', 'วิทยาศาสตร์', 1, 'วิทยาศาสตร์ชีวภาพ', 'เข้าใจความหลากหลายของระบบนิเวศ ความสัมพันธ์ระหว่างสิ่งไม่มีชีวิตกับสิ่งมีชีวิต และความสัมพันธ์ระหว่างสิ่งมีชีวิตกับสิ่งมีชีวิตต่าง ๆ ในระบบนิเวศการถ่ายทอดพลังงาน การเปลี่ยนแปลงแทนที่ในระบบนิเวศ ความหมายของประชากร ปัญหาและผลกระทบที่มีต่อทรัพยากรธรรมชาติและสิ่งแวดล้อมแนวทางในการอนุรักษ์ทรัพยากรธรรมชาติและการแก้ไขปัญหาสิ่งแวดล้อมรวมทั้งนำความรู้ไปใช้ประโยชน์'),
  ('ว 1.2', 'วิทยาศาสตร์', 1, 'วิทยาศาสตร์ชีวภาพ', 'เข้าใจสมบัติของสิ่งมีชีวิต หน่วยพื้นฐานของสิ่งมีชีวิต การลำเลียงสารเข้าและออกจากเซลล์ ความสัมพันธ์ของโครงสร้างและหน้าที่ของระบบต่าง ๆ ของสัตว์และมนุษย์ที่ทำงานสัมพันธ์กัน ความสัมพันธ์ของโครงสร้างและหน้าที่ของอวัยวะต่าง ๆ ของพืชที่ทำงานสัมพันธ์กัน รวมทั้งนำความรู้ไปใช้ประโยชน์'),
  ('ว 1.3', 'วิทยาศาสตร์', 1, 'วิทยาศาสตร์ชีวภาพ', 'เข้าใจกระบวนการและความสำคัญของการถ่ายทอดลักษณะทางพันธุกรรมสารพันธุกรรม การเปลี่ยนแปลงทางพันธุกรรมที่มีผลต่อสิ่งมีชีวิต ความหลากหลายทางชีวภาพและวิวัฒนาการของสิ่งมีชีวิต รวมทั้งนำความรู้ไปใช้ประโยชน์'),
  ('ว 2.1', 'วิทยาศาสตร์', 2, 'วิทยาศาสตร์กายภาพ', 'เข้าใจสมบัติของสสาร องค์ประกอบของสสาร ความสัมพันธ์ระหว่างสมบัติของสสารกับโครงสร้างและแรงยึดเหนี่ยวระหว่างอนุภาค หลักและธรรมชาติของการเปลี่ยนแปลงสถานะของสสาร การเกิดสารละลาย และการเกิดปฏิกิริยาเคมี'),
  ('ว 2.2', 'วิทยาศาสตร์', 2, 'วิทยาศาสตร์กายภาพ', 'เข้าใจธรรมชาติของแรงในชีวิตประจำวัน ผลของแรงที่กระทำต่อวัตถุลักษณะการเคลื่อนที่แบบต่าง ๆ ของวัตถุ รวมทั้งนำความรู้ไปใช้ประโยชน์'),
  ('ว 2.3', 'วิทยาศาสตร์', 2, 'วิทยาศาสตร์กายภาพ', 'เข้าใจความหมายของพลังงาน การเปลี่ยนแปลงและการถ่ายโอนพลังงานปฏิสัมพันธ์ระหว่างสสารและพลังงาน พลังงานในชีวิตประจำวัน ธรรมชาติของคลื่น ปรากฏการณ์ที่เกี่ยวข้องกับเสียง แสง และคลื่นแม่เหล็กไฟฟ้ารวมทั้งนำความรู้ไปใช้ประโยชน์'),
  ('ว 3.1', 'วิทยาศาสตร์', 3, 'วิทยาศาสตร์โลกและอวกาศ', 'เข้าใจองค์ประกอบ ลักษณะ กระบวนการเกิด และวิวัฒนาการของเอกภพกาแล็กซี ดาวฤกษ์ และระบบสุริยะ รวมทั้งปฏิสัมพันธ์ภายในระบบสุริยะที่ส่งผลต่อสิ่งมีชีวิต และการประยุกต์ใช้เทคโนโลยีอวกาศ'),
  ('ว 3.2', 'วิทยาศาสตร์', 3, 'วิทยาศาสตร์โลกและอวกาศ', 'เข้าใจองค์ประกอบและความสัมพันธ์ของระบบโลก กระบวนการเปลี่ยนแปลงภายในโลกและบนผิวโลก ธรณีพิบัติภัย กระบวนการเปลี่ยนแปลงลมฟ้าอากาศและภูมิอากาศโลก รวมทั้งผลต่อสิ่งมีชีวิตและสิ่งแวดล้อม'),
  ('ว 4.1', 'วิทยาศาสตร์', 4, 'เทคโนโลยี', 'เข้าใจแนวคิดหลักของเทคโนโลยีเพื่อการดำรงชีวิตในสังคมที่มีการเปลี่ยนแปลงอย่างรวดเร็ว ใช้ความรู้และทักษะทางด้านวิทยาศาสตร์ คณิตศาสตร์ และศาสตร์อื่น ๆ เพื่อแก้ปัญหาหรือพัฒนางานอย่างมีความคิดสร้างสรรค์ด้วยกระบวนการออกแบบเชิงวิศวกรรม เลือกใช้เทคโนโลยีอย่างเหมาะสมโดยคำนึงถึงผลกระทบต่อชีวิต สังคม และสิ่งแวดล้อม'),
  ('ว 4.2', 'วิทยาศาสตร์', 4, 'เทคโนโลยี', 'เข้าใจและใช้แนวคิดเชิงคำนวณในการแก้ปัญหาที่พบในชีวิตจริงอย่างเป็นขั้นตอนและเป็นระบบ ใช้เทคโนโลยีสารสนเทศและการสื่อสารในการเรียนรู้การทำงาน และการแก้ปัญหาได้อย่างมีประสิทธิภาพ รู้เท่าทัน และมีจริยธรรม')
INSERT INTO public.curriculum_indicators (indicator_code, grade, standard, description, learning_area, indicator_no) VALUES
  ('ว 1.1 ป.1/1', 'ป.1', 'ว 1.1', 'ระบุชื่อพืชและสัตว์ที่อาศัยอยู่บริเวณต่าง ๆ จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 1),
  ('ว 1.1 ป.1/2', 'ป.1', 'ว 1.1', 'บอกสภาพแวดล้อมที่เหมาะสมกับการดำรงชีวิตของสัตว์ในบริเวณที่อาศัยอยู่', 'วิทยาศาสตร์', 2),
  ('ว 1.1 ป.5/1', 'ป.5', 'ว 1.1', 'บรรยายโครงสร้างและลักษณะของสิ่งมีชีวิตที่เหมาะสมกับการดำรงชีวิต ซึ่งเป็นผลมาจากการปรับตัวของสิ่งมีชีวิตในแต่ละแหล่งที่อยู่', 'วิทยาศาสตร์', 1),
  ('ว 1.1 ป.5/2', 'ป.5', 'ว 1.1', 'อธิบายความสัมพันธ์ระหว่างสิ่งมีชีวิตกับสิ่งมีชีวิต และความสัมพันธ์ระหว่างสิ่งมีชีวิตกับสิ่งไม่มีชีวิต เพื่อประโยชน์ต่อการดำรงชีวิต', 'วิทยาศาสตร์', 2),
  ('ว 1.1 ป.5/3', 'ป.5', 'ว 1.1', 'เขียนโซ่อาหารและระบุบทบาทหน้าที่ของสิ่งมีชีวิตที่เป็นผู้ผลิตและผู้บริโภคในโซ่อาหาร', 'วิทยาศาสตร์', 3),
  ('ว 1.1 ป.5/4', 'ป.5', 'ว 1.1', 'ตระหนักในคุณค่าของสิ่งแวดล้อมที่มีต่อการดำรงชีวิตของสิ่งมีชีวิต โดยมีส่วนร่วมในการดูแลรักษาสิ่งแวดล้อม', 'วิทยาศาสตร์', 4),
  ('ว 1.1 ม.3/1', 'ม.3', 'ว 1.1', 'อธิบายปฏิสัมพันธ์ขององค์ประกอบของระบบนิเวศที่ได้จากการสำรวจ', 'วิทยาศาสตร์', 1),
  ('ว 1.1 ม.3/2', 'ม.3', 'ว 1.1', 'อธิบายรูปแบบความสัมพันธ์ระหว่างสิ่งมีชีวิตกับสิ่งมีชีวิตรูปแบบต่าง ๆ ในแหล่งที่อยู่เดียวกันที่ได้จากการสำรวจ', 'วิทยาศาสตร์', 2),
  ('ว 1.1 ม.3/3', 'ม.3', 'ว 1.1', 'สร้างแบบจำลองในการอธิบายการถ่ายทอดพลังงานในสายใยอาหาร', 'วิทยาศาสตร์', 3),
  ('ว 1.1 ม.3/4', 'ม.3', 'ว 1.1', 'อธิบายความสัมพันธ์ของผู้ผลิต ผู้บริโภค และผู้ย่อยสลายสารอินทรีย์ในระบบนิเวศ', 'วิทยาศาสตร์', 4),
  ('ว 1.1 ม.3/5', 'ม.3', 'ว 1.1', 'อธิบายการสะสมสารพิษในสิ่งมีชีวิตในโซ่อาหาร', 'วิทยาศาสตร์', 5),
  ('ว 1.1 ม.3/6', 'ม.3', 'ว 1.1', 'ตระหนักถึงความสัมพันธ์ของสิ่งมีชีวิต และสิ่งแวดล้อมในระบบนิเวศ โดยไม่ทำลายสมดุลของระบบนิเวศ', 'วิทยาศาสตร์', 6),
  ('ว 1.1 ม.4/1', 'ม.4', 'ว 1.1', 'สืบค้นข้อมูลและอธิบายความสัมพันธ์ของสภาพทางภูมิศาสตร์บนโลกกับความหลากหลายของไบโอม และยกตัวอย่างไบโอมชนิดต่าง ๆ', 'วิทยาศาสตร์', 1),
  ('ว 1.1 ม.4/2', 'ม.4', 'ว 1.1', 'สืบค้นข้อมูล อภิปรายสาเหตุ และยกตัวอย่างการเปลี่ยนแปลงแทนที่ของระบบนิเวศ', 'วิทยาศาสตร์', 2),
  ('ว 1.1 ม.4/3', 'ม.4', 'ว 1.1', 'สืบค้นข้อมูล อธิบายและยกตัวอย่างเกี่ยวกับการเปลี่ยนแปลงขององค์ประกอบทางกายภาพและทางชีวภาพที่มีผลต่อการเปลี่ยนแปลงขนาดของประชากรสิ่งมีชีวิตในระบบนิเวศ', 'วิทยาศาสตร์', 3),
  ('ว 1.1 ม.4/4', 'ม.4', 'ว 1.1', 'สืบค้นข้อมูลและอภิปรายเกี่ยวกับปัญหาและผลกระทบที่มีต่อทรัพยากรธรรมชาติและสิ่งแวดล้อม พร้อมทั้งนำเสนอแนวทางในการอนุรักษ์ทรัพยากรธรรมชาติและการแก้ไขปัญหาสิ่งแวดล้อม', 'วิทยาศาสตร์', 4),
  ('ว 1.2 ป.1/1', 'ป.1', 'ว 1.2', 'ระบุชื่อ บรรยายลักษณะและบอกหน้าที่ของส่วนต่าง ๆ ของร่างกายมนุษย์ สัตว์ และพืชรวมทั้งบรรยายการทำหน้าที่ร่วมกันของส่วนต่าง ๆ ของร่างกายมนุษย์ในการทำกิจกรรมต่าง ๆ จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 1),
  ('ว 1.2 ป.1/2', 'ป.1', 'ว 1.2', 'ตระหนักถึงความสำคัญของส่วนต่าง ๆ ของร่างกายตนเอง โดยการดูแลส่วนต่าง ๆ อย่างถูกต้อง ให้ปลอดภัย และรักษาความสะอาดอยู่เสมอ', 'วิทยาศาสตร์', 2),
  ('ว 1.2 ป.2/1', 'ป.2', 'ว 1.2', 'ระบุว่าพืชต้องการแสงและน้ำ เพื่อการเจริญเติบโต โดยใช้ข้อมูลจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 1.2 ป.2/2', 'ป.2', 'ว 1.2', 'ตระหนักถึงความจำเป็นที่พืชต้องได้รับน้ำและแสงเพื่อการเจริญเติบโต โดยดูแลพืชให้ได้รับสิ่งดังกล่าวอย่างเหมาะสม', 'วิทยาศาสตร์', 2),
  ('ว 1.2 ป.2/3', 'ป.2', 'ว 1.2', 'สร้างแบบจำลองที่บรรยายวัฏจักรชีวิตของพืชดอก', 'วิทยาศาสตร์', 3),
  ('ว 1.2 ป.3/1', 'ป.3', 'ว 1.2', 'บรรยายสิ่งที่จำเป็นต่อการดำรงชีวิต และการเจริญเติบโตของมนุษย์และสัตว์ โดยใช้ข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 1),
  ('ว 1.2 ป.3/2', 'ป.3', 'ว 1.2', 'ตระหนักถึงประโยชน์ของอาหาร น้ำ และอากาศโดยการดูแลตนเองและสัตว์ให้ได้รับสิ่งเหล่านี้อย่างเหมาะสม', 'วิทยาศาสตร์', 2),
  ('ว 1.2 ป.3/3', 'ป.3', 'ว 1.2', 'สร้างแบบจำลองที่บรรยายวัฏจักรชีวิตของสัตว์และเปรียบเทียบวัฏจักรชีวิตของสัตว์บางชนิด', 'วิทยาศาสตร์', 3),
  ('ว 1.2 ป.3/4', 'ป.3', 'ว 1.2', 'ตระหนักถึงคุณค่าของชีวิตสัตว์ โดยไม่ทำให้วัฏจักรชีวิตของสัตว์เปลี่ยนแปลง', 'วิทยาศาสตร์', 4),
  ('ว 1.2 ป.4/1', 'ป.4', 'ว 1.2', 'บรรยายหน้าที่ของราก ลำต้น ใบ และดอกของพืชดอก โดยใช้ข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 1),
  ('ว 1.2 ป.6/1', 'ป.6', 'ว 1.2', 'ระบุสารอาหารและบอกประโยชน์ของสารอาหารแต่ละประเภทจากอาหารที่ตนเองรับประทาน', 'วิทยาศาสตร์', 1),
  ('ว 1.2 ป.6/2', 'ป.6', 'ว 1.2', 'บอกแนวทางในการเลือกรับประทานอาหารให้ได้สารอาหารครบถ้วน ในสัดส่วนที่เหมาะสมกับเพศและวัย รวมทั้งความปลอดภัยต่อสุขภาพ', 'วิทยาศาสตร์', 2),
  ('ว 1.2 ป.6/3', 'ป.6', 'ว 1.2', 'ตระหนักถึงความสำคัญของสารอาหาร โดยการเลือกรับประทานอาหารที่มีสารอาหารครบถ้วนในสัดส่วนที่เหมาะสมกับเพศและวัย รวมทั้งปลอดภัยต่อสุขภาพ', 'วิทยาศาสตร์', 3),
  ('ว 1.2 ป.6/4', 'ป.6', 'ว 1.2', 'สร้างแบบจำลองระบบย่อยอาหาร และบรรยายหน้าที่ของอวัยวะในระบบย่อยอาหาร รวมทั้งอธิบายการย่อยอาหารและการดูดซึมสารอาหาร', 'วิทยาศาสตร์', 4),
  ('ว 1.2 ป.6/5', 'ป.6', 'ว 1.2', 'ตระหนักถึงความสำคัญของระบบย่อยอาหารโดยการบอกแนวทางในการดูแลรักษาอวัยวะในระบบย่อยอาหารให้ทำงานเป็นปกติ', 'วิทยาศาสตร์', 5),
  ('ว 1.2 ม.1/1', 'ม.1', 'ว 1.2', 'เปรียบเทียบรูปร่าง ลักษณะ และโครงสร้างของเซลล์พืชและเซลล์สัตว์ รวมทั้งบรรยายหน้าที่ของผนังเซลล์ เยื่อหุ้มเซลล์ ไซโทพลาซึมนิวเคลียส แวคิวโอล ไมโทคอนเดรียและคลอโรพลาสต์', 'วิทยาศาสตร์', 1),
  ('ว 1.2 ม.1/2', 'ม.1', 'ว 1.2', 'ใช้กล้องจุลทรรศน์ใช้แสงศึกษาเซลล์และโครงสร้างต่าง ๆ ภายในเซลล์', 'วิทยาศาสตร์', 2),
  ('ว 1.2 ม.1/3', 'ม.1', 'ว 1.2', 'อธิบายความสัมพันธ์ระหว่างรูปร่างกับการทำหน้าที่ของเซลล์', 'วิทยาศาสตร์', 3),
  ('ว 1.2 ม.1/4', 'ม.1', 'ว 1.2', 'อธิบายการจัดระบบของสิ่งมีชีวิต โดยเริ่มจากเซลล์ เนื้อเยื่อ อวัยวะ ระบบอวัยวะ จนเป็นสิ่งมีชีวิต', 'วิทยาศาสตร์', 4),
  ('ว 1.2 ม.1/5', 'ม.1', 'ว 1.2', 'อธิบายกระบวนการแพร่และออสโมซิสจากหลักฐานเชิงประจักษ์ และยกตัวอย่างการแพร่และออสโมซิสในชีวิตประจำวัน', 'วิทยาศาสตร์', 5),
  ('ว 1.2 ม.1/6', 'ม.1', 'ว 1.2', 'ระบุปัจจัยที่จำเป็นในการสังเคราะห์ด้วยแสงและผลผลิตที่เกิดขึ้นจากการสังเคราะห์ด้วยแสงโดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 6),
  ('ว 1.2 ม.1/7', 'ม.1', 'ว 1.2', 'อธิบายความสำคัญของการสังเคราะห์ด้วยแสงของพืชต่อสิ่งมีชีวิตและสิ่งแวดล้อม', 'วิทยาศาสตร์', 7),
  ('ว 1.2 ม.1/8', 'ม.1', 'ว 1.2', 'ตระหนักในคุณค่าของพืชที่มีต่อสิ่งมีชีวิตและสิ่งแวดล้อม โดยการร่วมกันปลูกและดูแลรักษาต้นไม้ในโรงเรียนและชุมชน', 'วิทยาศาสตร์', 8),
  ('ว 1.2 ม.1/9', 'ม.1', 'ว 1.2', 'บรรยายลักษณะและหน้าที่ของไซเล็มและโฟลเอ็ม', 'วิทยาศาสตร์', 9),
  ('ว 1.2 ม.1/10', 'ม.1', 'ว 1.2', 'เขียนแผนภาพที่บรรยายทิศทางการลำเลียงสารในไซเล็มและโฟลเอ็มของพืช', 'วิทยาศาสตร์', 10),
  ('ว 1.2 ม.1/11', 'ม.1', 'ว 1.2', 'อธิบายการสืบพันธุ์แบบอาศัยเพศ และไม่อาศัยเพศของพืชดอก', 'วิทยาศาสตร์', 11),
  ('ว 1.2 ม.1/12', 'ม.1', 'ว 1.2', 'อธิบายลักษณะโครงสร้างของดอกที่มีส่วนทำให้เกิดการถ่ายเรณู รวมทั้งบรรยายการปฏิสนธิของพืชดอก การเกิดผลและเมล็ดการกระจายเมล็ด และการงอกของเมล็ด', 'วิทยาศาสตร์', 12),
  ('ว 1.2 ม.1/13', 'ม.1', 'ว 1.2', 'ตระหนักถึงความสำคัญของสัตว์ที่ช่วยในการถ่ายเรณูของพืชดอก โดยการไม่ทำลายชีวิตของสัตว์ที่ช่วยในการถ่ายเรณู', 'วิทยาศาสตร์', 13),
  ('ว 1.2 ม.1/14', 'ม.1', 'ว 1.2', 'อธิบายความสำคัญของธาตุอาหารบางชนิดที่มีผลต่อการเจริญเติบโตและการดำรงชีวิตของพืช', 'วิทยาศาสตร์', 14),
  ('ว 1.2 ม.1/15', 'ม.1', 'ว 1.2', 'เลือกใช้ปุ๋ยที่มีธาตุอาหารเหมาะสมกับพืชในสถานการณ์ที่กำหนด', 'วิทยาศาสตร์', 15),
  ('ว 1.2 ม.1/16', 'ม.1', 'ว 1.2', 'เลือกวิธีการขยายพันธุ์พืชให้เหมาะสมกับความต้องการของมนุษย์ โดยใช้ความรู้เกี่ยวกับการสืบพันธุ์ของพืช', 'วิทยาศาสตร์', 16),
  ('ว 1.2 ม.1/17', 'ม.1', 'ว 1.2', 'อธิบายความสำคัญของเทคโนโลยีการเพาะเลี้ยงเนื้อเยื่อพืชในการใช้ประโยชน์ด้านต่าง ๆ', 'วิทยาศาสตร์', 17),
  ('ว 1.2 ม.1/18', 'ม.1', 'ว 1.2', 'ตระหนักถึงประโยชน์ของการขยายพันธุ์พืชโดยการนำความรู้ไปใช้ในชีวิตประจำวัน', 'วิทยาศาสตร์', 18),
  ('ว 1.2 ม.2/1', 'ม.2', 'ว 1.2', 'ระบุอวัยวะและบรรยายหน้าที่ของอวัยวะที่เกี่ยวข้องในระบบหายใจ', 'วิทยาศาสตร์', 1),
  ('ว 1.2 ม.2/2', 'ม.2', 'ว 1.2', 'อธิบายกลไกการหายใจเข้าและออก โดยใช้แบบจำลอง รวมทั้งอธิบายกระบวนการแลกเปลี่ยนแก๊ส', 'วิทยาศาสตร์', 2),
  ('ว 1.2 ม.2/3', 'ม.2', 'ว 1.2', 'ตระหนักถึงความสำคัญของระบบหายใจโดยการบอกแนวทางในการดูแลรักษาอวัยวะในระบบหายใจให้ทำงานเป็นปกติ', 'วิทยาศาสตร์', 3),
  ('ว 1.2 ม.2/4', 'ม.2', 'ว 1.2', 'ระบุอวัยวะและบรรยายหน้าที่ของอวัยวะในระบบขับถ่ายในการกำจัดของเสียทางไต', 'วิทยาศาสตร์', 4),
  ('ว 1.2 ม.2/5', 'ม.2', 'ว 1.2', 'ตระหนักถึงความสำคัญของระบบขับถ่ายในการกำจัดของเสียทางไต โดยการบอกแนวทางในการปฏิบัติตนที่ช่วยให้ระบบขับถ่ายทำหน้าที่ได้อย่างปกติ', 'วิทยาศาสตร์', 5),
  ('ว 1.2 ม.2/6', 'ม.2', 'ว 1.2', 'บรรยายโครงสร้างและหน้าที่ของหัวใจหลอดเลือด และเลือด', 'วิทยาศาสตร์', 6),
  ('ว 1.2 ม.2/7', 'ม.2', 'ว 1.2', 'อธิบายการทำงานของระบบหมุนเวียนเลือดโดยใช้แบบจำลอง', 'วิทยาศาสตร์', 7),
  ('ว 1.2 ม.2/8', 'ม.2', 'ว 1.2', 'ออกแบบการทดลองและทดลอง ในการเปรียบเทียบอัตราการเต้นของหัวใจ ขณะปกติและหลังทำกิจกรรม', 'วิทยาศาสตร์', 8),
  ('ว 1.2 ม.2/9', 'ม.2', 'ว 1.2', 'ตระหนักถึงความสำคัญของระบบหมุนเวียนเลือดโดยการบอกแนวทางในการดูแลรักษาอวัยวะในระบบหมุนเวียนเลือดให้ทำงานเป็นปกติ', 'วิทยาศาสตร์', 9),
  ('ว 1.2 ม.2/10', 'ม.2', 'ว 1.2', 'ระบุอวัยวะและบรรยายหน้าที่ของอวัยวะในระบบประสาทส่วนกลางในการควบคุมการทำงานต่าง ๆ ของร่างกาย', 'วิทยาศาสตร์', 10),
  ('ว 1.2 ม.2/11', 'ม.2', 'ว 1.2', 'ตระหนักถึงความสำคัญของระบบประสาทโดยการบอกแนวทางในการดูแลรักษา รวมถึงการป้องกันการกระทบกระเทือนและอันตรายต่อสมองและไขสันหลัง', 'วิทยาศาสตร์', 11),
  ('ว 1.2 ม.2/12', 'ม.2', 'ว 1.2', 'ระบุอวัยวะและบรรยายหน้าที่ของอวัยวะในระบบสืบพันธุ์ของเพศชายและเพศหญิงโดยใช้แบบจำลอง', 'วิทยาศาสตร์', 12),
  ('ว 1.2 ม.2/13', 'ม.2', 'ว 1.2', 'อธิบายผลของฮอร์โมนเพศชายและเพศหญิงที่ควบคุมการเปลี่ยนแปลงของร่างกาย เมื่อเข้าสู่วัยหนุ่มสาว', 'วิทยาศาสตร์', 13),
  ('ว 1.2 ม.2/14', 'ม.2', 'ว 1.2', 'ตระหนักถึงการเปลี่ยนแปลงของร่างกายเมื่อเข้าสู่วัยหนุ่มสาว โดยการดูแลรักษาร่างกายและจิตใจของตนเองในช่วงที่มีการเปลี่ยนแปลง', 'วิทยาศาสตร์', 14),
  ('ว 1.2 ม.2/15', 'ม.2', 'ว 1.2', 'อธิบายการตกไข่ การมีประจำเดือนการปฏิสนธิ และการพัฒนาของไซโกตจนคลอดเป็นทารก', 'วิทยาศาสตร์', 15),
  ('ว 1.2 ม.2/16', 'ม.2', 'ว 1.2', 'เลือกวิธีการคุมกำเนิดที่เหมาะสมกับสถานการณ์ที่กำหนด', 'วิทยาศาสตร์', 16),
  ('ว 1.2 ม.2/17', 'ม.2', 'ว 1.2', 'ตระหนักถึงผลกระทบของการตั้งครรภ์ก่อนวัยอันควร โดยการประพฤติตนให้เหมาะสม', 'วิทยาศาสตร์', 17),
  ('ว 1.2 ม.4/1', 'ม.4', 'ว 1.2', 'อธิบายโครงสร้างและสมบัติของเยื่อหุ้มเซลล์ที่สัมพันธ์กับการลำเลียงสาร และเปรียบเทียบการลำเลียงสารผ่านเยื่อหุ้มเซลล์แบบต่าง ๆ', 'วิทยาศาสตร์', 1),
  ('ว 1.2 ม.4/2', 'ม.4', 'ว 1.2', 'อธิบายการควบคุมดุลยภาพของน้ำและสารในเลือดโดยการทำงานของไต', 'วิทยาศาสตร์', 2),
  ('ว 1.2 ม.4/3', 'ม.4', 'ว 1.2', 'อธิบายการควบคุมดุลยภาพของกรด-เบสของเลือดโดยการทำงานของไตและปอด', 'วิทยาศาสตร์', 3),
  ('ว 1.2 ม.4/4', 'ม.4', 'ว 1.2', 'อธิบายการควบคุมดุลยภาพของอุณหภูมิภายในร่างกายโดยระบบหมุนเวียนเลือด ผิวหนัง และกล้ามเนื้อโครงร่าง', 'วิทยาศาสตร์', 4),
  ('ว 1.2 ม.4/5', 'ม.4', 'ว 1.2', 'อธิบาย และเขียนแผนผังเกี่ยวกับการตอบสนองของร่างกายแบบไม่จำเพาะ และแบบจำเพาะต่อสิ่งแปลกปลอมของร่างกาย', 'วิทยาศาสตร์', 5),
  ('ว 1.2 ม.4/6', 'ม.4', 'ว 1.2', 'สืบค้นข้อมูล อธิบาย และยกตัวอย่างโรคหรืออาการที่เกิดจากความผิดปกติของระบบภูมิคุ้มกัน', 'วิทยาศาสตร์', 6),
  ('ว 1.2 ม.4/7', 'ม.4', 'ว 1.2', 'อธิบายภาวะภูมิคุ้มกันบกพร่องที่มีสาเหตุมาจากการติดเชื้อ HIV', 'วิทยาศาสตร์', 7),
  ('ว 1.2 ม.4/8', 'ม.4', 'ว 1.2', 'ทดสอบ และบอกชนิดของสารอาหารที่พืชสังเคราะห์ได้', 'วิทยาศาสตร์', 8),
  ('ว 1.2 ม.4/9', 'ม.4', 'ว 1.2', 'สืบค้นข้อมูล อภิปราย และยกตัวอย่างเกี่ยวกับการใช้ประโยชน์จากสารต่าง ๆ ที่พืชบางชนิดสร้างขึ้น', 'วิทยาศาสตร์', 9),
  ('ว 1.2 ม.4/10', 'ม.4', 'ว 1.2', 'ออกแบบการทดลอง ทดลอง และอธิบายเกี่ยวกับปัจจัยภายนอกที่มีผลต่อการเจริญเติบโตของพืช', 'วิทยาศาสตร์', 10),
  ('ว 1.2 ม.4/11', 'ม.4', 'ว 1.2', 'สืบค้นข้อมูลเกี่ยวกับสารควบคุมการเจริญเติบโตของพืชที่มนุษย์สังเคราะห์ขึ้นและยกตัวอย่างการนำมาประยุกต์ใช้ทางด้านการเกษตรของพืช', 'วิทยาศาสตร์', 11),
  ('ว 1.2 ม.4/12', 'ม.4', 'ว 1.2', 'สังเกต และอธิบายการตอบสนองของพืชต่อสิ่งเร้าในรูปแบบต่าง ๆ ที่มีผลต่อการดำรงชีวิต', 'วิทยาศาสตร์', 12),
  ('ว 1.3 ป.2/1', 'ป.2', 'ว 1.3', 'เปรียบเทียบลักษณะของสิ่งมีชีวิตและสิ่งไม่มีชีวิต จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 1),
  ('ว 1.3 ป.4/1', 'ป.4', 'ว 1.3', 'จำแนกสิ่งมีชีวิตโดยใช้ความเหมือน และความแตกต่างของลักษณะของสิ่งมีชีวิตออกเป็นกลุ่มพืช กลุ่มสัตว์ และกลุ่มที่ไม่ใช่พืชและสัตว์', 'วิทยาศาสตร์', 1),
  ('ว 1.3 ป.4/2', 'ป.4', 'ว 1.3', 'จำแนกพืชออกเป็นพืชดอกและพืชไม่มีดอกโดยใช้การมีดอกเป็นเกณฑ์ โดยใช้ข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 2),
  ('ว 1.3 ป.4/3', 'ป.4', 'ว 1.3', 'จำแนกสัตว์ออกเป็นสัตว์มีกระดูกสันหลังและสัตว์ไม่มีกระดูกสันหลัง โดยใช้การมีกระดูกสันหลังเป็นเกณฑ์ โดยใช้ข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 3),
  ('ว 1.3 ป.4/4', 'ป.4', 'ว 1.3', 'บรรยายลักษณะเฉพาะที่สังเกตได้ของสัตว์มีกระดูกสันหลังในกลุ่มปลา กลุ่มสัตว์สะเทินน้ำสะเทินบก กลุ่มสัตว์เลื้อยคลาน กลุ่มนก และกลุ่มสัตว์เลี้ยงลูกด้วยน้ำนม และยกตัวอย่างสิ่งมีชีวิตในแต่ละกลุ่ม', 'วิทยาศาสตร์', 4),
  ('ว 1.3 ป.5/1', 'ป.5', 'ว 1.3', 'อธิบายลักษณะทางพันธุกรรมที่มีการถ่ายทอดจากพ่อแม่สู่ลูกของพืช สัตว์ และมนุษย์', 'วิทยาศาสตร์', 1),
  ('ว 1.3 ป.5/2', 'ป.5', 'ว 1.3', 'แสดงความอยากรู้อยากเห็น โดยการถามคำถามเกี่ยวกับลักษณะที่คล้ายคลึงกันของตนเองกับพ่อแม่', 'วิทยาศาสตร์', 2),
  ('ว 1.3 ม.3/1', 'ม.3', 'ว 1.3', 'อธิบายความสัมพันธ์ระหว่าง ยีน ดีเอ็นเอ และโครโมโซม โดยใช้แบบจำลอง', 'วิทยาศาสตร์', 1),
  ('ว 1.3 ม.3/2', 'ม.3', 'ว 1.3', 'อธิบายการถ่ายทอดลักษณะทางพันธุกรรมจากการผสมโดยพิจารณาลักษณะเดียวที่แอลลีลเด่นข่มแอลลีลด้อยอย่างสมบูรณ์', 'วิทยาศาสตร์', 2),
  ('ว 1.3 ม.3/3', 'ม.3', 'ว 1.3', 'อธิบายการเกิดจีโนไทป์และฟีโนไทป์ของลูกและคำนวณอัตราส่วนการเกิดจีโนไทป์และฟีโนไทป์ของรุ่นลูก', 'วิทยาศาสตร์', 3),
  ('ว 1.3 ม.3/4', 'ม.3', 'ว 1.3', 'อธิบายความแตกต่างของการแบ่งเซลล์แบบไมโทซิสและไมโอซิส', 'วิทยาศาสตร์', 4),
  ('ว 1.3 ม.3/5', 'ม.3', 'ว 1.3', 'บอกได้ว่าการเปลี่ยนแปลงของยีนหรือโครโมโซมอาจทำให้เกิดโรคทางพันธุกรรม พร้อมทั้งยกตัวอย่างโรคทางพันธุกรรม', 'วิทยาศาสตร์', 5),
  ('ว 1.3 ม.3/6', 'ม.3', 'ว 1.3', 'ตระหนักถึงประโยชน์ของความรู้เรื่องโรคทางพันธุกรรม โดยรู้ว่าก่อนแต่งงานควรปรึกษาแพทย์เพื่อตรวจและวินิจฉัยภาวะเสี่ยงของลูกที่อาจเกิดโรคทางพันธุกรรม', 'วิทยาศาสตร์', 6),
  ('ว 1.3 ม.3/7', 'ม.3', 'ว 1.3', 'อธิบายการใช้ประโยชน์จากสิ่งมีชีวิตดัดแปรพันธุกรรม และผลกระทบที่อาจมีต่อมนุษย์และสิ่งแวดล้อม โดยใช้ข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 7),
  ('ว 1.3 ม.3/8', 'ม.3', 'ว 1.3', 'ตระหนักถึงประโยชน์และผลกระทบของสิ่งมีชีวิตดัดแปรพันธุกรรมที่อาจมีต่อมนุษย์และสิ่งแวดล้อมโดยการเผยแพร่ความรู้ที่ได้จากการโต้แย้งทางวิทยาศาสตร์ ซึ่งมีข้อมูลสนับสนุน', 'วิทยาศาสตร์', 8),
  ('ว 1.3 ม.3/9', 'ม.3', 'ว 1.3', 'เปรียบเทียบความหลากหลายทางชีวภาพในระดับชนิดสิ่งมีชีวิตในระบบนิเวศต่าง ๆ', 'วิทยาศาสตร์', 9),
  ('ว 1.3 ม.3/10', 'ม.3', 'ว 1.3', 'อธิบายความสำคัญของความหลากหลายทางชีวภาพที่มีต่อการรักษาสมดุลของระบบนิเวศและต่อมนุษย์', 'วิทยาศาสตร์', 10),
  ('ว 1.3 ม.3/11', 'ม.3', 'ว 1.3', 'แสดงความตระหนักในคุณค่าและความสำคัญของความหลากหลายทางชีวภาพ โดยมีส่วนร่วมในการดูแลรักษาความหลากหลายทางชีวภาพ', 'วิทยาศาสตร์', 11),
  ('ว 1.3 ม.4/1', 'ม.4', 'ว 1.3', 'อธิบายความสัมพันธ์ระหว่างยีน การสังเคราะห์โปรตีน และลักษณะทางพันธุกรรม', 'วิทยาศาสตร์', 1),
  ('ว 1.3 ม.4/2', 'ม.4', 'ว 1.3', 'อธิบายหลักการถ่ายทอดลักษณะที่ถูกควบคุมด้วยยีนที่อยู่บนโครโมโซมเพศและมัลติเปิลแอลลีล', 'วิทยาศาสตร์', 2),
  ('ว 1.3 ม.4/3', 'ม.4', 'ว 1.3', 'อธิบายผลที่เกิดจากการเปลี่ยนแปลงลำดับนิวคลีโอไทด์ในดีเอ็นเอต่อการแสดงลักษณะของสิ่งมีชีวิต', 'วิทยาศาสตร์', 3),
  ('ว 1.3 ม.4/4', 'ม.4', 'ว 1.3', 'สืบค้นข้อมูล และยกตัวอย่างการนำมิวเทชันไปใช้ประโยชน์', 'วิทยาศาสตร์', 4),
  ('ว 1.3 ม.4/5', 'ม.4', 'ว 1.3', 'สืบค้นข้อมูล และอภิปรายผลของเทคโนโลยีทางดีเอ็นเอที่มีต่อมนุษย์และสิ่งแวดล้อม', 'วิทยาศาสตร์', 5),
  ('ว 1.3 ม.4/6', 'ม.4', 'ว 1.3', 'สืบค้นข้อมูล อธิบาย และยกตัวอย่างความหลากหลายของสิ่งมีชีวิต ซึ่งเป็นผลมาจากวิวัฒนาการ', 'วิทยาศาสตร์', 6),
  ('ว 2.1 ป.1/1', 'ป.1', 'ว 2.1', 'อธิบายสมบัติที่สังเกตได้ของวัสดุที่ใช้ทำวัตถุซึ่งทำจากวัสดุชนิดเดียวหรือหลายชนิดประกอบกันโดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.1 ป.1/2', 'ป.1', 'ว 2.1', 'ระบุชนิดของวัสดุและจัดกลุ่มวัสดุตามสมบัติที่สังเกตได้', 'วิทยาศาสตร์', 2),
  ('ว 2.1 ป.2/1', 'ป.2', 'ว 2.1', 'เปรียบเทียบสมบัติการดูดซับน้ำของวัสดุโดยใช้หลักฐานเชิงประจักษ์ และระบุการนำสมบัติการดูดซับน้ำของวัสดุไปประยุกต์ใช้ในการทำวัตถุในชีวิตประจำวัน', 'วิทยาศาสตร์', 1),
  ('ว 2.1 ป.2/2', 'ป.2', 'ว 2.1', 'อธิบายสมบัติที่สังเกตได้ของวัสดุที่เกิดจากการนำวัสดุมาผสมกันโดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 2),
  ('ว 2.1 ป.2/3', 'ป.2', 'ว 2.1', 'เปรียบเทียบสมบัติที่สังเกตได้ของวัสดุ เพื่อนำมาทำเป็นวัตถุในการใช้งานตามวัตถุประสงค์และอธิบายการนำวัสดุที่ใช้แล้วกลับมาใช้ใหม่โดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 3),
  ('ว 2.1 ป.2/4', 'ป.2', 'ว 2.1', 'ตระหนักถึงประโยชน์ของการนำวัสดุที่ใช้แล้วกลับมาใช้ใหม่ โดยการนำวัสดุที่ใช้แล้วกลับมาใช้ใหม่', 'วิทยาศาสตร์', 4),
  ('ว 2.1 ป.3/1', 'ป.3', 'ว 2.1', 'อธิบายว่าวัตถุประกอบขึ้นจากชิ้นส่วนย่อย ๆ ซึ่งสามารถแยกออกจากกันได้และประกอบกันเป็นวัตถุชิ้นใหม่ได้ โดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.1 ป.3/2', 'ป.3', 'ว 2.1', 'อธิบายการเปลี่ยนแปลงของวัสดุเมื่อทำให้ร้อนขึ้นหรือทำให้เย็นลง โดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 2),
  ('ว 2.1 ป.4/1', 'ป.4', 'ว 2.1', 'เปรียบเทียบสมบัติทางกายภาพด้านความแข็งสภาพยืดหยุ่น การนำความร้อน และการนำไฟฟ้าของวัสดุโดยใช้หลักฐานเชิงประจักษ์จากการทดลองและระบุการนำสมบัติเรื่องความแข็งสภาพยืดหยุ่น การนำความร้อน และการนำไฟฟ้าของวัสดุไปใช้ในชีวิตประจำวันผ่านกระบวนการออกแบบชิ้นงาน', 'วิทยาศาสตร์', 1),
  ('ว 2.1 ป.4/2', 'ป.4', 'ว 2.1', 'แลกเปลี่ยนความคิดกับผู้อื่นโดยการอภิปรายเกี่ยวกับสมบัติทางกายภาพของวัสดุอย่างมีเหตุผลจากการทดลอง', 'วิทยาศาสตร์', 2),
  ('ว 2.1 ป.4/3', 'ป.4', 'ว 2.1', 'เปรียบเทียบสมบัติของสสารทั้ง 3 สถานะ จากข้อมูลที่ได้จากการสังเกตมวล การต้องการที่อยู่รูปร่างและปริมาตรของสสาร', 'วิทยาศาสตร์', 3),
  ('ว 2.1 ป.4/4', 'ป.4', 'ว 2.1', 'ใช้เครื่องมือเพื่อวัดมวล และปริมาตรของสสารทั้ง 3 สถานะ', 'วิทยาศาสตร์', 4),
  ('ว 2.1 ป.5/1', 'ป.5', 'ว 2.1', 'อธิบายการเปลี่ยนสถานะของสสาร เมื่อทำให้สสารร้อนขึ้นหรือเย็นลง โดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.1 ป.5/2', 'ป.5', 'ว 2.1', 'อธิบายการละลายของสารในน้ำ โดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 2),
  ('ว 2.1 ป.5/3', 'ป.5', 'ว 2.1', 'วิเคราะห์การเปลี่ยนแปลงของสารเมื่อเกิดการเปลี่ยนแปลงทางเคมี โดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 3),
  ('ว 2.1 ป.5/4', 'ป.5', 'ว 2.1', 'วิเคราะห์และระบุการเปลี่ยนแปลงที่ผันกลับได้และการเปลี่ยนแปลงที่ผันกลับไม่ได้', 'วิทยาศาสตร์', 4),
  ('ว 2.1 ป.6/1', 'ป.6', 'ว 2.1', 'อธิบายและเปรียบเทียบการแยกสารผสมโดยการหยิบออก การร่อน การใช้แม่เหล็กดึงดูดการรินออก การกรอง และการตกตะกอนโดยใช้หลักฐานเชิงประจักษ์ รวมทั้งระบุวิธีแก้ปัญหาในชีวิตประจำวันเกี่ยวกับการแยกสาร', 'วิทยาศาสตร์', 1),
  ('ว 2.1 ม.1/1', 'ม.1', 'ว 2.1', 'อธิบายสมบัติทางกายภาพบางประการของธาตุโลหะ อโลหะ และกึ่งโลหะ โดยใช้หลักฐานเชิงประจักษ์ที่ได้จากการสังเกตและการทดสอบและใช้สารสนเทศที่ได้จากแหล่งข้อมูลต่าง ๆ รวมทั้งจัดกลุ่มธาตุเป็นโลหะ อโลหะ และกึ่งโลหะ', 'วิทยาศาสตร์', 1),
  ('ว 2.1 ม.1/2', 'ม.1', 'ว 2.1', 'วิเคราะห์ผลจากการใช้ธาตุโลหะ อโลหะ กึ่งโลหะและธาตุกัมมันตรังสี ที่มีต่อสิ่งมีชีวิต สิ่งแวดล้อมเศรษฐกิจและสังคม จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 2),
  ('ว 2.1 ม.1/3', 'ม.1', 'ว 2.1', 'ตระหนักถึงคุณค่าของการใช้ธาตุโลหะ อโลหะกึ่งโลหะ ธาตุกัมมันตรังสี โดยเสนอแนวทางการใช้ธาตุอย่างปลอดภัย คุ้มค่า', 'วิทยาศาสตร์', 3),
  ('ว 2.1 ม.1/4', 'ม.1', 'ว 2.1', 'เปรียบเทียบจุดเดือด จุดหลอมเหลวของสารบริสุทธิ์และสารผสม โดยการวัดอุณหภูมิ เขียนกราฟแปลความหมายข้อมูลจากกราฟ หรือสารสนเทศ', 'วิทยาศาสตร์', 4),
  ('ว 2.1 ม.1/5', 'ม.1', 'ว 2.1', 'อธิบายและเปรียบเทียบความหนาแน่นของสารบริสุทธิ์และสารผสม', 'วิทยาศาสตร์', 5),
  ('ว 2.1 ม.1/6', 'ม.1', 'ว 2.1', 'ใช้เครื่องมือเพื่อวัดมวลและปริมาตรของสารบริสุทธิ์และสารผสม', 'วิทยาศาสตร์', 6),
  ('ว 2.1 ม.1/7', 'ม.1', 'ว 2.1', 'อธิบายเกี่ยวกับความสัมพันธ์ระหว่างอะตอมธาตุ และสารประกอบ โดยใช้แบบจำลองและสารสนเทศ', 'วิทยาศาสตร์', 7),
  ('ว 2.1 ม.1/8', 'ม.1', 'ว 2.1', 'อธิบายโครงสร้างอะตอมที่ประกอบด้วยโปรตอน นิวตรอน และอิเล็กตรอน โดยใช้แบบจำลอง', 'วิทยาศาสตร์', 8),
  ('ว 2.1 ม.1/9', 'ม.1', 'ว 2.1', 'อธิบายและเปรียบเทียบการจัดเรียงอนุภาคแรงยึดเหนี่ยวระหว่างอนุภาค และการเคลื่อนที่ของอนุภาคของสสารชนิดเดียวกันในสถานะของแข็ง ของเหลว และแก๊ส โดยใช้แบบจำลอง', 'วิทยาศาสตร์', 9),
  ('ว 2.1 ม.1/10', 'ม.1', 'ว 2.1', 'อธิบายความสัมพันธ์ระหว่างพลังงานความร้อนกับการเปลี่ยนสถานะของสสาร โดยใช้หลักฐานเชิงประจักษ์และแบบจำลอง', 'วิทยาศาสตร์', 10),
  ('ว 2.1 ม.2/1', 'ม.2', 'ว 2.1', 'อธิบายการแยกสารผสมโดยการระเหยแห้งการตกผลึก การกลั่นอย่างง่ายโครมาโทกราฟีแบบกระดาษ การสกัดด้วยตัวทำละลาย โดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.1 ม.2/2', 'ม.2', 'ว 2.1', 'แยกสารโดยการระเหยแห้ง การตกผลึกการกลั่นอย่างง่าย โครมาโทกราฟีแบบกระดาษการสกัดด้วยตัวทำละลาย', 'วิทยาศาสตร์', 2),
  ('ว 2.1 ม.2/3', 'ม.2', 'ว 2.1', 'นำวิธีการแยกสารไปใช้แก้ปัญหาในชีวิตประจำวันโดยบูรณาการวิทยาศาสตร์ คณิตศาสตร์เทคโนโลยี และวิศวกรรมศาสตร์', 'วิทยาศาสตร์', 3),
  ('ว 2.1 ม.2/4', 'ม.2', 'ว 2.1', 'ออกแบบการทดลองและทดลองในการอธิบายผลของชนิดตัวละลาย ชนิดตัวทำละลายอุณหภูมิที่มีต่อสภาพละลายได้ของสาร รวมทั้งอธิบายผลของความดันที่มีต่อสภาพละลายได้ของสาร โดยใช้สารสนเทศ', 'วิทยาศาสตร์', 4),
  ('ว 2.1 ม.2/5', 'ม.2', 'ว 2.1', 'ระบุปริมาณตัวละลายในสารละลาย ในหน่วยความเข้มข้นเป็นร้อยละ ปริมาตรต่อปริมาตรมวลต่อมวล และมวลต่อปริมาตร', 'วิทยาศาสตร์', 5),
  ('ว 2.1 ม.2/6', 'ม.2', 'ว 2.1', 'ตระหนักถึงความสำคัญของการนำความรู้เรื่องความเข้มข้นของสารไปใช้ โดยยกตัวอย่างการใช้สารละลายในชีวิตประจำวันอย่างถูกต้องและปลอดภัย', 'วิทยาศาสตร์', 6),
  ('ว 2.1 ม.3/1', 'ม.3', 'ว 2.1', 'ระบุสมบัติทางกายภาพและการใช้ประโยชน์วัสดุประเภทพอลิเมอร์ เซรามิก และวัสดุผสมโดยใช้หลักฐานเชิงประจักษ์ และสารสนเทศ', 'วิทยาศาสตร์', 1),
  ('ว 2.1 ม.3/2', 'ม.3', 'ว 2.1', 'ตระหนักถึงคุณค่าของการใช้วัสดุประเภทพอลิเมอร์ เซรามิก และวัสดุผสม โดยเสนอแนะแนวทางการใช้วัสดุอย่างประหยัดและคุ้มค่า', 'วิทยาศาสตร์', 2),
  ('ว 2.1 ม.3/3', 'ม.3', 'ว 2.1', 'อธิบายการเกิดปฏิกิริยาเคมี รวมถึงการจัดเรียงตัวใหม่ของอะตอมเมื่อเกิดปฏิกิริยาเคมีโดยใช้แบบจำลองและสมการข้อความ', 'วิทยาศาสตร์', 3),
  ('ว 2.1 ม.3/4', 'ม.3', 'ว 2.1', 'อธิบายกฎทรงมวล โดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 4),
  ('ว 2.1 ม.3/5', 'ม.3', 'ว 2.1', 'วิเคราะห์ปฏิกิริยาดูดความร้อน และปฏิกิริยาคายความร้อน จากการเปลี่ยนแปลงพลังงานความร้อนของปฏิกิริยา', 'วิทยาศาสตร์', 5),
  ('ว 2.1 ม.3/6', 'ม.3', 'ว 2.1', 'อธิบายปฏิกิริยาการเกิดสนิมของเหล็ก ปฏิกิริยาของกรดกับโลหะ ปฏิกิริยาของกรดกับเบส และปฏิกิริยาของเบสกับโลหะ โดยใช้หลักฐานเชิงประจักษ์ และอธิบายปฏิกิริยาการเผาไหม้การเกิดฝนกรด การสังเคราะห์ด้วยแสง โดยใช้สารสนเทศ รวมทั้งเขียนสมการข้อความแสดงปฏิกิริยาดังกล่าว', 'วิทยาศาสตร์', 6),
  ('ว 2.1 ม.3/7', 'ม.3', 'ว 2.1', 'ระบุประโยชน์และโทษของปฏิกิริยาเคมีที่มีต่อสิ่งมีชีวิตและสิ่งแวดล้อม และยกตัวอย่างวิธีการป้องกันและแก้ปัญหาที่เกิดจากปฏิกิริยาเคมีที่พบในชีวิตประจำวัน จากการสืบค้นข้อมูล', 'วิทยาศาสตร์', 7),
  ('ว 2.1 ม.3/8', 'ม.3', 'ว 2.1', 'ออกแบบวิธีแก้ปัญหาในชีวิตประจำวัน โดยใช้ความรู้เกี่ยวกับปฏิกิริยาเคมีโดยบูรณาการวิทยาศาสตร์ คณิตศาสตร์เทคโนโลยี และวิศวกรรมศาสตร์', 'วิทยาศาสตร์', 8),
  ('ว 2.1 ม.5/1', 'ม.5', 'ว 2.1', 'ระบุว่าสารเป็นธาตุหรือสารประกอบ และอยู่ในรูปอะตอม โมเลกุล หรือไอออนจากสูตรเคมี', 'วิทยาศาสตร์', 1),
  ('ว 2.1 ม.5/2', 'ม.5', 'ว 2.1', 'เปรียบเทียบความเหมือนและความแตกต่างของแบบจำลองอะตอมของโบร์กับแบบจำลองอะตอมแบบกลุ่มหมอก', 'วิทยาศาสตร์', 2),
  ('ว 2.1 ม.5/3', 'ม.5', 'ว 2.1', 'ระบุจำนวนโปรตอน นิวตรอน และอิเล็กตรอนของอะตอม และไอออนที่เกิดจากอะตอมเดียว', 'วิทยาศาสตร์', 3),
  ('ว 2.1 ม.5/4', 'ม.5', 'ว 2.1', 'เขียนสัญลักษณ์นิวเคลียร์ของธาตุและระบุการเป็นไอโซโทป', 'วิทยาศาสตร์', 4),
  ('ว 2.1 ม.5/5', 'ม.5', 'ว 2.1', 'ระบุหมู่และคาบของธาตุ และระบุว่าธาตุเป็นโลหะ อโลหะ กึ่งโลหะ กลุ่มธาตุเรพรีเซนเททีฟหรือกลุ่มธาตุแทรนซิชัน จากตารางธาตุ', 'วิทยาศาสตร์', 5),
  ('ว 2.1 ม.5/6', 'ม.5', 'ว 2.1', 'เปรียบเทียบสมบัติการนำไฟฟ้า การให้และรับอิเล็กตรอนระหว่างธาตุในกลุ่มโลหะกับอโลหะ', 'วิทยาศาสตร์', 6),
  ('ว 2.1 ม.5/7', 'ม.5', 'ว 2.1', 'สืบค้นข้อมูลและนำเสนอตัวอย่างประโยชน์และอันตรายที่เกิดจากธาตุเรพรีเซนเททีฟและธาตุแทรนซิชัน', 'วิทยาศาสตร์', 7),
  ('ว 2.1 ม.5/8', 'ม.5', 'ว 2.1', 'ระบุว่าพันธะโคเวเลนต์เป็นพันธะเดี่ยว พันธะคู่หรือพันธะสาม และระบุจำนวนคู่อิเล็กตรอนระหว่างอะตอมคู่ร่วมพันธะ จากสูตรโครงสร้าง', 'วิทยาศาสตร์', 8),
  ('ว 2.1 ม.5/9', 'ม.5', 'ว 2.1', 'ระบุสภาพขั้วของสารที่โมเลกุลประกอบด้วย2 อะตอม', 'วิทยาศาสตร์', 9),
  ('ว 2.1 ม.5/10', 'ม.5', 'ว 2.1', 'ระบุสารที่เกิดพันธะไฮโดรเจนได้จากสูตรโครงสร้าง', 'วิทยาศาสตร์', 10),
  ('ว 2.1 ม.5/11', 'ม.5', 'ว 2.1', 'อธิบายความสัมพันธ์ระหว่างจุดเดือดของสารโคเวเลนต์กับแรงดึงดูดระหว่างโมเลกุลตามสภาพขั้วหรือการเกิดพันธะไฮโดรเจน', 'วิทยาศาสตร์', 11),
  ('ว 2.1 ม.5/12', 'ม.5', 'ว 2.1', 'เขียนสูตรเคมีของไอออนและสารประกอบไอออนิก', 'วิทยาศาสตร์', 12),
  ('ว 2.1 ม.5/13', 'ม.5', 'ว 2.1', 'ระบุว่าสารเกิดการละลายแบบแตกตัวหรือไม่แตกตัว พร้อมให้เหตุผลและระบุว่าสารละลายที่ได้เป็นสารละลายอิเล็กโทรไลต์หรือนอนอิเล็กโทรไลต์', 'วิทยาศาสตร์', 13),
  ('ว 2.1 ม.5/14', 'ม.5', 'ว 2.1', 'ระบุสารประกอบอินทรีย์ประเภทไฮโดรคาร์บอนว่าอิ่มตัวหรือไม่อิ่มตัวจากสูตรโครงสร้าง', 'วิทยาศาสตร์', 14),
  ('ว 2.1 ม.5/15', 'ม.5', 'ว 2.1', 'สืบค้นข้อมูลและเปรียบเทียบสมบัติทางกายภาพระหว่างพอลิเมอร์และมอนอเมอร์ของพอลิเมอร์ชนิดนั้น', 'วิทยาศาสตร์', 15),
  ('ว 2.1 ม.5/16', 'ม.5', 'ว 2.1', 'ระบุสมบัติความเป็นกรด-เบสจากโครงสร้างของสารประกอบอินทรีย์', 'วิทยาศาสตร์', 16),
  ('ว 2.1 ม.5/17', 'ม.5', 'ว 2.1', 'อธิบายสมบัติการละลายในตัวทำละลายชนิดต่าง ๆ ของสาร', 'วิทยาศาสตร์', 17),
  ('ว 2.1 ม.5/18', 'ม.5', 'ว 2.1', 'วิเคราะห์และอธิบายความสัมพันธ์ระหว่างโครงสร้างกับสมบัติเทอร์มอพลาสติกและเทอร์มอเซตของพอลิเมอร์ และการนำพอลิเมอร์ไปใช้ประโยชน์', 'วิทยาศาสตร์', 18),
  ('ว 2.1 ม.5/19', 'ม.5', 'ว 2.1', 'สืบค้นข้อมูลและนำเสนอผลกระทบของการใช้ผลิตภัณฑ์พอลิเมอร์ที่มีต่อสิ่งมีชีวิตและสิ่งแวดล้อม พร้อมแนวทางป้องกันหรือแก้ไข', 'วิทยาศาสตร์', 19),
  ('ว 2.1 ม.5/20', 'ม.5', 'ว 2.1', 'ระบุสูตรเคมีของสารตั้งต้น ผลิตภัณฑ์ และแปลความหมายของสัญลักษณ์ในสมการเคมีของปฏิกิริยาเคมี', 'วิทยาศาสตร์', 20),
  ('ว 2.1 ม.5/21', 'ม.5', 'ว 2.1', 'ทดลองและอธิบายผลของความเข้มข้นพื้นที่ผิว อุณหภูมิ และตัวเร่งปฏิกิริยาที่มีผลต่ออัตราการเกิดปฏิกิริยาเคมี', 'วิทยาศาสตร์', 21),
  ('ว 2.1 ม.5/22', 'ม.5', 'ว 2.1', 'สืบค้นข้อมูลและอธิบายปัจจัยที่มีผลต่ออัตราการเกิดปฏิกิริยาเคมีที่ใช้ประโยชน์ในชีวิตประจำวันหรือในอุตสาหกรรม', 'วิทยาศาสตร์', 22),
  ('ว 2.1 ม.5/23', 'ม.5', 'ว 2.1', 'อธิบายความหมายของปฏิกิริยารีดอกซ์', 'วิทยาศาสตร์', 23),
  ('ว 2.1 ม.5/24', 'ม.5', 'ว 2.1', 'อธิบายสมบัติของสารกัมมันตรังสี และคำนวณครึ่งชีวิตและปริมาณของสารกัมมันตรังสี', 'วิทยาศาสตร์', 24),
  ('ว 2.1 ม.5/25', 'ม.5', 'ว 2.1', 'สืบค้นข้อมูลและนำเสนอตัวอย่างประโยชน์ของสารกัมมันตรังสีและการป้องกันอันตรายที่เกิดจากกัมมันตภาพรังสี', 'วิทยาศาสตร์', 25),
  ('ว 2.2 ป.3/1', 'ป.3', 'ว 2.2', 'ระบุผลของแรงที่มีต่อการเปลี่ยนแปลงการเคลื่อนที่ของวัตถุจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.2 ป.3/2', 'ป.3', 'ว 2.2', 'เปรียบเทียบและยกตัวอย่างแรงสัมผัสและแรงไม่สัมผัสที่มีผลต่อการเคลื่อนที่ของวัตถุโดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 2),
  ('ว 2.2 ป.3/3', 'ป.3', 'ว 2.2', 'จำแนกวัตถุโดยใช้การดึงดูดกับแม่เหล็กเป็นเกณฑ์จากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 3),
  ('ว 2.2 ป.3/4', 'ป.3', 'ว 2.2', 'ระบุขั้วแม่เหล็กและพยากรณ์ผลที่เกิดขึ้นระหว่างขั้วแม่เหล็กเมื่อนำมาเข้าใกล้กันจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 4),
  ('ว 2.2 ป.4/1', 'ป.4', 'ว 2.2', 'ระบุผลของแรงโน้มถ่วงที่มีต่อวัตถุจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.2 ป.4/2', 'ป.4', 'ว 2.2', 'ใช้เครื่องชั่งสปริงในการวัดน้ำหนักของวัตถุ', 'วิทยาศาสตร์', 2),
  ('ว 2.2 ป.4/3', 'ป.4', 'ว 2.2', 'บรรยายมวลของวัตถุที่มีผลต่อการเปลี่ยนแปลงการเคลื่อนที่ของวัตถุจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 3),
  ('ว 2.2 ป.5/1', 'ป.5', 'ว 2.2', 'อธิบายวิธีการหาแรงลัพธ์ของแรงหลายแรงในแนวเดียวกันที่กระทำต่อวัตถุในกรณีที่วัตถุอยู่นิ่งจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.2 ป.5/2', 'ป.5', 'ว 2.2', 'เขียนแผนภาพแสดงแรงที่กระทำต่อวัตถุที่อยู่ในแนวเดียวกันและแรงลัพธ์ที่กระทำต่อวัตถุ', 'วิทยาศาสตร์', 2),
  ('ว 2.2 ป.5/3', 'ป.5', 'ว 2.2', 'ใช้เครื่องชั่งสปริงในการวัดแรงที่กระทำต่อวัตถุ', 'วิทยาศาสตร์', 3),
  ('ว 2.2 ป.5/4', 'ป.5', 'ว 2.2', 'ระบุผลของแรงเสียดทานที่มีต่อการเปลี่ยนแปลงการเคลื่อนที่ของวัตถุจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 4),
  ('ว 2.2 ป.5/5', 'ป.5', 'ว 2.2', 'เขียนแผนภาพแสดงแรงเสียดทานและแรงที่อยู่ในแนวเดียวกันที่กระทำต่อวัตถุ', 'วิทยาศาสตร์', 5),
  ('ว 2.2 ป.6/1', 'ป.6', 'ว 2.2', 'อธิบายการเกิดและผลของแรงไฟฟ้าซึ่งเกิดจากวัตถุที่ผ่านการขัดถู โดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.2 ม.1/1', 'ม.1', 'ว 2.2', 'สร้างแบบจำลองที่อธิบายความสัมพันธ์ระหว่างความดันอากาศกับความสูงจากพื้นโลก', 'วิทยาศาสตร์', 1),
  ('ว 2.2 ม.2/1', 'ม.2', 'ว 2.2', 'พยากรณ์การเคลื่อนที่ของวัตถุที่เป็นผลของแรงลัพธ์ที่เกิดจากแรงหลายแรงที่กระทำต่อวัตถุในแนวเดียวกันจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.2 ม.2/2', 'ม.2', 'ว 2.2', 'เขียนแผนภาพแสดงแรงและแรงลัพธ์ที่เกิดจากแรงหลายแรงที่กระทำต่อวัตถุในแนวเดียวกัน', 'วิทยาศาสตร์', 2),
  ('ว 2.2 ม.2/3', 'ม.2', 'ว 2.2', 'ออกแบบการทดลองและทดลองด้วยวิธีที่เหมาะสมในการอธิบายปัจจัยที่มีผลต่อความดันของของเหลว', 'วิทยาศาสตร์', 3),
  ('ว 2.2 ม.2/4', 'ม.2', 'ว 2.2', 'วิเคราะห์แรงพยุงและการจม การลอยของวัตถุในของเหลวจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 4),
  ('ว 2.2 ม.2/5', 'ม.2', 'ว 2.2', 'เขียนแผนภาพแสดงแรงที่กระทำต่อวัตถุในของเหลว', 'วิทยาศาสตร์', 5),
  ('ว 2.2 ม.2/6', 'ม.2', 'ว 2.2', 'อธิบายแรงเสียดทานสถิตและแรงเสียดทานจลน์จากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 6),
  ('ว 2.2 ม.2/7', 'ม.2', 'ว 2.2', 'ออกแบบการทดลองและทดลองด้วยวิธีที่เหมาะสมในการอธิบายปัจจัยที่มีผลต่อขนาดของแรงเสียดทาน', 'วิทยาศาสตร์', 7),
  ('ว 2.2 ม.2/8', 'ม.2', 'ว 2.2', 'เขียนแผนภาพแสดงแรงเสียดทานและแรงอื่น ๆ ที่กระทำต่อวัตถุ', 'วิทยาศาสตร์', 8),
  ('ว 2.2 ม.2/9', 'ม.2', 'ว 2.2', 'ตระหนักถึงประโยชน์ของความรู้เรื่องแรงเสียดทานโดยวิเคราะห์สถานการณ์ปัญหาและเสนอแนะวิธีการลดหรือเพิ่มแรงเสียดทานที่เป็นประโยชน์ต่อการทำกิจกรรมในชีวิตประจำวัน', 'วิทยาศาสตร์', 9),
  ('ว 2.2 ม.2/10', 'ม.2', 'ว 2.2', 'ออกแบบการทดลองและทดลองด้วยวิธีที่เหมาะสมในการอธิบายโมเมนต์ของแรง เมื่อวัตถุอยู่ในสภาพสมดุลต่อการหมุน และคำนวณโดยใช้สมการ M = Fl', 'วิทยาศาสตร์', 10),
  ('ว 2.2 ม.2/11', 'ม.2', 'ว 2.2', 'เปรียบเทียบแหล่งของสนามแม่เหล็กสนามไฟฟ้า และสนามโน้มถ่วง และทิศทางของแรงที่กระทำต่อวัตถุที่อยู่ในแต่ละสนามจากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 11),
  ('ว 2.2 ม.2/12', 'ม.2', 'ว 2.2', 'เขียนแผนภาพแสดงแรงแม่เหล็ก แรงไฟฟ้าและแรงโน้มถ่วงที่กระทำต่อวัตถุ', 'วิทยาศาสตร์', 12),
  ('ว 2.2 ม.2/13', 'ม.2', 'ว 2.2', 'วิเคราะห์ความสัมพันธ์ระหว่างขนาดของแรงแม่เหล็ก แรงไฟฟ้า และแรงโน้มถ่วงที่กระทำต่อวัตถุที่อยู่ในสนามนั้น ๆ กับระยะห่างจากแหล่งของสนามถึงวัตถุจากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 13),
  ('ว 2.2 ม.2/14', 'ม.2', 'ว 2.2', 'อธิบายและคำนวณอัตราเร็วและความเร็วของการเคลื่อนที่ของวัตถุ โดยใช้สมการ s s v = และ v = t t จากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 14),
  ('ว 2.2 ม.2/15', 'ม.2', 'ว 2.2', 'เขียนแผนภาพแสดงการกระจัดและความเร็ว', 'วิทยาศาสตร์', 15),
  ('ว 2.2 ม.5/1', 'ม.5', 'ว 2.2', 'วิเคราะห์และแปลความหมายข้อมูลความเร็วกับเวลาของการเคลื่อนที่ของวัตถุ เพื่ออธิบายความเร่งของวัตถุ', 'วิทยาศาสตร์', 1),
  ('ว 2.2 ม.5/2', 'ม.5', 'ว 2.2', 'สังเกตและอธิบายการหาแรงลัพธ์ที่เกิดจากแรงหลายแรงที่อยู่ในระนาบเดียวกันที่กระทำต่อวัตถุโดยการเขียนแผนภาพการรวมแบบเวกเตอร์', 'วิทยาศาสตร์', 2),
  ('ว 2.2 ม.5/3', 'ม.5', 'ว 2.2', 'สังเกต วิเคราะห์ และอธิบายความสัมพันธ์ระหว่างความเร่งของวัตถุกับแรงลัพธ์ที่กระทำต่อวัตถุและมวลของวัตถุ', 'วิทยาศาสตร์', 3),
  ('ว 2.2 ม.5/4', 'ม.5', 'ว 2.2', 'สังเกตและอธิบายแรงกิริยาและแรงปฏิกิริยาระหว่างวัตถุคู่หนึ่ง ๆ', 'วิทยาศาสตร์', 4),
  ('ว 2.2 ม.5/5', 'ม.5', 'ว 2.2', 'สังเกตและอธิบายผลของความเร่งที่มีต่อการเคลื่อนที่แบบต่าง ๆ ของวัตถุ ได้แก่ การเคลื่อนที่แนวตรง การเคลื่อนที่แบบโพรเจกไทล์การเคลื่อนที่แบบวงกลม และการเคลื่อนที่แบบสั่น', 'วิทยาศาสตร์', 5),
  ('ว 2.2 ม.5/6', 'ม.5', 'ว 2.2', 'สืบค้นข้อมูลและอธิบายแรงโน้มถ่วงที่เกี่ยวกับการเคลื่อนที่ของวัตถุต่าง ๆ รอบโลก', 'วิทยาศาสตร์', 6),
  ('ว 2.2 ม.5/7', 'ม.5', 'ว 2.2', 'สังเกตและอธิบายการเกิดสนามแม่เหล็กเนื่องจากกระแสไฟฟ้า', 'วิทยาศาสตร์', 7),
  ('ว 2.2 ม.5/8', 'ม.5', 'ว 2.2', 'สังเกตและอธิบายแรงแม่เหล็กที่กระทำต่ออนุภาคที่มีประจุไฟฟ้าที่เคลื่อนที่ในสนามแม่เหล็กและแรงแม่เหล็กที่กระทำต่อลวดตัวนำที่มีกระแสไฟฟ้าผ่านในสนามแม่เหล็ก รวมทั้งอธิบายหลักการทำงานของมอเตอร์', 'วิทยาศาสตร์', 8),
  ('ว 2.2 ม.5/9', 'ม.5', 'ว 2.2', 'สังเกตและอธิบายการเกิดอีเอ็มเอฟ รวมทั้งยกตัวอย่างการนำความรู้ไปใช้ประโยชน์', 'วิทยาศาสตร์', 9),
  ('ว 2.2 ม.5/10', 'ม.5', 'ว 2.2', 'สืบค้นข้อมูลและอธิบายแรงเข้มและแรงอ่อน', 'วิทยาศาสตร์', 10),
  ('ว 2.3 ป.1/1', 'ป.1', 'ว 2.3', 'บรรยายการเกิดเสียงและทิศทางการเคลื่อนที่ของเสียงจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.3 ป.2/1', 'ป.2', 'ว 2.3', 'บรรยายแนวการเคลื่อนที่ของแสงจากแหล่งกำเนิดแสง และอธิบายการมองเห็นวัตถุจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.3 ป.2/2', 'ป.2', 'ว 2.3', 'ตระหนักในคุณค่าของความรู้ของการมองเห็นโดยเสนอแนะแนวทางการป้องกันอันตรายจากการมองวัตถุที่อยู่ในบริเวณที่มีแสงสว่างไม่เหมาะสม', 'วิทยาศาสตร์', 2),
  ('ว 2.3 ป.3/1', 'ป.3', 'ว 2.3', 'ยกตัวอย่างการเปลี่ยนพลังงานหนึ่งไปเป็นอีกพลังงานหนึ่งจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.3 ป.3/2', 'ป.3', 'ว 2.3', 'บรรยายการทำงานของเครื่องกำเนิดไฟฟ้าและระบุแหล่งพลังงานในการผลิตไฟฟ้า จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 2),
  ('ว 2.3 ป.3/3', 'ป.3', 'ว 2.3', 'ตระหนักในประโยชน์และโทษของไฟฟ้า โดยนำเสนอวิธีการใช้ไฟฟ้าอย่างประหยัด และปลอดภัย', 'วิทยาศาสตร์', 3),
  ('ว 2.3 ป.4/1', 'ป.4', 'ว 2.3', 'จำแนกวัตถุเป็นตัวกลางโปร่งใสตัวกลางโปร่งแสง และวัตถุทึบแสง จากลักษณะการมองเห็นสิ่งต่าง ๆ ผ่านวัตถุนั้นเป็นเกณฑ์โดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.3 ป.5/1', 'ป.5', 'ว 2.3', 'อธิบายการได้ยินเสียงผ่านตัวกลางจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.3 ป.5/2', 'ป.5', 'ว 2.3', 'ระบุตัวแปร ทดลอง และอธิบายลักษณะและการเกิดเสียงสูง เสียงต่ำ', 'วิทยาศาสตร์', 2),
  ('ว 2.3 ป.5/3', 'ป.5', 'ว 2.3', 'ออกแบบการทดลองและอธิบายลักษณะและการเกิดเสียงดัง เสียงค่อย', 'วิทยาศาสตร์', 3),
  ('ว 2.3 ป.5/4', 'ป.5', 'ว 2.3', 'วัดระดับเสียงโดยใช้เครื่องมือวัดระดับเสียง', 'วิทยาศาสตร์', 4),
  ('ว 2.3 ป.5/5', 'ป.5', 'ว 2.3', 'ตระหนักในคุณค่าของความรู้เรื่องระดับเสียงโดยเสนอแนะแนวทางในการหลีกเลี่ยงและลดมลพิษทางเสียง', 'วิทยาศาสตร์', 5),
  ('ว 2.3 ป.6/1', 'ป.6', 'ว 2.3', 'ระบุส่วนประกอบและบรรยายหน้าที่ของแต่ละส่วนประกอบของวงจรไฟฟ้าอย่างง่ายจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.3 ป.6/2', 'ป.6', 'ว 2.3', 'เขียนแผนภาพและต่อวงจรไฟฟ้าอย่างง่าย', 'วิทยาศาสตร์', 2),
  ('ว 2.3 ป.6/3', 'ป.6', 'ว 2.3', 'ออกแบบการทดลองและทดลองด้วยวิธีที่เหมาะสมในการอธิบายวิธีการและผลของการต่อเซลล์ไฟฟ้าแบบอนุกรม', 'วิทยาศาสตร์', 3),
  ('ว 2.3 ป.6/4', 'ป.6', 'ว 2.3', 'ตระหนักถึงประโยชน์ของความรู้ของการต่อเซลล์ไฟฟ้าแบบอนุกรมโดยบอกประโยชน์และการประยุกต์ใช้ในชีวิตประจำวัน', 'วิทยาศาสตร์', 4),
  ('ว 2.3 ป.6/5', 'ป.6', 'ว 2.3', 'ออกแบบการทดลองและทดลองด้วยวิธีที่เหมาะสมในการอธิบายการต่อหลอดไฟฟ้าแบบอนุกรมและแบบขนาน', 'วิทยาศาสตร์', 5),
  ('ว 2.3 ป.6/6', 'ป.6', 'ว 2.3', 'ตระหนักถึงประโยชน์ของความรู้ของการต่อหลอดไฟฟ้าแบบอนุกรมและแบบขนาน โดยบอกประโยชน์ ข้อจำกัด และการประยุกต์ใช้ในชีวิตประจำวัน', 'วิทยาศาสตร์', 6),
  ('ว 2.3 ป.6/7', 'ป.6', 'ว 2.3', 'อธิบายการเกิดเงามืดเงามัวจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 7),
  ('ว 2.3 ป.6/8', 'ป.6', 'ว 2.3', 'เขียนแผนภาพรังสีของแสงแสดงการเกิดเงามืดเงามัว', 'วิทยาศาสตร์', 8),
  ('ว 2.3 ม.1/1', 'ม.1', 'ว 2.3', 'วิเคราะห์ แปลความหมายข้อมูล และคำนวณปริมาณความร้อนที่ทำให้สสารเปลี่ยนอุณหภูมิและเปลี่ยนสถานะโดยใช้สมการ Q = mc ∆ t และ Q = mL', 'วิทยาศาสตร์', 1),
  ('ว 2.3 ม.1/2', 'ม.1', 'ว 2.3', 'ใช้เทอร์มอมิเตอร์ในการวัดอุณหภูมิของสสาร', 'วิทยาศาสตร์', 2),
  ('ว 2.3 ม.1/3', 'ม.1', 'ว 2.3', 'สร้างแบบจำลองที่อธิบายการขยายตัวหรือหดตัวของสสารเนื่องจากได้รับหรือสูญเสียความร้อน', 'วิทยาศาสตร์', 3),
  ('ว 2.3 ม.1/4', 'ม.1', 'ว 2.3', 'ตระหนักถึงประโยชน์ของความรู้ของการหดและขยายตัวของสสารเนื่องจากความร้อนโดยวิเคราะห์สถานการณ์ปัญหา และเสนอแนะวิธีการนำความรู้มาแก้ปัญหาในชีวิตประจำวัน', 'วิทยาศาสตร์', 4),
  ('ว 2.3 ม.1/5', 'ม.1', 'ว 2.3', 'วิเคราะห์สถานการณ์การถ่ายโอนความร้อนและคำนวณปริมาณความร้อนที่ถ่ายโอนระหว่างสสารจนเกิดสมดุลความร้อนโดยใช้สมการ Q = Q สูญเสีย ได้รับ', 'วิทยาศาสตร์', 5),
  ('ว 2.3 ม.1/6', 'ม.1', 'ว 2.3', 'สร้างแบบจำลองที่อธิบายการถ่ายโอนความร้อนโดยการนำความร้อน การพาความร้อนการแผ่รังสีความร้อน', 'วิทยาศาสตร์', 6),
  ('ว 2.3 ม.1/7', 'ม.1', 'ว 2.3', 'ออกแบบ เลือกใช้ และสร้างอุปกรณ์ เพื่อแก้ปัญหาในชีวิตประจำวันโดยใช้ความรู้เกี่ยวกับการถ่ายโอนความร้อน', 'วิทยาศาสตร์', 7),
  ('ว 2.3 ม.2/1', 'ม.2', 'ว 2.3', 'วิเคราะห์สถานการณ์และคำนวณเกี่ยวกับงานและกำลังที่เกิดจากแรงที่กระทำต่อวัตถุโดยใช้สมการ W = Fs และ P = W t จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 1),
  ('ว 2.3 ม.2/2', 'ม.2', 'ว 2.3', 'วิเคราะห์หลักการทำงานของเครื่องกลอย่างง่ายจากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 2),
  ('ว 2.3 ม.2/3', 'ม.2', 'ว 2.3', 'ตระหนักถึงประโยชน์ของความรู้ของเครื่องกลอย่างง่าย โดยบอกประโยชน์และการประยุกต์ใช้ในชีวิตประจำวัน', 'วิทยาศาสตร์', 3),
  ('ว 2.3 ม.2/4', 'ม.2', 'ว 2.3', 'ออกแบบและทดลองด้วยวิธีที่เหมาะสมในการอธิบายปัจจัยที่มีผลต่อพลังงานจลน์และพลังงานศักย์โน้มถ่วง', 'วิทยาศาสตร์', 4),
  ('ว 2.3 ม.2/5', 'ม.2', 'ว 2.3', 'แปลความหมายข้อมูลและอธิบายการเปลี่ยนพลังงานระหว่างพลังงานศักย์โน้มถ่วงและพลังงานจลน์ของวัตถุโดยพลังงานกลของวัตถุมีค่าคงตัวจากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 5),
  ('ว 2.3 ม.2/6', 'ม.2', 'ว 2.3', 'วิเคราะห์สถานการณ์และอธิบายการเปลี่ยนและการถ่ายโอนพลังงานโดยใช้กฎการอนุรักษ์พลังงาน', 'วิทยาศาสตร์', 6),
  ('ว 2.3 ม.3/1', 'ม.3', 'ว 2.3', 'วิเคราะห์ความสัมพันธ์ระหว่างความต่างศักย์กระแสไฟฟ้า และความต้านทาน และคำนวณปริมาณที่เกี่ยวข้องโดยใช้สมการ V = IR จากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 2.3 ม.3/2', 'ม.3', 'ว 2.3', 'เขียนกราฟความสัมพันธ์ระหว่างกระแสไฟฟ้าและความต่างศักย์ไฟฟ้า', 'วิทยาศาสตร์', 2),
  ('ว 2.3 ม.3/3', 'ม.3', 'ว 2.3', 'ใช้โวลต์มิเตอร์ แอมมิเตอร์ในการวัดปริมาณทางไฟฟ้า', 'วิทยาศาสตร์', 3),
  ('ว 2.3 ม.3/4', 'ม.3', 'ว 2.3', 'วิเคราะห์ความต่างศักย์ไฟฟ้าและกระแสไฟฟ้าในวงจรไฟฟ้าเมื่อต่อตัวต้านทานหลายตัวแบบอนุกรมและแบบขนานจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 4),
  ('ว 2.3 ม.3/5', 'ม.3', 'ว 2.3', 'เขียนแผนภาพวงจรไฟฟ้าแสดงการต่อตัวต้านทานแบบอนุกรมและขนาน', 'วิทยาศาสตร์', 5),
  ('ว 2.3 ม.3/6', 'ม.3', 'ว 2.3', 'บรรยายการทำงานของชิ้นส่วนอิเล็กทรอนิกส์อย่างง่ายในวงจรจากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 6),
  ('ว 2.3 ม.3/7', 'ม.3', 'ว 2.3', 'เขียนแผนภาพและต่อชิ้นส่วนอิเล็กทรอนิกส์อย่างง่ายในวงจรไฟฟ้า', 'วิทยาศาสตร์', 7),
  ('ว 2.3 ม.3/8', 'ม.3', 'ว 2.3', 'อธิบายและคำนวณพลังงานไฟฟ้าโดยใช้สมการ W = Pt รวมทั้งคำนวณค่าไฟฟ้าของเครื่องใช้ไฟฟ้าในบ้าน', 'วิทยาศาสตร์', 8),
  ('ว 2.3 ม.3/9', 'ม.3', 'ว 2.3', 'ตระหนักในคุณค่าของการเลือกใช้เครื่องใช้ไฟฟ้าโดยนำเสนอวิธีการใช้เครื่องใช้ไฟฟ้าอย่างประหยัดและปลอดภัย', 'วิทยาศาสตร์', 9),
  ('ว 2.3 ม.3/10', 'ม.3', 'ว 2.3', 'สร้างแบบจำลองที่อธิบายการเกิดคลื่นและบรรยายส่วนประกอบของคลื่น', 'วิทยาศาสตร์', 10),
  ('ว 2.3 ม.3/11', 'ม.3', 'ว 2.3', 'อธิบายคลื่นแม่เหล็กไฟฟ้าและสเปกตรัมคลื่นแม่เหล็กไฟฟ้าจากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 11),
  ('ว 2.3 ม.3/12', 'ม.3', 'ว 2.3', 'ตระหนักถึงประโยชน์และอันตรายจากคลื่นแม่เหล็กไฟฟ้าโดยนำเสนอการใช้ประโยชน์ในด้านต่าง ๆ และอันตรายจากคลื่นแม่เหล็กไฟฟ้าในชีวิตประจำวัน', 'วิทยาศาสตร์', 12),
  ('ว 2.3 ม.3/13', 'ม.3', 'ว 2.3', 'ออกแบบการทดลองและดำเนินการทดลองด้วยวิธีที่เหมาะสมในการอธิบายกฎการสะท้อนของแสง', 'วิทยาศาสตร์', 13),
  ('ว 2.3 ม.3/14', 'ม.3', 'ว 2.3', 'เขียนแผนภาพการเคลื่อนที่ของแสง แสดงการเกิดภาพจากกระจกเงา', 'วิทยาศาสตร์', 14),
  ('ว 2.3 ม.3/15', 'ม.3', 'ว 2.3', 'อธิบายการหักเหของแสงเมื่อผ่านตัวกลางโปร่งใสที่แตกต่างกัน และอธิบายการกระจายแสงของแสงขาวเมื่อผ่านปริซึมจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 15),
  ('ว 2.3 ม.3/16', 'ม.3', 'ว 2.3', 'เขียนแผนภาพการเคลื่อนที่ของแสงแสดงการเกิดภาพจากเลนส์บาง', 'วิทยาศาสตร์', 16),
  ('ว 2.3 ม.3/17', 'ม.3', 'ว 2.3', 'อธิบายปรากฏการณ์ที่เกี่ยวกับแสง และการทำงานของทัศนอุปกรณ์จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 17),
  ('ว 2.3 ม.3/18', 'ม.3', 'ว 2.3', 'เขียนแผนภาพการเคลื่อนที่ของแสง แสดงการเกิดภาพของทัศนอุปกรณ์และเลนส์ตา', 'วิทยาศาสตร์', 18),
  ('ว 2.3 ม.3/19', 'ม.3', 'ว 2.3', 'อธิบายผลของความสว่างที่มีต่อดวงตาจากข้อมูลที่ได้จากการสืบค้น', 'วิทยาศาสตร์', 19),
  ('ว 2.3 ม.3/20', 'ม.3', 'ว 2.3', 'วัดความสว่างของแสงโดยใช้อุปกรณ์วัดความสว่างของแสง', 'วิทยาศาสตร์', 20),
  ('ว 2.3 ม.3/21', 'ม.3', 'ว 2.3', 'ตระหนักในคุณค่าของความรู้เรื่อง ความสว่างของแสงที่มีต่อดวงตา โดยวิเคราะห์สถานการณ์ปัญหาและเสนอแนะการจัดความสว่างให้เหมาะสมในการทำกิจกรรมต่าง ๆ', 'วิทยาศาสตร์', 21),
  ('ว 2.3 ม.5/1', 'ม.5', 'ว 2.3', 'สืบค้นข้อมูลและอธิบายพลังงานนิวเคลียร์ฟิชชันและฟิวชัน และความสัมพันธ์ระหว่างมวลกับพลังงานที่ปลดปล่อยออกมาจากฟิชชันและฟิวชัน', 'วิทยาศาสตร์', 1),
  ('ว 2.3 ม.5/2', 'ม.5', 'ว 2.3', 'สืบค้นข้อมูล และอธิบายการเปลี่ยนพลังงานทดแทนเป็นพลังงานไฟฟ้า รวมทั้งสืบค้นและอภิปรายเกี่ยวกับเทคโนโลยีที่นำมาแก้ปัญหาหรือตอบสนองความต้องการทางด้านพลังงานโดยเน้นด้านประสิทธิภาพและความคุ้มค่าด้านค่าใช้จ่าย', 'วิทยาศาสตร์', 2),
  ('ว 2.3 ม.5/3', 'ม.5', 'ว 2.3', 'สังเกต และอธิบายการสะท้อน การหักเหการเลี้ยวเบน และการรวมคลื่น', 'วิทยาศาสตร์', 3),
  ('ว 2.3 ม.5/4', 'ม.5', 'ว 2.3', 'สังเกต และอธิบายความถี่ธรรมชาติ การสั่นพ้องและผลที่เกิดขึ้นจากการสั่นพ้อง', 'วิทยาศาสตร์', 4),
  ('ว 2.3 ม.5/5', 'ม.5', 'ว 2.3', 'สังเกต และอธิบายการสะท้อน การหักเหการเลี้ยวเบน และการรวมคลื่นของคลื่นเสียง', 'วิทยาศาสตร์', 5),
  ('ว 2.3 ม.5/6', 'ม.5', 'ว 2.3', 'สืบค้นข้อมูล และอธิบายความสัมพันธ์ระหว่างความเข้มเสียงกับระดับเสียงและผลของความถี่กับระดับเสียงที่มีต่อการได้ยินเสียง', 'วิทยาศาสตร์', 6),
  ('ว 2.3 ม.5/7', 'ม.5', 'ว 2.3', 'สังเกต และอธิบายการเกิดเสียงสะท้อนกลับบีต ดอปเพลอร์ และการสั่นพ้องของเสียง', 'วิทยาศาสตร์', 7),
  ('ว 2.3 ม.5/8', 'ม.5', 'ว 2.3', 'สืบค้นข้อมูล และยกตัวอย่างการนำความรู้เกี่ยวกับเสียงไปใช้ประโยชน์ในชีวิตประจำวัน', 'วิทยาศาสตร์', 8),
  ('ว 2.3 ม.5/9', 'ม.5', 'ว 2.3', 'สังเกต และอธิบายการมองเห็นสีของวัตถุและความผิดปกติในการมองเห็นสี', 'วิทยาศาสตร์', 9),
  ('ว 2.3 ม.5/10', 'ม.5', 'ว 2.3', 'สังเกต และอธิบายการทำงานของแผ่นกรองแสงสี การผสมแสงสี การผสมสารสี และการนำไปใช้ประโยชน์ในชีวิตประจำวัน', 'วิทยาศาสตร์', 10),
  ('ว 2.3 ม.5/11', 'ม.5', 'ว 2.3', 'สืบค้นข้อมูลและอธิบายคลื่นแม่เหล็กไฟฟ้าส่วนประกอบคลื่นแม่เหล็กไฟฟ้า และหลักการทำงานของอุปกรณ์บางชนิดที่อาศัยคลื่นแม่เหล็กไฟฟ้า', 'วิทยาศาสตร์', 11),
  ('ว 2.3 ม.5/12', 'ม.5', 'ว 2.3', 'สืบค้นข้อมูลและอธิบายการสื่อสาร โดยอาศัยคลื่นแม่เหล็กไฟฟ้าในการส่งผ่านสารสนเทศและเปรียบเทียบการสื่อสารด้วยสัญญาณแอนะล็อกกับสัญญาณดิจิทัล', 'วิทยาศาสตร์', 12),
  ('ว 3.1 ป.1/1', 'ป.1', 'ว 3.1', 'ระบุดาวที่ปรากฏบนท้องฟ้าในเวลากลางวันและกลางคืนจากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 1),
  ('ว 3.1 ป.1/2', 'ป.1', 'ว 3.1', 'อธิบายสาเหตุที่มองไม่เห็นดาวส่วนใหญ่ในเวลากลางวันจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 2),
  ('ว 3.1 ป.3/1', 'ป.3', 'ว 3.1', 'อธิบายแบบรูปเส้นทางการขึ้นและตก ของดวงอาทิตย์โดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 3.1 ป.3/2', 'ป.3', 'ว 3.1', 'อธิบายสาเหตุการเกิดปรากฏการณ์การขึ้นและตกของดวงอาทิตย์ การเกิดกลางวันกลางคืนและการกำหนดทิศ โดยใช้แบบจำลอง', 'วิทยาศาสตร์', 2),
  ('ว 3.1 ป.3/3', 'ป.3', 'ว 3.1', 'ตระหนักถึงความสำคัญของดวงอาทิตย์ โดยบรรยายประโยชน์ของดวงอาทิตย์ต่อสิ่งมีชีวิต', 'วิทยาศาสตร์', 3),
  ('ว 3.1 ป.4/1', 'ป.4', 'ว 3.1', 'อธิบายแบบรูปเส้นทางการขึ้นและตกของดวงจันทร์ โดยใช้หลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 1),
  ('ว 3.1 ป.4/2', 'ป.4', 'ว 3.1', 'สร้างแบบจำลองที่อธิบายแบบรูปการเปลี่ยนแปลงรูปร่างปรากฏของดวงจันทร์และพยากรณ์รูปร่างปรากฏของดวงจันทร์', 'วิทยาศาสตร์', 2),
  ('ว 3.1 ป.4/3', 'ป.4', 'ว 3.1', 'สร้างแบบจำลองแสดงองค์ประกอบของระบบสุริยะ และอธิบายเปรียบเทียบคาบการโคจรของดาวเคราะห์ต่าง ๆ จากแบบจำลอง', 'วิทยาศาสตร์', 3),
  ('ว 3.1 ป.5/1', 'ป.5', 'ว 3.1', 'เปรียบเทียบความแตกต่างของดาวเคราะห์และดาวฤกษ์จากแบบจำลอง', 'วิทยาศาสตร์', 1),
  ('ว 3.1 ป.5/2', 'ป.5', 'ว 3.1', 'ใช้แผนที่ดาวระบุตำแหน่งและเส้นทางการขึ้นและตกของกลุ่มดาวฤกษ์บนท้องฟ้า และอธิบายแบบรูปเส้นทางการขึ้นและตกของกลุ่มดาวฤกษ์บนท้องฟ้าในรอบปี', 'วิทยาศาสตร์', 2),
  ('ว 3.1 ป.6/1', 'ป.6', 'ว 3.1', 'สร้างแบบจำลองที่อธิบายการเกิด และเปรียบเทียบปรากฏการณ์สุริยุปราคาและจันทรุปราคา', 'วิทยาศาสตร์', 1),
  ('ว 3.1 ป.6/2', 'ป.6', 'ว 3.1', 'อธิบายพัฒนาการของเทคโนโลยีอวกาศ และยกตัวอย่างการนำเทคโนโลยีอวกาศมาใช้ประโยชน์ในชีวิตประจำวัน จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 2),
  ('ว 3.1 ม.3/1', 'ม.3', 'ว 3.1', 'อธิบายการโคจรของดาวเคราะห์รอบดวงอาทิตย์ด้วยแรงโน้มถ่วงจากสมการ 2 F = (Gm m )/r 1 2', 'วิทยาศาสตร์', 1),
  ('ว 3.1 ม.3/2', 'ม.3', 'ว 3.1', 'สร้างแบบจำลองที่อธิบายการเกิดฤดู และการเคลื่อนที่ปรากฏของดวงอาทิตย์', 'วิทยาศาสตร์', 2),
  ('ว 3.1 ม.3/3', 'ม.3', 'ว 3.1', 'สร้างแบบจำลองที่อธิบายการเกิดข้างขึ้นข้างแรม การเปลี่ยนแปลงเวลาการขึ้นและตกของดวงจันทร์ และการเกิดน้ำขึ้นน้ำลง', 'วิทยาศาสตร์', 3),
  ('ว 3.1 ม.3/4', 'ม.3', 'ว 3.1', 'อธิบายการใช้ประโยชน์ของเทคโนโลยีอวกาศและยกตัวอย่างความก้าวหน้าของโครงการสำรวจอวกาศ จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 4),
  ('ว 3.1 ม.6/1', 'ม.6', 'ว 3.1', 'อธิบายการกำเนิดและการเปลี่ยนแปลงพลังงานสสาร ขนาด อุณหภูมิของเอกภพหลังเกิดบิกแบงในช่วงเวลาต่าง ๆ ตามวิวัฒนาการของเอกภพ', 'วิทยาศาสตร์', 1),
  ('ว 3.1 ม.6/2', 'ม.6', 'ว 3.1', 'อธิบายหลักฐานที่สนับสนุนทฤษฎีบิกแบงจากความสัมพันธ์ระหว่างความเร็วกับระยะทางของกาแล็กซี รวมทั้งข้อมูลการค้นพบไมโครเวฟพื้นหลังจากอวกาศ', 'วิทยาศาสตร์', 2),
  ('ว 3.1 ม.6/3', 'ม.6', 'ว 3.1', 'อธิบายโครงสร้างและองค์ประกอบของกาแล็กซีทางช้างเผือก และระบุตำแหน่งของระบบสุริยะพร้อมอธิบายเชื่อมโยงกับการสังเกตเห็นทางช้างเผือกของคนบนโลก', 'วิทยาศาสตร์', 3),
  ('ว 3.1 ม.6/4', 'ม.6', 'ว 3.1', 'อธิบายกระบวนการเกิดดาวฤกษ์ โดยแสดงการเปลี่ยนแปลงความดัน อุณหภูมิ ขนาดจากดาวฤกษ์ก่อนเกิดจนเป็นดาวฤกษ์', 'วิทยาศาสตร์', 4),
  ('ว 3.1 ม.6/5', 'ม.6', 'ว 3.1', 'ระบุปัจจัยที่ส่งผลต่อความส่องสว่างของดาวฤกษ์ และอธิบายความสัมพันธ์ระหว่างความส่องสว่างกับโชติมาตรของดาวฤกษ์', 'วิทยาศาสตร์', 5),
  ('ว 3.1 ม.6/6', 'ม.6', 'ว 3.1', 'อธิบายความสัมพันธ์ระหว่างสี อุณหภูมิผิวและสเปกตรัมของดาวฤกษ์', 'วิทยาศาสตร์', 6),
  ('ว 3.1 ม.6/7', 'ม.6', 'ว 3.1', 'อธิบายลำดับวิวัฒนาการที่สัมพันธ์กับมวลตั้งต้นและวิเคราะห์การเปลี่ยนแปลงสมบัติบางประการของดาวฤกษ์', 'วิทยาศาสตร์', 7),
  ('ว 3.1 ม.6/8', 'ม.6', 'ว 3.1', 'อธิบายกระบวนการเกิดระบบสุริยะ และการแบ่งเขตบริวารของดวงอาทิตย์ และลักษณะของดาวเคราะห์ที่เอื้อต่อการดำรงชีวิต', 'วิทยาศาสตร์', 8),
  ('ว 3.1 ม.6/9', 'ม.6', 'ว 3.1', 'อธิบายโครงสร้างของดวงอาทิตย์ การเกิดลมสุริยะ พายุสุริยะ และสืบค้นข้อมูล วิเคราะห์นำเสนอปรากฏการณ์หรือเหตุการณ์ที่เกี่ยวข้องกับผลของลมสุริยะ และพายุสุริยะที่มีต่อโลกรวมทั้งประเทศไทย', 'วิทยาศาสตร์', 9),
  ('ว 3.1 ม.6/10', 'ม.6', 'ว 3.1', 'สืบค้นข้อมูล อธิบายการสำรวจอวกาศ โดยใช้กล้องโทรทรรศน์ในช่วงความยาวคลื่นต่าง ๆ ดาวเทียม ยานอวกาศ สถานีอวกาศ และนำเสนอแนวคิดการนำความรู้ทางด้านเทคโนโลยีอวกาศมาประยุกต์ใช้ ในชีวิตประจำวันหรือในอนาคต', 'วิทยาศาสตร์', 10),
  ('ว 3.2 ป.1/1', 'ป.1', 'ว 3.2', 'อธิบายลักษณะภายนอกของหิน จากลักษณะเฉพาะตัวที่สังเกตได้', 'วิทยาศาสตร์', 1),
  ('ว 3.2 ป.2/1', 'ป.2', 'ว 3.2', 'ระบุส่วนประกอบของดิน และจำแนกชนิดของดินโดยใช้ลักษณะเนื้อดินและการจับตัวเป็นเกณฑ์', 'วิทยาศาสตร์', 1),
  ('ว 3.2 ป.2/2', 'ป.2', 'ว 3.2', 'อธิบายการใช้ประโยชน์จากดิน จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 2),
  ('ว 3.2 ป.3/1', 'ป.3', 'ว 3.2', 'ระบุส่วนประกอบของอากาศ บรรยายความสำคัญของอากาศ และผลกระทบของมลพิษทางอากาศต่อสิ่งมีชีวิต จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 1),
  ('ว 3.2 ป.3/2', 'ป.3', 'ว 3.2', 'ตระหนักถึงความสำคัญของอากาศ โดยนำเสนอแนวทางการปฏิบัติตนในการลดการเกิดมลพิษทางอากาศ', 'วิทยาศาสตร์', 2),
  ('ว 3.2 ป.3/3', 'ป.3', 'ว 3.2', 'อธิบายการเกิดลมจากหลักฐานเชิงประจักษ์', 'วิทยาศาสตร์', 3),
  ('ว 3.2 ป.3/4', 'ป.3', 'ว 3.2', 'บรรยายประโยชน์และโทษของลม จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 4),
  ('ว 3.2 ป.5/1', 'ป.5', 'ว 3.2', 'เปรียบเทียบปริมาณน้ำในแต่ละแหล่ง และระบุปริมาณน้ำที่มนุษย์สามารถนำมาใช้ประโยชน์ได้จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 1),
  ('ว 3.2 ป.5/2', 'ป.5', 'ว 3.2', 'ตระหนักถึงคุณค่าของน้ำโดยนำเสนอแนวทางการใช้น้ำอย่างประหยัดและการอนุรักษ์น้ำ', 'วิทยาศาสตร์', 2),
  ('ว 3.2 ป.5/3', 'ป.5', 'ว 3.2', 'สร้างแบบจำลองที่อธิบายการหมุนเวียนของน้ำในวัฏจักรน้ำ', 'วิทยาศาสตร์', 3),
  ('ว 3.2 ป.5/4', 'ป.5', 'ว 3.2', 'เปรียบเทียบกระบวนการเกิดเมฆ หมอก น้ำค้างและน้ำค้างแข็ง จากแบบจำลอง', 'วิทยาศาสตร์', 4),
  ('ว 3.2 ป.5/5', 'ป.5', 'ว 3.2', 'เปรียบเทียบกระบวนการเกิดฝน หิมะ และลูกเห็บ จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 5),
  ('ว 3.2 ป.6/1', 'ป.6', 'ว 3.2', 'เปรียบเทียบกระบวนการเกิดหินอัคนีหินตะกอน และหินแปร และอธิบายวัฏจักรหินจากแบบจำลอง', 'วิทยาศาสตร์', 1),
  ('ว 3.2 ป.6/2', 'ป.6', 'ว 3.2', 'บรรยายและยกตัวอย่างการใช้ประโยชน์ของหินและแร่ในชีวิตประจำวันจากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 2),
  ('ว 3.2 ป.6/3', 'ป.6', 'ว 3.2', 'สร้างแบบจำลองที่อธิบายการเกิดซากดึกดำบรรพ์และคาดคะเนสภาพแวดล้อมในอดีตของซากดึกดำบรรพ์', 'วิทยาศาสตร์', 3),
  ('ว 3.2 ป.6/4', 'ป.6', 'ว 3.2', 'เปรียบเทียบการเกิดลมบก ลมทะเล และมรสุมรวมทั้งอธิบายผลที่มีต่อสิ่งมีชีวิตและสิ่งแวดล้อมจากแบบจำลอง', 'วิทยาศาสตร์', 4),
  ('ว 3.2 ป.6/5', 'ป.6', 'ว 3.2', 'อธิบายผลของมรสุมต่อการเกิดฤดูของประเทศไทยจากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 5),
  ('ว 3.2 ป.6/6', 'ป.6', 'ว 3.2', 'บรรยายลักษณะและผลกระทบของน้ำท่วมการกัดเซาะชายฝั่ง ดินถล่ม แผ่นดินไหว สึนามิ', 'วิทยาศาสตร์', 6),
  ('ว 3.2 ป.6/7', 'ป.6', 'ว 3.2', 'ตระหนักถึงผลกระทบของภัยธรรมชาติและธรณีพิบัติภัย โดยนำเสนอแนวทางในการเฝ้าระวังและปฏิบัติตนให้ปลอดภัยจากภัยธรรมชาติและธรณีพิบัติภัยที่อาจเกิดในท้องถิ่น', 'วิทยาศาสตร์', 7),
  ('ว 3.2 ป.6/8', 'ป.6', 'ว 3.2', 'สร้างแบบจำลองที่อธิบายการเกิดปรากฏการณ์เรือนกระจก และผลของปรากฏการณ์เรือนกระจกต่อสิ่งมีชีวิต', 'วิทยาศาสตร์', 8),
  ('ว 3.2 ป.6/9', 'ป.6', 'ว 3.2', 'ตระหนักถึงผลกระทบของปรากฏการณ์เรือนกระจก โดยนำเสนอแนวทางการปฏิบัติตนเพื่อลดกิจกรรมที่ก่อให้เกิดแก๊สเรือนกระจก', 'วิทยาศาสตร์', 9),
  ('ว 3.2 ม.1/1', 'ม.1', 'ว 3.2', 'สร้างแบบจำลองที่อธิบายการแบ่งชั้นบรรยากาศและเปรียบเทียบประโยชน์ของบรรยากาศแต่ละชั้น', 'วิทยาศาสตร์', 1),
  ('ว 3.2 ม.1/2', 'ม.1', 'ว 3.2', 'อธิบายปัจจัยที่มีผลต่อการเปลี่ยนแปลงองค์ประกอบของลมฟ้าอากาศ จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 2),
  ('ว 3.2 ม.1/3', 'ม.1', 'ว 3.2', 'เปรียบเทียบกระบวนการเกิดพายุ ฝนฟ้าคะนองและพายุหมุนเขตร้อน และผลที่มีต่อสิ่งมีชีวิตและสิ่งแวดล้อม รวมทั้งนำเสนอแนวทางการปฏิบัติตนให้เหมาะสมและปลอดภัย', 'วิทยาศาสตร์', 3),
  ('ว 3.2 ม.1/4', 'ม.1', 'ว 3.2', 'อธิบายการพยากรณ์อากาศ และพยากรณ์อากาศอย่างง่ายจากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 4),
  ('ว 3.2 ม.1/5', 'ม.1', 'ว 3.2', 'ตระหนักถึงคุณค่าของการพยากรณ์อากาศโดยนำเสนอแนวทางการปฏิบัติตนและการใช้ประโยชน์จากคำพยากรณ์อากาศ', 'วิทยาศาสตร์', 5),
  ('ว 3.2 ม.1/6', 'ม.1', 'ว 3.2', 'อธิบายสถานการณ์และผลกระทบการเปลี่ยนแปลงภูมิอากาศโลกจากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 6),
  ('ว 3.2 ม.1/7', 'ม.1', 'ว 3.2', 'ตระหนักถึงผลกระทบของการเปลี่ยนแปลงภูมิอากาศโลก โดยนำเสนอแนวทางการปฏิบัติตนภายใต้การเปลี่ยนแปลงภูมิอากาศโลก', 'วิทยาศาสตร์', 7),
  ('ว 3.2 ม.2/1', 'ม.2', 'ว 3.2', 'เปรียบเทียบกระบวนการเกิด สมบัติ และการใช้ประโยชน์ รวมทั้งอธิบายผลกระทบจากการใช้เชื้อเพลิงซากดึกดำบรรพ์ จากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 1),
  ('ว 3.2 ม.2/2', 'ม.2', 'ว 3.2', 'แสดงความตระหนักถึงผลจากการใช้เชื้อเพลิงซากดึกดำบรรพ์ โดยนำเสนอแนวทางการใช้เชื้อเพลิงซากดึกดำบรรพ์', 'วิทยาศาสตร์', 2),
  ('ว 3.2 ม.2/3', 'ม.2', 'ว 3.2', 'เปรียบเทียบข้อดีและข้อจำกัดของพลังงานทดแทนแต่ละประเภทจากการรวบรวมข้อมูลและนำเสนอแนวทางการใช้พลังงานทดแทนที่เหมาะสมในท้องถิ่น', 'วิทยาศาสตร์', 3),
  ('ว 3.2 ม.2/4', 'ม.2', 'ว 3.2', 'สร้างแบบจำลองที่อธิบายโครงสร้างภายในโลกตามองค์ประกอบทางเคมีจากข้อมูลที่รวบรวมได้', 'วิทยาศาสตร์', 4),
  ('ว 3.2 ม.2/5', 'ม.2', 'ว 3.2', 'อธิบายกระบวนการผุพังอยู่กับที่ การกร่อนและการสะสมตัวของตะกอนจากแบบจำลองรวมทั้งยกตัวอย่างผลของกระบวนการดังกล่าวที่ทำให้ผิวโลกเกิดการเปลี่ยนแปลง', 'วิทยาศาสตร์', 5),
  ('ว 3.2 ม.2/6', 'ม.2', 'ว 3.2', 'อธิบายลักษณะของชั้นหน้าตัดดินและกระบวนการเกิดดิน จากแบบจำลอง รวมทั้งระบุปัจจัยที่ทำให้ดินมีลักษณะและสมบัติแตกต่างกัน', 'วิทยาศาสตร์', 6),
  ('ว 3.2 ม.2/7', 'ม.2', 'ว 3.2', 'ตรวจวัดสมบัติบางประการของดิน โดยใช้เครื่องมือที่เหมาะสมและนำเสนอแนวทางการใช้ประโยชน์ดินจากข้อมูลสมบัติของดิน', 'วิทยาศาสตร์', 7),
  ('ว 3.2 ม.2/8', 'ม.2', 'ว 3.2', 'อธิบายปัจจัยและกระบวนการเกิดแหล่งน้ำผิวดินและแหล่งน้ำใต้ดิน จากแบบจำลอง', 'วิทยาศาสตร์', 8),
  ('ว 3.2 ม.2/9', 'ม.2', 'ว 3.2', 'สร้างแบบจำลองที่อธิบายการใช้น้ำ และนำเสนอแนวทางการใช้น้ำอย่างยั่งยืนในท้องถิ่นของตนเอง', 'วิทยาศาสตร์', 9),
  ('ว 3.2 ม.2/10', 'ม.2', 'ว 3.2', 'สร้างแบบจำลองที่อธิบายกระบวนการเกิดและผลกระทบของน้ำท่วม การกัดเซาะชายฝั่งดินถล่ม หลุมยุบ แผ่นดินทรุด', 'วิทยาศาสตร์', 10),
  ('ว 3.2 ม.6/1', 'ม.6', 'ว 3.2', 'อธิบายการแบ่งชั้นและสมบัติของโครงสร้างโลกพร้อมยกตัวอย่างข้อมูลที่สนับสนุน', 'วิทยาศาสตร์', 1),
  ('ว 3.2 ม.6/2', 'ม.6', 'ว 3.2', 'อธิบายหลักฐานทางธรณีวิทยาที่สนับสนุนการเคลื่อนที่ของแผ่นธรณี', 'วิทยาศาสตร์', 2),
  ('ว 3.2 ม.6/3', 'ม.6', 'ว 3.2', 'ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่ของแผ่นธรณี พร้อมยกตัวอย่างหลักฐานทางธรณีวิทยาที่พบ', 'วิทยาศาสตร์', 3),
  ('ว 3.2 ม.6/4', 'ม.6', 'ว 3.2', 'อธิบายสาเหตุ กระบวนการเกิดภูเขาไฟระเบิดรวมทั้งสืบค้นข้อมูลพื้นที่เสี่ยงภัย ออกแบบและนำเสนอแนวทางการเฝ้าระวังและการปฏิบัติตนให้ปลอดภัย', 'วิทยาศาสตร์', 4),
  ('ว 3.2 ม.6/5', 'ม.6', 'ว 3.2', 'อธิบายสาเหตุ กระบวนการเกิด ขนาดและความรุนแรง และผลจากแผ่นดินไหว รวมทั้งสืบค้นข้อมูลพื้นที่เสี่ยงภัย ออกแบบและนำเสนอแนวทางการเฝ้าระวังและการปฏิบัติตนให้ปลอดภัย', 'วิทยาศาสตร์', 5),
  ('ว 3.2 ม.6/6', 'ม.6', 'ว 3.2', 'อธิบายสาเหตุ กระบวนการเกิด และผลจากสึนามิรวมทั้งสืบค้นข้อมูลพื้นที่เสี่ยงภัย ออกแบบและนำเสนอแนวทางการเฝ้าระวังและการปฏิบัติตนให้ปลอดภัย', 'วิทยาศาสตร์', 6),
  ('ว 3.2 ม.6/7', 'ม.6', 'ว 3.2', 'อธิบายปัจจัยสำคัญที่มีผลต่อการได้รับพลังงานจากดวงอาทิตย์แตกต่างกันในแต่ละบริเวณของโลก', 'วิทยาศาสตร์', 7),
  ('ว 3.2 ม.6/8', 'ม.6', 'ว 3.2', 'อธิบายการหมุนเวียนของอากาศ ที่เป็นผลมาจากความแตกต่างของความกดอากาศ', 'วิทยาศาสตร์', 8),
  ('ว 3.2 ม.6/9', 'ม.6', 'ว 3.2', 'อธิบายทิศทางการเคลื่อนที่ของอากาศ ที่เป็นผลมาจากการหมุนรอบตัวเองของโลก', 'วิทยาศาสตร์', 9),
  ('ว 3.2 ม.6/10', 'ม.6', 'ว 3.2', 'อธิบายการหมุนเวียนของอากาศตามเขตละติจูด และผลที่มีต่อภูมิอากาศ', 'วิทยาศาสตร์', 10),
  ('ว 3.2 ม.6/11', 'ม.6', 'ว 3.2', 'อธิบายปัจจัยที่ทำให้เกิดการหมุนเวียนของน้ำผิวหน้าในมหาสมุทร และรูปแบบการหมุนเวียนของน้ำผิวหน้าในมหาสมุทร', 'วิทยาศาสตร์', 11),
  ('ว 3.2 ม.6/12', 'ม.6', 'ว 3.2', 'อธิบายผลของการหมุนเวียนของอากาศและน้ำผิวหน้าในมหาสมุทรที่มีต่อลักษณะภูมิอากาศ ลมฟ้าอากาศ สิ่งมีชีวิต และสิ่งแวดล้อม', 'วิทยาศาสตร์', 12),
  ('ว 3.2 ม.6/13', 'ม.6', 'ว 3.2', 'อธิบายปัจจัยที่มีผลต่อการเปลี่ยนแปลงภูมิอากาศของโลก พร้อมทั้งนำเสนอแนวปฏิบัติเพื่อลดกิจกรรมของมนุษย์ ที่ส่งผลต่อการเปลี่ยนแปลงภูมิอากาศโลก', 'วิทยาศาสตร์', 13),
  ('ว 3.2 ม.6/14', 'ม.6', 'ว 3.2', 'แปลความหมายสัญลักษณ์ลมฟ้าอากาศที่สำคัญจากแผนที่อากาศ และนำข้อมูลสารสนเทศต่าง ๆ มาวางแผนการดำเนินชีวิตให้สอดคล้องกับสภาพลมฟ้าอากาศ', 'วิทยาศาสตร์', 14),
  ('ว 4.1 ม.1/1', 'ม.1', 'ว 4.1', 'อธิบายแนวคิดหลักของเทคโนโลยีในชีวิตประจำวันและวิเคราะห์สาเหตุหรือปัจจัยที่ส่งผลต่อการเปลี่ยนแปลงของเทคโนโลยี', 'วิทยาศาสตร์', 1),
  ('ว 4.1 ม.1/2', 'ม.1', 'ว 4.1', 'ระบุปัญหาหรือความต้องการในชีวิตประจำวันรวบรวม วิเคราะห์ข้อมูลและแนวคิดที่เกี่ยวข้องกับปัญหา', 'วิทยาศาสตร์', 2),
  ('ว 4.1 ม.1/3', 'ม.1', 'ว 4.1', 'ออกแบบวิธีการแก้ปัญหา โดยวิเคราะห์เปรียบเทียบ และตัดสินใจเลือกข้อมูลที่จำเป็นนำเสนอแนวทางการแก้ปัญหาให้ผู้อื่นเข้าใจวางแผนและดำเนินการแก้ปัญหา', 'วิทยาศาสตร์', 3),
  ('ว 4.1 ม.1/4', 'ม.1', 'ว 4.1', 'ทดสอบ ประเมินผล และระบุข้อบกพร่องที่เกิดขึ้น พร้อมทั้งหาแนวทางการปรับปรุงแก้ไขและนำเสนอผลการแก้ปัญหา', 'วิทยาศาสตร์', 4),
  ('ว 4.1 ม.1/5', 'ม.1', 'ว 4.1', 'ใช้ความรู้และทักษะเกี่ยวกับวัสดุ อุปกรณ์เครื่องมือ กลไก ไฟฟ้า หรืออิเล็กทรอนิกส์เพื่อแก้ปัญหาได้อย่างถูกต้อง เหมาะสมและปลอดภัย', 'วิทยาศาสตร์', 5),
  ('ว 4.1 ม.2/1', 'ม.2', 'ว 4.1', 'คาดการณ์แนวโน้มเทคโนโลยีที่จะเกิดขึ้นโดยพิจารณาจากสาเหตุหรือปัจจัยที่ส่งผลต่อการเปลี่ยนแปลงของเทคโนโลยี และวิเคราะห์เปรียบเทียบ ตัดสินใจเลือกใช้เทคโนโลยีโดยคำนึงถึงผลกระทบที่เกิดขึ้นต่อชีวิต สังคมและสิ่งแวดล้อม', 'วิทยาศาสตร์', 1),
  ('ว 4.1 ม.2/2', 'ม.2', 'ว 4.1', 'ระบุปัญหาหรือความต้องการในชุมชนหรือท้องถิ่น สรุปกรอบของปัญหา รวบรวม วิเคราะห์ข้อมูลและแนวคิดที่เกี่ยวข้องกับปัญหา', 'วิทยาศาสตร์', 2),
  ('ว 4.1 ม.2/3', 'ม.2', 'ว 4.1', 'ออกแบบวิธีการแก้ปัญหา โดยวิเคราะห์เปรียบเทียบ และตัดสินใจเลือกข้อมูลที่จำเป็นภายใต้เงื่อนไขและทรัพยากรที่มีอยู่ นำเสนอแนวทางการแก้ปัญหาให้ผู้อื่นเข้าใจ วางแผนขั้นตอนการทำงานและดำเนินการแก้ปัญหาอย่างเป็นขั้นตอน', 'วิทยาศาสตร์', 3),
  ('ว 4.1 ม.2/4', 'ม.2', 'ว 4.1', 'ทดสอบ ประเมินผล และอธิบายปัญหาหรือข้อบกพร่องที่เกิดขึ้น ภายใต้กรอบเงื่อนไขพร้อมทั้งหาแนวทางการปรับปรุงแก้ไข และนำเสนอผลการแก้ปัญหา', 'วิทยาศาสตร์', 4),
  ('ว 4.1 ม.2/5', 'ม.2', 'ว 4.1', 'ใช้ความรู้ และทักษะเกี่ยวกับวัสดุ อุปกรณ์เครื่องมือ กลไก ไฟฟ้า และอิเล็กทรอนิกส์เพื่อแก้ปัญหาหรือพัฒนางานได้อย่างถูกต้องเหมาะสม และปลอดภัย', 'วิทยาศาสตร์', 5),
  ('ว 4.1 ม.3/1', 'ม.3', 'ว 4.1', 'วิเคราะห์สาเหตุ หรือปัจจัยที่ส่งผลต่อการเปลี่ยนแปลงของเทคโนโลยี และความสัมพันธ์ของเทคโนโลยีกับศาสตร์อื่น โดยเฉพาะวิทยาศาสตร์ หรือคณิตศาสตร์ เพื่อเป็นแนวทางการแก้ปัญหาหรือพัฒนางาน', 'วิทยาศาสตร์', 1),
  ('ว 4.1 ม.3/2', 'ม.3', 'ว 4.1', 'ระบุปัญหาหรือความต้องการของชุมชนหรือท้องถิ่น เพื่อพัฒนางานอาชีพ สรุปกรอบของปัญหา รวบรวม วิเคราะห์ข้อมูลและแนวคิดที่เกี่ยวข้องกับปัญหา โดยคำนึงถึงความถูกต้องด้านทรัพย์สินทางปัญญา', 'วิทยาศาสตร์', 2),
  ('ว 4.1 ม.3/3', 'ม.3', 'ว 4.1', 'ออกแบบวิธีการแก้ปัญหา โดยวิเคราะห์เปรียบเทียบ และตัดสินใจเลือกข้อมูลที่จำเป็นภายใต้เงื่อนไขและทรัพยากรที่มีอยู่ นำเสนอแนวทางการแก้ปัญหาให้ผู้อื่นเข้าใจด้วยเทคนิคหรือวิธีการที่หลากหลาย วางแผนขั้นตอนการทำงานและดำเนินการแก้ปัญหาอย่างเป็นขั้นตอน', 'วิทยาศาสตร์', 3),
  ('ว 4.1 ม.3/4', 'ม.3', 'ว 4.1', 'ทดสอบ ประเมินผล วิเคราะห์ และให้เหตุผลของปัญหาหรือข้อบกพร่องที่เกิดขึ้นภายใต้กรอบเงื่อนไข พร้อมทั้งหาแนวทางการปรับปรุงแก้ไข และนำเสนอผลการแก้ปัญหา', 'วิทยาศาสตร์', 4),
  ('ว 4.1 ม.3/5', 'ม.3', 'ว 4.1', 'ใช้ความรู้ และทักษะเกี่ยวกับวัสดุ อุปกรณ์เครื่องมือ กลไก ไฟฟ้าและอิเล็กทรอนิกส์ให้ถูกต้องกับลักษณะของงาน และปลอดภัยเพื่อแก้ปัญหาหรือพัฒนางาน', 'วิทยาศาสตร์', 5),
  ('ว 4.1 ม.4/1', 'ม.4', 'ว 4.1', 'วิเคราะห์แนวคิดหลักของเทคโนโลยี ความสัมพันธ์กับศาสตร์อื่น โดยเฉพาะวิทยาศาสตร์ หรือคณิตศาสตร์ รวมทั้งประเมินผลกระทบที่จะเกิดขึ้นต่อมนุษย์ สังคม เศรษฐกิจ และสิ่งแวดล้อม เพื่อเป็นแนวทางในการพัฒนาเทคโนโลยี', 'วิทยาศาสตร์', 1),
  ('ว 4.1 ม.4/2', 'ม.4', 'ว 4.1', 'ระบุปัญหาหรือความต้องการที่มีผลกระทบต่อสังคม รวบรวม วิเคราะห์ข้อมูลและแนวคิดที่เกี่ยวข้องกับปัญหาที่มีความซับซ้อนเพื่อสังเคราะห์วิธีการ เทคนิคในการแก้ปัญหาโดยคำนึงถึงความถูกต้องด้านทรัพย์สินทางปัญญา', 'วิทยาศาสตร์', 2),
  ('ว 4.1 ม.4/3', 'ม.4', 'ว 4.1', 'ออกแบบวิธีการแก้ปัญหา โดยวิเคราะห์เปรียบเทียบ และตัดสินใจเลือกข้อมูลที่จำเป็นภายใต้เงื่อนไขและทรัพยากรที่มีอยู่ นำเสนอแนวทางการแก้ปัญหาให้ผู้อื่นเข้าใจด้วยเทคนิคหรือวิธีการที่หลากหลาย โดยใช้ซอฟต์แวร์ช่วยในการออกแบบ วางแผนขั้นตอนการทำงานและดำเนินการแก้ปัญหา', 'วิทยาศาสตร์', 3),
  ('ว 4.1 ม.4/4', 'ม.4', 'ว 4.1', 'ทดสอบ ประเมินผล วิเคราะห์ และให้เหตุผลของปัญหาหรือข้อบกพร่องที่เกิดขึ้นภายใต้กรอบเงื่อนไข หาแนวทางการปรับปรุงแก้ไขและนำเสนอผลการแก้ปัญหา พร้อมทั้งเสนอแนวทางการพัฒนาต่อยอด', 'วิทยาศาสตร์', 4),
  ('ว 4.1 ม.4/5', 'ม.4', 'ว 4.1', 'ใช้ความรู้และทักษะเกี่ยวกับวัสดุ อุปกรณ์เครื่องมือ กลไก ไฟฟ้าและอิเล็กทรอนิกส์และเทคโนโลยีที่ซับซ้อนในการแก้ปัญหาหรือพัฒนางาน ได้อย่างถูกต้อง เหมาะสมและปลอดภัย', 'วิทยาศาสตร์', 5),
  ('ว 4.1 ม.5/1', 'ม.5', 'ว 4.1', 'ประยุกต์ใช้ความรู้และทักษะจากศาสตร์ต่าง ๆ รวมทั้งทรัพยากรในการทำโครงงานเพื่อแก้ปัญหาหรือพัฒนางาน', 'วิทยาศาสตร์', 1),
  ('ว 4.2 ป.1/1', 'ป.1', 'ว 4.2', 'แก้ปัญหาอย่างง่ายโดยใช้การลองผิดลองถูกการเปรียบเทียบ', 'วิทยาศาสตร์', 1),
  ('ว 4.2 ป.1/2', 'ป.1', 'ว 4.2', 'แสดงลำดับขั้นตอนการทำงานหรือการแก้ปัญหาอย่างง่ายโดยใช้ภาพ สัญลักษณ์ หรือข้อความ', 'วิทยาศาสตร์', 2),
  ('ว 4.2 ป.1/3', 'ป.1', 'ว 4.2', 'เขียนโปรแกรมอย่างง่าย โดยใช้ซอฟต์แวร์หรือสื่อ', 'วิทยาศาสตร์', 3),
  ('ว 4.2 ป.1/4', 'ป.1', 'ว 4.2', 'ใช้เทคโนโลยีในการสร้าง จัดเก็บ เรียกใช้ข้อมูลตามวัตถุประสงค์', 'วิทยาศาสตร์', 4),
  ('ว 4.2 ป.1/5', 'ป.1', 'ว 4.2', 'ใช้เทคโนโลยีสารสนเทศอย่างปลอดภัย ปฏิบัติตามข้อตกลงในการใช้คอมพิวเตอร์ร่วมกัน ดูแลรักษาอุปกรณ์เบื้องต้น ใช้งานอย่างเหมาะสม', 'วิทยาศาสตร์', 5),
  ('ว 4.2 ป.2/1', 'ป.2', 'ว 4.2', 'แสดงลำดับขั้นตอนการทำงานหรือการแก้ปัญหาอย่างง่ายโดยใช้ภาพ สัญลักษณ์ หรือข้อความ', 'วิทยาศาสตร์', 1),
  ('ว 4.2 ป.2/2', 'ป.2', 'ว 4.2', 'เขียนโปรแกรมอย่างง่าย โดยใช้ซอฟต์แวร์หรือสื่อ และตรวจหาข้อผิดพลาดของโปรแกรม', 'วิทยาศาสตร์', 2),
  ('ว 4.2 ป.2/3', 'ป.2', 'ว 4.2', 'ใช้เทคโนโลยีในการสร้าง จัดหมวดหมู่ ค้นหาจัดเก็บ เรียกใช้ข้อมูลตามวัตถุประสงค์', 'วิทยาศาสตร์', 3),
  ('ว 4.2 ป.2/4', 'ป.2', 'ว 4.2', 'ใช้เทคโนโลยีสารสนเทศอย่างปลอดภัย ปฏิบัติตามข้อตกลงในการใช้คอมพิวเตอร์ร่วมกัน ดูแลรักษาอุปกรณ์เบื้องต้น ใช้งานอย่างเหมาะสม', 'วิทยาศาสตร์', 4),
  ('ว 4.2 ป.3/1', 'ป.3', 'ว 4.2', 'แสดงอัลกอริทึมในการทำงานหรือการแก้ปัญหาอย่างง่ายโดยใช้ภาพ สัญลักษณ์ หรือข้อความ', 'วิทยาศาสตร์', 1),
  ('ว 4.2 ป.3/2', 'ป.3', 'ว 4.2', 'เขียนโปรแกรมอย่างง่าย โดยใช้ซอฟต์แวร์หรือสื่อ และตรวจหาข้อผิดพลาดของโปรแกรม', 'วิทยาศาสตร์', 2),
  ('ว 4.2 ป.3/3', 'ป.3', 'ว 4.2', 'ใช้อินเทอร์เน็ตค้นหาความรู้', 'วิทยาศาสตร์', 3),
  ('ว 4.2 ป.3/4', 'ป.3', 'ว 4.2', 'รวบรวม ประมวลผล และนำเสนอข้อมูล โดยใช้ซอฟต์แวร์ตามวัตถุประสงค์', 'วิทยาศาสตร์', 4),
  ('ว 4.2 ป.3/5', 'ป.3', 'ว 4.2', 'ใช้เทคโนโลยีสารสนเทศอย่างปลอดภัย ปฏิบัติตามข้อตกลงในการใช้อินเทอร์เน็ต', 'วิทยาศาสตร์', 5),
  ('ว 4.2 ป.4/1', 'ป.4', 'ว 4.2', 'ใช้เหตุผลเชิงตรรกะในการแก้ปัญหา การอธิบายการทำงาน การคาดการณ์ผลลัพธ์ จากปัญหาอย่างง่าย', 'วิทยาศาสตร์', 1),
  ('ว 4.2 ป.4/2', 'ป.4', 'ว 4.2', 'ออกแบบ และเขียนโปรแกรมอย่างง่าย โดยใช้ซอฟต์แวร์หรือสื่อ และตรวจหาข้อผิดพลาดและแก้ไข', 'วิทยาศาสตร์', 2),
  ('ว 4.2 ป.4/3', 'ป.4', 'ว 4.2', 'ใช้อินเทอร์เน็ตค้นหาความรู้ และประเมินความน่าเชื่อถือของข้อมูล', 'วิทยาศาสตร์', 3),
  ('ว 4.2 ป.4/4', 'ป.4', 'ว 4.2', 'รวบรวม ประเมิน นำเสนอข้อมูลและสารสนเทศโดยใช้ซอฟต์แวร์ที่หลากหลาย เพื่อแก้ปัญหาในชีวิตประจำวัน', 'วิทยาศาสตร์', 4),
  ('ว 4.2 ป.4/5', 'ป.4', 'ว 4.2', 'ใช้เทคโนโลยีสารสนเทศอย่างปลอดภัย เข้าใจสิทธิและหน้าที่ของตน เคารพในสิทธิของผู้อื่นแจ้งผู้เกี่ยวข้องเมื่อพบข้อมูลหรือบุคคลที่ไม่เหมาะสม', 'วิทยาศาสตร์', 5),
  ('ว 4.2 ป.5/1', 'ป.5', 'ว 4.2', 'ใช้เหตุผลเชิงตรรกะในการแก้ปัญหา การอธิบายการทำงาน การคาดการณ์ผลลัพธ์ จากปัญหาอย่างง่าย', 'วิทยาศาสตร์', 1),
  ('ว 4.2 ป.5/2', 'ป.5', 'ว 4.2', 'ออกแบบ และเขียนโปรแกรมที่มีการใช้เหตุผลเชิงตรรกะอย่างง่าย ตรวจหาข้อผิดพลาดและแก้ไข', 'วิทยาศาสตร์', 2),
  ('ว 4.2 ป.5/3', 'ป.5', 'ว 4.2', 'ใช้อินเทอร์เน็ตค้นหาข้อมูล ติดต่อสื่อสารและทำงานร่วมกัน ประเมินความน่าเชื่อถือของข้อมูล', 'วิทยาศาสตร์', 3),
  ('ว 4.2 ป.5/4', 'ป.5', 'ว 4.2', 'รวบรวม ประเมิน นำเสนอข้อมูลและสารสนเทศตามวัตถุประสงค์โดยใช้ซอฟต์แวร์หรือบริการบนอินเทอร์เน็ตที่หลากหลาย เพื่อแก้ปัญหาในชีวิตประจำวัน', 'วิทยาศาสตร์', 4),
  ('ว 4.2 ป.5/5', 'ป.5', 'ว 4.2', 'ใช้เทคโนโลยีสารสนเทศอย่างปลอดภัย มีมารยาทเข้าใจสิทธิและหน้าที่ของตน เคารพในสิทธิของผู้อื่น แจ้งผู้เกี่ยวข้องเมื่อพบข้อมูลหรือบุคคลที่ไม่เหมาะสม', 'วิทยาศาสตร์', 5),
  ('ว 4.2 ป.6/1', 'ป.6', 'ว 4.2', 'ใช้เหตุผลเชิงตรรกะในการอธิบายและออกแบบวิธีการแก้ปัญหาที่พบในชีวิตประจำวัน', 'วิทยาศาสตร์', 1),
  ('ว 4.2 ป.6/2', 'ป.6', 'ว 4.2', 'ออกแบบและเขียนโปรแกรมอย่างง่าย เพื่อแก้ปัญหาในชีวิตประจำวัน ตรวจหาข้อผิดพลาดของโปรแกรมและแก้ไข', 'วิทยาศาสตร์', 2),
  ('ว 4.2 ป.6/3', 'ป.6', 'ว 4.2', 'ใช้อินเทอร์เน็ตในการค้นหาข้อมูลอย่างมีประสิทธิภาพ', 'วิทยาศาสตร์', 3),
  ('ว 4.2 ป.6/4', 'ป.6', 'ว 4.2', 'ใช้เทคโนโลยีสารสนเทศทำงานร่วมกันอย่างปลอดภัย เข้าใจสิทธิและหน้าที่ของตน เคารพในสิทธิของผู้อื่น แจ้งผู้เกี่ยวข้องเมื่อพบข้อมูลหรือบุคคลที่ไม่เหมาะสม', 'วิทยาศาสตร์', 4),
  ('ว 4.2 ม.1/1', 'ม.1', 'ว 4.2', 'ออกแบบอัลกอริทึมที่ใช้แนวคิดเชิงนามธรรมเพื่อแก้ปัญหาหรืออธิบายการทำงานที่พบในชีวิตจริง', 'วิทยาศาสตร์', 1),
  ('ว 4.2 ม.1/2', 'ม.1', 'ว 4.2', 'ออกแบบและเขียนโปรแกรมอย่างง่ายเพื่อแก้ปัญหาทางคณิตศาสตร์หรือวิทยาศาสตร์', 'วิทยาศาสตร์', 2),
  ('ว 4.2 ม.1/3', 'ม.1', 'ว 4.2', 'รวบรวมข้อมูลปฐมภูมิ ประมวลผล ประเมินผลนำเสนอข้อมูล และสารสนเทศ ตามวัตถุประสงค์โดยใช้ซอฟต์แวร์ หรือบริการบนอินเทอร์เน็ตที่หลากหลาย', 'วิทยาศาสตร์', 3),
  ('ว 4.2 ม.1/4', 'ม.1', 'ว 4.2', 'ใช้เทคโนโลยีสารสนเทศอย่างปลอดภัย ใช้สื่อและแหล่งข้อมูลตามข้อกำหนดและข้อตกลง', 'วิทยาศาสตร์', 4),
  ('ว 4.2 ม.2/1', 'ม.2', 'ว 4.2', 'ออกแบบอัลกอริทึมที่ใช้แนวคิดเชิงคำนวณในการแก้ปัญหา หรือการทำงานที่พบในชีวิตจริง', 'วิทยาศาสตร์', 1),
  ('ว 4.2 ม.2/2', 'ม.2', 'ว 4.2', 'ออกแบบและเขียนโปรแกรมที่ใช้ตรรกะและฟังก์ชันในการแก้ปัญหา', 'วิทยาศาสตร์', 2),
  ('ว 4.2 ม.2/3', 'ม.2', 'ว 4.2', 'อภิปรายองค์ประกอบและหลักการทำงานของระบบคอมพิวเตอร์ และเทคโนโลยีการสื่อสารเพื่อประยุกต์ใช้งานหรือแก้ปัญหาเบื้องต้น', 'วิทยาศาสตร์', 3),
  ('ว 4.2 ม.2/4', 'ม.2', 'ว 4.2', 'ใช้เทคโนโลยีสารสนเทศอย่างปลอดภัย มีความรับผิดชอบ สร้างและแสดงสิทธิในการเผยแพร่ผลงาน', 'วิทยาศาสตร์', 4),
  ('ว 4.2 ม.3/1', 'ม.3', 'ว 4.2', 'พัฒนาแอปพลิเคชันที่มีการบูรณาการกับวิชาอื่นอย่างสร้างสรรค์', 'วิทยาศาสตร์', 1),
  ('ว 4.2 ม.3/2', 'ม.3', 'ว 4.2', 'รวบรวมข้อมูล ประมวลผล ประเมินผล นำเสนอข้อมูลและสารสนเทศตามวัตถุประสงค์ โดยใช้ซอฟต์แวร์หรือบริการบนอินเทอร์เน็ตที่หลากหลาย', 'วิทยาศาสตร์', 2),
  ('ว 4.2 ม.3/3', 'ม.3', 'ว 4.2', 'ประเมินความน่าเชื่อถือของข้อมูล วิเคราะห์สื่อและผลกระทบจากการให้ข่าวสารที่ผิด เพื่อการใช้งานอย่างรู้เท่าทัน', 'วิทยาศาสตร์', 3),
  ('ว 4.2 ม.3/4', 'ม.3', 'ว 4.2', 'ใช้เทคโนโลยีสารสนเทศอย่างปลอดภัย และมีความรับผิดชอบต่อสังคม ปฏิบัติตามกฎหมายเกี่ยวกับคอมพิวเตอร์ ใช้ลิขสิทธิ์ของผู้อื่นโดยชอบธรรม', 'วิทยาศาสตร์', 4),
  ('ว 4.2 ม.4/1', 'ม.4', 'ว 4.2', 'ประยุกต์ใช้แนวคิดเชิงคำนวณในการพัฒนาโครงงานที่มีการบูรณาการกับวิชาอื่นอย่างสร้างสรรค์ และเชื่อมโยงกับชีวิตจริง', 'วิทยาศาสตร์', 1),
  ('ว 4.2 ม.5/1', 'ม.5', 'ว 4.2', 'รวบรวม วิเคราะห์ข้อมูล และใช้ความรู้ด้านวิทยาการคอมพิวเตอร์ สื่อดิจิทัล เทคโนโลยีสารสนเทศในการแก้ปัญหาหรือเพิ่มมูลค่าให้กับบริการหรือผลิตภัณฑ์ที่ใช้ในชีวิตจริงอย่างสร้างสรรค์', 'วิทยาศาสตร์', 1),
  ('ว 4.2 ม.6/1', 'ม.6', 'ว 4.2', 'ใช้เทคโนโลยีสารสนเทศในการนำเสนอ และแบ่งปันข้อมูลอย่างปลอดภัย มีจริยธรรม และวิเคราะห์การเปลี่ยนแปลงเทคโนโลยีสารสนเทศที่มีผลต่อการดำเนินชีวิต อาชีพ สังคม และวัฒนธรรม', 'วิทยาศาสตร์', 1)
INSERT INTO public.curriculum_core_content (standard_code, grade, seq, content) VALUES
  ('ว 1.1', 'ป.1', 1, 'บริเวณต่าง ๆ ในท้องถิ่น เช่น สนามหญ้า ใต้ต้นไม้สวนหย่อม แหล่งน้ำ อาจพบพืชและสัตว์หลายชนิดอาศัยอยู่'),
  ('ว 1.1', 'ป.1', 2, 'บริเวณที่แตกต่างกันอาจพบพืชและสัตว์แตกต่างกันเพราะสภาพแวดล้อมของแต่ละบริเวณจะมีความเหมาะสมต่อการดำรงชีวิตของพืชและสัตว์ที่อาศัยอยู่ในแต่ละบริเวณ เช่น สระน้ำ มีน้ำเป็นที่อยู่อาศัยของหอย ปลา สาหร่าย เป็นที่หลบภัยและมีแหล่งอาหารของหอยและปลา บริเวณต้นมะม่วงมีต้นมะม่วงเป็นแหล่งที่อยู่ และมีอาหารสำหรับกระรอกและมด'),
  ('ว 1.1', 'ป.1', 3, 'ถ้าสภาพแวดล้อมในบริเวณที่พืชและสัตว์อาศัยอยู่มีการเปลี่ยนแปลง จะมีผลต่อการดำรงชีวิตของพืชและสัตว์'),
  ('ว 1.1', 'ป.5', 1, 'สิ่งมีชีวิตทั้งพืชและสัตว์มีโครงสร้างและลักษณะที่เหมาะสมในแต่ละแหล่งที่อยู่ ซึ่งเป็นผลมาจากการปรับตัวของสิ่งมีชีวิต เพื่อให้ดำรงชีวิตและอยู่รอดได้ในแต่ละแหล่งที่อยู่ เช่น ผักตบชวามีช่องอากาศในก้านใบ ช่วยให้ลอยน้ำได้ ต้นโกงกางที่ขึ้นอยู่ในป่าชายเลนมีรากค้ำจุนทำให้ลำต้นไม่ล้ม ปลามีครีบช่วยในการเคลื่อนที่ในน้ำ'),
  ('ว 1.1', 'ป.5', 2, 'ในแหล่งที่อยู่หนึ่ง ๆ สิ่งมีชีวิตจะมีความสัมพันธ์ซึ่งกันและกันและสัมพันธ์กับสิ่งไม่มีชีวิต เพื่อประโยชน์ต่อการดำรงชีวิต เช่น ความสัมพันธ์กันด้านการกินกันเป็นอาหาร เป็นแหล่งที่อยู่อาศัยหลบภัยและเลี้ยงดูลูกอ่อน ใช้อากาศในการหายใจ'),
  ('ว 1.1', 'ป.5', 3, 'สิ่งมีชีวิตมีการกินกันเป็นอาหาร โดยกินต่อกันเป็นทอด ๆ ในรูปแบบของโซ่อาหาร ทำให้สามารถระบุบทบาทหน้าที่ของสิ่งมีชีวิตเป็นผู้ผลิตและผู้บริโภค'),
  ('ว 1.1', 'ม.3', 1, 'ระบบนิเวศประกอบด้วยองค์ประกอบที่มีชีวิตเช่น พืช สัตว์ จุลินทรีย์ และองค์ประกอบที่ไม่มีชีวิต เช่น แสง น้ำ อุณหภูมิ แร่ธาตุ แก๊สองค์ประกอบเหล่านี้มีปฏิสัมพันธ์กัน เช่นพืชต้องการแสง น้ำ และแก๊สคาร์บอนไดออกไซด์ในการสร้างอาหาร สัตว์ต้องการอาหาร และสภาพแวดล้อมที่เหมาะสมในการดำรงชีวิต เช่นอุณหภูมิ ความชื้น องค์ประกอบทั้งสองส่วนนี้จะต้องมีความสัมพันธ์กันอย่างเหมาะสมระบบนิเวศจึงจะสามารถคงอยู่ต่อไปได้'),
  ('ว 1.1', 'ม.3', 2, 'สิ่งมีชีวิตกับสิ่งมีชีวิตมีความสัมพันธ์กันในรูปแบบต่าง ๆ เช่น ภาวะพึ่งพากัน ภาวะอิงอาศัยภาวะเหยื่อกับผู้ล่า ภาวะปรสิต'),
  ('ว 1.1', 'ม.3', 3, 'สิ่งมีชีวิตชนิดเดียวกันที่อาศัยอยู่ร่วมกันในแหล่งที่อยู่เดียวกัน ในช่วงเวลาเดียวกัน เรียกว่าประชากร'),
  ('ว 1.1', 'ม.3', 4, 'กลุ่มสิ่งมีชีวิตประกอบด้วยประชากรของสิ่งมีชีวิตหลาย ๆ ชนิด อาศัยอยู่ร่วมกันในแหล่งที่อยู่เดียวกัน'),
  ('ว 1.1', 'ม.3', 5, 'กลุ่มสิ่งมีชีวิตในระบบนิเวศแบ่งตามหน้าที่ได้เป็น3 กลุ่ม ได้แก่ ผู้ผลิต ผู้บริโภค และผู้ย่อยสลายสารอินทรีย์ สิ่งมีชีวิตทั้ง 3 กลุ่มนี้ มีความสัมพันธ์กัน ผู้ผลิตเป็นสิ่งมีชีวิตที่สร้างอาหารได้เอง โดยกระบวนการสังเคราะห์ด้วยแสงผู้บริโภค เป็นสิ่งมีชีวิตที่ไม่สามารถสร้างอาหารได้เอง และต้องกินผู้ผลิตหรือสิ่งมีชีวิตอื่นเป็นอาหาร เมื่อผู้ผลิตและผู้บริโภคตายลง จะถูกย่อยโดยผู้ย่อยสลายสารอินทรีย์ซึ่งจะเปลี่ยนสารอินทรีย์เป็นสารอนินทรีย์กลับคืนสู่สิ่งแวดล้อม ทำให้เกิดการหมุนเวียนสารเป็นวัฏจักรจำนวนผู้ผลิต ผู้บริโภค และผู้ย่อยสลายสารอินทรีย์จะต้องมีความเหมาะสม จึงทำให้กลุ่มสิ่งมีชีวิตอยู่ได้อย่างสมดุล'),
  ('ว 1.1', 'ม.3', 6, 'พลังงานถูกถ่ายทอดจากผู้ผลิตไปยังผู้บริโภคลำดับต่าง ๆ รวมทั้งผู้ย่อยสลายสารอินทรีย์ในรูปแบบสายใยอาหาร ที่ประกอบด้วย โซ่อาหารหลายโซ่ที่สัมพันธ์กัน ในการถ่ายทอดพลังงานในโซ่อาหาร พลังงานที่ถูกถ่ายทอดไปจะลดลงเรื่อย ๆ ตามลำดับของการบริโภค'),
  ('ว 1.1', 'ม.3', 7, 'การถ่ายทอดพลังงานในระบบนิเวศ อาจทำให้มีสารพิษสะสมอยู่ในสิ่งมีชีวิตได้ จนอาจก่อให้เกิดอันตรายต่อสิ่งมีชีวิต และทำลายสมดุลในระบบนิเวศ ดังนั้นการดูแลรักษาระบบนิเวศให้เกิดความสมดุล และคงอยู่ตลอดไปจึงเป็นสิ่งสำคัญ'),
  ('ว 1.1', 'ม.4', 1, 'บริเวณของโลกแต่ละบริเวณมีสภาพทางภูมิศาสตร์ที่แตกต่างกัน แบ่งออกได้เป็นหลายเขตตามสภาพภูมิอากาศและปริมาณน้ำฝน ทำให้มีระบบนิเวศที่หลากหลายซึ่งส่งผลให้เกิดความหลากหลายของไบโอม'),
  ('ว 1.1', 'ม.4', 2, 'การเปลี่ยนแปลงของระบบนิเวศเกิดขึ้นได้ตลอดเวลาทั้งการเปลี่ยนแปลงที่เกิดขึ้นเองตามธรรมชาติและเกิดจากการกระทำของมนุษย์'),
  ('ว 1.1', 'ม.4', 3, 'การเปลี่ยนแปลงแทนที่เป็นการเปลี่ยนแปลงของกลุ่มสิ่งมีชีวิตที่เกิดขึ้นอย่างช้า ๆ เป็นเวลานานซึ่งเป็นผลจากปฏิสัมพันธ์ระหว่างองค์ประกอบทางกายภาพและทางชีวภาพ ส่งผลให้ระบบนิเวศเปลี่ยนแปลงไปสู่สมดุลจนเกิดสังคมสมบูรณ์ได้'),
  ('ว 1.1', 'ม.4', 4, 'การเปลี่ยนแปลงขององค์ประกอบในระบบนิเวศทั้งทางกายภาพและทางชีวภาพมีผลต่อการเปลี่ยนแปลงขนาดของประชากร'),
  ('ว 1.1', 'ม.4', 5, 'มนุษย์ใช้ทรัพยากรธรรมชาติโดยปราศจากความระมัดระวัง และมีการพัฒนาเทคโนโลยีใหม่ ๆ เพื่อช่วยอำนวยความสะดวกต่าง ๆ แก่มนุษย์ส่งผลต่อการเปลี่ยนแปลงทรัพยากรธรรมชาติและสิ่งแวดล้อม'),
  ('ว 1.1', 'ม.4', 6, 'ปัญหาที่เกิดกับทรัพยากรธรรมชาติและสิ่งแวดล้อมบางปัญหาส่งผลกระทบในระดับท้องถิ่นบางปัญหาก็ส่งผลกระทบในระดับประเทศและบางปัญหาส่งผลกระทบในระดับโลก'),
  ('ว 1.1', 'ม.4', 7, 'การลดปริมาณการใช้ทรัพยากรธรรมชาติการกำจัดของเสียที่เป็นสาเหตุของปัญหาสิ่งแวดล้อมและการวางแผนจัดการทรัพยากรธรรมชาติที่ดีเป็นตัวอย่างของแนวทางในการอนุรักษ์ทรัพยากรธรรมชาติ และการลดปัญหาสิ่งแวดล้อมที่เกิดขึ้น เพื่อให้เกิดการใช้ประโยชน์ที่ยั่งยืน'),
  ('ว 1.2', 'ป.1', 1, 'มนุษย์มีส่วนต่าง ๆ ที่มีลักษณะและหน้าที่แตกต่างกัน เพื่อให้เหมาะสมในการดำรงชีวิตเช่น ตามีหน้าที่ไว้มองดู โดยมีหนังตาและขนตาเพื่อป้องกันอันตรายให้กับตา หูมีหน้าที่รับฟังเสียงโดยมีใบหูและรูหู เพื่อเป็นทางผ่านของเสียงปากมีหน้าที่พูด กินอาหาร มีช่องปากและมีริมฝีปากบนล่าง แขนและมือมีหน้าที่ยก หยิบ จับมีท่อนแขนและนิ้วมือที่ขยับได้ สมองมีหน้าที่ควบคุมการทำงานของส่วนต่าง ๆ ของร่างกายอยู่ในกะโหลกศีรษะ โดยส่วนต่าง ๆ ของร่างกายจะทำหน้าที่ร่วมกันในการทำกิจกรรมในชีวิตประจำวัน'),
  ('ว 1.2', 'ป.1', 2, 'สัตว์มีหลายชนิด แต่ละชนิดมีส่วนต่าง ๆ ที่มีลักษณะและหน้าที่แตกต่างกัน เพื่อให้เหมาะสมในการดำรงชีวิต เช่น ปลามีครีบเป็นแผ่น ส่วนกบเต่า แมว มีขา 4 ขา และมีเท้าสำหรับใช้ในการเคลื่อนที่'),
  ('ว 1.2', 'ป.1', 3, 'พืชมีส่วนต่าง ๆ ที่มีลักษณะและหน้าที่แตกต่างกันเพื่อให้เหมาะสมในการดำรงชีวิต โดยทั่วไป รากมีลักษณะเรียวยาว และแตกแขนงเป็นรากเล็ก ๆ ทำหน้าที่ดูดน้ำ ลำต้นมีลักษณะเป็นทรงกระบอกตั้งตรงและมีกิ่งก้าน ทำหน้าที่ชูกิ่งก้าน ใบและดอก ใบมีลักษณะเป็นแผ่นแบน ทำหน้าที่สร้างอาหาร นอกจากนี้พืชหลายชนิด อาจมีดอกที่มีสี รูปร่างต่าง ๆ ทำหน้าที่สืบพันธุ์ รวมทั้งมีผลที่มีเปลือก มีเนื้อห่อหุ้มเมล็ด และมีเมล็ดซึ่งสามารถงอกเป็นต้นใหม่ได้'),
  ('ว 1.2', 'ป.1', 4, 'มนุษย์ใช้ส่วนต่าง ๆ ของร่างกายในการทำกิจกรรมต่าง ๆ เพื่อการดำรงชีวิต มนุษย์จึงควรใช้ส่วนต่าง ๆ ของร่างกายอย่างถูกต้อง ปลอดภัยและรักษาความสะอาดอยู่เสมอ เช่น ใช้ตามองตัวหนังสือในที่ที่มีแสงสว่างเพียงพอ ดูแลตาให้ปลอดภัยจากอันตราย และรักษาความสะอาดตาอยู่เสมอ'),
  ('ว 1.2', 'ป.2', 1, 'พืชต้องการน้ำ แสง เพื่อการเจริญเติบโต'),
  ('ว 1.2', 'ป.2', 2, 'พืชดอกเมื่อเจริญเติบโตและมีดอก ดอกจะมีการสืบพันธุ์เปลี่ยนแปลงไปเป็นผล ภายในผลมีเมล็ดเมื่อเมล็ดงอก ต้นอ่อนที่อยู่ภายในเมล็ดจะเจริญเติบโตเป็นพืชต้นใหม่ พืชต้นใหม่จะเจริญเติบโตออกดอกเพื่อสืบพันธุ์มีผลต่อไปได้อีกหมุนเวียนต่อเนื่องเป็นวัฏจักรชีวิตของพืชดอก'),
  ('ว 1.2', 'ป.3', 1, 'มนุษย์และสัตว์ต้องการอาหาร น้ำ และอากาศเพื่อการดำรงชีวิตและการเจริญเติบโต'),
  ('ว 1.2', 'ป.3', 2, 'อาหารช่วยให้ร่างกายแข็งแรงและเจริญเติบโตน้ำช่วยให้ร่างกายทำงานได้อย่างปกติ อากาศใช้ในการหายใจ'),
  ('ว 1.2', 'ป.3', 3, 'สัตว์เมื่อเป็นตัวเต็มวัยจะสืบพันธุ์มีลูก เมื่อลูกเจริญเติบโตเป็นตัวเต็มวัยก็สืบพันธุ์มีลูกต่อไปได้อีก หมุนเวียนต่อเนื่องเป็นวัฏจักรชีวิตของสัตว์ซึ่งสัตว์แต่ละชนิด เช่น ผีเสื้อ กบ ไก่ มนุษย์จะมีวัฏจักรชีวิตที่เฉพาะและแตกต่างกัน'),
  ('ว 1.2', 'ป.4', 1, 'ส่วนต่าง ๆ ของพืชดอกทำหน้าที่แตกต่างกัน - รากทำหน้าที่ดูดน้ำและธาตุอาหารขึ้นไปยังลำต้น - ลำต้นทำหน้าที่ลำเลียงน้ำต่อไปยังส่วนต่าง ๆ ของพืช - ใบทำหน้าที่สร้างอาหาร อาหารที่พืชสร้างขึ้นคือ น้ำตาลซึ่งจะเปลี่ยนเป็นแป้ง - ดอกทำหน้าที่สืบพันธุ์ ประกอบด้วยส่วนประกอบต่าง ๆ ได้แก่ กลีบเลี้ยง กลีบดอกเกสรเพศผู้ และเกสรเพศเมีย ซึ่งส่วนประกอบแต่ละส่วนของดอกทำหน้าที่แตกต่างกัน'),
  ('ว 1.2', 'ป.6', 1, 'สารอาหารที่อยู่ในอาหารมี 6 ประเภท ได้แก่คาร์โบไฮเดรต โปรตีน ไขมัน เกลือแร่ วิตามินและน้ำ'),
  ('ว 1.2', 'ป.6', 2, 'อาหารแต่ละชนิดประกอบด้วยสารอาหารที่แตกต่างกัน อาหารบางอย่างประกอบด้วยสารอาหารประเภทเดียว อาหารบางอย่างประกอบด้วยสารอาหารมากกว่าหนึ่งประเภท'),
  ('ว 1.2', 'ป.6', 3, 'สารอาหารแต่ละประเภทมีประโยชน์ต่อร่างกายแตกต่างกัน โดยคาร์โบไฮเดรต โปรตีน และไขมันเป็นสารอาหารที่ให้พลังงานแก่ร่างกาย ส่วนเกลือแร่วิตามิน และน้ำ เป็นสารอาหารที่ไม่ให้พลังงานแก่ร่างกาย แต่ช่วยให้ร่างกายทำงานได้เป็นปกติ'),
  ('ว 1.2', 'ป.6', 4, 'การรับประทานอาหาร เพื่อให้ร่างกายเจริญเติบโต มีการเปลี่ยนแปลงของร่างกายตามเพศและวัย และมีสุขภาพดี จำเป็นต้องรับประทานให้ได้พลังงานเพียงพอกับความต้องการของร่างกายและให้ได้สารอาหารครบถ้วน ในสัดส่วนที่เหมาะสมกับเพศและวัย รวมทั้งต้องคำนึงถึงชนิดและปริมาณของวัตถุเจือปนในอาหารเพื่อความปลอดภัยต่อสุขภาพ'),
  ('ว 1.2', 'ป.6', 5, 'ระบบย่อยอาหารประกอบด้วยอวัยวะต่าง ๆ ได้แก่ปาก หลอดอาหาร กระเพาะอาหาร ลำไส้เล็กลำไส้ใหญ่ ทวารหนัก ตับ และตับอ่อน ซึ่งทำหน้าที่ร่วมกันในการย่อยและดูดซึมสารอาหาร - ปากมีฟันช่วยบดเคี้ยวอาหารให้มีขนาดเล็กลงและมีลิ้นช่วยคลุกเคล้าอาหารกับน้ำลายในน้ำลายมีเอนไซม์ย่อยแป้งให้เป็นน้ำตาล - หลอดอาหารทำหน้าที่ลำเลียงอาหารจากปากไปยังกระเพาะอาหาร ภายในกระเพาะอาหารมีการย่อยโปรตีนโดยกรดและเอนไซม์ที่สร้างจากกระเพาะอาหาร - ลำไส้เล็กมีเอนไซม์ที่สร้างจากผนังลำไส้เล็กเองและจากตับอ่อนที่ช่วยย่อยโปรตีน คาร์โบไฮเดรตและไขมัน โดยโปรตีน คาร์โบไฮเดรต และไขมันที่ผ่านการย่อยจนเป็นสารอาหารขนาดเล็กพอที่จะดูดซึมได้ รวมถึงน้ำ เกลือแร่ และวิตามินจะถูกดูดซึมที่ผนังลำไส้เล็กเข้าสู่กระแสเลือดเพื่อลำเลียงไปยังส่วนต่าง ๆ ของร่างกาย ซึ่งโปรตีน คาร์โบไฮเดรต และไขมัน จะถูกนำไปใช้เป็นแหล่งพลังงานสำหรับใช้ในกิจกรรมต่าง ๆ ส่วนน้ำ เกลือแร่ และวิตามิน จะช่วยให้ร่างกายทำงานได้เป็นปกติ - ตับสร้างน้ำดีแล้วส่งมายังลำไส้เล็กช่วยให้ไขมันแตกตัว - ลำไส้ใหญ่ทำหน้าที่ดูดน้ำและเกลือแร่ เป็นบริเวณที่มีอาหารที่ย่อยไม่ได้หรือย่อยไม่หมดเป็นกากอาหาร ซึ่งจะถูกกำจัดออกทางทวารหนัก'),
  ('ว 1.2', 'ป.6', 6, 'อวัยวะต่าง ๆ ในระบบย่อยอาหารมีความสำคัญจึงควรปฏิบัติตน ดูแลรักษาอวัยวะให้ทำงานเป็นปกติ'),
  ('ว 1.2', 'ม.1', 1, 'เซลล์เป็นหน่วยพื้นฐานของสิ่งมีชีวิต สิ่งมีชีวิตบางชนิดมีเซลล์เพียงเซลล์เดียว เช่น อะมีบาพารามีเซียม ยีสต์ บางชนิดมีหลายเซลล์ เช่นพืช สัตว์'),
  ('ว 1.2', 'ม.1', 2, 'โครงสร้างพื้นฐานที่พบทั้งในเซลล์พืชและเซลล์สัตว์และสามารถสังเกตได้ด้วยกล้องจุลทรรศน์ใช้แสงได้แก่ เยื่อหุ้มเซลล์ ไซโทพลาซึม และนิวเคลียสโครงสร้างที่พบในเซลล์พืชแต่ไม่พบในเซลล์สัตว์ได้แก่ ผนังเซลล์และคลอโรพลาสต์'),
  ('ว 1.2', 'ม.1', 3, 'โครงสร้างต่าง ๆ ของเซลล์มีหน้าที่แตกต่างกัน - ผนังเซลล์ ทำหน้าที่ให้ความแข็งแรงแก่เซลล์ - เยื่อหุ้มเซลล์ ทำหน้าที่ห่อหุ้มเซลล์และควบคุมการลำเลียงสารเข้าและออกจากเซลล์ - นิวเคลียส ทำหน้าที่ควบคุมการทำงานของเซลล์ - ไซโทพลาซึม มีออร์แกเนลล์ที่ทำหน้าที่แตกต่างกัน - แวคิวโอล ทำหน้าที่เก็บน้ำและสารต่าง ๆ - ไมโทคอนเดรีย ทำหน้าที่เกี่ยวกับการสลายสารอาหารเพื่อให้ได้พลังงานแก่เซลล์ - คลอโรพลาสต์ เป็นแหล่งที่เกิดการสังเคราะห์ด้วยแสง'),
  ('ว 1.2', 'ม.1', 4, 'เซลล์ของสิ่งมีชีวิตมีรูปร่าง ลักษณะ ที่หลากหลายและมีความเหมาะสมกับหน้าที่ของเซลล์นั้น เช่นเซลล์ประสาทส่วนใหญ่ มีเส้นใยประสาทเป็นแขนงยาว นำกระแสประสาทไปยังเซลล์อื่น ๆ ที่อยู่ไกลออกไป เซลล์ขนราก เป็นเซลล์ผิวของรากที่มีผนังเซลล์และเยื่อหุ้มเซลล์ยื่นยาวออกมาลักษณะคล้ายขนเส้นเล็ก ๆ เพื่อเพิ่มพื้นที่ผิวในการดูดน้ำและธาตุอาหาร'),
  ('ว 1.2', 'ม.1', 5, 'พืชและสัตว์เป็นสิ่งมีชีวิตหลายเซลล์มีการจัดระบบ โดยเริ่มจากเซลล์ไปเป็นเนื้อเยื่อ อวัยวะระบบอวัยวะ และสิ่งมีชีวิตตามลำดับ เซลล์หลายเซลล์มารวมกันเป็นเนื้อเยื่อ เนื้อเยื่อหลายชนิดมารวมกันและทำงานร่วมกันเป็นอวัยวะ อวัยวะต่าง ๆ ทำงานร่วมกันเป็นระบบอวัยวะ ระบบอวัยวะทุกระบบทำงานร่วมกันเป็นสิ่งมีชีวิต'),
  ('ว 1.2', 'ม.1', 6, 'เซลล์มีการนำสารเข้าสู่เซลล์ เพื่อใช้ในกระบวนการต่าง ๆ ของเซลล์ และมีการขจัดสารบางอย่างที่เซลล์ไม่ต้องการออกนอกเซลล์ การนำสารเข้าและออกจากเซลล์มีหลายวิธี เช่น การแพร่เป็นการเคลื่อนที่ของสารจากบริเวณที่มีความเข้มข้นของสารสูงไปสู่บริเวณที่มีความเข้มข้นของสารต่ำ ส่วนออสโมซิส เป็นการแพร่ของน้ำผ่านเยื่อหุ้มเซลล์ จากด้านที่มีความเข้มข้นของสารละลายต่ำไปยังด้านที่มีความเข้มข้นของสารละลายสูงกว่า'),
  ('ว 1.2', 'ม.1', 7, 'กระบวนการสังเคราะห์ด้วยแสงของพืชที่เกิดขึ้นในคลอโรพลาสต์ จำเป็นต้องใช้แสง แก๊สคาร์บอนได - ออกไซด์ คลอโรฟิลล์ และน้ำ ผลผลิตที่ได้จากการสังเคราะห์ด้วยแสง ได้แก่ น้ำตาลและแก๊สออกซิเจน'),
  ('ว 1.2', 'ม.1', 8, 'การสังเคราะห์ด้วยแสง เป็นกระบวนการที่สำคัญต่อสิ่งมีชีวิต เพราะเป็นกระบวนการเดียวที่สามารถนำพลังงานแสงมาเปลี่ยนเป็นพลังงานในรูปสารประกอบอินทรีย์และเก็บสะสมในรูปแบบต่าง ๆ ในโครงสร้างของพืช พืชจึงเป็นแหล่งอาหารและพลังงานที่สำคัญของสิ่งมีชีวิตอื่นนอกจากนี้กระบวนการสังเคราะห์ด้วยแสงยังเป็นกระบวนการหลักในการสร้างแก๊สออกซิเจนให้กับบรรยากาศเพื่อให้สิ่งมีชีวิตอื่น ใช้ในกระบวนการหายใจ'),
  ('ว 1.2', 'ม.1', 9, 'พืชมีไซเล็มและโฟลเอ็ม ซึ่งเป็นเนื้อเยื่อมีลักษณะคล้ายท่อ เรียงตัวกันเป็นกลุ่มเฉพาะที่โดยไซเล็มทำหน้าที่ลำเลียงน้ำและธาตุอาหารมีทิศทางลำเลียงจากรากไปสู่ลำต้น ใบ และส่วนต่าง ๆ ของพืช เพื่อใช้ในการสังเคราะห์ด้วยแสงรวมถึงกระบวนการอื่น ๆ ส่วนโฟลเอ็มทำหน้าที่ลำเลียงอาหารที่ได้จากการสังเคราะห์ด้วยแสงมีทิศทางลำเลียงจากบริเวณที่มีการสังเคราะห์ด้วยแสงไปสู่ส่วนต่าง ๆ ของพืช'),
  ('ว 1.2', 'ม.1', 10, 'พืชดอกทุกชนิดสามารถสืบพันธุ์แบบอาศัยเพศได้และบางชนิดสามารถสืบพันธุ์แบบไม่อาศัยเพศได้'),
  ('ว 1.2', 'ม.1', 11, 'การสืบพันธุ์แบบอาศัยเพศเป็นการสืบพันธุ์ที่มีการผสมกันของสเปิร์มกับเซลล์ไข่ การสืบพันธุ์แบบอาศัยเพศของพืชดอกเกิดขึ้นที่ดอก โดยภายในอับเรณูของส่วนเกสรเพศผู้มีเรณู ซึ่งทำหน้าที่สร้างสเปิร์ม ภายในออวุลของส่วนเกสรเพศเมียมีถุงเอ็มบริโอ ทำหน้าที่สร้างเซลล์ไข่'),
  ('ว 1.2', 'ม.1', 12, 'การสืบพันธุ์แบบไม่อาศัยเพศ เป็นการสืบพันธุ์ที่พืชต้นใหม่ไม่ได้เกิดจากการปฏิสนธิระหว่างสเปิร์มกับเซลล์ไข่ แต่เกิดจากส่วนต่าง ๆ ของพืช เช่นราก ลำต้น ใบ มีการเจริญเติบโตและพัฒนาขึ้นมาเป็นต้นใหม่ได้'),
  ('ว 1.2', 'ม.1', 13, 'การถ่ายเรณู คือ การเคลื่อนย้ายของเรณูจากอับเรณูไปยังยอดเกสรเพศเมีย ซึ่งเกี่ยวข้องกับลักษณะและโครงสร้างของดอก เช่น สีของกลีบดอก ตำแหน่งของเกสรเพศผู้และเกสรเพศเมีย โดยมีสิ่งที่ช่วยในการถ่ายเรณู เช่น แมลง ลม'),
  ('ว 1.2', 'ม.1', 14, 'การถ่ายเรณูจะนำไปสู่การปฏิสนธิ ซึ่งจะเกิดขึ้นที่ถุงเอ็มบริโอภายในออวุล หลังการปฏิสนธิจะได้ไซโกต และเอนโดสเปิร์ม ไซโกตจะพัฒนาต่อไปเป็นเอ็มบริโอ ออวุลพัฒนาไปเป็นเมล็ด และรังไข่พัฒนาไปเป็นผล'),
  ('ว 1.2', 'ม.1', 15, 'ผลและเมล็ดมีการกระจายออกจากต้นเดิม โดยวิธีการต่าง ๆ เมื่อเมล็ดไปตกในสภาพแวดล้อมที่เหมาะสมจะเกิดการงอกของเมล็ด โดยเอ็มบริโอภายในเมล็ดจะเจริญออกมา โดยระยะแรกจะอาศัยอาหารที่สะสมภายในเมล็ด จนกระทั่งใบแท้พัฒนา จนสามารถสังเคราะห์ด้วยแสงได้เต็มที่ และสร้างอาหารได้เองตามปกติ'),
  ('ว 1.2', 'ม.1', 16, 'พืชต้องการธาตุอาหารที่จำเป็นหลายชนิดในการเจริญเติบโตและการดำรงชีวิต'),
  ('ว 1.2', 'ม.1', 17, 'พืชต้องการธาตุอาหารบางชนิดในปริมาณมาก ได้แก่ไนโตรเจน ฟอสฟอรัส โพแทสเซียม แคลเซียมแมกนีเซียม และกำมะถัน ซึ่งในดินอาจมีไม่เพียงพอสำหรับการเจริญเติบโตของพืช จึงต้องมีการให้ธาตุอาหารในรูปของปุ๋ยกับพืชอย่างเหมาะสม'),
  ('ว 1.2', 'ม.1', 18, 'มนุษย์สามารถนำความรู้เรื่องการสืบพันธุ์แบบอาศัยเพศและไม่อาศัยเพศ มาใช้ในการขยายพันธุ์เพื่อเพิ่มจำนวนพืช เช่น การใช้เมล็ดที่ได้จากการสืบพันธุ์แบบอาศัยเพศมาเพาะเลี้ยงวิธีการนี้จะได้พืชในปริมาณมาก แต่อาจมีลักษณะที่แตกต่างไปจากพ่อแม่ ส่วนการตอนกิ่ง การปักชำการต่อกิ่ง การติดตา การทาบกิ่ง การเพาะเลี้ยงเนื้อเยื่อ เป็นการนำความรู้เรื่องการสืบพันธุ์แบบไม่อาศัยเพศของพืชมาใช้ในการขยายพันธุ์เพื่อให้ได้พืชที่มีลักษณะเหมือนต้นเดิม ซึ่งการขยายพันธุ์แต่ละวิธี มีขั้นตอนแตกต่างกัน จึงควรเลือกให้เหมาะสมกับความต้องการของมนุษย์ โดยต้องคำนึงถึงชนิดของพืชและลักษณะการสืบพันธุ์ของพืช'),
  ('ว 1.2', 'ม.1', 19, 'เทคโนโลยีการเพาะเลี้ยงเนื้อเยื่อพืช เป็นการนำความรู้เกี่ยวกับปัจจัยที่จำเป็นต่อการเจริญเติบโตของพืชมาใช้ในการเพิ่มจำนวนพืช และทำให้พืชสามารถเจริญเติบโตได้ในหลอดทดลอง ซึ่งจะได้พืชจำนวนมากในระยะเวลาสั้น และสามารถนำเทคโนโลยีการเพาะเลี้ยงเนื้อเยื่อมาประยุกต์เพื่อการอนุรักษ์พันธุกรรมพืช ปรับปรุงพันธุ์พืชที่มีความสำคัญทางเศรษฐกิจ การผลิตยาและสารสำคัญในพืช และอื่น ๆ'),
  ('ว 1.2', 'ม.2', 1, 'ระบบหายใจมีอวัยวะต่าง ๆ ที่เกี่ยวข้อง ได้แก่จมูก ท่อลม ปอด กะบังลม และกระดูกซี่โครง'),
  ('ว 1.2', 'ม.2', 2, 'มนุษย์หายใจเข้า เพื่อนำแก๊สออกซิเจนเข้าสู่ร่างกายเพื่อนำไปใช้ในเซลล์ และหายใจออกเพื่อกำจัดแก๊สคาร์บอนไดออกไซด์ออกจากร่างกาย'),
  ('ว 1.2', 'ม.2', 3, 'อากาศเคลื่อนที่เข้าและออกจากปอดได้เนื่องจากการเปลี่ยนแปลงปริมาตรและความดันของอากาศภายในช่องอกซึ่งเกี่ยวข้องกับการทำงานของกะบังลม และกระดูกซี่โครง'),
  ('ว 1.2', 'ม.2', 4, 'การแลกเปลี่ยนแก๊สออกซิเจนกับแก๊สคาร์บอนไดออกไซด์ในร่างกาย เกิดขึ้นบริเวณถุงลมในปอดกับหลอดเลือดฝอยที่ถุงลม และระหว่างหลอดเลือดฝอยกับเนื้อเยื่อ'),
  ('ว 1.2', 'ม.2', 5, 'การสูบบุหรี่ การสูดอากาศที่มีสารปนเปื้อน และการเป็นโรคเกี่ยวกับระบบหายใจบางโรคอาจทำให้เกิดโรคถุงลมโป่งพอง ซึ่งมีผลให้ความจุอากาศของปอดลดลง ดังนั้นจึงควรดูแลรักษาระบบหายใจ ให้ทำหน้าที่เป็นปกติ'),
  ('ว 1.2', 'ม.2', 6, 'ระบบขับถ่ายมีอวัยวะที่เกี่ยวข้อง คือ ไต ท่อไตกระเพาะปัสสาวะ และท่อปัสสาวะ โดยมีไตทำหน้าที่กำจัดของเสีย เช่น ยูเรีย แอมโมเนียกรดยูริก รวมทั้งสารที่ร่างกายไม่ต้องการออกจากเลือด และควบคุมสารที่มีมากหรือน้อยเกินไปเช่น น้ำ โดยขับออกมาในรูปของปัสสาวะ'),
  ('ว 1.2', 'ม.2', 7, 'การเลือกรับประทานอาหารที่เหมาะสม เช่นรับประทานอาหารที่ไม่มีรสเค็มจัด การดื่มน้ำสะอาดให้เพียงพอ เป็นแนวทางหนึ่งที่ช่วยให้ระบบขับถ่ายทำหน้าที่ได้อย่างปกติ'),
  ('ว 1.2', 'ม.2', 8, 'ระบบหมุนเวียนเลือดประกอบด้วย หัวใจหลอดเลือด และเลือด'),
  ('ว 1.2', 'ม.2', 9, 'หัวใจของมนุษย์แบ่งเป็น 4 ห้อง ได้แก่ หัวใจห้องบน 2 ห้อง และห้องล่าง 2 ห้อง ระหว่างหัวใจห้องบนและหัวใจห้องล่างมีลิ้นหัวใจกั้น'),
  ('ว 1.2', 'ม.2', 10, 'หลอดเลือด แบ่งเป็น หลอดเลือดอาร์เตอรีหลอดเลือดเวน หลอดเลือดฝอย ซึ่งมีโครงสร้างต่างกัน'),
  ('ว 1.2', 'ม.2', 11, 'เลือด ประกอบด้วย เซลล์เม็ดเลือด เพลตเลตและพลาสมา'),
  ('ว 1.2', 'ม.2', 12, 'การบีบและคลายตัวของหัวใจทำให้เลือดหมุนเวียนและลำเลียงสารอาหาร แก๊ส ของเสีย และสารอื่น ๆ ไปยังอวัยวะและเซลล์ต่าง ๆ ทั่วร่างกาย'),
  ('ว 1.2', 'ม.2', 13, 'เลือดที่มีปริมาณแก๊สออกซิเจนสูงจะออกจากหัวใจไปยังเซลล์ต่าง ๆ ทั่วร่างกาย ขณะเดียวกันแก๊สคาร์บอนไดออกไซด์จากเซลล์จะแพร่เข้าสู่เลือดและลำเลียงกลับเข้าสู่หัวใจและถูกส่งไปแลกเปลี่ยนแก๊สที่ปอด'),
  ('ว 1.2', 'ม.2', 14, 'ชีพจรบอกถึงจังหวะการเต้นของหัวใจซึ่งอัตราการเต้นของหัวใจในขณะปกติและหลังจากทำกิจกรรมต่าง ๆ จะแตกต่างกันส่วนความดันเลือด ระบบหมุนเวียนเลือดเกิดจากการทำงานของหัวใจและหลอดเลือด'),
  ('ว 1.2', 'ม.2', 15, 'อัตราการเต้นของหัวใจมีความแตกต่างกันในแต่ละบุคคล คนที่เป็นโรคหัวใจและหลอดเลือดจะส่งผลทำให้หัวใจสูบฉีดเลือดไม่เป็นปกติ'),
  ('ว 1.2', 'ม.2', 16, 'การออกกำลังกาย การเลือกรับประทานอาหารการพักผ่อน และการรักษาภาวะอารมณ์ให้เป็นปกติ จึงเป็นทางเลือกหนึ่งในการดูแลรักษาระบบหมุนเวียนเลือดให้เป็นปกติ'),
  ('ว 1.2', 'ม.2', 17, 'ระบบประสาทส่วนกลาง ประกอบด้วยสมองและไขสันหลัง จะทำหน้าที่ร่วมกับเส้นประสาทซึ่งเป็นระบบประสาทรอบนอก ในการควบคุมการทำงานของอวัยวะต่าง ๆ รวมถึงการแสดงพฤติกรรม เพื่อการตอบสนองต่อสิ่งเร้า'),
  ('ว 1.2', 'ม.2', 18, 'เมื่อมีสิ่งเร้ามากระตุ้นหน่วยรับความรู้สึก จะเกิดกระแสประสาทส่งไปตามเซลล์ประสาทรับความรู้สึกไปยังระบบประสาทส่วนกลาง แล้วส่งกระแสประสาทมาตามเซลล์ประสาทสั่งการ ไปยังหน่วยปฏิบัติงาน เช่น กล้ามเนื้อ'),
  ('ว 1.2', 'ม.2', 19, 'ระบบประสาทเป็นระบบที่มีความซับซ้อนและมีความสัมพันธ์กับทุกระบบในร่างกาย ดังนั้นจึงควรป้องกันการเกิดอุบัติเหตุที่กระทบกระเทือนต่อสมอง หลีกเลี่ยงการใช้สารเสพติด หลีกเลี่ยงภาวะเครียด และรับประทานอาหารที่มีประโยชน์เพื่อดูแลรักษาระบบประสาทให้ทำงานเป็นปกติ'),
  ('ว 1.2', 'ม.2', 20, 'มนุษย์มีระบบสืบพันธุ์ที่ประกอบด้วยอวัยวะต่าง ๆ ที่ทำหน้าที่เฉพาะ โดยรังไข่ในเพศหญิงจะทำหน้าที่ผลิตเซลล์ไข่ ส่วนอัณฑะในเพศชายจะทำหน้าที่สร้างเซลล์อสุจิ'),
  ('ว 1.2', 'ม.2', 21, 'ฮอร์โมนเพศทำหน้าที่ควบคุมการแสดงออกของลักษณะทางเพศที่แตกต่างกัน เมื่อเข้าสู่วัยหนุ่มสาวจะมีการสร้างเซลล์ไข่และเซลล์อสุจิ การตกไข่การมีรอบเดือน และถ้ามีการปฏิสนธิของเซลล์ไข่และเซลล์อสุจิจะทำให้เกิดการตั้งครรภ์'),
  ('ว 1.2', 'ม.2', 22, 'การมีประจำเดือน มีความสัมพันธ์กับการตกไข่โดยเป็นผลจากการเปลี่ยนแปลงของระดับฮอร์โมนเพศหญิง'),
  ('ว 1.2', 'ม.2', 23, 'เมื่อเพศหญิงมีการตกไข่และเซลล์ไข่ได้รับการปฏิสนธิกับเซลล์อสุจิจะทำให้ได้ไซโกตไซโกตจะเจริญเป็นเอ็มบริโอและฟีตัสจนกระทั่งคลอดเป็นทารก แต่ถ้าไม่มีการปฏิสนธิเซลล์ไข่จะสลายตัว ผนังด้านในมดลูกรวมทั้งหลอดเลือดจะสลายตัวและหลุดลอกออก เรียกว่าประจำเดือน'),
  ('ว 1.2', 'ม.2', 24, 'การคุมกำเนิดเป็นวิธีป้องกันไม่ให้เกิดการตั้งครรภ์โดยป้องกันไม่ให้เกิดการปฏิสนธิหรือไม่ให้มีการฝังตัวของเอ็มบริโอ ซึ่งมีหลายวิธี เช่น การใช้ถุงยางอนามัย การกินยาคุมกำเนิด'),
  ('ว 1.2', 'ม.4', 1, 'เยื่อหุ้มเซลล์มีโครงสร้างเป็นเยื่อหุ้มสองชั้นที่มีลิพิดเป็นองค์ประกอบ และมีโปรตีนแทรกอยู่'),
  ('ว 1.2', 'ม.4', 2, 'สารที่ละลายได้ในลิพิดและสารที่มีขนาดเล็กสามารถแพร่ผ่านเยื่อหุ้มเซลล์ได้โดยตรง ส่วนสารขนาดเล็กที่มีประจุต้องลำเลียงผ่านโปรตีนที่แทรกอยู่ที่เยื่อหุ้มเซลล์ ซึ่งมี 2 แบบ คือ การแพร่แบบฟาซิลิเทต และแอกทีฟทรานสปอร์ต ในกรณีสารขนาดใหญ่ เช่น โปรตีน จะลำเลียงเข้าโดยกระบวนการเอนโดไซโทซิส หรือลำเลียงออกโดยกระบวนการเอกโซไซโทซิส'),
  ('ว 1.2', 'ม.4', 3, 'การรักษาดุลยภาพของน้ำและสารในเลือดเกิดจากการทำงานของไต ซึ่งเป็นอวัยวะในระบบขับถ่ายที่มีความสำคัญในการกำจัดของเสียที่มีไนโตรเจนเป็นองค์ประกอบ รวมทั้งน้ำและสารที่มีปริมาณเกินความต้องการของร่างกาย'),
  ('ว 1.2', 'ม.4', 4, 'การรักษาดุลยภาพของกรด-เบสในเลือดเกิดจากการทำงานของไตที่ทำหน้าที่ขับหรือดูดกลับไฮโดรเจนไอออน ไฮโดรเจนคาร์บอเนตไอออนและแอมโมเนียมไอออน และการทำงานของปอดที่ทำหน้าที่กำจัดคาร์บอนไดออกไซด์'),
  ('ว 1.2', 'ม.4', 5, 'การรักษาดุลยภาพของอุณหภูมิภายในร่างกายเกิดจากการทำงานของระบบหมุนเวียนเลือดที่ควบคุมปริมาณเลือดไปที่ผิวหนัง การทำงานของต่อมเหงื่อ และกล้ามเนื้อโครงร่าง ซึ่งส่งผลถึงปริมาณความร้อนที่ถูกเก็บหรือระบายออกจากร่างกาย'),
  ('ว 1.2', 'ม.4', 6, 'เมื่อเชื้อโรคหรือสิ่งแปลกปลอมอื่นเข้าสู่เนื้อเยื่อในร่างกาย ร่างกายจะมีกลไกในการต่อต้านหรือทำลายสิ่งแปลกปลอมทั้งแบบไม่จำเพาะและแบบจำเพาะ'),
  ('ว 1.2', 'ม.4', 7, 'เซลล์เม็ดเลือดขาวกลุ่มฟาโกไซต์จะมีกลไกในการต่อต้านหรือทำลายสิ่งแปลกปลอมแบบไม่จำเพาะ'),
  ('ว 1.2', 'ม.4', 8, 'กลไกในการต่อต้านหรือทำลายสิ่งแปลกปลอมแบบจำเพาะเป็นการทำงานของเซลล์เม็ดเลือดขาวลิมโฟไซต์ชนิดบีและชนิดที ซึ่งเซลล์เม็ดเลือดขาวทั้งสองชนิดจะมีตัวรับแอนติเจน ทำให้เซลล์ทั้งสองสามารถตอบสนองแบบจำเพาะต่อแอนติเจนนั้น ๆ ได้'),
  ('ว 1.2', 'ม.4', 9, 'เซลล์บีทำหน้าที่สร้างแอนติบอดี ซึ่งช่วยในการจับกับสิ่งแปลกปลอมต่าง ๆ เพื่อทำลายต่อไปโดยระบบภูมิคุ้มกัน เซลล์ทีทำหน้าที่หลากหลายเช่น กระตุ้นการทำงานของเซลล์บีและเซลล์ทีชนิดอื่น ทำลายเซลล์ที่ติดไวรัสและเซลล์ที่ผิดปกติอื่น ๆ'),
  ('ว 1.2', 'ม.4', 10, 'บางกรณีร่างกายอาจเกิดความผิดปกติของระบบภูมิคุ้มกัน เช่น ภูมิคุ้มกันตอบสนองต่อแอนติเจนบางชนิดอย่างรุนแรงมากเกินไป หรือร่างกายมีปฏิกิริยาตอบสนองต่อแอนติเจนของตนเองอาจทำให้ร่างกายเกิดอาการผิดปกติได้'),
  ('ว 1.2', 'ม.4', 11, 'บุคคลที่ได้รับเลือดหรือสารคัดหลั่งที่มีเชื้อ HIV ซึ่งสามารถทำลายเซลล์ที ทำให้ภูมิคุ้มกันบกพร่องและติดเชื้อต่าง ๆ ได้ง่ายขึ้น'),
  ('ว 1.2', 'ม.4', 12, 'กระบวนการสังเคราะห์ด้วยแสงเป็นจุดเริ่มต้นของการสร้างน้ำตาลในพืช พืชเปลี่ยนน้ำตาลไปเป็นสารอาหารและสารอื่น ๆ เช่น คาร์โบไฮเดรตโปรตีน ไขมัน ที่จำเป็นต่อการดำรงชีวิตของพืชและสัตว์'),
  ('ว 1.2', 'ม.4', 13, 'มนุษย์สามารถนำสารต่าง ๆ ที่พืชบางชนิดสร้างขึ้นไปใช้ประโยชน์ เช่น ใช้เป็นยาหรือสมุนไพรในการรักษาโรคบางชนิด ใช้ในการไล่แมลง กำจัดศัตรูพืชและสัตว์ ใช้ในการยับยั้งการเจริญเติบโตของแบคทีเรีย และใช้เป็นวัตถุดิบในอุตสาหกรรม'),
  ('ว 1.2', 'ม.4', 14, 'ปัจจัยภายนอกที่มีผลต่อการเจริญเติบโต เช่น แสงน้ำ ธาตุอาหาร คาร์บอนไดออกไซด์ และออกซิเจนปัจจัยภายใน เช่น ฮอร์โมนพืช ซึ่งพืชมีการสังเคราะห์ขึ้น เพื่อควบคุมการเจริญเติบโตในช่วงชีวิตต่าง ๆ'),
  ('ว 1.2', 'ม.4', 15, 'มนุษย์มีการสังเคราะห์สารควบคุมการเจริญเติบโตของพืชโดยเลียนแบบฮอร์โมนพืช เพื่อนำมาใช้ควบคุมการเจริญเติบโตและเพิ่มผลผลิตของพืช'),
  ('ว 1.2', 'ม.4', 16, 'การตอบสนองต่อสิ่งเร้าของพืชแบ่งตามความสัมพันธ์กับทิศทางของสิ่งเร้าได้ ได้แก่ แบบที่มีทิศทางสัมพันธ์กับทิศทางของสิ่งเร้า เช่นดอกทานตะวันหันเข้าหาแสง ปลายรากเจริญเข้าหาแรงโน้มถ่วงของโลก และแบบที่ไม่มีทิศทางสัมพันธ์กับทิศทางของสิ่งเร้า เช่น การหุบและบานของดอก หรือการหุบและกางของใบพืชบางชนิด'),
  ('ว 1.2', 'ม.4', 17, 'การตอบสนองต่อสิ่งเร้าของพืชบางอย่างส่งผลต่อการเจริญเติบโต เช่น การเจริญในทิศทางเข้าหาหรือตรงข้ามกับแรงโน้มถ่วงของโลก การเจริญในทิศทางเข้าหาหรือตรงข้ามกับแสง และการตอบสนองต่อการสัมผัสสิ่งเร้า'),
  ('ว 1.3', 'ป.2', 1, 'สิ่งที่อยู่รอบตัวเรามีทั้งที่เป็นสิ่งมีชีวิตและสิ่งไม่มีชีวิต สิ่งมีชีวิตต้องการอาหาร มีการหายใจเจริญเติบโต ขับถ่าย เคลื่อนไหว ตอบสนองต่อสิ่งเร้าและสืบพันธุ์ได้ลูกที่มีลักษณะคล้ายคลึงกับพ่อแม่ส่วนสิ่งไม่มีชีวิตจะไม่มีลักษณะดังกล่าว'),
  ('ว 1.3', 'ป.4', 1, 'สิ่งมีชีวิตมีหลายชนิด สามารถจัดกลุ่มได้ โดยใช้ความเหมือนและความแตกต่างของลักษณะต่าง ๆ เช่น กลุ่มพืชสร้างอาหารเองได้ และเคลื่อนที่ด้วยตนเองไม่ได้ กลุ่มสัตว์กินสิ่งมีชีวิตอื่นเป็นอาหารและเคลื่อนที่ได้ กลุ่มที่ไม่ใช่พืชและสัตว์ เช่นเห็ด รา จุลินทรีย์'),
  ('ว 1.3', 'ป.4', 2, 'การจำแนกพืช สามารถใช้การมีดอกเป็นเกณฑ์ในการจำแนก ได้เป็นพืชดอกและพืชไม่มีดอก'),
  ('ว 1.3', 'ป.4', 3, 'การจำแนกสัตว์ สามารถใช้การมีกระดูกสันหลังเป็นเกณฑ์ในการจำแนก ได้เป็นสัตว์มีกระดูกสันหลังและสัตว์ไม่มีกระดูกสันหลัง'),
  ('ว 1.3', 'ป.4', 4, 'สัตว์มีกระดูกสันหลังมีหลายกลุ่ม ได้แก่ กลุ่มปลากลุ่มสัตว์สะเทินน้ำสะเทินบก กลุ่มสัตว์เลื้อยคลานกลุ่มนก และกลุ่มสัตว์เลี้ยงลูกด้วยน้ำนม ซึ่งแต่ละกลุ่มจะมีลักษณะเฉพาะที่สังเกตได้'),
  ('ว 1.3', 'ป.5', 1, 'สิ่งมีชีวิตทั้งพืช สัตว์ และมนุษย์ เมื่อโตเต็มที่จะมีการสืบพันธุ์เพื่อเพิ่มจำนวนและดำรงพันธุ์ โดยลูกที่เกิดมาจะได้รับการถ่ายทอดลักษณะทางพันธุกรรมจากพ่อแม่ทำให้มีลักษณะทางพันธุกรรมที่เฉพาะแตกต่างจากสิ่งมีชีวิตชนิดอื่น'),
  ('ว 1.3', 'ป.5', 2, 'พืชมีการถ่ายทอดลักษณะทางพันธุกรรม เช่นลักษณะของใบ สีดอก'),
  ('ว 1.3', 'ป.5', 3, 'สัตว์มีการถ่ายทอดลักษณะทางพันธุกรรม เช่นสีขน ลักษณะของขน ลักษณะของหู'),
  ('ว 1.3', 'ป.5', 4, 'มนุษย์มีการถ่ายทอดลักษณะทางพันธุกรรม เช่นเชิงผมที่หน้าผาก ลักยิ้ม ลักษณะหนังตา การห่อลิ้นลักษณะของติ่งหู'),
  ('ว 1.3', 'ม.3', 1, 'ลักษณะทางพันธุกรรมของสิ่งมีชีวิตสามารถถ่ายทอดจากรุ่นหนึ่งไปยังอีกรุ่นหนึ่งได้ โดยมียีนเป็นหน่วยควบคุมลักษณะทางพันธุกรรม'),
  ('ว 1.3', 'ม.3', 2, 'โครโมโซมประกอบด้วย ดีเอ็นเอ และโปรตีนขดอยู่ในนิวเคลียส ยีน ดีเอ็นเอ และโครโมโซมมีความสัมพันธ์กัน โดยบางส่วนของดีเอ็นเอทำหน้าที่เป็นยีนที่กำหนดลักษณะของสิ่งมีชีวิต'),
  ('ว 1.3', 'ม.3', 3, 'สิ่งมีชีวิตที่มีโครโมโซม 2 ชุด โครโมโซมที่เป็นคู่กันมีการเรียงลำดับของยีนบนโครโมโซมเหมือนกันเรียกว่า ฮอมอโลกัสโครโมโซม ยีนหนึ่งที่อยู่บนคู่ฮอมอโลกัสโครโมโซม อาจมีรูปแบบแตกต่างกัน เรียกแต่ละรูปแบบของยีนที่ต่างกันนี้ว่าแอลลีล ซึ่งการเข้าคู่กันของแอลลีลต่าง ๆ อาจส่งผลทำให้สิ่งมีชีวิตมีลักษณะที่แตกต่างกันได้'),
  ('ว 1.3', 'ม.3', 4, 'สิ่งมีชีวิตแต่ละชนิดมีจำนวนโครโมโซมคงที่ มนุษย์มีจำนวนโครโมโซม 23 คู่ เป็นออโตโซม 22 คู่ และโครโมโซมเพศ 1 คู่ เพศหญิงมีโครโมโซมเพศเป็น XX เพศชายมีโครโมโซมเพศเป็น XY'),
  ('ว 1.3', 'ม.3', 5, 'เมนเดลได้ศึกษาการถ่ายทอดลักษณะทางพันธุกรรมของต้นถั่วชนิดหนึ่ง และนำมาสู่หลักการพื้นฐานของการถ่ายทอดลักษณะทางพันธุกรรมของสิ่งมีชีวิต'),
  ('ว 1.3', 'ม.3', 6, 'สิ่งมีชีวิตที่มีโครโมโซมเป็น 2 ชุด ยีนแต่ละตำแหน่งบนฮอมอโลกัสโครโมโซมมี 2 แอลลีลโดยแอลลีลหนึ่งมาจากพ่อ และอีกแอลลีลมาจากแม่ ซึ่งอาจมีรูปแบบเดียวกัน หรือแตกต่างกันแอลลีลที่แตกต่างกันนี้ แอลลีลหนึ่งอาจมีการแสดงออกข่มอีกแอลลีลหนึ่งได้ เรียกแอลลีลนั้นว่าเป็นแอลลีลเด่น ส่วนแอลลีลที่ถูกข่มอย่างสมบูรณ์เรียกว่าเป็นแอลลีลด้อย'),
  ('ว 1.3', 'ม.3', 7, 'เมื่อมีการสร้างเซลล์สืบพันธุ์ แอลลีลที่เป็นคู่กันในแต่ละฮอมอโลกัสโครโมโซมจะแยกจากกันไปสู่เซลล์สืบพันธุ์แต่ละเซลล์ โดยแต่ละเซลล์สืบพันธุ์จะได้รับเพียง 1 แอลลีล และจะมาเข้าคู่กับแอลลีลที่ตำแหน่งเดียวกันของอีกเซลล์สืบพันธุ์หนึ่งเมื่อเกิดการปฏิสนธิ จนเกิดเป็นจีโนไทป์และแสดงฟีโนไทป์ในรุ่นลูก'),
  ('ว 1.3', 'ม.3', 8, 'กระบวนการแบ่งเซลล์ของสิ่งมีชีวิตมี 2 แบบ คือไมโทซิส และไมโอซิส'),
  ('ว 1.3', 'ม.3', 9, 'ไมโทซิส เป็นการแบ่งเซลล์เพื่อเพิ่มจำนวนเซลล์ร่างกาย ผลจากการแบ่งจะได้เซลล์ใหม่ 2 เซลล์ที่มีลักษณะและจำนวนโครโมโซมเหมือนเซลล์ตั้งต้น'),
  ('ว 1.3', 'ม.3', 10, 'ไมโอซิส เป็นการแบ่งเซลล์เพื่อสร้างเซลล์สืบพันธุ์ผลจากการแบ่งจะได้เซลล์ใหม่ 4 เซลล์ ที่มีจำนวนโครโมโซมเป็นครึ่งหนึ่งของเซลล์ตั้งต้นเมื่อเกิดการปฏิสนธิของเซลล์สืบพันธุ์ ลูกจะได้รับการถ่ายทอดโครโมโซมชุดหนึ่งจากพ่อและอีกชุดหนึ่งจากแม่ จึงเป็นผลให้รุ่นลูกมีจำนวนโครโมโซมเท่ากับรุ่นพ่อแม่และจะคงที่ในทุก ๆ รุ่น'),
  ('ว 1.3', 'ม.3', 11, 'การเปลี่ยนแปลงของยีนหรือโครโมโซม ส่งผลให้เกิดการเปลี่ยนแปลงลักษณะทางพันธุกรรมของสิ่งมีชีวิต เช่น โรคธาลัสซีเมียเกิดจากการเปลี่ยนแปลงของยีน กลุ่มอาการดาวน์เกิดจากการเปลี่ยนแปลงจำนวนโครโมโซม'),
  ('ว 1.3', 'ม.3', 12, 'โรคทางพันธุกรรมสามารถถ่ายทอดจากพ่อแม่ไปสู่ลูกได้ ดังนั้นก่อนแต่งงานและมีบุตรจึงควรป้องกันโดยการตรวจและวินิจฉัยภาวะเสี่ยงจากการถ่ายทอดโรคทางพันธุกรรม'),
  ('ว 1.3', 'ม.3', 13, 'มนุษย์เปลี่ยนแปลงพันธุกรรมของสิ่งมีชีวิตตามธรรมชาติ เพื่อให้ได้สิ่งมีชีวิตที่มีลักษณะตามต้องการ เรียกสิ่งมีชีวิตนี้ว่า สิ่งมีชีวิตดัดแปรพันธุกรรม'),
  ('ว 1.3', 'ม.3', 14, 'ในปัจจุบันมนุษย์มีการใช้ประโยชน์จากสิ่งมีชีวิตดัดแปรพันธุกรรมเป็นจำนวนมาก เช่น การผลิตอาหาร การผลิตยารักษาโรค การเกษตร อย่างไรก็ดีสังคมยังมีความกังวลเกี่ยวกับผลกระทบของสิ่งมีชีวิตดัดแปรพันธุกรรมที่มีต่อสิ่งมีชีวิตและสิ่งแวดล้อม ซึ่งยังทำการติดตามศึกษาผลกระทบดังกล่าว'),
  ('ว 1.3', 'ม.3', 15, 'ความหลากหลายทางชีวภาพ มี 3 ระดับ ได้แก่ความหลากหลายของระบบนิเวศ ความหลากหลายของชนิดสิ่งมีชีวิต และความหลากหลายทางพันธุกรรม ความหลากหลายทางชีวภาพนี้มีความสำคัญต่อการรักษาสมดุลของระบบนิเวศระบบนิเวศที่มีความหลากหลายทางชีวภาพสูงจะรักษาสมดุลได้ดีกว่าระบบนิเวศที่มีความหลากหลายทางชีวภาพต่ำกว่า นอกจากนี้ความหลากหลายทางชีวภาพยังมีความสำคัญต่อมนุษย์ในด้านต่าง ๆ เช่น ใช้เป็นอาหารยารักษาโรค วัตถุดิบในอุตสาหกรรมต่าง ๆ ดังนั้นจึงเป็นหน้าที่ของทุกคนในการดูแลรักษาความหลากหลายทางชีวภาพให้คงอยู่'),
  ('ว 1.3', 'ม.4', 1, 'ดีเอ็นเอ มีโครงสร้างประกอบด้วยนิวคลีโอไทด์มาเรียงต่อกัน โดยยีนเป็นช่วงของสายดีเอ็นเอที่มีลำดับนิวคลีโอไทด์ที่กำหนดลักษณะของโปรตีนที่สังเคราะห์ขึ้น ซึ่งส่งผลให้เกิดลักษณะทางพันธุกรรมต่าง ๆ'),
  ('ว 1.3', 'ม.4', 2, 'ลักษณะบางลักษณะมีโอกาสพบในเพศชายและเพศหญิงไม่เท่ากัน เช่น ตาบอดสี และฮีโมฟีเลียซึ่งควบคุมโดยยีนบนโครโมโซมเพศ บางลักษณะมีการควบคุมโดยยีนแบบมัลติเปิลแอลลีล เช่นหมู่เลือดระบบ ABO ซึ่งการถ่ายทอดลักษณะทางพันธุกรรมดังกล่าวจัดเป็นส่วนขยายของพันธุศาสตร์เมนเดล'),
  ('ว 1.3', 'ม.4', 3, 'มิวเทชันที่เปลี่ยนแปลงลำดับนิวคลีโอไทด์ หรือเปลี่ยนแปลงโครงสร้างหรือจำนวนโครโมโซมอาจส่งผลทำให้ลักษณะของสิ่งมีชีวิตเปลี่ยนแปลงไปจากเดิม ซึ่งอาจมีผลดีหรือผลเสีย'),
  ('ว 1.3', 'ม.4', 4, 'มนุษย์ใช้หลักการของการเกิดมิวเทชันในการชักนำให้ได้สิ่งมีชีวิตที่มีลักษณะที่แตกต่างจากเดิมโดยการใช้รังสีและสารเคมีต่าง ๆ'),
  ('ว 1.3', 'ม.4', 5, 'มนุษย์นำความรู้เทคโนโลยีทางดีเอ็นเอมาประยุกต์ใช้ทางด้านการแพทย์ และเภสัชกรรมเช่น การสร้างสิ่งมีชีวิตดัดแปรพันธุกรรม เพื่อผลิตยาและวัคซีน ด้านการเกษตร เช่น พืชดัดแปรพันธุกรรมที่ต้านทานโรคหรือแมลง สัตว์ดัดแปรพันธุกรรมที่มีลักษณะตามที่ต้องการ และด้านนิติวิทยาศาสตร์ เช่น การตรวจลายพิมพ์ดีเอ็นเอเพื่อหาความสัมพันธ์ทางสายเลือด หรือเพื่อหาผู้กระทำผิด'),
  ('ว 1.3', 'ม.4', 6, 'การใช้เทคโนโลยีทางดีเอ็นเอในด้านต่าง ๆ ต้องคำนึงถึงความปลอดภัยทางชีวภาพ ชีวจริยธรรมและผลกระทบทางด้านสังคม'),
  ('ว 1.3', 'ม.4', 7, 'สิ่งมีชีวิตที่มีอยู่ในปัจจุบันมีลักษณะที่ปรากฏให้เห็นแตกต่างกันซึ่งเป็นผลมาจากความหลากหลายของลักษณะทางพันธุกรรม ซึ่งเกิดจากมิวเทชันร่วมกับการคัดเลือกโดยธรรมชาติ'),
  ('ว 1.3', 'ม.4', 8, 'ผลจากกระบวนการคัดเลือกโดยธรรมชาติ ทำให้สิ่งมีชีวิตที่มีลักษณะเหมาะสมในการดำรงชีวิตสามารถปรับตัวให้อยู่รอดได้ในสิ่งแวดล้อมนั้น ๆ'),
  ('ว 1.3', 'ม.4', 9, 'กระบวนการคัดเลือกโดยธรรมชาติเป็นหลักการที่สำคัญอย่างหนึ่งที่ทำให้เกิดวิวัฒนาการของสิ่งมีชีวิต'),
  ('ว 2.1', 'ป.1', 1, 'วัสดุที่ใช้ทำวัตถุที่เป็นของเล่น ของใช้ มีหลายชนิดเช่น ผ้า แก้ว พลาสติก ยาง ไม้ อิฐ หิน กระดาษโลหะ วัสดุแต่ละชนิดมีสมบัติที่สังเกตได้ต่าง ๆ เช่น สี นุ่ม แข็ง ขรุขระ เรียบ ใส ขุ่น ยืดหดได้บิดงอได้'),
  ('ว 2.1', 'ป.1', 2, 'สมบัติที่สังเกตได้ของวัสดุแต่ละชนิดอาจเหมือนกันซึ่งสามารถนำมาใช้เป็นเกณฑ์ในการจัดกลุ่มวัสดุได้'),
  ('ว 2.1', 'ป.1', 3, 'วัสดุบางอย่างสามารถนำมาประกอบกัน เพื่อทำเป็นวัตถุต่าง ๆ เช่น ผ้าและกระดุม ใช้ทำเสื้อไม้และโลหะ ใช้ทำกระทะ'),
  ('ว 2.1', 'ป.2', 1, 'วัสดุแต่ละชนิดมีสมบัติการดูดซับน้ำแตกต่างกันจึงนำไปทำวัตถุเพื่อใช้ประโยชน์ได้แตกต่างกัน เช่นใช้ผ้าที่ดูดซับน้ำได้มากทำผ้าเช็ดตัว ใช้พลาสติกซึ่งไม่ดูดซับน้ำทำร่ม'),
  ('ว 2.1', 'ป.2', 2, 'วัสดุบางอย่างสามารถนำมาผสมกันซึ่งทำให้ได้สมบัติที่เหมาะสม เพื่อนำไปใช้ประโยชน์ตามต้องการ เช่น แป้งผสมน้ำตาลและกะทิ ใช้ทำขนมไทย ปูนปลาสเตอร์ผสมเยื่อกระดาษใช้ทำกระปุกออมสิน ปูนผสมหิน ทราย และน้ำใช้ทำคอนกรีต'),
  ('ว 2.1', 'ป.2', 3, 'การนำวัสดุมาทำเป็นวัตถุในการใช้งานตามวัตถุประสงค์ขึ้นอยู่กับสมบัติของวัสดุ วัสดุที่ใช้แล้วอาจนำกลับมาใช้ใหม่ได้ เช่น กระดาษใช้แล้วอาจนำมาทำเป็นจรวดกระดาษ ดอกไม้ประดิษฐ์ถุงใส่ของ'),
  ('ว 2.1', 'ป.3', 1, 'วัตถุอาจทำจากชิ้นส่วนย่อย ๆ ซึ่งแต่ละชิ้นมีลักษณะเหมือนกันมาประกอบเข้าด้วยกัน เมื่อแยกชิ้นส่วนย่อย ๆ แต่ละชิ้นของวัตถุออกจากกันสามารถนำชิ้นส่วนเหล่านั้นมาประกอบเป็นวัตถุชิ้นใหม่ได้ เช่น กำแพงบ้านมีก้อนอิฐหลาย ๆ ก้อนประกอบเข้าด้วยกัน และสามารถนำก้อนอิฐจากกำแพงบ้านมาประกอบเป็นพื้นทางเดินได้'),
  ('ว 2.1', 'ป.3', 2, 'เมื่อให้ความร้อนหรือทำให้วัสดุร้อนขึ้น และเมื่อลดความร้อนหรือทำให้วัสดุเย็นลง วัสดุจะเกิดการเปลี่ยนแปลงได้ เช่น สีเปลี่ยน รูปร่างเปลี่ยน'),
  ('ว 2.1', 'ป.4', 1, 'วัสดุแต่ละชนิดมีสมบัติทางกายภาพแตกต่างกันวัสดุที่มีความแข็งจะทนต่อแรงขูดขีด วัสดุที่มีสภาพยืดหยุ่นจะเปลี่ยนแปลงรูปร่างเมื่อมีแรงมากระทำและกลับสภาพเดิมได้ วัสดุที่นำความร้อนจะร้อนได้เร็วเมื่อได้รับความร้อนและวัสดุที่นำไฟฟ้าได้ จะให้กระแสไฟฟ้าผ่านได้ดังนั้นจึงอาจนำสมบัติต่าง ๆ มาพิจารณาเพื่อใช้ในกระบวนการออกแบบชิ้นงานเพื่อใช้ประโยชน์ในชีวิตประจำวัน'),
  ('ว 2.1', 'ป.4', 2, 'วัสดุเป็นสสารเพราะมีมวลและต้องการที่อยู่สสารมีสถานะเป็นของแข็ง ของเหลว หรือแก๊สของแข็ง มีปริมาตรและรูปร่างคงที่ ของเหลวมีปริมาตรคงที่ แต่มีรูปร่างเปลี่ยนไปตามภาชนะเฉพาะส่วนที่บรรจุของเหลว ส่วนแก๊สมีปริมาตรและรูปร่างเปลี่ยนไปตามภาชนะที่บรรจุ'),
  ('ว 2.1', 'ป.5', 1, 'การเปลี่ยนสถานะของสสารเป็นการเปลี่ยนแปลงทางกายภาพ เมื่อเพิ่มความร้อนให้กับสสารถึงระดับหนึ่งจะทำให้สสารที่เป็นของแข็งเปลี่ยนสถานะเป็นของเหลว เรียกว่า การหลอมเหลวและเมื่อเพิ่มความร้อนต่อไปจนถึงอีกระดับหนึ่งของเหลวจะเปลี่ยนเป็นแก๊ส เรียกว่าการกลายเป็นไอ แต่เมื่อลดความร้อนลงถึงระดับหนึ่งแก๊สจะเปลี่ยนสถานะเป็นของเหลว เรียกว่าการควบแน่น และถ้าลดความร้อนต่อไปอีกจนถึงระดับหนึ่งของเหลวจะเปลี่ยนสถานะเป็นของแข็งเรียกว่า การแข็งตัว สสารบางชนิดสามารถเปลี่ยนสถานะจากของแข็งเป็นแก๊สโดยไม่ผ่านการเป็นของเหลว เรียกว่า การระเหิด ส่วนแก๊สบางชนิดสามารถเปลี่ยนสถานะเป็นของแข็งโดยไม่ผ่านการเป็นของเหลว เรียกว่า การระเหิดกลับ'),
  ('ว 2.1', 'ป.5', 2, 'เมื่อใส่สารลงในน้ำแล้วสารนั้นรวมเป็นเนื้อเดียวกันกับน้ำทั่วทุกส่วน แสดงว่าสารเกิดการละลาย เรียกสารผสมที่ได้ว่าสารละลาย'),
  ('ว 2.1', 'ป.5', 3, 'เมื่อผสมสาร 2 ชนิดขึ้นไปแล้วมีสารใหม่เกิดขึ้นซึ่งมีสมบัติต่างจากสารเดิมหรือเมื่อสารชนิดเดียวเกิดการเปลี่ยนแปลงแล้วมีสารใหม่เกิดขึ้นการเปลี่ยนแปลงนี้เรียกว่า การเปลี่ยนแปลงทางเคมี ซึ่งสังเกตได้จากมีสีหรือกลิ่นต่างจากสารเดิม หรือมีฟองแก๊ส หรือมีตะกอนเกิดขึ้นหรือมีการเพิ่มขึ้นหรือลดลงของอุณหภูมิ'),
  ('ว 2.1', 'ป.5', 4, 'เมื่อสารเกิดการเปลี่ยนแปลงแล้ว สารสามารถเปลี่ยนกลับเป็นสารเดิมได้ เป็นการเปลี่ยนแปลงที่ผันกลับได้ เช่น การหลอมเหลว การกลายเป็นไอการละลาย แต่สารบางอย่างเกิดการเปลี่ยนแปลงแล้วไม่สามารถเปลี่ยนกลับเป็นสารเดิมได้เป็นการเปลี่ยนแปลงที่ผันกลับไม่ได้ เช่นการเผาไหม้ การเกิดสนิม'),
  ('ว 2.1', 'ป.6', 1, 'สารผสมประกอบด้วยสารตั้งแต่ 2 ชนิดขึ้นไปผสมกันเช่น น้ำมันผสมน้ำ ข้าวสารปนกรวดทราย วิธีการที่เหมาะสมในการแยกสารผสมขึ้นอยู่กับลักษณะและสมบัติของสารที่ผสมกัน ถ้าองค์ประกอบของสารผสมเป็นของแข็งกับของแข็งที่มีขนาดแตกต่างกันอย่างชัดเจน อาจใช้วิธีการหยิบออกหรือการร่อนผ่านวัสดุที่มีรู ถ้ามีสารใดสารหนึ่งเป็นสารแม่เหล็กอาจใช้วิธีการใช้แม่เหล็กดึงดูดถ้าองค์ประกอบเป็นของแข็งที่ไม่ละลายในของเหลว อาจใช้วิธีการรินออก การกรอง หรือการตกตะกอน ซึ่งวิธีการแยกสารสามารถนำไปใช้ประโยชน์ในชีวิตประจำวันได้'),
  ('ว 2.1', 'ม.1', 1, 'ธาตุแต่ละชนิดมีสมบัติเฉพาะตัวและมีสมบัติทางกายภาพบางประการเหมือนกันและบางประการต่างกัน ซึ่งสามารถนำมาจัดกลุ่มธาตุเป็นโลหะ อโลหะ และกึ่งโลหะ ธาตุโลหะมีจุดเดือดจุดหลอมเหลวสูง มีผิวมันวาว นำความร้อนนำไฟฟ้า ดึงเป็นเส้นหรือตีเป็นแผ่นบาง ๆ ได้ และมีความหนาแน่นทั้งสูงและต่ำ ธาตุอโลหะมีจุดเดือด จุดหลอมเหลวต่ำ มีผิวไม่มันวาวไม่นำความร้อน ไม่นำไฟฟ้า เปราะ แตกหักง่ายและมีความหนาแน่นต่ำ ธาตุกึ่งโลหะมีสมบัติบางประการเหมือนโลหะ และสมบัติบางประการเหมือนอโลหะ'),
  ('ว 2.1', 'ม.1', 2, 'ธาตุโลหะ อโลหะ และกึ่งโลหะ ที่สามารถแผ่รังสีได้จัดเป็นธาตุกัมมันตรังสี'),
  ('ว 2.1', 'ม.1', 3, 'ธาตุมีทั้งประโยชน์และโทษ การใช้ธาตุโลหะอโลหะ กึ่งโลหะ ธาตุกัมมันตรังสี ควรคำนึงถึงผลกระทบต่อสิ่งมีชีวิต สิ่งแวดล้อม เศรษฐกิจและสังคม'),
  ('ว 2.1', 'ม.1', 4, 'สารบริสุทธิ์ประกอบด้วยสารเพียงชนิดเดียวส่วนสารผสมประกอบด้วยสารตั้งแต่ 2 ชนิดขึ้นไป สารบริสุทธิ์แต่ละชนิดมีสมบัติบางประการที่เป็นค่าเฉพาะตัว เช่น จุดเดือดและจุดหลอมเหลวคงที่ แต่สารผสมมีจุดเดือดและจุดหลอมเหลวไม่คงที่ ขึ้นอยู่กับชนิดและสัดส่วนของสารที่ผสมอยู่ด้วยกัน'),
  ('ว 2.1', 'ม.1', 5, 'สารบริสุทธิ์แต่ละชนิดมีความหนาแน่น หรือมวลต่อหนึ่งหน่วยปริมาตรคงที่ เป็นค่าเฉพาะของสารนั้น ณ สถานะและอุณหภูมิหนึ่งแต่สารผสมมีความหนาแน่นไม่คงที่ขึ้นอยู่กับชนิดและสัดส่วนของสารที่ผสมอยู่ด้วยกัน'),
  ('ว 2.1', 'ม.1', 6, 'สารบริสุทธิ์แบ่งออกเป็นธาตุและสารประกอบธาตุประกอบด้วยอนุภาคที่เล็กที่สุดที่ยังแสดงสมบัติของธาตุนั้นเรียกว่า อะตอม ธาตุแต่ละชนิดประกอบด้วยอะตอมเพียงชนิดเดียวและไม่สามารถแยกสลายเป็นสารอื่นได้ด้วยวิธีทางเคมีธาตุเขียนแทนด้วยสัญลักษณ์ธาตุ สารประกอบเกิดจากอะตอมของธาตุตั้งแต่ 2 ชนิดขึ้นไปรวมตัวกันทางเคมีในอัตราส่วนคงที่ มีสมบัติแตกต่างจากธาตุที่เป็นองค์ประกอบ สามารถแยกเป็นธาตุได้ด้วยวิธีทางเคมี ธาตุและสารประกอบสามารถเขียนแทนได้ด้วยสูตรเคมี'),
  ('ว 2.1', 'ม.1', 7, 'อะตอมประกอบด้วยโปรตอน นิวตรอน และอิเล็กตรอน โปรตอนมีประจุไฟฟ้าบวก ธาตุชนิดเดียวกันมีจำนวนโปรตอนเท่ากันและเป็นค่าเฉพาะของธาตุนั้น นิวตรอนเป็นกลางทางไฟฟ้าส่วนอิเล็กตรอนมีประจุไฟฟ้าลบ เมื่ออะตอมมีจำนวนโปรตอนเท่ากับจำนวนอิเล็กตรอนจะเป็นกลางทางไฟฟ้า โปรตอนและนิวตรอนรวมกันตรงกลางอะตอมเรียกว่า นิวเคลียสส่วนอิเล็กตรอนเคลื่อนที่อยู่ในที่ว่างรอบนิวเคลียส'),
  ('ว 2.1', 'ม.1', 8, 'สสารทุกชนิดประกอบด้วยอนุภาค โดยสารชนิดเดียวกันที่มีสถานะของแข็ง ของเหลว แก๊สจะมีการจัดเรียงอนุภาค แรงยึดเหนี่ยวระหว่างอนุภาค การเคลื่อนที่ของอนุภาคแตกต่างกันซึ่งมีผลต่อรูปร่างและปริมาตรของสสาร'),
  ('ว 2.1', 'ม.1', 9, 'อนุภาคของของแข็งเรียงชิดกัน มีแรงยึดเหนี่ยวระหว่างอนุภาคมากที่สุด อนุภาคสั่นอยู่กับที่ทำให้มีรูปร่างและปริมาตรคงที่'),
  ('ว 2.1', 'ม.1', 10, 'อนุภาคของของเหลวอยู่ใกล้กัน มีแรงยึดเหนี่ยวระหว่างอนุภาคน้อยกว่าของแข็งแต่มากกว่าแก๊สอนุภาคเคลื่อนที่ได้แต่ไม่เป็นอิสระเท่าแก๊ส ทำให้มีรูปร่างไม่คงที่ แต่ปริมาตรคงที่'),
  ('ว 2.1', 'ม.1', 11, 'อนุภาคของแก๊สอยู่ห่างกันมาก มีแรงยึดเหนี่ยวระหว่างอนุภาคน้อยที่สุด อนุภาคเคลื่อนที่ได้อย่างอิสระทุกทิศทาง ทำให้มีรูปร่างและปริมาตรไม่คงที่'),
  ('ว 2.1', 'ม.1', 12, 'ความร้อนมีผลต่อการเปลี่ยนสถานะของสสารเมื่อให้ความร้อนแก่ของแข็ง อนุภาคของของแข็งจะมีพลังงานและอุณหภูมิเพิ่มขึ้นจนถึงระดับหนึ่งซึ่งของแข็งจะใช้ความร้อนในการเปลี่ยนสถานะเป็นของเหลว เรียกความร้อนที่ใช้ในการเปลี่ยนสถานะจากของแข็งเป็นของเหลวว่า ความร้อนแฝงของการหลอมเหลว และอุณหภูมิขณะเปลี่ยนสถานะจะคงที่ เรียกอุณหภูมินี้ว่าจุดหลอมเหลว'),
  ('ว 2.1', 'ม.1', 13, 'เมื่อให้ความร้อนแก่ของเหลว อนุภาคของของเหลวจะมีพลังงานและอุณหภูมิเพิ่มขึ้นจนถึงระดับหนึ่งซึ่งของเหลวจะใช้ความร้อนในการเปลี่ยนสถานะเป็นแก๊ส เรียกความร้อนที่ใช้ในการเปลี่ยนสถานะจากของเหลวเป็นแก๊สว่า ความร้อนแฝงของการกลายเป็นไอ และอุณหภูมิขณะเปลี่ยนสถานะจะคงที่ เรียกอุณหภูมินี้ว่า จุดเดือด'),
  ('ว 2.1', 'ม.1', 14, 'เมื่อทำให้อุณหภูมิของแก๊สลดลงจนถึงระดับหนึ่งแก๊สจะเปลี่ยนสถานะเป็นของเหลว เรียกอุณหภูมินี้ว่า จุดควบแน่น ซึ่งมีอุณหภูมิเดียวกับจุดเดือดของของเหลวนั้น'),
  ('ว 2.1', 'ม.1', 15, 'เมื่อทำให้อุณหภูมิของของเหลวลดลงจนถึงระดับหนึ่ง ของเหลวจะเปลี่ยนสถานะเป็นของแข็งเรียกอุณหภูมินี้ว่า จุดเยือกแข็ง ซึ่งมีอุณหภูมิเดียวกับจุดหลอมเหลวของของแข็งนั้น'),
  ('ว 2.1', 'ม.2', 1, 'การแยกสารผสมให้เป็นสารบริสุทธิ์ทำได้หลายวิธีขึ้นอยู่กับสมบัติของสารนั้น ๆ การระเหยแห้งใช้แยกสารละลายซึ่งประกอบด้วยตัวละลายที่เป็นของแข็งในตัวทำละลายที่เป็นของเหลว โดยใช้ความร้อนระเหยตัวทำละลายออกไปจนหมดเหลือแต่ตัวละลาย การตกผลึกใช้แยกสารละลายที่ประกอบด้วยตัวละลายที่เป็นของแข็งในตัวทำละลายที่เป็นของเหลว โดยทำให้สารละลายอิ่มตัวแล้วปล่อยให้ตัวทำละลายระเหยออกไปบางส่วนตัวละลายจะตกผลึกแยกออกมา การกลั่นอย่างง่ายใช้แยกสารละลายที่ประกอบด้วยตัวละลายและตัวทำละลายที่เป็นของเหลวที่มีจุดเดือดต่างกันมาก วิธีนี้จะแยกของเหลวบริสุทธิ์ออกจากสารละลายโดยให้ความร้อนกับสารละลายของเหลวจะเดือดและกลายเป็นไอแยกจากสารละลายแล้วควบแน่นกลับเป็นของเหลวอีกครั้ง ขณะที่ของเหลวเดือด อุณหภูมิของไอจะคงที่ โครมาโทกราฟีแบบกระดาษเป็นวิธีการแยกสารผสมที่มีปริมาณน้อยโดยใช้แยกสารที่มีสมบัติการละลายในตัวทำละลายและการถูกดูดซับด้วยตัวดูดซับแตกต่างกัน ทำให้สารแต่ละชนิดเคลื่อนที่ไปบนตัวดูดซับได้ต่างกัน สารจึงแยกออกจากกันได้ อัตราส่วนระหว่างระยะทางที่สารองค์ประกอบแต่ละชนิดเคลื่อนที่ได้บนตัวดูดซับกับระยะทางที่ตัวทำละลายเคลื่อนที่ได้ เป็นค่าเฉพาะตัวของสารแต่ละชนิดในตัวทำละลายและตัวดูดซับหนึ่ง ๆ การสกัดด้วยตัวทำละลายเป็นวิธีการแยกสารผสมที่มีสมบัติการละลายในตัวทำละลายที่ต่างกัน โดยชนิดของตัวทำละลายมีผลต่อชนิดและปริมาณของสารที่สกัดได้การสกัดโดยการกลั่นด้วยไอน้ำ ใช้แยกสารที่ระเหยง่าย ไม่ละลายน้ำ และไม่ทำปฏิกิริยากับน้ำออกจากสารที่ระเหยยาก โดยใช้ไอน้ำเป็นตัวพา'),
  ('ว 2.1', 'ม.2', 2, 'ความรู้ด้านวิทยาศาสตร์เกี่ยวกับการแยกสารบูรณาการกับคณิตศาสตร์ เทคโนโลยี โดยใช้กระบวนการทางวิศวกรรม สามารถนำไปใช้แก้ปัญหาในชีวิตประจำวันหรือปัญหาที่พบในชุมชนหรือสร้างนวัตกรรม โดยมีขั้นตอน ดังนี้ - ระบุปัญหาในชีวิตประจำวันที่เกี่ยวกับการแยกสารโดยใช้สมบัติทางกายภาพ หรือนวัตกรรมที่ต้องการพัฒนา โดยใช้หลักการดังกล่าว - รวบรวมข้อมูลและแนวคิดเกี่ยวกับการแยกสารโดยใช้สมบัติทางกายภาพที่สอดคล้องกับปัญหาที่ระบุ หรือนำไปสู่การพัฒนานวัตกรรมนั้น - ออกแบบวิธีการแก้ปัญหา หรือพัฒนานวัตกรรมที่เกี่ยวกับการแยกสารในสารผสม โดยใช้สมบัติทางกายภาพ โดยเชื่อมโยงความรู้ด้านวิทยาศาสตร์ คณิตศาสตร์ เทคโนโลยี และกระบวนการทางวิศวกรรม รวมทั้งกำหนดและควบคุมตัวแปรอย่างเหมาะสม ครอบคลุม - วางแผนและดำเนินการแก้ปัญหา หรือพัฒนานวัตกรรม รวบรวมข้อมูล จัดกระทำข้อมูลและเลือกวิธีการสื่อความหมายที่เหมาะสมในการนำเสนอผล - ทดสอบ ประเมินผล ปรับปรุงวิธีการแก้ปัญหาหรือนวัตกรรมที่พัฒนาขึ้น โดยใช้หลักฐานเชิงประจักษ์ที่รวบรวมได้ - นำเสนอวิธีการแก้ปัญหา หรือผลของนวัตกรรมที่พัฒนาขึ้น และผลที่ได้ โดยใช้วิธีการสื่อสารที่เหมาะสมและน่าสนใจ'),
  ('ว 2.1', 'ม.2', 3, 'สารละลายอาจมีสถานะเป็นของแข็ง ของเหลวและแก๊ส สารละลายประกอบด้วยตัวทำละลายและตัวละลาย กรณีสารละลายเกิดจากสารที่มีสถานะเดียวกัน สารที่มีปริมาณมากที่สุดจัดเป็นตัวทำละลาย กรณีสารละลายเกิดจากสารที่มีสถานะต่างกัน สารที่มีสถานะเดียวกันกับสารละลายจัดเป็นตัวทำละลาย'),
  ('ว 2.1', 'ม.2', 4, 'สารละลายที่ตัวละลายไม่สามารถละลายในตัวทำละลายได้อีกที่อุณหภูมิหนึ่ง ๆ เรียกว่าสารละลายอิ่มตัว'),
  ('ว 2.1', 'ม.2', 5, 'สภาพละลายได้ของสารในตัวทำละลาย เป็นค่าที่บอกปริมาณของสารที่ละลายได้ในตัวทำละลาย100 กรัม จนได้สารละลายอิ่มตัว ณ อุณหภูมิและความดันหนึ่ง ๆ สภาพละลายได้ของสารบ่งบอกความสามารถในการละลายได้ของตัวละลายในตัวทำละลาย ซึ่งความสามารถในการละลายของสารขึ้นอยู่กับชนิดของตัวทำละลายและตัวละลาย อุณหภูมิ และความดัน'),
  ('ว 2.1', 'ม.2', 6, 'สารชนิดหนึ่ง ๆ มีสภาพละลายได้แตกต่างกันในตัวทำละลายที่แตกต่างกัน และสารต่างชนิดกันมีสภาพละลายได้ในตัวทำละลายหนึ่ง ๆ ไม่เท่ากัน'),
  ('ว 2.1', 'ม.2', 7, 'เมื่ออุณหภูมิสูงขึ้น สารส่วนมาก สภาพละลายได้ของสารจะเพิ่มขึ้น ยกเว้นแก๊สเมื่ออุณหภูมิสูงขึ้นสภาพการละลายได้จะลดลง ส่วนความดันมีผลต่อแก๊ส โดยเมื่อความดันเพิ่มขึ้น สภาพละลายได้จะสูงขึ้น'),
  ('ว 2.1', 'ม.2', 8, 'ความรู้เกี่ยวกับสภาพละลายได้ของสาร เมื่อเปลี่ยนแปลงชนิดตัวละลาย ตัวทำละลาย และอุณหภูมิ สามารถนำไปใช้ประโยชน์ในชีวิตประจำวันเช่น การทำน้ำเชื่อมเข้มข้น การสกัดสารออกจากสมุนไพรให้ได้ปริมาณมากที่สุด'),
  ('ว 2.1', 'ม.2', 9, 'ความเข้มข้นของสารละลาย เป็นการระบุปริมาณตัวละลายในสารละลาย หน่วยความเข้มข้นมีหลายหน่วย ที่นิยมระบุเป็นหน่วยเป็นร้อยละปริมาตรต่อปริมาตร มวลต่อมวล และมวลต่อปริมาตร'),
  ('ว 2.1', 'ม.2', 10, 'ร้อยละโดยปริมาตรต่อปริมาตร เป็นการระบุปริมาตรตัวละลายในสารละลาย 100 หน่วยปริมาตรเดียวกัน นิยมใช้กับสารละลายที่เป็นของเหลวหรือแก๊ส'),
  ('ว 2.1', 'ม.2', 11, 'ร้อยละโดยมวลต่อมวล เป็นการระบุมวลตัวละลายในสารละลาย 100 หน่วยมวลเดียวกันนิยมใช้กับสารละลายที่มีสถานะเป็นของแข็ง'),
  ('ว 2.1', 'ม.2', 12, 'ร้อยละโดยมวลต่อปริมาตร เป็นการระบุมวลตัวละลายในสารละลาย 100 หน่วยปริมาตรนิยมใช้กับสารละลายที่มีตัวละลายเป็นของแข็งในตัวทำละลายที่เป็นของเหลว'),
  ('ว 2.1', 'ม.2', 13, 'การใช้สารละลาย ในชีวิตประจำวัน ควรพิจารณาจากความเข้มข้นของสารละลาย ขึ้นอยู่กับจุดประสงค์ของการใช้งาน และผลกระทบต่อสิ่งชีวิตและสิ่งแวดล้อม'),
  ('ว 2.1', 'ม.3', 1, 'พอลิเมอร์ เซรามิก และวัสดุผสม เป็นวัสดุที่ใช้มากในชีวิตประจำวัน'),
  ('ว 2.1', 'ม.3', 2, 'พอลิเมอร์เป็นสารประกอบโมเลกุลใหญ่ที่เกิดจากโมเลกุลจำนวนมากรวมตัวกันทางเคมีเช่น พลาสติก ยาง เส้นใย ซึ่งเป็นพอลิเมอร์ที่มีสมบัติแตกต่างกัน โดยพลาสติกเป็นพอลิเมอร์ที่ขึ้นรูปเป็นรูปทรงต่าง ๆ ได้ ยางยืดหยุ่นได้ส่วนเส้นใยเป็นพอลิเมอร์ที่สามารถดึงเป็นเส้นยาวได้พอลิเมอร์จึงใช้ประโยชน์ได้แตกต่างกัน'),
  ('ว 2.1', 'ม.3', 3, 'เซรามิกเป็นวัสดุที่ผลิตจาก ดิน หิน ทราย และแร่ธาตุต่าง ๆ จากธรรมชาติ และส่วนมากจะผ่านการเผาที่อุณหภูมิสูง เพื่อให้ได้เนื้อสารที่แข็งแรงเซรามิกสามารถทำเป็นรูปทรงต่าง ๆ ได้ สมบัติทั่วไปของเซรามิกจะแข็ง ทนต่อการสึกกร่อนและเปราะ สามารถนำไปใช้ประโยชน์ได้ เช่นภาชนะที่เป็นเครื่องปั้นดินเผา ชิ้นส่วนอิเล็กทรอนิกส์'),
  ('ว 2.1', 'ม.3', 4, 'วัสดุผสมเป็นวัสดุที่เกิดจากวัสดุตั้งแต่ 2 ประเภทที่มีสมบัติแตกต่างกันมารวมตัวกัน เพื่อนำไปใช้ประโยชน์ได้มากขึ้น เช่น เสื้อกันฝนบางชนิดเป็นวัสดุผสมระหว่างผ้ากับยาง คอนกรีตเสริมเหล็กเป็นวัสดุผสมระหว่างคอนกรีตกับเหล็ก'),
  ('ว 2.1', 'ม.3', 5, 'วัสดุบางชนิดสลายตัวยาก เช่น พลาสติก การใช้วัสดุอย่างฟุ่มเฟือยและไม่ระมัดระวังอาจก่อปัญหาต่อสิ่งแวดล้อม'),
  ('ว 2.1', 'ม.3', 6, 'การเกิดปฏิกิริยาเคมีหรือการเปลี่ยนแปลงทางเคมีของสาร เป็นการเปลี่ยนแปลงที่ทำให้เกิดสารใหม่ โดยสารที่เข้าทำปฏิกิริยา เรียกว่า สารตั้งต้นสารใหม่ที่เกิดขึ้นจากปฏิกิริยา เรียกว่า ผลิตภัณฑ์การเกิดปฏิกิริยาเคมีสามารถเขียนแทนได้ด้วยสมการข้อความ'),
  ('ว 2.1', 'ม.3', 7, 'การเกิดปฏิกิริยาเคมี อะตอมของสารตั้งต้นจะมีการจัดเรียงตัวใหม่ ได้เป็นผลิตภัณฑ์ ซึ่งมีสมบัติแตกต่างจากสารตั้งต้น โดยอะตอมแต่ละชนิดก่อนและหลังเกิดปฏิกิริยาเคมีมีจำนวนเท่ากัน'),
  ('ว 2.1', 'ม.3', 8, 'เมื่อเกิดปฏิกิริยาเคมี มวลรวมของสารตั้งต้นเท่ากับมวลรวมของผลิตภัณฑ์ ซึ่งเป็นไปตามกฎทรงมวล'),
  ('ว 2.1', 'ม.3', 9, 'เมื่อเกิดปฏิกิริยาเคมี มีการถ่ายโอนความร้อนควบคู่ไปกับการจัดเรียงตัวใหม่ของอะตอมของสารปฏิกิริยาที่มีการถ่ายโอนความร้อนจากสิ่งแวดล้อมเข้าสู่ระบบเป็นปฏิกิริยาดูดความร้อน ปฏิกิริยาที่มีการถ่ายโอนความร้อนจากระบบออกสู่สิ่งแวดล้อมเป็นปฏิกิริยาคายความร้อน โดยใช้เครื่องมือที่เหมาะสมในการวัดอุณหภูมิ เช่นเทอร์มอมิเตอร์ หัววัดที่สามารถตรวจสอบการเปลี่ยนแปลงของอุณหภูมิได้อย่างต่อเนื่อง'),
  ('ว 2.1', 'ม.3', 10, 'ปฏิกิริยาเคมีที่พบในชีวิตประจำวันมีหลายชนิดเช่น ปฏิกิริยาการเผาไหม้ การเกิดสนิมของเหล็กปฏิกิริยาของกรดกับโลหะ ปฏิกิริยาของกรดกับเบส ปฏิกิริยาของเบสกับโลหะ การเกิดฝนกรดการสังเคราะห์ด้วยแสง ปฏิกิริยาเคมีสามารถเขียนแทนได้ด้วยสมการข้อความ ซึ่งแสดงชื่อของสารตั้งต้นและผลิตภัณฑ์ เช่นเชื้อเพลิง + ออกซิเจน คาร์บอนไดออกไซด์ + น้ำ → ปฏิกิริยาการเผาไหม้เป็นปฏิกิริยาระหว่างสารกับออกซิเจน สารที่เกิดปฏิกิริยาการเผาไหม้ส่วนใหญ่เป็นสารประกอบที่มีคาร์บอนและไฮโดรเจนเป็นองค์ประกอบ ซึ่งถ้าเกิดการเผาไหม้อย่างสมบูรณ์ จะได้ผลิตภัณฑ์เป็นคาร์บอนไดออกไซด์และน้ำ'),
  ('ว 2.1', 'ม.3', 11, 'การเกิดสนิมของเหล็ก เกิดจากปฏิกิริยาเคมีระหว่างเหล็ก น้ำ และออกซิเจน ได้ผลิตภัณฑ์เป็นสนิมของเหล็ก'),
  ('ว 2.1', 'ม.3', 12, 'ปฏิกิริยาการเผาไหม้และการเกิดสนิมของเหล็กเป็นปฏิกิริยาระหว่างสารต่าง ๆ กับออกซิเจน'),
  ('ว 2.1', 'ม.3', 13, 'ปฏิกิริยาของกรดกับโลหะ กรดทำปฏิกิริยากับโลหะได้หลายชนิด ได้ผลิตภัณฑ์เป็นเกลือของโลหะและแก๊สไฮโดรเจน'),
  ('ว 2.1', 'ม.3', 14, 'ปฏิกิริยาของกรดกับสารประกอบคาร์บอเนตได้ผลิตภัณฑ์เป็นแก๊สคาร์บอนไดออกไซด์เกลือของโลหะ และน้ำ'),
  ('ว 2.1', 'ม.3', 15, 'ปฏิกิริยาของกรดกับเบส ได้ผลิตภัณฑ์เป็นเกลือของโลหะและน้ำ หรืออาจได้เพียงเกลือของโลหะ'),
  ('ว 2.1', 'ม.3', 16, 'ปฏิกิริยาของเบสกับโลหะบางชนิด ได้ผลิตภัณฑ์เป็นเกลือของเบสและแก๊สไฮโดรเจน'),
  ('ว 2.1', 'ม.3', 17, 'การเกิดฝนกรด เป็นผลจากปฏิกิริยาระหว่างน้ำฝนกับออกไซด์ของไนโตรเจน หรือออกไซด์ของซัลเฟอร์ ทำให้น้ำฝนมีสมบัติเป็นกรด'),
  ('ว 2.1', 'ม.3', 18, 'การสังเคราะห์ด้วยแสงของพืช เป็นปฏิกิริยาระหว่างแก๊สคาร์บอนไดออกไซด์กับน้ำ โดยมีแสงช่วยในการเกิดปฏิกิริยา ได้ผลิตภัณฑ์เป็นน้ำตาลกลูโคสและออกซิเจน'),
  ('ว 2.1', 'ม.3', 19, 'ปฏิกิริยาเคมีที่พบในชีวิตประจำวันมีทั้งประโยชน์และโทษต่อสิ่งมีชีวิตและสิ่งแวดล้อม จึงต้องระมัดระวังผลจากปฏิกิริยาเคมี ตลอดจนรู้จักวิธีป้องกันและแก้ปัญหาที่เกิดจากปฏิกิริยาเคมีที่พบในชีวิตประจำวัน'),
  ('ว 2.1', 'ม.3', 20, 'ความรู้เกี่ยวกับปฏิกิริยาเคมี สามารถนำไปใช้ประโยชน์ในชีวิตประจำวัน และสามารถบูรณาการกับคณิตศาสตร์ เทคโนโลยี และวิศวกรรมศาสตร์เพื่อใช้ปรับปรุงผลิตภัณฑ์ให้มีคุณภาพตามต้องการหรืออาจสร้างนวัตกรรมเพื่อป้องกันและแก้ปัญหาที่เกิดขึ้นจากปฏิกิริยาเคมี โดยใช้ความรู้เกี่ยวกับปฏิกิริยาเคมี เช่น การเปลี่ยนแปลงพลังงานความร้อนอันเนื่องมาจากปฏิกิริยาเคมีการเพิ่มปริมาณผลผลิต'),
  ('ว 2.1', 'ม.5', 1, 'สารเคมีทุกชนิดสามารถระบุได้ว่าเป็นธาตุหรือสารประกอบ และอยู่ในรูปของอะตอม โมเลกุลหรือไอออนได้ โดยพิจารณาจากสูตรเคมี'),
  ('ว 2.1', 'ม.5', 2, 'แบบจำลองอะตอมใช้อธิบายตำแหน่งของโปรตอนนิวตรอน และอิเล็กตรอนในอะตอม โดยโปรตอนและนิวตรอนอยู่รวมกันในนิวเคลียส ส่วนอิเล็กตรอนเคลื่อนที่รอบนิวเคลียส ซึ่งในแบบจำลองอะตอมของโบร์ อิเล็กตรอนเคลื่อนที่เป็นวง โดยแต่ละวงมีระยะห่างจากนิวเคลียสและมีพลังงานต่างกันและอิเล็กตรอนวงนอกสุด เรียกว่าเวเลนซ์อิเล็กตรอน'),
  ('ว 2.1', 'ม.5', 3, 'แบบจำลองอะตอมแบบกลุ่มหมอก แสดงโอกาสที่จะพบอิเล็กตรอนรอบนิวเคลียสในลักษณะกลุ่มหมอก เนื่องจากอิเล็กตรอนมีขนาดเล็กและเคลื่อนที่อย่างรวดเร็วตลอดเวลา จึงไม่สามารถระบุตำแหน่งที่แน่นอนได้'),
  ('ว 2.1', 'ม.5', 4, 'อะตอมของธาตุเป็นกลางทางไฟฟ้า มีจำนวนโปรตอนเท่ากับจำนวนอิเล็กตรอน การระบุชนิดของธาตุพิจารณาจากจำนวนโปรตอน'),
  ('ว 2.1', 'ม.5', 5, 'เมื่ออะตอมของธาตุมีการให้หรือรับอิเล็กตรอน ทำให้จำนวนโปรตอนและอิเล็กตรอนไม่เท่ากันเกิดเป็นไอออน โดยไอออนที่มีจำนวนอิเล็กตรอนน้อยกว่าจำนวนโปรตอน เรียกว่า ไอออนบวกส่วนไอออนที่มีจำนวนอิเล็กตรอนมากกว่าโปรตอน เรียกว่า ไอออนลบ'),
  ('ว 2.1', 'ม.5', 6, 'สัญลักษณ์นิวเคลียร์ ประกอบด้วยสัญลักษณ์ธาตุเลขอะตอมและเลขมวล โดยเลขอะตอมเป็นตัวเลขที่แสดงจำนวนโปรตอนในอะตอม เลขมวลเป็นตัวเลขที่แสดงผลรวมของจำนวนโปรตอนกับนิวตรอนในอะตอม ธาตุชนิดเดียวกันแต่มีเลขมวลต่างกัน เรียกว่าไอโซโทป'),
  ('ว 2.1', 'ม.5', 7, 'ธาตุจัดเป็นหมวดหมู่ได้อย่างเป็นระบบ โดยอาศัยตารางธาตุ ซึ่งในปัจจุบันจัดเรียงตามเลขอะตอมและความคล้ายคลึงของสมบัติ แบ่งออกเป็นหมู่ซึ่งเป็นแถวในแนวตั้ง และคาบซึ่งเป็นแถวในแนวนอนทำให้ธาตุที่มีสมบัติเป็นโลหะ อโลหะและกึ่งโลหะอยู่เป็นกลุ่มบริเวณใกล้ ๆ กัน และแบ่งธาตุออกเป็นกลุ่มธาตุเรพรีเซนเททีฟและกลุ่มธาตุแทรนซิชัน'),
  ('ว 2.1', 'ม.5', 8, 'ธาตุในกลุ่มโลหะ จะนำไฟฟ้าได้ดี และมีแนวโน้มให้อิเล็กตรอน ส่วนธาตุในกลุ่มอโลหะ จะไม่นำไฟฟ้า และมีแนวโน้มรับอิเล็กตรอน โดยธาตุเรพรีเซนเททีฟในหมู่ IA - IIA และธาตุแทรนซิชันทุกธาตุจัดเป็นธาตุในกลุ่มโลหะ ส่วนธาตุเรพรีเซนเททีฟในหมู่ IIIA - VIIA มีทั้งธาตุในกลุ่มโลหะและอโลหะส่วนธาตุเรพรีเซนเททีฟในหมู่ VIIIA จัดเป็นธาตุอโลหะทั้งหมด'),
  ('ว 2.1', 'ม.5', 9, 'ธาตุเรพรีเซนเททีฟและธาตุแทรนซิชันนำมาใช้ประโยชน์ในชีวิตประจำวันได้หลากหลายซึ่งธาตุบางชนิดมีสมบัติที่เป็นอันตราย จึงต้องคำนึงถึงการป้องกันอันตรายเพื่อความปลอดภัยในการใช้ประโยชน์'),
  ('ว 2.1', 'ม.5', 10, 'พันธะโคเวเลนต์ เป็นการยึดเหนี่ยวระหว่างอะตอมด้วยการใช้เวเลนซ์อิเล็กตรอนร่วมกัน เกิดเป็นโมเลกุล โดยการใช้เวเลนซ์อิเล็กตรอนร่วมกัน1 คู่เรียกว่า พันธะเดี่ยว เขียนแทนด้วยเส้นพันธะ1 เส้น ในโครงสร้างโมเลกุล ส่วนการใช้เวเลนซ์อิเล็กตรอนร่วมกัน 2 คู่ และ 3 คู่ เรียกว่าพันธะคู่ และพันธะสาม เขียนแทนด้วยเส้นพันธะ 2 เส้น และ 3 เส้น ตามลำดับ'),
  ('ว 2.1', 'ม.5', 11, 'สารที่มีพันธะภายในโมเลกุลเป็นพันธะโคเวเลนต์ทั้งหมดเรียกว่า สารโคเวเลนต์ โดยสารโคเวเลนต์ที่ประกอบด้วย 2 อะตอมของธาตุชนิดเดียวกันเป็นสารไม่มีขั้ว ส่วนสารโคเวเลนต์ ที่ประกอบด้วย 2 อะตอมของธาตุต่างชนิดกัน เป็นสารมีขั้ว สำหรับสารโคเวเลนต์ที่ประกอบด้วยอะตอมมากกว่า 2 อะตอม อาจเป็นสารมีขั้วหรือไม่มีขั้วขึ้นอยู่กับรูปร่างของโมเลกุล ซึ่งสภาพขั้วของสารโคเวเลนต์ส่งผลต่อแรงดึงดูดระหว่างโมเลกุลที่ทำให้จุดหลอมเหลวและจุดเดือดของสารโคเวเลนต์แตกต่างกัน นอกจากนี้สารบางชนิดมีจุดเดือดสูงกว่าปกติ เนื่องจากมีแรงดึงดูดระหว่างโมเลกุลสูงที่เรียกว่า พันธะไฮโดรเจนซึ่งสารเหล่านี้มีพันธะ N-H O-H หรือ F-H ภายในโครงสร้างโมเลกุล'),
  ('ว 2.1', 'ม.5', 12, 'สารประกอบไอออนิกส่วนใหญ่เกิดจากการรวมตัวกันของไอออนบวกของธาตุโลหะและไอออนลบของธาตุอโลหะ ในบางกรณีไอออนอาจประกอบด้วยกลุ่มของอะตอม โดยเมื่อไอออนรวมตัวกันเกิดเป็นสารประกอบไอออนิกจะมีสัดส่วนการรวมตัวเพื่อทำให้ประจุของสารประกอบเป็นกลางทางไฟฟ้า โดยไอออนบวกและไอออนลบจะจัดเรียงตัวสลับต่อเนื่องกันไปใน 3 มิติ เกิดเป็นผลึกของสารซึ่งสูตรเคมีของสารประกอบไอออนิกประกอบด้วยสัญลักษณ์ธาตุที่เป็นไอออนบวกตามด้วยสัญลักษณ์ธาตุที่เป็นไอออนลบ โดยมีตัวเลขที่แสดงจำนวนไอออนแต่ละชนิดเป็นอัตราส่วนอย่างต่ำ'),
  ('ว 2.1', 'ม.5', 13, 'สารจะละลายน้ำได้เมื่อองค์ประกอบของสารสามารถเกิดแรงดึงดูดกับโมเลกุลของน้ำได้โดยการละลายของสารในน้ำเกิดได้ 2 ลักษณะคือ การละลายแบบแตกตัว และการละลายแบบไม่แตกตัว การละลายแบบแตกตัวเกิดขึ้นกับสารประกอบไอออนิก และสารโคเวเลนต์บางชนิดที่มีสมบัติเป็นกรดหรือเบส โดยเมื่อสารเกิดการละลายแบบแตกตัวจะได้ไอออนที่สามารถเคลื่อนที่ได้ ทำให้ได้สารละลายที่นำไฟฟ้าซึ่งเรียกว่า สารละลายอิเล็กโทรไลต์ การละลายแบบไม่แตกตัวเกิดขึ้นกับสารโคเวเลนต์ที่มีขั้วสูงสามารถดึงดูดกับโมเลกุลของน้ำได้ดี โดยเมื่อเกิดการละลายโมเลกุลของสารจะไม่แตกตัวเป็นไอออน และสารละลายที่ได้จะไม่นำไฟฟ้าซึ่งเรียกว่า สารละลายนอนอิเล็กโทรไลต์'),
  ('ว 2.1', 'ม.5', 14, 'สารประกอบอินทรีย์เป็นสารประกอบของคาร์บอนส่วนใหญ่พบในสิ่งมีชีวิต มีโครงสร้างหลากหลายและแบ่งได้หลายประเภท เนื่องจากธาตุคาร์บอน สามารถเกิดพันธะกับคาร์บอนด้วยกันเองและธาตุอื่น ๆ นอกจากนี้พันธะระหว่างคาร์บอนยังมีหลายรูปแบบ ได้แก่ พันธะเดี่ยวพันธะคู่ พันธะสาม'),
  ('ว 2.1', 'ม.5', 15, 'สารประกอบอินทรีย์ที่มีเฉพาะธาตุคาร์บอนและไฮโดรเจนเป็นองค์ประกอบ เรียกว่า สารประกอบไฮโดรคาร์บอน โดยสารประกอบไฮโดรคาร์บอนอิ่มตัวมีพันธะระหว่างคาร์บอนเป็นพันธะเดี่ยวทุกพันธะในโครงสร้าง ส่วนสารประกอบไฮโดรคาร์บอนไม่อิ่มตัวมีพันธะระหว่างคาร์บอนเป็นพันธะคู่หรือพันธะสามอย่างน้อย 1 พันธะในโครงสร้าง'),
  ('ว 2.1', 'ม.5', 16, 'สารที่พบในชีวิตประจำวันมีทั้งโมเลกุลขนาดเล็กและขนาดใหญ่ พอลิเมอร์เป็นสารที่มีโมเลกุลขนาดใหญ่ที่เกิดจากมอนอเมอร์หลายโมเลกุลเชื่อมต่อกันด้วยพันธะเคมี ทำให้สมบัติทางกายภาพของพอลิเมอร์แตกต่างจากมอนอเมอร์ที่เป็นสารตั้งต้น เช่น สถานะ จุดหลอมเหลวการละลาย'),
  ('ว 2.1', 'ม.5', 17, 'สารประกอบอินทรีย์ที่มีหมู่ -COOH สามารถแสดงสมบัติความเป็นกรด ส่วนสารประกอบอินทรีย์ที่มีหมู่ -NH สามารถแสดงสมบัติความเป็นเบส 2'),
  ('ว 2.1', 'ม.5', 18, 'การละลายของสารพิจารณาได้จากความมีขั้วของตัวละลายและตัวทำละลาย โดยสารสามารถละลายได้ในตัวทำละลายที่มีขั้วใกล้เคียงกันโดยสารมีขั้วละลายในตัวทำละลายที่มีขั้วส่วนสารไม่มีขั้วละลายในตัวทำละลายที่ไม่มีขั้วและสารมีขั้วไม่ละลายในตัวทำละลายที่ไม่มีขั้ว'),
  ('ว 2.1', 'ม.5', 19, 'โครงสร้างของพอลิเมอร์อาจเป็นแบบเส้น แบบกิ่งหรือแบบร่างแห โดยพอลิเมอร์แบบเส้นและแบบกิ่ง มีสมบัติเทอร์มอพลาสติก ส่วนพอลิเมอร์แบบร่างแห มีสมบัติเทอร์มอเซต จึงมีการใช้ประโยชน์ได้แตกต่างกัน'),
  ('ว 2.1', 'ม.5', 20, 'การใช้ผลิตภัณฑ์พอลิเมอร์ในปริมาณมากก่อให้เกิดปัญหาที่ส่งผลกระทบต่อสิ่งมีชีวิตและสิ่งแวดล้อมดังนั้นจึงควรตระหนักถึงการลดปริมาณการใช้การใช้ซ้ำ และการนำกลับมาใช้ใหม่'),
  ('ว 2.1', 'ม.5', 21, 'ปฏิกิริยาเคมีทำให้เกิดการเปลี่ยนแปลงของสารโดยปฏิกิริยาเคมีอาจให้พลังงานความร้อนพลังงานแสง หรือพลังงานไฟฟ้า ที่สามารถนำไปใช้ประโยชน์ในด้านต่าง ๆ ได้'),
  ('ว 2.1', 'ม.5', 22, 'ปฏิกิริยาเคมีแสดงได้ด้วยสมการเคมี ซึ่งมีสูตรเคมีของสารตั้งต้นอยู่ทางด้านซ้ายของลูกศร และสูตรเคมีของผลิตภัณฑ์อยู่ทางด้านขวา โดยจำนวนอะตอมรวมของแต่ละธาตุทางด้านซ้ายและขวาเท่ากัน นอกจากนี้สมการเคมียังอาจแสดงปัจจัยอื่นเช่น สถานะ พลังงานที่เกี่ยวข้อง ตัวเร่งปฏิกิริยาเคมีที่ใช้'),
  ('ว 2.1', 'ม.5', 23, 'อัตราการเกิดปฏิกิริยาเคมีขึ้นอยู่กับความเข้มข้นอุณหภูมิ พื้นที่ผิว หรือตัวเร่งปฏิกิริยา'),
  ('ว 2.1', 'ม.5', 24, 'ความรู้เกี่ยวกับปัจจัยที่มีผลต่ออัตราการเกิดปฏิกิริยาเคมีสามารถนำไปใช้ประโยชน์ในชีวิตประจำวันและในอุตสาหกรรม'),
  ('ว 2.1', 'ม.5', 25, 'ปฏิกิริยาเคมีบางประเภทเกิดจากการถ่ายโอนอิเล็กตรอนของสารในปฏิกิริยาเคมี ซึ่งเรียกว่าปฏิกิริยารีดอกซ์'),
  ('ว 2.1', 'ม.5', 26, 'สารที่สามารถแผ่รังสีได้เรียกว่า สารกัมมันตรังสีซึ่งมีนิวเคลียสที่สลายตัวอย่างต่อเนื่อง ระยะเวลาที่สารกัมมันตรังสีสลายตัวจนเหลือครึ่งหนึ่งของปริมาณเดิม เรียกว่า ครึ่งชีวิต โดยสารกัมมันตรังสีแต่ละชนิดมีค่าครึ่งชีวิตแตกต่างกัน'),
  ('ว 2.1', 'ม.5', 27, 'รังสีที่แผ่จากสารกัมมันตรังสีมีหลายชนิด เช่นแอลฟา บีตา แกมมา ซึ่งสามารถนำมาใช้ประโยชน์ได้แตกต่างกัน การนำสารกัมมันตรังสีแต่ละชนิดมาใช้ ต้องคำนึงถึงผลกระทบต่อสิ่งมีชีวิตและสิ่งแวดล้อม รวมทั้งมีการจัดการอย่างเหมาะสม'),
  ('ว 2.2', 'ป.3', 1, 'การดึงหรือการผลักเป็นการออกแรงกระทำต่อวัตถุ แรงมีผลต่อการเคลื่อนที่ของวัตถุ แรงอาจทำให้วัตถุเกิดการเคลื่อนที่โดยเปลี่ยนตำแหน่งจากที่หนึ่งไปยังอีกที่หนึ่ง'),
  ('ว 2.2', 'ป.3', 2, 'การเปลี่ยนแปลงการเคลื่อนที่ของวัตถุ ได้แก่วัตถุที่อยู่นิ่งเปลี่ยนเป็นเคลื่อนที่ วัตถุที่กำลังเคลื่อนที่เปลี่ยนเป็นเคลื่อนที่เร็วขึ้นหรือช้าลงหรือหยุดนิ่ง หรือเปลี่ยนทิศทางการเคลื่อนที่'),
  ('ว 2.2', 'ป.3', 3, 'การดึงหรือการผลักเป็นการออกแรงที่เกิดจากวัตถุหนึ่งกระทำกับอีกวัตถุหนึ่ง โดยวัตถุทั้งสองอาจสัมผัสหรือไม่ต้องสัมผัสกัน เช่น การออกแรงโดยใช้มือดึงหรือการผลักโต๊ะให้เคลื่อนที่เป็นการออกแรงที่วัตถุต้องสัมผัสกัน แรงนี้จึงเป็นแรงสัมผัส ส่วนการที่แม่เหล็กดึงดูดหรือผลักระหว่างแม่เหล็กเป็นแรงที่เกิดขึ้นโดยแม่เหล็กไม่จำเป็นต้องสัมผัสกัน แรงแม่เหล็กนี้จึงเป็นแรงไม่สัมผัส'),
  ('ว 2.2', 'ป.3', 4, 'แม่เหล็กสามารถดึงดูดสารแม่เหล็กได้'),
  ('ว 2.2', 'ป.3', 5, 'แรงแม่เหล็กเป็นแรงที่เกิดขึ้นระหว่างแม่เหล็กกับสารแม่เหล็ก หรือแม่เหล็กกับแม่เหล็กแม่เหล็ก มี 2 ขั้ว คือ ขั้วเหนือและขั้วใต้ขั้วแม่เหล็กชนิดเดียวกันจะผลักกัน ต่างชนิดกันจะดึงดูดกัน'),
  ('ว 2.2', 'ป.4', 1, 'แรงโน้มถ่วงของโลกเป็นแรงดึงดูดที่โลกกระทำต่อวัตถุ มีทิศทางเข้าสู่ศูนย์กลางโลก และเป็นแรงไม่สัมผัส แรงดึงดูดที่โลกกระทำกับวัตถุหนึ่ง ๆ ทำให้วัตถุตกลงสู่พื้นโลก และทำให้วัตถุมีน้ำหนักวัดน้ำหนักของวัตถุได้จากเครื่องชั่งสปริง น้ำหนักของวัตถุขึ้นกับมวลของวัตถุ โดยวัตถุที่มีมวลมากจะมีน้ำหนักมาก วัตถุที่มีมวลน้อยจะมีน้ำหนักน้อย'),
  ('ว 2.2', 'ป.4', 2, 'มวล คือ ปริมาณเนื้อของสสารทั้งหมดที่ประกอบกันเป็นวัตถุ ซึ่งมีผลต่อความยากง่ายในการเปลี่ยนแปลงการเคลื่อนที่ของวัตถุ วัตถุที่มีมวลมากจะเปลี่ยนแปลงการเคลื่อนที่ได้ยากกว่าวัตถุที่มีมวลน้อย ดังนั้นมวลของวัตถุนอกจากจะหมายถึงเนื้อทั้งหมดของวัตถุนั้นแล้วยังหมายถึงการต้านการเปลี่ยนแปลงการเคลื่อนที่ของวัตถุนั้นด้วย'),
  ('ว 2.2', 'ป.5', 1, 'แรงลัพธ์เป็นผลรวมของแรงที่กระทำต่อวัตถุ โดยแรงลัพธ์ของแรง 2 แรงที่กระทำต่อวัตถุเดียวกันจะมีขนาดเท่ากับผลรวมของแรงทั้งสองเมื่อแรงทั้งสองอยู่ในแนวเดียวกันและมีทิศทางเดียวกันแต่จะมีขนาดเท่ากับผลต่างของแรงทั้งสองเมื่อแรงทั้งสองอยู่ในแนวเดียวกันแต่มีทิศทางตรงข้ามกัน สำหรับวัตถุที่อยู่นิ่งแรงลัพธ์ที่กระทำต่อวัตถุมีค่าเป็นศูนย์'),
  ('ว 2.2', 'ป.5', 2, 'การเขียนแผนภาพของแรงที่กระทำต่อวัตถุสามารถเขียนได้โดยใช้ลูกศร โดยหัวลูกศรแสดงทิศทางของแรง และความยาวของลูกศรแสดงขนาดของแรงที่กระทำต่อวัตถุ'),
  ('ว 2.2', 'ป.5', 3, 'แรงเสียดทานเป็นแรงที่เกิดขึ้นระหว่างผิวสัมผัสของวัตถุ เพื่อต้านการเคลื่อนที่ของวัตถุนั้น โดยถ้าออกแรงกระทำต่อวัตถุที่อยู่นิ่งบนพื้นผิวหนึ่งให้เคลื่อนที่ แรงเสียดทานจากพื้นผิวนั้นก็จะต้านการเคลื่อนที่ของวัตถุ แต่ถ้าวัตถุกำลังเคลื่อนที่แรงเสียดทานก็จะทำให้วัตถุนั้นเคลื่อนที่ช้าลงหรือหยุดนิ่ง'),
  ('ว 2.2', 'ป.6', 1, 'วัตถุ 2 ชนิดที่ผ่านการขัดถูแล้ว เมื่อนำเข้าใกล้กันอาจดึงดูดหรือผลักกัน แรงที่เกิดขึ้นนี้เป็นแรงไฟฟ้า ซึ่งเป็นแรงไม่สัมผัส เกิดขึ้นระหว่างวัตถุที่มีประจุไฟฟ้า ซึ่งประจุไฟฟ้ามี 2 ชนิด คือประจุไฟฟ้าบวกและประจุไฟฟ้าลบ วัตถุที่มีประจุไฟฟ้าชนิดเดียวกันผลักกัน ชนิดตรงข้ามกันดึงดูดกัน'),
  ('ว 2.2', 'ม.1', 1, 'เมื่อวัตถุอยู่ในอากาศจะมีแรงที่อากาศกระทำต่อวัตถุในทุกทิศทาง แรงที่อากาศกระทำต่อวัตถุขึ้นอยู่กับขนาดพื้นที่ของวัตถุนั้น แรงที่อากาศกระทำตั้งฉากกับผิววัตถุต่อหนึ่งหน่วยพื้นที่เรียกว่า ความดันอากาศ'),
  ('ว 2.2', 'ม.1', 2, 'ความดันอากาศมีความสัมพันธ์กับความสูงจากพื้นโลก โดยบริเวณที่สูงจากพื้นโลกขึ้นไปอากาศเบาบางลง มวลอากาศน้อยลง ความดันอากาศก็จะลดลง'),
  ('ว 2.2', 'ม.2', 1, 'แรงเป็นปริมาณเวกเตอร์ เมื่อมีแรงหลาย ๆ แรงกระทำต่อวัตถุ แล้วแรงลัพธ์ที่กระทำต่อวัตถุมีค่าเป็นศูนย์ วัตถุจะไม่เปลี่ยนแปลงการเคลื่อนที่แต่ถ้าแรงลัพธ์ที่กระทำต่อวัตถุมีค่าไม่เป็นศูนย์วัตถุจะเปลี่ยนแปลงการเคลื่อนที่'),
  ('ว 2.2', 'ม.2', 2, 'เมื่อวัตถุอยู่ในของเหลวจะมีแรงที่ของเหลวกระทำต่อวัตถุในทุกทิศทาง โดยแรงที่ของเหลวกระทำตั้งฉากกับผิววัตถุต่อหนึ่งหน่วยพื้นที่เรียกว่าความดันของของเหลว'),
  ('ว 2.2', 'ม.2', 3, 'ความดันของของเหลวมีความสัมพันธ์กับความลึกจากระดับผิวหน้าของของเหลว โดยบริเวณที่ลึกลงไปจากระดับผิวหน้าของของเหลวมากขึ้นความดันของของเหลวจะเพิ่มขึ้น เนื่องจากของเหลวที่อยู่ลึกกว่า จะมีน้ำหนักของของเหลวด้านบนกระทำมากกว่า'),
  ('ว 2.2', 'ม.2', 4, 'เมื่อวัตถุอยู่ในของเหลว จะมีแรงพยุงเนื่องจากของเหลวกระทำต่อวัตถุ โดยมีทิศขึ้นในแนวดิ่งการจมหรือการลอยของวัตถุขึ้นกับน้ำหนักของวัตถุและแรงพยุง ถ้าน้ำหนักของวัตถุและแรงพยุงของของเหลวมีค่าเท่ากัน วัตถุจะลอยนิ่งอยู่ในของเหลว แต่ถ้าน้ำหนักของวัตถุมีค่ามากกว่าแรงพยุงของของเหลววัตถุจะจม'),
  ('ว 2.2', 'ม.2', 5, 'แรงเสียดทานเป็นแรงที่เกิดขึ้นระหว่างผิวสัมผัสของวัตถุ เพื่อต้านการเคลื่อนที่ของวัตถุนั้นโดยถ้าออกแรงกระทำต่อวัตถุที่อยู่นิ่งบนพื้นผิวให้เคลื่อนที่ แรงเสียดทานก็จะต้านการเคลื่อนที่ของวัตถุ แรงเสียดทานที่เกิดขึ้นในขณะที่วัตถุยังไม่เคลื่อนที่เรียก แรงเสียดทานสถิต แต่ถ้าวัตถุกำลังเคลื่อนที่ แรงเสียดทานก็จะทำให้วัตถุนั้นเคลื่อนที่ช้าลงหรือหยุดนิ่ง เรียก แรงเสียดทานจลน์'),
  ('ว 2.2', 'ม.2', 6, 'ขนาดของแรงเสียดทานระหว่างผิวสัมผัสของวัตถุขึ้นกับลักษณะผิวสัมผัสและขนาดของแรงปฏิกิริยาตั้งฉากระหว่างผิวสัมผัส'),
  ('ว 2.2', 'ม.2', 7, 'กิจกรรมในชีวิตประจำวันบางกิจกรรมต้องการแรงเสียดทาน เช่น การเปิดฝาเกลียวขวดน้ำการใช้แผ่นกันลื่นในห้องน้ำ บางกิจกรรมไม่ต้องการแรงเสียดทาน เช่น การลากวัตถุบนพื้นการใช้น้ำมันหล่อลื่นในเครื่องยนต์'),
  ('ว 2.2', 'ม.2', 8, 'ความรู้เรื่องแรงเสียดทานสามารถนำไปใช้ประโยชน์ในชีวิตประจำวันได้'),
  ('ว 2.2', 'ม.2', 9, 'เมื่อมีแรงที่กระทำต่อวัตถุโดยไม่ผ่านศูนย์กลางมวลของวัตถุ จะเกิดโมเมนต์ของแรง ทำให้วัตถุหมุนรอบศูนย์กลางมวลของวัตถุนั้น'),
  ('ว 2.2', 'ม.2', 10, 'โมเมนต์ของแรงเป็นผลคูณของแรงที่กระทำต่อวัตถุกับระยะทางจากจุดหมุนไปตั้งฉากกับแนวแรง เมื่อผลรวมของโมเมนต์ของแรงมีค่าเป็นศูนย์วัตถุจะอยู่ในสภาพสมดุลต่อการหมุน โดยโมเมนต์ของแรงในทิศทวนเข็มนาฬิกาจะมีขนาดเท่ากับโมเมนต์ของแรงในทิศตามเข็มนาฬิกา'),
  ('ว 2.2', 'ม.2', 11, 'ของเล่นหลายชนิดประกอบด้วยอุปกรณ์หลายส่วนที่ใช้หลักการโมเมนต์ของแรง ความรู้เรื่องโมเมนต์ของแรงสามารถนำไปใช้ออกแบบและประดิษฐ์ของเล่นได้'),
  ('ว 2.2', 'ม.2', 12, 'วัตถุที่มีมวลจะมีสนามโน้มถ่วงอยู่โดยรอบแรงโน้มถ่วงที่กระทำต่อวัตถุที่อยู่ในสนามโน้มถ่วงจะมีทิศพุ่งเข้าหาวัตถุที่เป็นแหล่งของสนามโน้มถ่วง'),
  ('ว 2.2', 'ม.2', 13, 'วัตถุที่มีประจุไฟฟ้าจะมีสนามไฟฟ้าอยู่โดยรอบแรงไฟฟ้าที่กระทำต่อวัตถุที่มีประจุจะมีทิศพุ่งเข้าหาหรือออกจากวัตถุที่มีประจุที่เป็นแหล่งของสนามไฟฟ้า'),
  ('ว 2.2', 'ม.2', 14, 'วัตถุที่เป็นแม่เหล็กจะมีสนามแม่เหล็กอยู่โดยรอบแรงแม่เหล็กที่กระทำต่อขั้วแม่เหล็กจะมีทิศพุ่งเข้าหาหรือออกจากขั้วแม่เหล็กที่เป็นแหล่งของสนามแม่เหล็ก'),
  ('ว 2.2', 'ม.2', 15, 'ขนาดของแรงโน้มถ่วง แรงไฟฟ้า และแรงแม่เหล็กที่กระทำต่อวัตถุที่อยู่ในสนามนั้น ๆ จะมีค่าลดลงเมื่อวัตถุอยู่ห่างจากแหล่งของสนามนั้น ๆ มากขึ้น'),
  ('ว 2.2', 'ม.2', 16, 'การเคลื่อนที่ของวัตถุเป็นการเปลี่ยนตำแหน่งของวัตถุเทียบกับตำแหน่งอ้างอิง โดยมีปริมาณที่เกี่ยวข้องกับการเคลื่อนที่ซึ่งมีทั้งปริมาณสเกลาร์และปริมาณเวกเตอร์ เช่น ระยะทางอัตราเร็ว การกระจัด ความเร็ว ปริมาณสเกลาร์เป็นปริมาณที่มีขนาด เช่น ระยะทาง อัตราเร็วปริมาณเวกเตอร์เป็นปริมาณที่มีทั้งขนาดและทิศทาง เช่น การกระจัด ความเร็ว'),
  ('ว 2.2', 'ม.2', 17, 'เขียนแผนภาพแทนปริมาณเวกเตอร์ได้ด้วยลูกศรโดยความยาวของลูกศรแสดงขนาดและหัวลูกศรแสดงทิศทางของเวกเตอร์นั้น ๆ'),
  ('ว 2.2', 'ม.2', 18, 'ระยะทางเป็นปริมาณสเกลาร์ โดยระยะทางเป็นความยาวของเส้นทางที่เคลื่อนที่ได้'),
  ('ว 2.2', 'ม.2', 19, 'การกระจัดเป็นปริมาณเวกเตอร์ โดยการกระจัดมีทิศชี้จากตำแหน่งเริ่มต้นไปยังตำแหน่งสุดท้ายและมีขนาดเท่ากับระยะที่สั้นที่สุดระหว่างสองตำแหน่งนั้น'),
  ('ว 2.2', 'ม.2', 20, 'อัตราเร็วเป็นปริมาณสเกลาร์ โดยอัตราเร็วเป็นอัตราส่วนของระยะทางต่อเวลา'),
  ('ว 2.2', 'ม.2', 21, 'ความเร็วปริมาณเวกเตอร์มีทิศเดียวกับทิศของการกระจัด โดยความเร็วเป็นอัตราส่วนของการกระจัดต่อเวลา'),
  ('ว 2.2', 'ม.5', 1, 'การเคลื่อนที่ของวัตถุที่มีการเปลี่ยนความเร็วเป็นการเคลื่อนที่ด้วยความเร่ง ความเร่งเป็นอัตราส่วนของความเร็วที่เปลี่ยนไปต่อเวลาและเป็นปริมาณเวกเตอร์ ในกรณีที่วัตถุที่อยู่นิ่งหรือเคลื่อนที่ในแนวตรงด้วยความเร็วคงตัววัตถุนั้นมีความเร่งเป็นศูนย์'),
  ('ว 2.2', 'ม.5', 2, 'วัตถุมีความเร็วเพิ่มขึ้น ถ้าความเร็วและความเร่งมีทิศเดียวกัน และมีความเร็วลดลง ถ้าความเร็วและความเร่งมีทิศตรงกันข้าม'),
  ('ว 2.2', 'ม.5', 3, 'เมื่อมีแรงหลายแรงกระทำต่อวัตถุหนึ่ง โดยแรงทุกแรงอยู่ในระนาบเดียวกันสามารถหาแรงลัพธ์ที่กระต่อวัตถุนั้นได้โดยรวมแบบเวกเตอร์'),
  ('ว 2.2', 'ม.5', 4, 'เมื่อแรงลัพธ์มีค่าไม่เท่ากับศูนย์กระทำต่อวัตถุจะทำให้วัตถุเคลื่อนที่ด้วยความเร่งมีทิศทางเดียวกับแรงลัพธ์โดยขนาดของความเร่งขึ้นกับขนาดของแรงลัพธ์กระทำต่อวัตถุและมวลของวัตถุ'),
  ('ว 2.2', 'ม.5', 5, 'แรงกระทำระหว่างวัตถุคู่หนึ่ง ๆ เป็นแรงกิริยาและแรงปฏิกิริยา แรงทั้งสองมีขนาดเท่ากันเกิดขึ้นพร้อมกัน กระทำกับวัตถุคนละก้อนแต่มีทิศทางตรงข้าม'),
  ('ว 2.2', 'ม.5', 6, 'วัตถุที่เคลื่อนที่ด้วยความเร่งคงตัวหรือความเร่งไม่คงตัว อาจเป็นการเคลื่อนที่แนวตรงการเคลื่อนที่แนวโค้ง หรือการเคลื่อนที่แบบสั่นการเคลื่อนที่แนวตรงด้วยความเร่งคงตัว นำไปใช้อธิบายการตกแบบเสรี การเคลื่อนที่แนวโค้งด้วยความเร่งคงตัว นำไปใช้อธิบายการเคลื่อนที่แบบโพรเจกไทล์ การเคลื่อนที่แนวโค้งด้วยความเร่งมีทิศทางตั้งฉากกับความเร็วตลอดเวลา นำไปใช้อธิบายการเคลื่อนที่แบบวงกลม การเคลื่อนที่กลับไปกลับมาด้วยความเร่งมีทิศทางเข้าสู่จุดที่แรงลัพธ์เป็นศูนย์ เรียกจุดนี้ว่าตำแหน่งสมดุลซึ่งนำไปใช้อธิบายการเคลื่อนที่แบบสั่น'),
  ('ว 2.2', 'ม.5', 7, 'ในบริเวณที่มีสนามโน้มถ่วง เมื่อมีวัตถุที่มีมวลจะมีแรงโน้มถ่วงซึ่งเป็นแรงดึงดูดของโลกกระทำต่อวัตถุ แรงนี้นำไปใช้อธิบายการเคลื่อนที่ของวัตถุต่าง ๆ เช่น ดาวเทียม และดวงจันทร์รอบโลก'),
  ('ว 2.2', 'ม.5', 8, 'กระแสไฟฟ้าทำให้เกิดสนามแม่เหล็กในบริเวณรอบแนวการเคลื่อนที่ของกระแสไฟฟ้า หาทิศทางของสนามแม่เหล็กเนื่องจากกระแสไฟฟ้าได้จากกฎมือขวา'),
  ('ว 2.2', 'ม.5', 9, 'ในบริเวณที่มีสนามแม่เหล็ก เมื่อมีอนุภาคที่มีประจุไฟฟ้าเคลื่อนที่โดยไม่อยู่ในแนวเดียวกับสนามแม่เหล็ก หรือมีกระแสไฟฟ้าผ่านลวดตัวนำโดยกระแสไฟฟ้าไม่อยู่ในแนวเดียวกับสนามแม่เหล็ก จะมีแรงแม่เหล็กกระทำ ซึ่งเป็นพื้นฐานในการสร้างมอเตอร์'),
  ('ว 2.2', 'ม.5', 10, 'เมื่อมีสนามแม่เหล็กเปลี่ยนแปลงตัดขดลวดตัวนำทำให้เกิดอีเอ็มเอฟ ซึ่งเป็นพื้นฐานในการสร้างเครื่องกำเนิดไฟฟ้า'),
  ('ว 2.2', 'ม.5', 11, 'ภายในนิวเคลียสมีแรงเข้มที่เป็นแรงยึดเหนี่ยวของอนุภาคในนิวเคลียส และเป็นแรงหลักที่ใช้อธิบายเสถียรภาพของนิวเคลียส นอกจากนี้ยังมีแรงอ่อน ซึ่งเป็นแรงที่ใช้อธิบายการสลายให้อนุภาคบีตาของธาตุกัมมันตรังสี'),
  ('ว 2.3', 'ป.1', 1, 'เสียงเกิดจากการสั่นของวัตถุ วัตถุที่ทำให้เกิดเสียงเป็นแหล่งกำเนิดเสียง ซึ่งมีทั้งแหล่งกำเนิดเสียงตามธรรมชาติและแหล่งกำเนิดเสียงที่มนุษย์สร้างขึ้น เสียงเคลื่อนที่ออกจากแหล่งกำเนิดเสียงทุกทิศทาง'),
  ('ว 2.3', 'ป.2', 1, 'แสงเคลื่อนที่จากแหล่งกำเนิดแสงทุกทิศทางเป็นแนวตรง เมื่อมีแสงจากวัตถุมาเข้าตาจะทำให้มองเห็นวัตถุนั้น การมองเห็นวัตถุที่เป็นแหล่งกำเนิดแสง แสงจากวัตถุนั้นจะเข้าสู่ตาโดยตรงส่วนการมองเห็นวัตถุที่ไม่ใช่แหล่งกำเนิดแสง ต้องมีแสงจากแหล่งกำเนิดแสงไปกระทบวัตถุแล้วสะท้อนเข้าตา ถ้ามีแสงที่สว่างมาก ๆ เข้าสู่ตาอาจเกิดอันตรายต่อตาได้ จึงต้องหลีกเลี่ยงการมองหรือใช้แผ่นกรองแสงที่มีคุณภาพเมื่อจำเป็น และต้องจัดความสว่างให้เหมาะสมกับการทำกิจกรรมต่าง ๆ เช่น การอ่านหนังสือการดูจอโทรทัศน์ การใช้โทรศัพท์เคลื่อนที่และแท็บเล็ต'),
  ('ว 2.3', 'ป.3', 1, 'พลังงานเป็นปริมาณที่แสดงถึงความสามารถในการทำงาน พลังงานมีหลายแบบ เช่นพลังงานกล พลังงานไฟฟ้า พลังงานแสงพลังงานเสียง และพลังงานความร้อน โดยพลังงานสามารถเปลี่ยนจากพลังงานหนึ่งไปเป็นอีกพลังงานหนึ่งได้ เช่น การถูมือจนรู้สึกร้อนเป็นการเปลี่ยนพลังงานกลเป็นพลังงานความร้อนแผงเซลล์สุริยะเปลี่ยนพลังงานแสงเป็นพลังงานไฟฟ้า หรือเครื่องใช้ไฟฟ้าเปลี่ยนพลังงานไฟฟ้าเป็นพลังงานอื่น'),
  ('ว 2.3', 'ป.3', 2, 'ไฟฟ้าผลิตจากเครื่องกำเนิดไฟฟ้าซึ่งใช้พลังงานจากแหล่งพลังงานธรรมชาติหลายแหล่ง เช่นพลังงานจากลม พลังงานจากน้ำ พลังงานจากแก๊สธรรมชาติ'),
  ('ว 2.3', 'ป.3', 3, 'พลังงานไฟฟ้ามีความสำคัญต่อชีวิตประจำวันการใช้ไฟฟ้านอกจากต้องใช้อย่างถูกวิธี ประหยัดและคุ้มค่าแล้ว ยังต้องคำนึงถึงความปลอดภัยด้วย'),
  ('ว 2.3', 'ป.4', 1, 'เมื่อมองสิ่งต่าง ๆ โดยมีวัตถุต่างชนิดกันมากั้นแสงจะทำให้ลักษณะการมองเห็นสิ่งนั้น ๆ ชัดเจนต่างกัน จึงจำแนกวัตถุที่มากั้นออกเป็นตัวกลางโปร่งใส ซึ่งทำให้มองเห็นสิ่งต่าง ๆ ได้ชัดเจนตัวกลางโปร่งแสงทำให้มองเห็นสิ่งต่าง ๆ ได้ไม่ชัดเจน และวัตถุทึบแสงทำให้มองไม่เห็นสิ่งต่าง ๆ นั้น'),
  ('ว 2.3', 'ป.5', 1, 'การได้ยินเสียงต้องอาศัยตัวกลาง โดยอาจเป็นของแข็ง ของเหลว หรืออากาศ เสียงจะส่งผ่านตัวกลางมายังหู'),
  ('ว 2.3', 'ป.5', 2, 'เสียงที่ได้ยินมีระดับสูงต่ำของเสียงต่างกันขึ้นกับความถี่ของการสั่นของแหล่งกำเนิดเสียง โดยเมื่อแหล่งกำเนิดเสียงสั่นด้วยความถี่ต่ำจะเกิดเสียงต่ำแต่ถ้าสั่นด้วยความถี่สูงจะเกิดเสียงสูง ส่วนเสียงดังค่อยที่ได้ยินขึ้นกับพลังงานการสั่นของแหล่งกำเนิดเสียง โดยเมื่อแหล่งกำเนิดเสียงสั่นด้วยพลังงานมากจะเกิดเสียงดัง แต่ถ้าแหล่งกำเนิดเสียงสั่นด้วยพลังงานน้อยจะเกิดเสียงค่อย'),
  ('ว 2.3', 'ป.5', 3, 'เสียงดังมาก ๆ เป็นอันตรายต่อการได้ยินและเสียงที่ก่อให้เกิดความรำคาญเป็นมลพิษทางเสียงเดซิเบลเป็นหน่วยที่บอกถึงความดังของเสียง'),
  ('ว 2.3', 'ป.6', 1, 'วงจรไฟฟ้าอย่างง่ายประกอบด้วย แหล่งกำเนิดไฟฟ้าสายไฟฟ้า และเครื่องใช้ไฟฟ้าหรืออุปกรณ์ไฟฟ้าแหล่งกำเนิดไฟฟ้า เช่น ถ่านไฟฉาย หรือแบตเตอรี่ ทำหน้าที่ให้พลังงานไฟฟ้า สายไฟฟ้าเป็นตัวนำไฟฟ้า ทำหน้าที่เชื่อมต่อระหว่างแหล่งกำเนิดไฟฟ้าและเครื่องใช้ไฟฟ้าเข้าด้วยกันเครื่องใช้ไฟฟ้ามีหน้าที่เปลี่ยนพลังงานไฟฟ้าเป็นพลังงานอื่น'),
  ('ว 2.3', 'ป.6', 2, 'เมื่อนำเซลล์ไฟฟ้าหลายเซลล์มาต่อเรียงกันโดยให้ขั้วบวกของเซลล์ไฟฟ้าเซลล์หนึ่งต่อกับขั้วลบของอีกเซลล์หนึ่งเป็นการต่อแบบอนุกรมทำให้มีพลังงานไฟฟ้าเหมาะสมกับเครื่องใช้ไฟฟ้าซึ่งการต่อเซลล์ไฟฟ้าแบบอนุกรมสามารถนำไปใช้ประโยชน์ในชีวิตประจำวัน เช่น การต่อเซลล์ไฟฟ้าในไฟฉาย'),
  ('ว 2.3', 'ป.6', 3, 'การต่อหลอดไฟฟ้าแบบอนุกรมเมื่อถอดหลอดไฟฟ้าดวงใดดวงหนึ่งออกทำให้หลอดไฟฟ้าที่เหลือดับทั้งหมด ส่วนการต่อหลอดไฟฟ้าแบบขนาน เมื่อถอดหลอดไฟฟ้าดวงใดดวงหนึ่งออกหลอดไฟฟ้าที่เหลือก็ยังสว่างได้ การต่อหลอดไฟฟ้าแต่ละแบบสามารถนำไปใช้ประโยชน์ได้เช่น การต่อหลอดไฟฟ้าหลายดวงในบ้านจึงต้องต่อหลอดไฟฟ้าแบบขนาน เพื่อเลือกใช้หลอดไฟฟ้าดวงใดดวงหนึ่งได้ตามต้องการ'),
  ('ว 2.3', 'ป.6', 4, 'เมื่อนำวัตถุทึบแสงมากั้นแสงจะเกิดเงาบนฉากรับแสงที่อยู่ด้านหลังวัตถุ โดยเงามีรูปร่างคล้ายวัตถุที่ทำให้เกิดเงา เงามัวเป็นบริเวณที่มีแสงบางส่วนตกลงบนฉาก ส่วนเงามืดเป็นบริเวณที่ไม่มีแสงตกลงบนฉากเลย'),
  ('ว 2.3', 'ม.1', 1, 'เมื่อสสารได้รับหรือสูญเสียความร้อนอาจทำให้สสารเปลี่ยนอุณหภูมิ เปลี่ยนสถานะ หรือเปลี่ยนรูปร่าง'),
  ('ว 2.3', 'ม.1', 2, 'ปริมาณความร้อนที่ทำให้สสารเปลี่ยนอุณหภูมิขึ้นกับมวล ความร้อนจำเพาะ และอุณหภูมิที่เปลี่ยนไป'),
  ('ว 2.3', 'ม.1', 3, 'ปริมาณความร้อนที่ทำให้สสารเปลี่ยนสถานะขึ้นกับมวลและความร้อนแฝงจำเพาะ โดยขณะที่สสารเปลี่ยนสถานะ อุณหภูมิจะไม่เปลี่ยนแปลง'),
  ('ว 2.3', 'ม.1', 4, 'ความร้อนทำให้สสารขยายตัวหรือหดตัวได้เนื่องจากเมื่อสสารได้รับความร้อนจะทำให้อนุภาคเคลื่อนที่เร็วขึ้น ทำให้เกิดการขยายตัวแต่เมื่อสสารคายความร้อนจะทำให้อนุภาคเคลื่อนที่ช้าลง ทำให้เกิดการหดตัว'),
  ('ว 2.3', 'ม.1', 5, 'ความรู้เรื่องการหดและขยายตัวของสสารเนื่องจากความร้อนนำไปใช้ประโยชน์ได้ด้านต่าง ๆ เช่น การสร้างถนน การสร้างรางรถไฟการทำเทอร์มอมิเตอร์'),
  ('ว 2.3', 'ม.1', 6, 'ความร้อนถ่ายโอนจากสสารที่มีอุณหภูมิสูงกว่าไปยังสสารที่มีอุณหภูมิต่ำกว่าจนกระทั่งอุณหภูมิของสสารทั้งสองเท่ากัน สภาพที่สสารทั้งสองมีอุณหภูมิเท่ากัน เรียกว่า สมดุลความร้อน'),
  ('ว 2.3', 'ม.1', 7, 'เมื่อมีการถ่ายโอนความร้อนจากสสารที่มีอุณหภูมิต่างกันจนเกิดสมดุลความร้อนความร้อนที่เพิ่มขึ้นของสสารหนึ่งจะเท่ากับความร้อนที่ลดลงของอีกสสารหนึ่ง ซึ่งเป็นไปตามกฎการอนุรักษ์พลังงาน'),
  ('ว 2.3', 'ม.1', 8, 'การถ่ายโอนความร้อนมี 3 แบบ คือการนำความร้อน การพาความร้อน และการแผ่รังสีความร้อน การนำความร้อนเป็นการถ่ายโอนความร้อนที่อาศัยตัวกลาง โดยที่ตัวกลางไม่เคลื่อนที่ การพาความร้อนเป็นการถ่ายโอนความร้อนที่อาศัยตัวกลาง โดยที่ตัวกลางเคลื่อนที่ไปด้วย ส่วนการแผ่รังสีความร้อนเป็นการถ่ายโอนความร้อนที่ไม่ต้องอาศัยตัวกลาง'),
  ('ว 2.3', 'ม.1', 9, 'ความรู้เกี่ยวกับการถ่ายโอนความร้อนสามารถนำไปใช้ประโยชน์ในชีวิตประจำวันได้ เช่นการเลือกใช้วัสดุเพื่อนำมาทำภาชนะบรรจุอาหารเพื่อเก็บความร้อน หรือการออกแบบระบบระบายความร้อนในอาคาร'),
  ('ว 2.3', 'ม.2', 1, 'เมื่อออกแรงกระทำต่อวัตถุ แล้วทำให้วัตถุเคลื่อนที่ โดยแรงอยู่ในแนวเดียวกับการเคลื่อนที่จะเกิดงาน งานจะมีค่ามากหรือน้อยขึ้นกับขนาดของแรงและระยะทางในแนวเดียวกับแรง'),
  ('ว 2.3', 'ม.2', 2, 'งานที่ทำในหนึ่งหน่วยเวลาเรียกว่า กำลัง หลักการของงานนำไปอธิบายการทำงานของเครื่องกลอย่างง่าย ได้แก่ คาน พื้นเอียง รอกเดี่ยว ลิ่มสกรู ล้อและเพลา ซี่งนำไปใช้ประโยชน์ด้านต่าง ๆ ในชีวิตประจำวัน'),
  ('ว 2.3', 'ม.2', 3, 'พลังงานจลน์เป็นพลังงานของวัตถุที่เคลื่อนที่พลังงานจลน์จะมีค่ามากหรือน้อยขึ้นกับมวลและอัตราเร็ว ส่วนพลังงานศักย์โน้มถ่วงเกี่ยวข้องกับตำแหน่งของวัตถุ จะมีค่ามากหรือน้อยขึ้นกับมวลและตำแหน่งของวัตถุ เมื่อวัตถุอยู่ในสนามโน้มถ่วง วัตถุจะมีพลังงานศักย์โน้มถ่วงพลังงานจลน์และพลังงานศักย์โน้มถ่วงเป็นพลังงานกล'),
  ('ว 2.3', 'ม.2', 4, 'ผลรวมของพลังงานศักย์โน้มถ่วงและพลังงานจลน์เป็นพลังงานกล พลังงานศักย์โน้มถ่วงและพลังงานจลน์ของวัตถุหนึ่ง ๆ สามารถเปลี่ยนกลับไปมาได้ โดยผลรวมของพลังงานศักย์โน้มถ่วงและพลังงานจลน์มีค่าคงตัว นั่นคือพลังงานกลของวัตถุมีค่าคงตัว'),
  ('ว 2.3', 'ม.2', 5, 'พลังงานรวมของระบบมีค่าคงตัวซึ่งอาจเปลี่ยนจากพลังงานหนึ่งเป็นอีกพลังงานหนึ่ง เช่นพลังงานกลเปลี่ยนเป็นพลังงานไฟฟ้าพลังงานจลน์เปลี่ยนเป็นพลังงานความร้อนพลังงานเสียง พลังงานแสง เนื่องมาจากแรงเสียดทาน พลังงานเคมีในอาหารเปลี่ยนเป็นพลังงานที่ไปใช้ในการทำงานของสิ่งมีชีวิต'),
  ('ว 2.3', 'ม.2', 6, 'นอกจากนี้พลังงานยังสามารถถ่ายโอนไปยังอีกระบบหนึ่งหรือได้รับพลังงานจากระบบอื่นได้เช่น การถ่ายโอนความร้อนระหว่างสสารการถ่ายโอนพลังงานของการสั่นของแหล่งกำเนิดเสียงไปยังผู้ฟัง ทั้งการเปลี่ยนพลังงานและการถ่ายโอนพลังงาน พลังงานรวมทั้งหมดมีค่าเท่าเดิมตามกฎการอนุรักษ์พลังงาน'),
  ('ว 2.3', 'ม.3', 1, 'เมื่อต่อวงจรไฟฟ้าครบวงจรจะมีกระแสไฟฟ้าออกจากขั้วบวกผ่านวงจรไฟฟ้าไปยังขั้วลบของแหล่งกำเนิดไฟฟ้า ซึ่งวัดค่าได้จากแอมมิเตอร์'),
  ('ว 2.3', 'ม.3', 2, 'ค่าที่บอกความแตกต่างของพลังงานไฟฟ้าต่อหน่วยประจุระหว่างจุด 2 จุด เรียกว่า ความต่างศักย์ซึ่งวัดค่าได้จากโวลต์มิเตอร์'),
  ('ว 2.3', 'ม.3', 3, 'ขนาดของกระแสไฟฟ้ามีค่าแปรผันตรงกับความต่างศักย์ระหว่างปลายทั้งสองของตัวนำโดยอัตราส่วนระหว่างความต่างศักย์และกระแสไฟฟ้ามีค่าคงที่ เรียกค่าคงที่นี้ว่า ความต้านทาน'),
  ('ว 2.3', 'ม.3', 4, 'ในวงจรไฟฟ้าประกอบด้วยแหล่งกำเนิดไฟฟ้าสายไฟฟ้า และอุปกรณ์ไฟฟ้า โดยอุปกรณ์ไฟฟ้าแต่ละชิ้นมีความต้านทาน ในการต่อตัวต้านทานหลายตัว มีทั้งต่อแบบอนุกรมและแบบขนาน'),
  ('ว 2.3', 'ม.3', 5, 'การต่อตัวต้านทานหลายตัวแบบอนุกรมในวงจรไฟฟ้า ความต่างศักย์ที่คร่อมตัวต้านทานแต่ละตัวมีค่าเท่ากับผลรวมของความต่างศักย์ที่คร่อมตัวต้านทานแต่ละตัว โดยกระแสไฟฟ้าที่ผ่านตัวต้านทานแต่ละตัวมีค่าเท่ากัน'),
  ('ว 2.3', 'ม.3', 6, 'การต่อตัวต้านทานหลายตัวแบบขนานในวงจรไฟฟ้า กระแสไฟฟ้าที่ผ่านวงจรมีค่าเท่ากับผลรวมของกระแสไฟฟ้าที่ผ่านตัวต้านทานแต่ละตัวโดยความต่างศักย์ที่คร่อมตัวต้านทานแต่ละตัวมีค่าเท่ากัน'),
  ('ว 2.3', 'ม.3', 7, 'ชิ้นส่วนอิเล็กทรอนิกส์มีหลายชนิด เช่น ตัวต้านทานไดโอด ทรานซิสเตอร์ ตัวเก็บประจุ โดยชิ้นส่วนแต่ละชนิดทำหน้าที่แตกต่างกันเพื่อให้วงจรทำงานได้ตามต้องการ'),
  ('ว 2.3', 'ม.3', 8, 'ตัวต้านทานทำหน้าที่ควบคุมปริมาณกระแสไฟฟ้าในวงจรไฟฟ้า ไดโอดทำหน้าที่ให้กระแสไฟฟ้าผ่านทางเดียว ทรานซิสเตอร์ทำหน้าที่เป็นสวิตช์ปิดหรือเปิดวงจรไฟฟ้าและควบคุมปริมาณกระแสไฟฟ้า ตัวเก็บประจุทำหน้าที่เก็บและคายประจุไฟฟ้า'),
  ('ว 2.3', 'ม.3', 9, 'เครื่องใช้ไฟฟ้าอย่างง่ายประกอบด้วยชิ้นส่วนอิเล็กทรอนิกส์หลายชนิดที่ทำงานร่วมกันการต่อวงจรอิเล็กทรอนิกส์โดยเลือกใช้ชิ้นส่วนอิเล็กทรอนิกส์ที่เหมาะสมตามหน้าที่ของชิ้นส่วนนั้น ๆ จะสามารถทำให้วงจรไฟฟ้าทำงานได้ตามต้องการ'),
  ('ว 2.3', 'ม.3', 10, 'เครื่องใช้ไฟฟ้าจะมีค่ากำลังไฟฟ้าและความต่างศักย์กำกับไว้ กำลังไฟฟ้ามีหน่วยเป็นวัตต์ ความต่างศักย์มีหน่วยเป็นโวลต์ ค่าไฟฟ้าส่วนใหญ่คิดจากพลังงานไฟฟ้าที่ใช้ทั้งหมด ซึ่งหาได้จากผลคูณของกำลังไฟฟ้า ในหน่วยกิโลวัตต์ กับเวลาในหน่วยชั่วโมง พลังงานไฟฟ้ามีหน่วยเป็นกิโลวัตต์ ชั่วโมง หรือหน่วย'),
  ('ว 2.3', 'ม.3', 11, 'วงจรไฟฟ้าในบ้านมีการต่อเครื่องใช้ไฟฟ้าแบบขนานเพื่อให้ความต่างศักย์เท่ากัน การใช้เครื่องใช้ไฟฟ้าในชีวิตประจำวันต้องเลือกใช้เครื่องใช้ไฟฟ้าที่มีความต่างศักย์และกำลังไฟฟ้าให้เหมาะกับการใช้งาน และการใช้เครื่องใช้ไฟฟ้าและอุปกรณ์ไฟฟ้าต้องใช้อย่างถูกต้อง ปลอดภัย และประหยัด'),
  ('ว 2.3', 'ม.3', 12, 'คลื่นเกิดจากการส่งผ่านพลังงานโดยอาศัยตัวกลางและไม่อาศัยตัวกลาง ในคลื่นกล พลังงานจะถูกถ่ายโอนผ่านตัวกลางโดยอนุภาคของตัวกลางไม่เคลื่อนที่ไปกับคลื่น คลื่นที่แผ่ออกมาจากแหล่งกำเนิดคลื่นอย่างต่อเนื่องและมีรูปแบบที่ซ้ำกัน บรรยายได้ด้วยความยาวคลื่น ความถี่แอมพลิจูด'),
  ('ว 2.3', 'ม.3', 13, 'คลื่นแม่เหล็กไฟฟ้าเป็นคลื่นที่ไม่อาศัยตัวกลางในการเคลื่อนที่ มีความถี่ต่อเนื่องเป็นช่วงกว้างมากเคลื่อนที่ในสุญญากาศด้วยอัตราเร็วเท่ากันแต่จะเคลื่อนที่ด้วยอัตราเร็วต่างกันในตัวกลางอื่นคลื่นแม่เหล็กไฟฟ้าแบ่งออกเป็นช่วงความถี่ต่าง ๆ เรียกว่า สเปกตรัมของคลื่นแม่เหล็กไฟฟ้า แต่ละช่วงความถี่มีชื่อเรียกต่างกัน ได้แก่ คลื่นวิทยุไมโครเวฟ อินฟราเรด แสงที่มองเห็น อัลตราไวโอเลตรังสีเอกซ์และรังสีแกมมา ซึ่งสามารถนำไปใช้ประโยชน์ได้'),
  ('ว 2.3', 'ม.3', 14, 'เลเซอร์เป็นคลื่นแม่เหล็กไฟฟ้าที่มีความยาวคลื่นเดียว เป็นลำแสงขนานและมีความเข้มสูง นำไปใช้ประโยชน์ในด้านต่าง ๆ เช่น ด้านการสื่อสารมีการใช้เลเซอร์สำหรับส่งสารสนเทศผ่านเส้นใยนำแสง โดยอาศัยหลักการการสะท้อนกลับหมดของแสง ด้านการแพทย์ใช้ในการผ่าตัด'),
  ('ว 2.3', 'ม.3', 15, 'คลื่นแม่เหล็กไฟฟ้านอกจากจะสามารถนำไปใช้ประโยชน์แล้ว ยังมีโทษต่อมนุษย์ด้วย เช่นถ้ามนุษย์ได้รับรังสีอัลตราไวโอเลตมากเกินไปอาจจะทำให้เกิดมะเร็งผิวหนัง หรือถ้าได้รังสีแกมมาซึ่งเป็นคลื่นแม่เหล็กไฟฟ้าที่มีพลังงานสูงและสามารถทะลุผ่านเซลล์และอวัยวะได้อาจทำลายเนื้อเยื่อหรืออาจทำให้เสียชีวิตได้เมื่อได้รับรังสีแกมมาในปริมาณสูง'),
  ('ว 2.3', 'ม.3', 16, 'เมื่อแสงตกกระทบวัตถุจะเกิดการสะท้อนซึ่งเป็นไปตามกฎการสะท้อนของแสง โดยรังสีตกกระทบเส้นแนวฉาก รังสีสะท้อนอยู่ในระนาบเดียวกันและมุมตกกระทบเท่ากับมุมสะท้อน ภาพจากกระจกเงาเกิดจากรังสีสะท้อนตัดกันหรือต่อแนวรังสีสะท้อนให้ตัดกัน โดยถ้ารังสีสะท้อนตัดกันจริงจะเกิดภาพจริง แต่ถ้าต่อแนวรังสีสะท้อนให้ไปตัดกัน จะเกิดภาพเสมือน'),
  ('ว 2.3', 'ม.3', 17, 'เมื่อแสงเดินทางผ่านตัวกลางโปร่งใสที่แตกต่างกัน เช่น อากาศและน้ำ อากาศและแก้ว จะเกิดการหักเห หรืออาจเกิดการสะท้อนกลับหมดในตัวกลางที่แสงตกกระทบ การหักเหของแสงผ่านเลนส์ทำให้เกิดภาพที่มีชนิดและขนาดต่าง ๆ'),
  ('ว 2.3', 'ม.3', 18, 'แสงขาวประกอบด้วยแสงสีต่าง ๆ เมื่อแสงขาวผ่านปริซึมจะเกิดการกระจายแสงเป็นแสงสีต่าง ๆ เรียกว่า สเปกตรัมของแสงขาว เมื่อเคลื่อนที่ในตัวกลางใด ๆ ที่ไม่ใช่อากาศ จะมีอัตราเร็วต่างกันจึงมีการหักเหต่างกัน'),
  ('ว 2.3', 'ม.3', 19, 'การสะท้อนและการหักเหของแสงนำไปใช้อธิบายปรากฏการณ์ที่เกี่ยวกับแสง เช่น รุ้ง มิราจ และอธิบายการทำงานของทัศนอุปกรณ์ เช่น แว่นขยายกระจกโค้งจราจร กล้องโทรทรรศน์กล้องจุลทรรศน์ และแว่นสายตา'),
  ('ว 2.3', 'ม.3', 20, 'ในการมองวัตถุ เลนส์ตาจะถูกปรับโฟกัส เพื่อให้เกิดภาพชัดที่จอตา ความบกพร่องทางสายตาเช่น สายตาสั้น และสายตายาว เป็นเพราะตำแหน่งที่เกิดภาพไม่ได้อยู่ที่จอตาพอดี จึงต้องใช้เลนส์ในการแก้ไขเพื่อช่วยให้มองเห็นเหมือนคนสายตาปกติ โดยคนสายตาสั้นใช้เลนส์เว้า ส่วนคนสายตายาวใช้เลนส์นูน'),
  ('ว 2.3', 'ม.3', 21, 'ความสว่างของแสงมีผลต่อดวงตามนุษย์ การใช้สายตาในสภาพแวดล้อมที่มีความสว่างไม่เหมาะสมจะเป็นอันตรายต่อดวงตา เช่น การดูวัตถุในที่มีความสว่างมากหรือน้อยเกินไป การจ้องดูหน้าจอภาพเป็นเวลานาน ความสว่างบนพื้นที่รับแสงมีหน่วยเป็นลักซ์ ความรู้เกี่ยวกับความสว่างสามารถนำมาใช้จัดความสว่างให้เหมาะสมกับการทำกิจกรรมต่าง ๆ เช่น การจัดความสว่างที่เหมาะสมสำหรับการอ่านหนังสือ'),
  ('ว 2.3', 'ม.5', 1, 'พลังงานที่ปลดปล่อยออกมาจากฟิชชัน หรือฟิวชันเรียกว่า พลังงานนิวเคลียร์ โดยฟิชชันเป็นปฏิกิริยาที่นิวเคลียสที่มีมวลมากแตกออกเป็นนิวเคลียสที่มีมวลน้อยกว่า ส่วนฟิวชันเป็นปฏิกิริยาที่นิวเคลียสที่มีมวลน้อยรวมตัวกันเกิดเป็นนิวเคลียสที่มีมวลมากขึ้น พลังงานนิวเคลียร์ที่ปลดปล่อยออกมาจากฟิชชันและฟิวชัน มีค่าเป็นไปตามความสัมพันธ์ระหว่างมวลกับพลังงาน'),
  ('ว 2.3', 'ม.5', 2, 'การนำพลังงานทดแทนมาใช้เป็นการแก้ปัญหาหรือตอบสนองความต้องการด้านพลังงาน เช่นการเปลี่ยนพลังงานนิวเคลียร์เป็นพลังงานไฟฟ้าในโรงไฟฟ้านิวเคลียร์ และการเปลี่ยนพลังงานแสงอาทิตย์เป็นพลังงานไฟฟ้าโดยเซลล์สุริยะ'),
  ('ว 2.3', 'ม.5', 3, 'เทคโนโลยีต่าง ๆ ที่นำมาแก้ปัญหาหรือตอบสนองความต้องการทางด้านพลังงานเป็นการนำความรู้ทักษะและกระบวนการทางวิทยาศาสตร์มาสร้างอุปกรณ์หรือผลิตภัณฑ์ต่าง ๆ ที่ช่วยให้การใช้พลังงานมีประสิทธิภาพยิ่งขึ้น'),
  ('ว 2.3', 'ม.5', 4, 'เมื่อคลื่นเคลื่อนที่ไปพบสิ่งกีดขวาง จะเกิดการสะท้อน เมื่อคลื่นเคลื่อนที่ผ่านรอยต่อระหว่างตัวกลางที่ต่างกัน จะเกิดการหักเห เมื่อคลื่นเคลื่อนที่ไปพบขอบสิ่งกีดขวางจะเกิดการเลี้ยวเบนเมื่อคลื่นสองขบวนมาพบกันจะเกิดการรวมคลื่นเกิดรูปร่างของคลื่นรวม หลังจากคลื่นทั้งสองเคลื่อนที่ผ่านพ้นกันแล้วจะแยกกัน โดยแต่ละคลื่นยังคงมีรูปร่างและทิศทางเดิม'),
  ('ว 2.3', 'ม.5', 5, 'เมื่อกระตุ้นให้วัตถุสั่นแล้วหยุดกระตุ้น วัตถุจะสั่นด้วยความถี่ที่เรียกว่า ความถี่ธรรมชาติ ถ้ามีแรงกระตุ้นวัตถุที่กำลังสั่นด้วยความถี่ของการออกแรงตรงกับความถี่ธรรมชาติของวัตถุนั้นจะทำให้วัตถุสั่นด้วยแอมพลิจูดมากขึ้น เรียกว่าการสั่นพ้อง เช่น การสั่นพ้องของอาคารสูงการสั่นพ้องของสะพาน การสั่นพ้องของเสียงในเครื่องดนตรีประเภทเป่า'),
  ('ว 2.3', 'ม.5', 6, 'เสียงมีการสะท้อน การหักเห การเลี้ยวเบนและการรวมคลื่นเช่นเดียวกับคลื่นอื่น ๆ'),
  ('ว 2.3', 'ม.5', 7, 'ความถี่ของคลื่นเสียงเป็นปริมาณที่ใช้บอกเสียงสูงเสียงต่ำ โดยความถี่ที่คนได้ยินมีค่าอยู่ระหว่าง20-20,000 เฮิรตซ์ ระดับเสียงเป็นปริมาณที่ใช้บอกความดังของเสียงซึ่งขึ้นกับความเข้มเสียงโดยความเข้มเสียงเป็นพลังงานเสียงที่ตกตั้งฉากบนพื้นที่หนึ่งหน่วยในหนึ่งหน่วยเวลา เสียงที่มีความดังมากเกินไปเป็นอันตรายต่อหู'),
  ('ว 2.3', 'ม.5', 8, 'เมื่อเสียงจากแหล่งกำเนิดเดินทางไปกระทบวัตถุแล้วสะท้อนกลับมายังผู้ฟัง ถ้าผู้ฟังได้ยินเสียงที่ออกจากแหล่งกำเนิดและเสียงที่สะท้อนกลับมาแยกจากกัน เสียงที่ได้ยินนี้เป็นเสียงสะท้อนกลับ'),
  ('ว 2.3', 'ม.5', 9, 'เมื่อคลื่นเสียงสองขบวนที่มีความถี่ใกล้เคียงกันมารวมกันจะเกิดบีต'),
  ('ว 2.3', 'ม.5', 10, 'เมื่อแหล่งกำเนิดเสียงเคลื่อนที่ ผู้ฟังเคลื่อนที่ หรือทั้งแหล่งกำเนิดและผู้ฟังเคลื่อนที่ ผู้ฟังจะได้ยินเสียงที่มีความถี่เปลี่ยนไป เรียกว่า ปรากฏการณ์ดอปเพลอร์'),
  ('ว 2.3', 'ม.5', 11, 'ถ้าอากาศในท่อถูกกระตุ้นด้วยคลื่นเสียงที่มีความถี่เท่ากับความถี่ธรรมชาติของอากาศในท่อนั้นจะเกิดการสั่นพ้องของเสียง'),
  ('ว 2.3', 'ม.5', 12, 'ความรู้เกี่ยวกับเสียงนำไปใช้ประโยชน์ในด้านต่าง ๆ เช่น คลื่นเหนือเสียงหรืออัลตราซาวนด์ใช้ในทางการแพทย์ บีตของเสียงในการปรับเทียบเสียงของเครื่องดนตรี การสั่นพ้องของเสียงใช้ในการออกแบบเครื่องดนตรีและอธิบายการเปล่งเสียงของมนุษย์'),
  ('ว 2.3', 'ม.5', 13, 'เมื่อแสงตกกระทบวัตถุ วัตถุจะดูดกลืนแสงสีบางสีโดยขึ้นกับสารสีบนผิววัตถุ และสะท้อนแสงสีที่เหลือออกมา ทำให้มองเห็นวัตถุเป็นสีต่าง ๆ ขึ้นกับแสงสีที่สะท้อนออกมา ความผิดปกติในการมองเห็นสีหรือการบอดสีเกิดจากความบกพร่องของเซลล์รูปกรวยบนจอตา'),
  ('ว 2.3', 'ม.5', 14, 'แผ่นกรองแสงสียอมให้แสงสีบางสีผ่านออกไปได้และกั้นบางแสงสี'),
  ('ว 2.3', 'ม.5', 15, 'การผสมแสงสีทำให้ได้แสงสีที่หลากหลายเปลี่ยนไปจากเดิม ถ้านำแสงสีปฐมภูมิในสัดส่วนที่เหมาะสมมาผสมกันจะได้แสงขาว'),
  ('ว 2.3', 'ม.5', 16, 'การผสมสารสีทำให้ได้สารสีที่หลากหลายเปลี่ยนไปจากเดิม ถ้านำสารสีปฐมภูมิในปริมาณที่เท่ากันมาผสมกันจะได้สารสีผสมเป็นสีดำ'),
  ('ว 2.3', 'ม.5', 17, 'การผสมแสงสีและการผสมสารสีสามารถนำไปใช้ประโยชน์ในด้านต่าง ๆ เช่น ด้านศิลปะด้านการแสดง'),
  ('ว 2.3', 'ม.5', 18, 'คลื่นแม่เหล็กไฟฟ้าประกอบด้วยสนามแม่เหล็กและสนามไฟฟ้าที่เปลี่ยนแปลงตลอดเวลาโดยสนามทั้งสองมีทิศทางตั้งฉากกัน และตั้งฉากกับทิศทางการเคลื่อนที่ของคลื่น'),
  ('ว 2.3', 'ม.5', 19, 'อุปกรณ์บางชนิดทำงานโดยอาศัยคลื่นแม่เหล็กไฟฟ้าเช่น เครื่องควบคุมระยะไกล เครื่องถ่ายภาพเอกซเรย์คอมพิวเตอร์ และเครื่องถ่ายภาพการสั่นพ้องแม่เหล็ก'),
  ('ว 2.3', 'ม.5', 20, 'ในการสื่อสารโดยอาศัยคลื่นแม่เหล็กไฟฟ้าเพื่อส่งผ่านสารสนเทศจากที่หนึ่งไปอีกที่หนึ่งสารสนเทศจะถูกแปลงให้อยู่ในรูปสัญญาณสำหรับส่งไปยังปลายทางซึ่งจะมีการแปลงสัญญาณกลับมาเป็นสารสนเทศที่เหมือนเดิม'),
  ('ว 2.3', 'ม.5', 21, 'สัญญาณที่ใช้ในการสื่อสารมีสองชนิด คือแอนะล็อกและดิจิทัล การส่งผ่านสารสนเทศด้วยสัญญาณดิจิทัลสามารถส่งผ่านได้โดยมีความผิดพลาดน้อยกว่าสัญญาณแอนะล็อก'),
  ('ว 3.1', 'ป.1', 1, 'บนท้องฟ้ามีดวงอาทิตย์ ดวงจันทร์ และดาวซึ่งในเวลากลางวันจะมองเห็นดวงอาทิตย์และอาจมองเห็นดวงจันทร์บางเวลาในบางวันแต่ไม่สามารถมองเห็นดาว'),
  ('ว 3.1', 'ป.1', 2, 'ในเวลากลางวันมองไม่เห็นดาวส่วนใหญ่ เนื่องจากแสงอาทิตย์สว่างกว่าจึงกลบแสงของดาว ส่วนในเวลากลางคืนจะมองเห็นดาวและมองเห็นดวงจันทร์เกือบทุกคืน'),
  ('ว 3.1', 'ป.3', 1, 'คนบนโลกมองเห็นดวงอาทิตย์ปรากฏขึ้นทางด้านหนึ่งและตกทางอีกด้านหนึ่งทุกวันหมุนเวียนเป็นแบบรูปซ้ำ ๆ'),
  ('ว 3.1', 'ป.3', 2, 'โลกกลมและหมุนรอบตัวเองขณะโคจรรอบดวงอาทิตย์ ทำให้บริเวณของโลกได้รับแสงอาทิตย์ไม่พร้อมกัน โลกด้านที่ได้รับแสงจากดวงอาทิตย์จะเป็นกลางวันส่วนด้านตรงข้ามที่ไม่ได้รับแสงจะเป็นกลางคืน นอกจากนี้คนบนโลกจะมองเห็นดวงอาทิตย์ปรากฏขึ้นทางด้านหนึ่ง ซึ่งกำหนดให้เป็นทิศตะวันออก และมองเห็นดวงอาทิตย์ตกทางอีกด้านหนึ่ง ซึ่งกำหนดให้เป็นทิศตะวันตกและเมื่อให้ด้านขวามืออยู่ทางทิศตะวันออกด้านซ้ายมืออยู่ทางทิศตะวันตก ด้านหน้าจะเป็นทิศเหนือ และด้านหลังจะเป็นทิศใต้'),
  ('ว 3.1', 'ป.3', 3, 'ในเวลากลางวันโลกจะได้รับพลังงานแสงและพลังงานความร้อนจากดวงอาทิตย์ ทำให้สิ่งมีชีวิตดำรงชีวิตอยู่ได้'),
  ('ว 3.1', 'ป.4', 1, 'ดวงจันทร์เป็นบริวารของโลก โดยดวงจันทร์หมุนรอบตัวเองขณะโคจรรอบโลก ขณะที่โลกก็หมุนรอบตัวเองด้วยเช่นกัน การหมุนรอบตัวเองของโลกจากทิศตะวันตกไปทิศตะวันออกในทิศทางทวนเข็มนาฬิกาเมื่อมองจากขั้วโลกเหนือทำให้มองเห็นดวงจันทร์ปรากฏขึ้นทางด้านทิศตะวันออกและตกทางด้านทิศตะวันตกหมุนเวียนเป็นแบบรูปซ้ำ ๆ'),
  ('ว 3.1', 'ป.4', 2, 'ดวงจันทร์เป็นวัตถุที่เป็นทรงกลม แต่รูปร่างของดวงจันทร์ที่มองเห็นหรือรูปร่างปรากฏของดวงจันทร์บนท้องฟ้าแตกต่างกันไปในแต่ละวันโดยในแต่ละวันดวงจันทร์จะมีรูปร่างปรากฏเป็นเสี้ยวที่มีขนาดเพิ่มขึ้นอย่างต่อเนื่องจนเต็มดวงจากนั้นรูปร่างปรากฏของดวงจันทร์จะแหว่งและมีขนาดลดลงอย่างต่อเนื่องจนมองไม่เห็นดวงจันทร์ จากนั้นรูปร่างปรากฏของดวงจันทร์จะเป็นเสี้ยวใหญ่ขึ้นจนเต็มดวงอีกครั้งการเปลี่ยนแปลงเช่นนี้เป็นแบบรูปซ้ำกันทุกเดือน'),
  ('ว 3.1', 'ป.4', 3, 'ระบบสุริยะเป็นระบบที่มีดวงอาทิตย์เป็นศูนย์กลางและมีบริวารประกอบด้วย ดาวเคราะห์แปดดวงและบริวาร ซึ่งดาวเคราะห์แต่ละดวงมีขนาดและระยะห่างจากดวงอาทิตย์แตกต่างกัน และยังประกอบด้วย ดาวเคราะห์แคระ ดาวเคราะห์น้อย ดาวหาง และวัตถุขนาดเล็กอื่น ๆ โคจรอยู่รอบดวงอาทิตย์ วัตถุขนาดเล็กอื่น ๆ เมื่อเข้ามาในชั้นบรรยากาศเนื่องจากแรงโน้มถ่วงของโลกทำให้เกิดเป็นดาวตกหรือผีพุ่งไต้และอุกกาบาต'),
  ('ว 3.1', 'ป.5', 1, 'ดาวที่มองเห็นบนท้องฟ้าอยู่ในอวกาศซึ่งเป็นบริเวณที่อยู่นอกบรรยากาศของโลก มีทั้งดาวฤกษ์และดาวเคราะห์ ดาวฤกษ์เป็นแหล่งกำเนิดแสงจึงสามารถมองเห็นได้ ส่วนดาวเคราะห์ไม่ใช่แหล่งกำเนิดแสง แต่สามารถมองเห็นได้เนื่องจากแสงจากดวงอาทิตย์ตกกระทบดาวเคราะห์แล้วสะท้อนเข้าสู่ตา'),
  ('ว 3.1', 'ป.5', 2, 'การมองเห็นกลุ่มดาวฤกษ์มีรูปร่างต่าง ๆ เกิดจากจินตนาการของผู้สังเกต กลุ่มดาวฤกษ์ต่าง ๆ ที่ปรากฏในท้องฟ้าแต่ละกลุ่มมีดาวฤกษ์แต่ละดวงเรียงกันที่ตำแหน่งคงที่ และมีเส้นทางการขึ้นและตกตามเส้นทางเดิมทุกคืน ซึ่งจะปรากฏตำแหน่งเดิม การสังเกตตำแหน่งและการขึ้นและตกของดาวฤกษ์ และกลุ่มดาวฤกษ์ สามารถทำได้โดยใช้แผนที่ดาว ซึ่งระบุมุมทิศและมุมเงยที่กลุ่มดาวนั้นปรากฏ ผู้สังเกตสามารถใช้มือในการประมาณค่าของมุมเงยเมื่อสังเกตดาวในท้องฟ้า'),
  ('ว 3.1', 'ป.6', 1, 'เมื่อโลกและดวงจันทร์ โคจรมาอยู่ในแนวเส้นตรงเดียวกันกับดวงอาทิตย์ในระยะทางที่เหมาะสมทำให้ดวงจันทร์บังดวงอาทิตย์ เงาของดวงจันทร์ทอดมายังโลก ผู้สังเกตที่อยู่บริเวณเงาจะมองเห็นดวงอาทิตย์มืดไป เกิดปรากฏการณ์สุริยุปราคาซึ่งมีทั้งสุริยุปราคาเต็มดวง สุริยุปราคาบางส่วนและสุริยุปราคาวงแหวน'),
  ('ว 3.1', 'ป.6', 2, 'หากดวงจันทร์และโลกโคจรมาอยู่ในแนวเส้นตรงเดียวกันกับดวงอาทิตย์ แล้วดวงจันทร์เคลื่อนที่ผ่านเงาของโลก จะมองเห็นดวงจันทร์มืดไปเกิดปรากฏการณ์จันทรุปราคา ซึ่งมีทั้งจันทรุปราคาเต็มดวง และจันทรุปราคาบางส่วน'),
  ('ว 3.1', 'ป.6', 3, 'เทคโนโลยีอวกาศเริ่มจากความต้องการของมนุษย์ในการสำรวจวัตถุท้องฟ้าโดยใช้ตาเปล่ากล้องโทรทรรศน์ และได้พัฒนาไปสู่การขนส่งเพื่อสำรวจอวกาศด้วยจรวดและยานขนส่งอวกาศและยังคงพัฒนาอย่างต่อเนื่อง ปัจจุบันมีการนำเทคโนโลยีอวกาศบางประเภทมาประยุกต์ใช้ในชีวิตประจำวัน เช่น การใช้ดาวเทียมเพื่อการสื่อสาร การพยากรณ์อากาศ หรือการสำรวจทรัพยากรธรรมชาติ การใช้อุปกรณ์วัดชีพจรและการเต้นของหัวใจ หมวกนิรภัย ชุดกีฬา'),
  ('ว 3.1', 'ม.3', 1, 'ในระบบสุริยะมีดวงอาทิตย์เป็นศูนย์กลางโดยมีดาวเคราะห์และบริวาร ดาวเคราะห์แคระดาวเคราะห์น้อย ดาวหาง และอื่น ๆ เช่น วัตถุคอยเปอร์โคจรอยู่โดยรอบ ซึ่งดาวเคราะห์ และวัตถุเหล่านี้โคจรรอบดวงอาทิตย์ด้วยแรงโน้มถ่วงแรงโน้มถ่วงเป็นแรงดึงดูดระหว่างวัตถุสองวัตถุโดยเป็นสัดส่วนกับผลคูณของมวลทั้งสอง และเป็นสัดส่วนผกผันกับกำลังสองของระยะทางระหว่าง 2 วัตถุทั้งสอง แสดงได้โดยสมการ F = (Gm m )/r 1 2 เมื่อ F แทนความโน้มถ่วงระหว่างมวลทั้งสอง G แทนค่านิจโน้มถ่วงสากล m แทนมวลของ 1 วัตถุแรก m แทนมวลของวัตถุที่สอง และ 2 r แทนระยะห่างระหว่างวัตถุทั้งสอง'),
  ('ว 3.1', 'ม.3', 2, 'การที่โลกโคจรรอบดวงอาทิตย์ในลักษณะที่แกนโลกเอียงกับแนวตั้งฉากของระนาบทางโคจรทำให้ส่วนต่าง ๆ บนโลกได้รับปริมาณแสงจากดวงอาทิตย์แตกต่างกันในรอบปี เกิดเป็นฤดูกลางวันกลางคืนยาวไม่เท่ากัน และตำแหน่งการขึ้นและตกของดวงอาทิตย์ที่ขอบฟ้าและเส้นทางการขึ้นและตกของดวงอาทิตย์เปลี่ยนไปในรอบปี ซึ่งส่งผลต่อการดำรงชีวิต'),
  ('ว 3.1', 'ม.3', 3, 'ดวงจันทร์โคจรรอบโลก โลกและดวงจันทร์โคจรรอบดวงอาทิตย์ ดวงจันทร์รับแสงจากดวงอาทิตย์ครึ่งดวงตลอดเวลา เมื่อดวงจันทร์โคจรรอบโลกได้หันส่วนสว่างมายังโลกแตกต่างกัน จึงทำให้คนบนโลกสังเกตส่วนสว่างของดวงจันทร์แตกต่างไปในแต่ละวันเกิดเป็นข้างขึ้นข้างแรม'),
  ('ว 3.1', 'ม.3', 4, 'ดวงจันทร์โคจรรอบโลกในทิศทางเดียวกันกับที่โลกหมุนรอบตัวเอง จึงทำให้เห็นดวงจันทร์ขึ้นช้าไปประมาณวันละ 50 นาที'),
  ('ว 3.1', 'ม.3', 5, 'แรงโน้มถ่วงที่ดวงจันทร์ ดวงอาทิตย์กระทำต่อโลกทำให้เกิดปรากฏการณ์น้ำขึ้นน้ำลง ซึ่งส่งผลต่อสิ่งแวดล้อมและสิ่งมีชีวิตบนโลก วันที่น้ำมีระดับการขึ้นสูงสุดและลงต่ำสุดเรียก วันน้ำเกิดส่วนวันที่ระดับน้ำมีการขึ้นและลงน้อยเรียกวันน้ำตาย โดยวันน้ำเกิด น้ำตาย มีความสัมพันธ์กับข้างขึ้นข้างแรม'),
  ('ว 3.1', 'ม.3', 6, 'เทคโนโลยีอวกาศได้มีบทบาทต่อการดำรงชีวิตของมนุษย์ในปัจจุบันมากมาย มนุษย์ได้ใช้ประโยชน์จากเทคโนโลยีอวกาศ เช่น ระบบนำทางด้วยดาวเทียม (GNSS) การติดตามพายุสถานการณ์ไฟป่า ดาวเทียมช่วยภัยแล้งการตรวจคราบน้ำมันในทะเล'),
  ('ว 3.1', 'ม.3', 7, 'โครงการสำรวจอวกาศต่าง ๆ ได้พัฒนาเพิ่มพูนความรู้ความเข้าใจต่อโลก ระบบสุริยะและเอกภพมากขึ้นเป็นลำดับ ตัวอย่างโครงการสำรวจอวกาศเช่น การสำรวจสิ่งมีชีวิตนอกโลก การสำรวจดาวเคราะห์นอกระบบสุริยะ การสำรวจดาวอังคารและบริวารอื่นของดวงอาทิตย์'),
  ('ว 3.1', 'ม.6', 1, 'ทฤษฎีกำเนิดเอกภพที่ยอมรับในปัจจุบัน คือทฤษฎีบิกแบง ระบุว่าเอกภพเริ่มต้นจากบิกแบงที่เอกภพมีขนาดเล็กมาก และมีอุณหภูมิสูงมากซึ่งเป็นจุดเริ่มต้นของเวลาและวิวัฒนาการของเอกภพ โดยหลังเกิดบิกแบง เอกภพเกิดการขยายตัวอย่างรวดเร็ว มีอุณหภูมิลดลง มีสสารคงอยู่ในรูปอนุภาคและปฏิยานุภาคหลายชนิด และมีวิวัฒนาการต่อเนื่องจนถึงปัจจุบัน ซึ่งมีเนบิวลากาแล็กซี ดาวฤกษ์ และระบบสุริยะเป็นสมาชิกบางส่วนของเอกภพ'),
  ('ว 3.1', 'ม.6', 2, 'หลักฐานสำคัญที่สนับสนุนทฤษฎีบิกแบง คือการขยายตัวของเอกภพ ซึ่งอธิบายด้วยกฎฮับเบิลโดยใช้ความสัมพันธ์ระหว่างความเร็วและระยะทางของกาแล็กซีที่เคลื่อนที่ห่างออกจากโลกและหลักฐานอีกประการ คือ การค้นพบไมโครเวฟพื้นหลัง ที่กระจายตัวอย่างสม่ำเสมอทุกทิศทางและสอดคล้องกับอุณหภูมิเฉลี่ยของอวกาศมีค่าประมาณ 2.73 เคลวิน'),
  ('ว 3.1', 'ม.6', 3, 'กาแล็กซี ประกอบด้วย ดาวฤกษ์จำนวนหลายแสนล้านดวง ซึ่งอยู่กันเป็นระบบของดาวฤกษ์นอกจากนี้ ยังประกอบด้วยเทห์ฟ้าอื่น เช่นเนบิวลา และสสารระหว่างดาว โดยองค์ประกอบต่าง ๆ ภายในของกาแล็กซีอยู่รวมกันด้วยแรงโน้มถ่วง'),
  ('ว 3.1', 'ม.6', 4, 'กาแล็กซีมีรูปร่างแตกต่างกัน โดยระบบสุริยะอยู่ในกาแล็กซีทางช้างเผือกซึ่งเป็นกาแล็กซีกังหันแบบมีคาน มีโครงสร้าง คือ นิวเคลียส จาน และฮาโล ดาวฤกษ์จำนวนมากอยู่ในบริเวณนิวเคลียสและจาน โดยมีระบบสุริยะอยู่ห่างจากจุดศูนย์กลางของกาแล็กซีทางช้างเผือก ประมาณ 30,000 ปีแสงซึ่งทางช้างเผือกที่สังเกตเห็นในท้องฟ้าเป็นบริเวณหนึ่งของกาแล็กซีทางช้างเผือกในมุมมองของคนบนโลก แถบฝ้าสีขาวจาง ๆ ของทางช้างเผือกคือดาวฤกษ์ ที่อยู่อย่างหนาแน่นในกาแล็กซีทางช้างเผือก'),
  ('ว 3.1', 'ม.6', 5, 'ดาวฤกษ์ส่วนใหญ่อยู่รวมกันเป็นระบบดาวฤกษ์คือ ดาวฤกษ์ที่อยู่รวมกันตั้งแต่ 2 ดวงขึ้นไปดาวฤกษ์เป็นก้อนแก๊สร้อนขนาดใหญ่ เกิดจากการยุบตัวของกลุ่มสสารในเนบิวลาภายใต้แรงโน้มถ่วง ทำให้บางส่วนของเนบิวลามีขนาดเล็กลงความดันและอุณหภูมิเพิ่มขึ้น เกิดเป็นดาวฤกษ์ก่อนเกิด เมื่ออุณหภูมิที่แก่นสูงขึ้นจนเกิดปฏิกิริยาเทอร์มอนิวเคลียร์ ดาวฤกษ์ก่อนเกิดจะกลายเป็นดาวฤกษ์ ดาวฤกษ์อยู่ในสภาพสมดุลระหว่างแรงดันกับแรงโน้มถ่วงซึ่งเรียกว่า สมดุลอุทกสถิตจึงทำให้ดาวฤกษ์มีเสถียรภาพและปลดปล่อยพลังงานเป็นเวลานาน ตลอดช่วงชีวิตของดาวฤกษ์'),
  ('ว 3.1', 'ม.6', 6, 'ปฏิกิริยาเทอร์มอนิวเคลียร์ เป็นปฏิกิริยาหลักของกระบวนการสร้างพลังงานของดาวฤกษ์ที่แก่นของดาวฤกษ์ ทำให้เกิดการหลอมนิวเคลียสของไฮโดรเจนเป็นนิวเคลียสฮีเลียมแล้วก่อให้เกิดพลังงานอย่างต่อเนื่อง'),
  ('ว 3.1', 'ม.6', 7, 'ความส่องสว่างของดาวฤกษ์เป็นพลังงานจากดาวฤกษ์ที่ปลดปล่อยออกมาในเวลา 1 วินาทีต่อหน่วยพื้นที่ ณ ตำแหน่งของผู้สังเกต แต่เนื่องจากตาของมนุษย์ไม่ตอบสนองต่อการเปลี่ยนแปลงความส่องสว่างที่มีค่าน้อย ๆ จึงกำหนดค่าการเปรียบเทียบความส่องสว่างของดาวฤกษ์ด้วยค่าโชติมาตร ซึ่งเป็นการแสดงระดับความส่องสว่างของดาวฤกษ์ ณ ตำแหน่งของผู้สังเกต'),
  ('ว 3.1', 'ม.6', 8, 'สีของดาวฤกษ์สัมพันธ์กับอุณหภูมิผิว และสเปกตรัมของดาวฤกษ์ ซึ่งนักดาราศาสตร์ใช้สเปกตรัมในการจำแนกชนิดของดาวฤกษ์'),
  ('ว 3.1', 'ม.6', 9, 'มวลของดาวฤกษ์ขึ้นอยู่กับมวลของดาวฤกษ์ก่อนเกิด ดาวฤกษ์ที่มีมวลมากจะผลิตและใช้พลังงานมาก จึงมีอายุสั้นกว่าดาวฤกษ์ที่มีมวลน้อย'),
  ('ว 3.1', 'ม.6', 10, 'ดาวฤกษ์มีการวิวัฒนาการที่แตกต่างกันการวิวัฒนาการและจุดจบของดาวฤกษ์ขึ้นอยู่กับมวลตั้งต้นของดาวฤกษ์ ส่วนใหญ่เทียบกับจำนวนเท่าของมวลดวงอาทิตย์'),
  ('ว 3.1', 'ม.6', 11, 'ระบบสุริยะเกิดจากการรวมตัวกันของกลุ่มฝุ่นและแก๊สที่เรียกว่า เนบิวลาสุริยะ โดยฝุ่นและแก๊สประมาณร้อยละ 99.8 ของมวล ได้รวมตัวเป็นดวงอาทิตย์ซึ่งเป็นก้อนแก๊สร้อน หรือ พลาสมาสสารส่วนที่เหลือรวมตัวเป็นดาวเคราะห์และบริวารอื่น ๆ ของดวงอาทิตย์ ดังนั้นจึงแบ่งเขตบริวารของดวงอาทิตย์ตามลักษณะการเกิดและองค์ประกอบ ได้แก่ ดาวเคราะห์ชั้นในดาวเคราะห์น้อย ดาวเคราะห์ชั้นนอก และดงดาวหาง'),
  ('ว 3.1', 'ม.6', 12, 'โลกเป็นดาวเคราะห์ในระบบสุริยะที่มีสิ่งมีชีวิตเพราะโคจรรอบดวงอาทิตย์ในระยะทางที่เหมาะสมอยู่ในเขตที่เอื้อต่อการมีสิ่งมีชีวิต มีอุณหภูมิเหมาะสมและสามารถเกิดน้ำที่ยังคงสถานะเป็นของเหลวได้ ปัจจุบันมีการค้นพบดาวเคราะห์ที่อยู่นอกระบบสุริยะจำนวนมาก และมีดาวเคราะห์บางดวงที่อยู่ในเขตที่เอื้อต่อการมีสิ่งมีชีวิตคล้ายโลก'),
  ('ว 3.1', 'ม.6', 13, 'ดวงอาทิตย์มีโครงสร้างภายในแบ่งเป็นแก่นเขตการแผ่รังสี และเขตการพาความร้อน และมีชั้นบรรยากาศอยู่เหนือเขตพาความร้อน ซึ่งแบ่งเป็น 3 คือ ชั้นโฟโตสเฟียร์ ชั้นโครโมสเฟียร์และคอโรนา ในชั้นบรรยากาศของดวงอาทิตย์มีปรากฏการณ์สำคัญ เช่น จุดมืดดวงอาทิตย์การลุกจ้า ที่ทำให้เกิดลมสุริยะ และพายุสุริยะซึ่งส่งผลต่อโลก'),
  ('ว 3.1', 'ม.6', 14, 'ลมสุริยะ เกิดจากการแพร่กระจายของอนุภาคจากชั้นคอโรนาออกสู่อวกาศตลอดเวลา อนุภาคที่หลุดออกสู่อวกาศเป็นอนุภาคที่มีประจุลมสุริยะส่งผลทำให้เกิดหางของดาวหางที่เรืองแสงและชี้ไปทางทิศตรงกันข้ามกับดวงอาทิตย์และเกิดปรากฏการณ์แสงเหนือ แสงใต้'),
  ('ว 3.1', 'ม.6', 15, 'พายุสุริยะ เกิดจากการปลดปล่อยอนุภาคมีประจุพลังงานสูงจำนวนมหาศาล มักเกิดบ่อยครั้งในช่วงที่มีการลุกจ้า และในช่วงที่มีจุดมืดดวงอาทิตย์จำนวนมาก และในบางครั้งมีการพ่นก้อนมวลคอโรนา พายุสุริยะอาจส่งผลต่อสนามแม่เหล็กโลก จึงอาจรบกวนระบบการส่งกระแสไฟฟ้าและการสื่อสาร รวมทั้งอาจส่งผลต่อวงจรอิเล็กทรอนิกส์ของดาวเทียม นอกจากนั้นมักทำให้เกิดปรากฏการณ์แสงเหนือ แสงใต้ที่สังเกตได้ชัดเจน'),
  ('ว 3.1', 'ม.6', 16, 'มนุษย์ใช้เทคโนโลยีอวกาศในการศึกษา เพื่อขยายขอบเขตความรู้ด้านวิทยาศาสตร์ และในขณะเดียวกันมนุษย์ได้นำเทคโนโลยีอวกาศมาใช้ประโยชน์ในด้านต่าง ๆ เช่น วัสดุศาสตร์ อาหารการแพทย์'),
  ('ว 3.1', 'ม.6', 17, 'นักวิทยาศาสตร์ได้สร้างกล้องโทรทรรศน์ เพื่อศึกษาแหล่งกำเนิดของรังสีหรืออนุภาคในอวกาศ ในช่วงความยาวคลื่นต่าง ๆ ได้แก่ คลื่นวิทยุ ไมโครเวฟอินฟราเรด แสง อัลตราไวโอเลต และรังสีเอ็กซ์'),
  ('ว 3.1', 'ม.6', 18, 'ยานอวกาศ คือ ยานพาหนะที่นำมนุษย์หรืออุปกรณ์ทางดาราศาสตร์ขึ้นไปสู่อวกาศ เพื่อสำรวจหรือเดินทางไปยังดาวดวงอื่น ส่วนสถานีอวกาศ คือ ห้องปฏิบัติการลอยฟ้า ที่โคจรรอบโลกใช้ในการศึกษาวิจัยทางวิทยาศาสตร์ในสาขาต่าง ๆ ในสภาพไร้น้ำหนัก'),
  ('ว 3.1', 'ม.6', 19, 'ดาวเทียม คือ อุปกรณ์ที่ใช้ในการสำรวจวัตถุท้องฟ้าและนำมาประยุกต์ใช้ในด้านต่าง ๆ เช่น การสื่อสารโทรคมนาคม การระบุตำแหน่งบนโลก การสำรวจทรัพยากรธรรมชาติ อุตุนิยมวิทยา โดยดาวเทียมมีหลายประเภทสามารถแบ่งได้ตามเกณฑ์วงโคจรและการใช้งาน'),
  ('ว 3.2', 'ป.1', 1, 'หินที่อยู่ในธรรมชาติมีลักษณะภายนอกเฉพาะตัวที่สังเกตได้ เช่น สี ลวดลาย น้ำหนัก ความแข็งและเนื้อหิน'),
  ('ว 3.2', 'ป.2', 1, 'ดินประกอบด้วยเศษหิน ซากพืช ซากสัตว์ผสมอยู่ในเนื้อดิน มีอากาศและน้ำแทรกอยู่ตามช่องว่างในเนื้อดิน ดินจำแนกเป็น ดินร่วน ดินเหนียวและดินทราย ตามลักษณะเนื้อดินและการจับตัวของดินซึ่งมีผลต่อการอุ้มน้ำที่แตกต่างกัน'),
  ('ว 3.2', 'ป.2', 2, 'ดินแต่ละชนิดนำไปใช้ประโยชน์ได้แตกต่างกันตามลักษณะและสมบัติของดิน'),
  ('ว 3.2', 'ป.3', 1, 'อากาศโดยทั่วไปไม่มีสี ไม่มีกลิ่น ประกอบด้วยแก๊สไนโตรเจน แก๊สออกซิเจน แก๊สคาร์บอนไดออกไซด์แก๊สอื่น ๆ รวมทั้งไอน้ำ และฝุ่นละออง อากาศมีความสำคัญต่อสิ่งมีชีวิต หากส่วนประกอบของอากาศไม่เหมาะสม เนื่องจากมีแก๊สบางชนิดหรือฝุ่นละอองในปริมาณมาก อาจเป็นอันตรายต่อสิ่งมีชีวิตชนิดต่าง ๆ จัดเป็นมลพิษทางอากาศ'),
  ('ว 3.2', 'ป.3', 2, 'แนวทางการปฏิบัติตนเพื่อลดการปล่อยมลพิษทางอากาศ เช่น ใช้พาหนะร่วมกัน หรือเลือกใช้เทคโนโลยีที่ลดมลพิษทางอากาศ'),
  ('ว 3.2', 'ป.3', 3, 'ลม คือ อากาศที่เคลื่อนที่ เกิดจากความแตกต่างกันของอุณหภูมิอากาศบริเวณที่อยู่ใกล้กัน โดยอากาศบริเวณที่มีอุณหภูมิสูงจะลอยตัวสูงขึ้น และอากาศบริเวณที่มีอุณหภูมิต่ำกว่าจะเคลื่อนเข้าไปแทนที่'),
  ('ว 3.2', 'ป.3', 4, 'ลมสามารถนำมาใช้เป็นแหล่งพลังงานทดแทนในการผลิตไฟฟ้า และนำไปใช้ประโยชน์ในการทำกิจกรรมต่าง ๆ ของมนุษย์ หากลมเคลื่อนที่ด้วยความเร็วสูงอาจทำให้เกิดอันตรายและความเสียหายต่อชีวิตและทรัพย์สินได้'),
  ('ว 3.2', 'ป.5', 1, 'โลกมีทั้งน้ำจืดและน้ำเค็มซึ่งอยู่ในแหล่งน้ำต่าง ๆ ที่มีทั้งแหล่งน้ำผิวดิน เช่น ทะเล มหาสมุทร บึงแม่น้ำ และแหล่งน้ำใต้ดิน เช่น น้ำในดิน และน้ำบาดาล น้ำทั้งหมดของโลกแบ่งเป็นน้ำเค็มประมาณร้อยละ 97.5 ซึ่งอยู่ในมหาสมุทรและแหล่งน้ำอื่น ๆ และที่เหลืออีกประมาณร้อยละ 2.5 เป็นน้ำจืด ถ้าเรียงลำดับปริมาณน้ำจืดจากมากไปน้อยจะอยู่ที่ ธารน้ำแข็ง และพืดน้ำแข็ง น้ำใต้ดิน ชั้นดินเยือกแข็งคงตัวและน้ำแข็งใต้ดิน ทะเลสาบ ความชื้นในดิน ความชื้นในบรรยากาศ บึง แม่น้ำ และน้ำในสิ่งมีชีวิต'),
  ('ว 3.2', 'ป.5', 2, 'น้ำจืดที่มนุษย์นำมาใช้ได้มีปริมาณน้อยมากจึงควรใช้น้ำอย่างประหยัดและร่วมกันอนุรักษ์น้ำ'),
  ('ว 3.2', 'ป.5', 3, 'วัฏจักรน้ำ เป็นการหมุนเวียนของน้ำที่มีแบบรูปซ้ำเดิม และต่อเนื่องระหว่างน้ำในบรรยากาศน้ำผิวดิน และน้ำใต้ดิน โดยพฤติกรรมการดำรงชีวิตของพืชและสัตว์ส่งผลต่อวัฏจักรน้ำ'),
  ('ว 3.2', 'ป.5', 4, 'ไอน้ำในอากาศจะควบแน่นเป็นละอองน้ำเล็ก ๆ โดยมีละอองลอย เช่น เกลือ ฝุ่นละออง ละอองเรณูของดอกไม้ เป็นอนุภาคแกนกลาง เมื่อละอองน้ำจำนวนมากเกาะกลุ่มรวมกันลอยอยู่สูงจากพื้นดินมาก เรียกว่า เมฆ แต่ละอองน้ำที่เกาะกลุ่มรวมกันอยู่ใกล้พื้นดิน เรียกว่า หมอกส่วนไอน้ำที่ควบแน่นเป็นละอองน้ำเกาะอยู่บนพื้นผิววัตถุใกล้พื้นดิน เรียกว่า น้ำค้างถ้าอุณหภูมิใกล้พื้นดินต่ำกว่าจุดเยือกแข็งน้ำค้างก็จะกลายเป็นน้ำค้างแข็ง'),
  ('ว 3.2', 'ป.5', 5, 'ฝน หิมะ ลูกเห็บ เป็นหยาดน้ำฟ้าซึ่งเป็นน้ำที่มีสถานะต่าง ๆ ที่ตกจากฟ้าถึงพื้นดิน ฝนเกิดจากละอองน้ำในเมฆที่รวมตัวกันจนอากาศไม่สามารถพยุงไว้ได้จึงตกลงมา หิมะเกิดจากไอน้ำในอากาศระเหิดกลับเป็นผลึกน้ำแข็ง รวมตัวกันจนมีน้ำหนักมากขึ้นจนเกินกว่าอากาศจะพยุงไว้จึงตกลงมาลูกเห็บเกิดจากหยดน้ำที่เปลี่ยนสถานะเป็นน้ำแข็งแล้วถูกพายุพัดวนซ้ำไปซ้ำมาในเมฆฝนฟ้าคะนองที่มีขนาดใหญ่และอยู่ในระดับสูงจนเป็นก้อนน้ำแข็งขนาดใหญ่ขึ้นแล้วตกลงมา'),
  ('ว 3.2', 'ป.6', 1, 'หินเป็นวัสดุแข็งเกิดขึ้นเองตามธรรมชาติประกอบด้วย แร่ตั้งแต่หนึ่งชนิดขึ้นไป สามารถจำแนกหินตามกระบวนการเกิดได้เป็น 3 ประเภทได้แก่ หินอัคนี หินตะกอน และหินแปร'),
  ('ว 3.2', 'ป.6', 2, 'หินอัคนีเกิดจากการเย็นตัวของแมกมา เนื้อหินมีลักษณะเป็นผลึก ทั้งผลึกขนาดใหญ่และขนาดเล็ก บางชนิดอาจเป็นเนื้อแก้วหรือมีรูพรุน'),
  ('ว 3.2', 'ป.6', 3, 'หินตะกอน เกิดจากการทับถมของตะกอนเมื่อถูกแรงกดทับและมีสารเชื่อมประสานจึงเกิดเป็นหินเนื้อหินกลุ่มนี้ส่วนใหญ่มีลักษณะเป็นเม็ดตะกอนมีทั้งเนื้อหยาบและเนื้อละเอียด บางชนิดเป็นเนื้อผลึกที่ยึดเกาะกันเกิดจากการตกผลึกหรือตกตะกอนจากน้ำโดยเฉพาะน้ำทะเล บางชนิดมีลักษณะเป็นชั้น ๆ จึงเรียกอีกชื่อว่า หินชั้น'),
  ('ว 3.2', 'ป.6', 4, 'หินแปร เกิดจากการแปรสภาพของหินเดิมซึ่งอาจเป็นหินอัคนี หินตะกอน หรือหินแปรโดยการกระทำของความร้อน ความดัน และปฏิกิริยาเคมี เนื้อหินของหินแปรบางชนิดผลึกของแร่เรียงตัวขนานกันเป็นแถบ บางชนิดแซะออกเป็นแผ่นได้ บางชนิดเป็นเนื้อผลึกที่มีความแข็งมาก'),
  ('ว 3.2', 'ป.6', 5, 'หินในธรรมชาติทั้ง 3 ประเภท มีการเปลี่ยนแปลงจากประเภทหนึ่งไปเป็นอีกประเภทหนึ่ง หรือประเภทเดิมได้ โดยมีแบบรูปการเปลี่ยนแปลงคงที่และต่อเนื่องเป็นวัฏจักร'),
  ('ว 3.2', 'ป.6', 6, 'หินและแร่แต่ละชนิดมีลักษณะและสมบัติแตกต่างกัน มนุษย์ใช้ประโยชน์จากแร่ในชีวิตประจำวันในลักษณะต่าง ๆ เช่น นำแร่มาทำเครื่องสำอาง ยาสีฟัน เครื่องประดับ อุปกรณ์ทางการแพทย์ และนำหินมาใช้ในงานก่อสร้างต่าง ๆ เป็นต้น'),
  ('ว 3.2', 'ป.6', 7, 'ซากดึกดำบรรพ์เกิดจากการทับถมหรือการประทับรอยของสิ่งมีชีวิตในอดีต จนเกิดเป็นโครงสร้างของซากหรือร่องรอยของสิ่งมีชีวิตที่ปรากฏอยู่ในหิน ในประเทศไทยพบซากดึกดำบรรพ์ที่หลากหลาย เช่น พืช ปะการังหอย ปลา เต่า ไดโนเสาร์ และรอยตีนสัตว์'),
  ('ว 3.2', 'ป.6', 8, 'ซากดึกดำบรรพ์สามารถใช้เป็นหลักฐานหนึ่งที่ช่วยอธิบายสภาพแวดล้อมของพื้นที่ในอดีตขณะเกิดสิ่งมีชีวิตนั้น เช่น หากพบซากดึกดำบรรพ์ของหอยน้ำจืด สภาพแวดล้อมบริเวณนั้นอาจเคยเป็นแหล่งน้ำจืดมาก่อน และหากพบซากดึกดำบรรพ์ของพืช สภาพแวดล้อมบริเวณนั้นอาจเคยเป็นป่ามาก่อน นอกจากนี้ซากดึกดำบรรพ์ยังสามารถใช้ระบุอายุของหิน และเป็นข้อมูลในการศึกษาวิวัฒนาการของสิ่งมีชีวิต'),
  ('ว 3.2', 'ป.6', 9, 'ลมบก ลมทะเล และมรสุม เกิดจากพื้นดินและพื้นน้ำ ร้อนและเย็นไม่เท่ากันทำให้อุณหภูมิอากาศเหนือพื้นดินและพื้นน้ำแตกต่างกัน จึงเกิดการเคลื่อนที่ของอากาศจากบริเวณที่มีอุณหภูมิต่ำไปยังบริเวณที่มีอุณหภูมิสูง'),
  ('ว 3.2', 'ป.6', 10, 'ลมบกและลมทะเลเป็นลมประจำถิ่นที่พบบริเวณชายฝั่ง โดยลมบกเกิดในเวลากลางคืน ทำให้มีลมพัดจากชายฝั่งไปสู่ทะเล ส่วนลมทะเลเกิดในเวลากลางวัน ทำให้มีลมพัดจากทะเลเข้าสู่ชายฝั่ง'),
  ('ว 3.2', 'ป.6', 11, 'มรสุมเป็นลมประจำฤดูเกิดบริเวณเขตร้อนของโลก ซึ่งเป็นบริเวณกว้างระดับภูมิภาคประเทศไทยได้รับผลจากมรสุมตะวันออกเฉียงเหนือในช่วงประมาณกลางเดือนตุลาคมจนถึงเดือนกุมภาพันธ์ทำให้เกิดฤดูหนาว และได้รับผลจากมรสุมตะวันตกเฉียงใต้ในช่วงประมาณกลางเดือนพฤษภาคมจนถึงกลางเดือนตุลาคมทำให้เกิดฤดูฝน ส่วนช่วงประมาณกลางเดือนกุมภาพันธ์จนถึงกลางเดือนพฤษภาคมเป็นช่วงเปลี่ยนมรสุมและประเทศไทยอยู่ใกล้เส้นศูนย์สูตร แสงอาทิตย์เกือบตั้งตรงและตั้งตรงประเทศไทยในเวลาเที่ยงวัน ทำให้ได้รับความร้อนจากดวงอาทิตย์อย่างเต็มที่ อากาศจึงร้อนอบอ้าวทำให้เกิดฤดูร้อน'),
  ('ว 3.2', 'ป.6', 12, 'น้ำท่วม การกัดเซาะชายฝั่ง ดินถล่ม แผ่นดินไหวและสึนามิ มีผลกระทบต่อชีวิตและสิ่งแวดล้อมแตกต่างกัน'),
  ('ว 3.2', 'ป.6', 13, 'มนุษย์ควรเรียนรู้วิธีปฏิบัติตนให้ปลอดภัย เช่นติดตามข่าวสารอย่างสม่ำเสมอ เตรียมถุงยังชีพให้พร้อมใช้ตลอดเวลา และปฏิบัติตามคำสั่งของผู้ปกครองและเจ้าหน้าที่อย่างเคร่งครัดเมื่อเกิดภัยธรรมชาติและธรณีพิบัติภัย'),
  ('ว 3.2', 'ป.6', 14, 'ปรากฏการณ์เรือนกระจกเกิดจากแก๊สเรือนกระจกในชั้นบรรยากาศของโลกกักเก็บความร้อนแล้วคายความร้อนบางส่วนกลับสู่ผิวโลก ทำให้อากาศบนโลกมีอุณหภูมิเหมาะสมต่อการดำรงชีวิต'),
  ('ว 3.2', 'ป.6', 15, 'หากปรากฏการณ์เรือนกระจกรุนแรงมากขึ้นจะมีผลต่อการเปลี่ยนแปลงภูมิอากาศโลกมนุษย์จึงควรร่วมกันลดกิจกรรมที่ก่อให้เกิดแก๊สเรือนกระจก'),
  ('ว 3.2', 'ม.1', 1, 'โลกมีบรรยากาศห่อหุ้ม นักวิทยาศาสตร์ใช้สมบัติและองค์ประกอบของบรรยากาศในการแบ่งบรรยากาศของโลกออกเป็นชั้น ซึ่งแบ่งได้หลายรูปแบบตามเกณฑ์ที่แตกต่างกัน โดยทั่วไปนักวิทยาศาสตร์ใช้เกณฑ์การเปลี่ยนแปลงอุณหภูมิตามความสูงแบ่งบรรยากาศได้เป็น 5 ได้แก่ ชั้นโทรโพสเฟียร์ชั้นสตราโตสเฟียร์ ชั้นมีโซสเฟียร์ ชั้นเทอร์โมสเฟียร์และชั้นเอกโซสเฟียร์'),
  ('ว 3.2', 'ม.1', 2, 'บรรยากาศแต่ละชั้นมีประโยชน์ต่อสิ่งมีชีวิตแตกต่างกัน โดยชั้นโทรโพสเฟียร์มีปรากฏการณ์ลมฟ้าอากาศที่สำคัญต่อการดำรงชีวิตของสิ่งมีชีวิตชั้นสตราโตสเฟียร์ช่วยดูดกลืนรังสีอัลตราไวโอเลตจากดวงอาทิตย์ไม่ให้มายังโลกมากเกินไปชั้นมีโซสเฟียร์ช่วยชะลอวัตถุนอกโลกที่ผ่านเข้ามาให้เกิดการเผาไหม้กลายเป็นวัตถุขนาดเล็กลดโอกาสที่จะทำความเสียหายแก่สิ่งมีชีวิตบนโลกชั้นเทอร์โมสเฟียร์สามารถสะท้อนคลื่นวิทยุ และชั้นเอกโซสเฟียร์เหมาะสำหรับการโคจรของดาวเทียมรอบโลกในระดับต่ำ'),
  ('ว 3.2', 'ม.1', 3, 'ลมฟ้าอากาศ เป็นสภาวะของอากาศในเวลาหนึ่งของพื้นที่หนึ่งที่มีการเปลี่ยนแปลงตลอดเวลาขึ้นอยู่กับองค์ประกอบลมฟ้าอากาศ ได้แก่อุณหภูมิอากาศ ความกดอากาศ ลม ความชื้นเมฆ และหยาดน้ำฟ้า โดยหยาดน้ำฟ้าที่พบบ่อยในประเทศไทยได้แก่ ฝน องค์ประกอบลมฟ้าอากาศเปลี่ยนแปลงตลอดเวลาขึ้นอยู่กับปัจจัยต่าง ๆ เช่น ปริมาณรังสีจากดวงอาทิตย์และลักษณะพื้นผิวโลกส่งผลต่ออุณหภูมิอากาศอุณหภูมิอากาศและปริมาณไอน้ำส่งผลต่อความชื้น ความกดอากาศส่งผลต่อลม ความชื้นและลมส่งผลต่อเมฆ'),
  ('ว 3.2', 'ม.1', 4, 'พายุฝนฟ้าคะนอง เกิดจากการที่อากาศที่มีอุณหภูมิและความชื้นสูงเคลื่อนที่ขึ้นสู่ระดับความสูง ที่มีอุณหภูมิต่ำลง จนกระทั่งไอน้ำในอากาศเกิดการควบแน่นเป็นละอองน้ำ และเกิดต่อเนื่องเป็นเมฆขนาดใหญ่ พายุฝนฟ้าคะนองทำให้เกิดฝนตกหนัก ลมกรรโชกแรง ฟ้าแลบฟ้าผ่า ซึ่งอาจก่อให้เกิดอันตรายต่อชีวิตและทรัพย์สิน'),
  ('ว 3.2', 'ม.1', 5, 'พายุหมุนเขตร้อนเกิดเหนือมหาสมุทรหรือทะเลที่น้ำมีอุณหภูมิสูงตั้งแต่ 26-27 องศาเซลเซียสขึ้นไป ทำให้อากาศที่มีอุณหภูมิและความชื้นสูงบริเวณนั้นเคลื่อนที่สูงขึ้นอย่างรวดเร็วเป็นบริเวณกว้าง อากาศจากบริเวณอื่นเคลื่อนเข้ามาแทนที่และพัดเวียนเข้าหาศูนย์กลางของพายุยิ่งใกล้ศูนย์กลาง อากาศจะเคลื่อนที่พัดเวียนเกือบเป็นวงกลมและมีอัตราเร็วสูงที่สุด พายุหมุนเขตร้อนทำให้เกิดคลื่นพายุซัดฝั่ง ฝนตกหนักซึ่งอาจก่อให้เกิดอันตรายต่อชีวิตและทรัพย์สินจึงควรปฏิตนให้ปลอดภัยโดยติดตามข่าวสารการพยากรณ์อากาศ และไม่เข้าไปอยู่ในพื้นที่ที่เสี่ยงภัย'),
  ('ว 3.2', 'ม.1', 6, 'การพยากรณ์อากาศเป็นการคาดการณ์ลมฟ้าอากาศที่จะเกิดขึ้นในอนาคต โดยมีการตรวจวัดองค์ประกอบลมฟ้าอากาศ การสื่อสารแลกเปลี่ยนข้อมูลองค์ประกอบลมฟ้าอากาศระหว่างพื้นที่การวิเคราะห์ข้อมูลและสร้างคำพยากรณ์อากาศ'),
  ('ว 3.2', 'ม.1', 7, 'การพยากรณ์อากาศสามารถนำมาใช้ประโยชน์ด้านต่าง ๆ เช่น การใช้ชีวิตประจำวัน การคมนาคมการเกษตร การป้องกัน และเฝ้าระวังภัยพิบัติทางธรรมชาติ'),
  ('ว 3.2', 'ม.1', 8, 'ภูมิอากาศโลกเกิดการเปลี่ยนแปลงอย่างต่อเนื่องโดยปัจจัยทางธรรมชาติ แต่ปัจจุบันการเปลี่ยนแปลงภูมิอากาศเกิดขึ้นอย่างรวดเร็วเนื่องจากกิจกรรมของมนุษย์ในการปลดปล่อยแก๊สเรือนกระจกสู่บรรยากาศ แก๊สเรือนกระจกที่ถูกปลดปล่อยมากที่สุด ได้แก่ แก๊สคาร์บอนไดออกไซด์ซึ่งหมุนเวียนอยู่ในวัฏจักรคาร์บอน'),
  ('ว 3.2', 'ม.1', 9, 'การเปลี่ยนแปลงภูมิอากาศโลกก่อให้เกิดผลกระทบต่อสิ่งมีชีวิตและสิ่งแวดล้อม เช่นการหลอมเหลวของน้ำแข็งขั้วโลก การเพิ่มขึ้นของระดับทะเล การเปลี่ยนแปลงวัฏจักรน้ำการเกิดโรคอุบัติใหม่และอุบัติซ้ำ และการเกิดภัยพิบัติทางธรรมชาติที่รุนแรงขึ้น มนุษย์จึงควรเรียนรู้แนวทางการปฏิบัติตนภายใต้สถานการณ์ดังกล่าว ทั้งแนวทางการปฏิบัติตนให้เหมาะสมและแนวทางการลดกิจกรรมที่ส่งผลต่อการเปลี่ยนแปลงภูมิอากาศโลก'),
  ('ว 3.2', 'ม.2', 1, 'เชื้อเพลิงซากดึกดำบรรพ์ เกิดจากการเปลี่ยนแปลงสภาพของซากสิ่งมีชีวิตในอดีต โดยกระบวนการทางเคมีและธรณีวิทยา เชื้อเพลิงซากดึกดำบรรพ์ได้แก่ ถ่านหิน หินน้ำมัน และปิโตรเลียม ซึ่งเกิดจากวัตถุต้นกำเนิด และสภาพแวดล้อมการเกิดที่แตกต่างกัน ทำให้ได้ชนิดของเชื้อเพลิงซากดึกดำบรรพ์ที่มีลักษณะ สมบัติ และการนำไปใช้ประโยชน์แตกต่างกัน สำหรับปิโตรเลียมจะต้องมีการผ่านการกลั่นลำดับส่วนก่อนการใช้งานเพื่อให้ได้ผลิตภัณฑ์ที่เหมาะสมต่อการใช้ประโยชน์เชื้อเพลิงซากดึกดำบรรพ์เป็นทรัพยากรที่ใช้แล้วหมดไป เนื่องจากต้องใช้เวลานานหลายล้านปีจึงจะเกิดขึ้นใหม่ได้'),
  ('ว 3.2', 'ม.2', 2, 'การเผาไหม้เชื้อเพลิงซากดึกดำบรรพ์ในกิจกรรมต่าง ๆ ของมนุษย์จะทำให้เกิดมลพิษทางอากาศซึ่งส่งผลกระทบต่อสิ่งมีชีวิตและสิ่งแวดล้อมนอกจากนี้แก๊สบางชนิดที่เกิดจากการเผาไหม้เชื้อเพลิงซากดึกดำบรรพ์ เช่น แก๊สคาร์บอนไดออกไซด์และไนตรัสออกไซด์ ยังเป็นแก๊สเรือนกระจกซึ่งส่งผลให้เกิดการเปลี่ยนแปลงภูมิอากาศของโลกรุนแรงขึ้น ดังนั้นจึงควรใช้เชื้อเพลิงซากดึกดำบรรพ์ โดยคำนึงถึงผลที่เกิดขึ้นต่อสิ่งมีชีวิตและสิ่งแวดล้อม เช่น เลือกใช้พลังงานทดแทน หรือเลือกใช้เทคโนโลยีที่ลดการใช้เชื้อเพลิงซากดึกดำบรรพ์'),
  ('ว 3.2', 'ม.2', 3, 'เชื้อเพลิงซากดึกดำบรรพ์เป็นแหล่งพลังงานที่สำคัญในกิจกรรมต่าง ๆ ของมนุษย์ เนื่องจากเชื้อเพลิงซากดึกดำบรรพ์มีปริมาณจำกัดและมักเพิ่มมลภาวะในบรรยากาศมากขึ้น จึงมีการใช้พลังงานทดแทนมากขึ้น เช่น พลังงานแสงอาทิตย์พลังงานลม พลังงานน้ำ พลังงานชีวมวลพลังงานคลื่น พลังงานความร้อนใต้พิภพพลังงานไฮโดรเจน ซึ่งพลังงานทดแทนแต่ละชนิดจะมีข้อดีและข้อจำกัดที่แตกต่างกัน'),
  ('ว 3.2', 'ม.2', 4, 'โครงสร้างภายในโลกแบ่งออกเป็นชั้นตามองค์ประกอบทางเคมี ได้แก่ เปลือกโลก ซึ่งอยู่นอกสุด ประกอบด้วยสารประกอบของซิลิกอนและอะลูมิเนียมเป็นหลัก เนื้อโลกคือส่วนที่อยู่ใต้เปลือกโลกลงไปจนถึงแก่นโลก มีองค์ประกอบหลักเป็นสารประกอบของซิลิกอน แมกนีเซียมและเหล็ก และแก่นโลกคือส่วนที่อยู่ใจกลางของโลก มีองค์ประกอบหลักเป็นเหล็กและนิกเกิลซึ่งแต่ละชั้นมีลักษณะแตกต่างกัน'),
  ('ว 3.2', 'ม.2', 5, 'การผุพังอยู่กับที่ การกร่อน และการสะสมตัวของตะกอน เป็นกระบวนการเปลี่ยนแปลงทางธรณีวิทยา ที่ทำให้ผิวโลกเกิดการเปลี่ยนแปลงเป็นภูมิลักษณ์แบบต่าง ๆ โดยมีปัจจัยสำคัญ คือน้ำ ลม ธารน้ำแข็ง แรงโน้มถ่วงของโลก สิ่งมีชีวิตสภาพอากาศ และปฏิกิริยาเคมี'),
  ('ว 3.2', 'ม.2', 6, 'การผุพังอยู่กับที่ คือ การที่หินผุพังทำลายลงด้วยกระบวนการต่าง ๆ ได้แก่ ลมฟ้าอากาศกับน้ำฝน และรวมทั้งการกระทำของต้นไม้กับแบคทีเรีย ตลอดจนการแตกตัวทางกลศาสตร์ซึ่งมีการเพิ่มและลดอุณหภูมิสลับกัน เป็นต้น'),
  ('ว 3.2', 'ม.2', 7, 'การกร่อน คือ กระบวนการหนึ่งหรือหลายกระบวนการที่ทำให้สารเปลือกโลกหลุดไปละลายไปหรือกร่อนไปโดยมีตัวนำพาธรรมชาติคือ ลม น้ำ และธารน้ำแข็ง ร่วมกับปัจจัยอื่น ๆ ได้แก่ ลมฟ้าอากาศ สารละลาย การครูดถูการนำพา ทั้งนี้ไม่รวมถึงการพังทลายเป็นกลุ่มก้อน เช่น แผ่นดินถล่ม ภูเขาไฟระเบิด'),
  ('ว 3.2', 'ม.2', 8, 'การสะสมตัวของตะกอน คือ การสะสมตัวของวัตถุจากการนำพาของน้ำ ลม หรือธารน้ำแข็ง'),
  ('ว 3.2', 'ม.2', 9, 'ดินเกิดจากหินที่ผุพังตามธรรมชาติผสมคลุกเคล้ากับอินทรียวัตถุที่ได้จากการเน่าเปื่อยของซากพืชซากสัตว์ทับถมเป็นชั้น ๆ บนผิวโลก ชั้นดินแบ่งออกเป็นหลายชั้น ขนานหรือเกือบขนานไปกับผิวหน้าดิน แต่ละชั้นมีลักษณะแตกต่างกันเนื่องจากสมบัติทางกายภาพ เคมี ชีวภาพ และลักษณะอื่น ๆ เช่น สี โครงสร้าง เนื้อดิน การยึดตัวความเป็นกรด-เบส สามารถสังเกตได้จากการสำรวจภาคสนาม การเรียกชื่อชั้นดินหลักจะใช้อักษรภาษาอังกฤษตัวใหญ่ ได้แก่ O, A, E, B, C, R'),
  ('ว 3.2', 'ม.2', 10, 'ชั้นหน้าตัดดิน เป็นชั้นดินที่มีลักษณะปรากฏให้เห็นเรียงลำดับเป็นชั้นจากชั้นบนสุดถึงชั้นล่างสุด'),
  ('ว 3.2', 'ม.2', 11, 'ปัจจัยที่ทำให้ดินแต่ละท้องถิ่นมีลักษณะและสมบัติแตกต่างกัน ได้แก่ วัตถุต้นกำเนิดดิน ภูมิอากาศสิ่งมีชีวิตในดิน สภาพภูมิประเทศ และระยะเวลาในการเกิดดิน'),
  ('ว 3.2', 'ม.2', 12, 'สมบัติบางประการของดิน เช่น เนื้อดิน ความชื้นดินค่าความเป็นกรด-เบส ธาตุอาหารในดิน สามารถนำไปใช้ในการตัดสินใจถึงแนวทางการใช้ประโยชน์ที่ดิน โดยอาจนำไปใช้ประโยชน์ทางการเกษตรหรืออื่น ๆ ซึ่งดินที่ไม่เหมาะสมต่อการทำการเกษตร เช่น ดินจืด ดินเปรี้ยว ดินเค็มและดินดาน อาจเกิดจากสภาพดินตามธรรมชาติหรือการใช้ประโยชน์จะต้องปรับปรุงให้มีสภาพเหมาะสม เพื่อนำไปใช้ประโยชน์'),
  ('ว 3.2', 'ม.2', 13, 'แหล่งน้ำผิวดินเกิดจากน้ำฝนที่ตกลงบนพื้นโลกไหลจากที่สูงลงสู่ที่ต่ำด้วยแรงโน้มถ่วง การไหลของน้ำทำให้พื้นโลกเกิดการกัดเซาะเป็นร่องน้ำเช่น ลำธาร คลอง และแม่น้ำ ซึ่งร่องน้ำจะมีขนาดและรูปร่างแตกต่างกัน ขึ้นอยู่กับปริมาณน้ำฝนระยะเวลาในการกัดเซาะ ชนิดดินและหิน และลักษณะภูมิประเทศ เช่น ความลาดชัน ความสูงต่ำของพื้นที่ เมื่อน้ำไหลไปยังบริเวณที่เป็นแอ่งจะเกิดการสะสมตัวเป็นแหล่งน้ำ เช่น บึง ทะเลสาบทะเล และมหาสมุทร'),
  ('ว 3.2', 'ม.2', 14, 'แหล่งน้ำใต้ดินเกิดจากการซึมของน้ำผิวดินลงไปสะสมตัวใต้พื้นโลก ซึ่งแบ่งเป็นน้ำในดินและน้ำบาดาล น้ำในดินเป็นน้ำที่อยู่ร่วมกับอากาศตามช่องว่างระหว่างเม็ดดิน ส่วนน้ำบาดาลเป็นน้ำที่ไหลซึมลึกลงไปและถูกกักเก็บไว้ในชั้นหินหรือชั้นดิน จนอิ่มตัวไปด้วยน้ำ'),
  ('ว 3.2', 'ม.2', 15, 'แหล่งน้ำผิวดินและแหล่งน้ำใต้ดินถูกนำมาใช้ในกิจกรรมต่าง ๆ ของมนุษย์ ส่งผลต่อการจัดการการใช้ประโยชน์น้ำและคุณภาพของแหล่งน้ำเนื่องจากการเพิ่มขึ้นของจำนวนประชากรการใช้ประโยชน์พื้นที่ในด้านต่าง ๆ เช่นภาคเกษตรกรรม ภาคอุตสาหกรรม และการเปลี่ยนแปลงภูมิอากาศ ทำให้เกิดการเปลี่ยนแปลงปริมาณน้ำฝนในพื้นที่ลุ่มน้ำและแหล่งน้ำผิวดินไม่เพียงพอสำหรับกิจกรรมของมนุษย์ น้ำจากแหล่งน้ำใต้ดินจึงถูกนำมาใช้มากขึ้น ส่งผลให้ปริมาณน้ำใต้ดินลดลงมากจึงต้องมีการจัดการใช้น้ำอย่างเหมาะสมและยั่งยืนซึ่งอาจทำได้โดยการจัดหาแหล่งน้ำเพื่อให้มีแหล่งน้ำเพียงพอสำหรับการดำรงชีวิต การจัดสรรและการใช้น้ำอย่างมีประสิทธิภาพ การอนุรักษ์และฟื้นฟูแหล่งน้ำ การป้องกันและแก้ไขปัญหาคุณภาพน้ำ'),
  ('ว 3.2', 'ม.2', 16, 'น้ำท่วม การกัดเซาะชายฝั่ง ดินถล่ม หลุมยุบแผ่นดินทรุด มีกระบวนการเกิดและผลกระทบที่แตกต่างกัน ซึ่งอาจสร้างความเสียหายร้ายแรงแก่ชีวิต และทรัพย์สิน'),
  ('ว 3.2', 'ม.2', 17, 'น้ำท่วม เกิดจากพื้นที่หนึ่งได้รับปริมาณน้ำเกินกว่าที่จะกักเก็บได้ ทำให้แผ่นดินจมอยู่ใต้น้ำ โดยขึ้นอยู่กับปริมาณน้ำและสภาพทางธรณีวิทยาของพื้นที่'),
  ('ว 3.2', 'ม.2', 18, 'การกัดเซาะชายฝั่ง เป็นกระบวนการเปลี่ยนแปลงของชายฝั่งทะเลที่เกิดขึ้นตลอดเวลาจากการกัดเซาะของคลื่นหรือลม ทำให้ตะกอนจากที่หนึ่งไปตกทับถมในอีกบริเวณหนึ่ง แนวของชายฝั่งเดิมจึงเปลี่ยนแปลงไป บริเวณที่มีตะกอนเคลื่อนเข้ามาน้อยกว่าปริมาณที่ตะกอนเคลื่อนออกไปถือว่าเป็นบริเวณที่มีการกัดเซาะชายฝั่ง'),
  ('ว 3.2', 'ม.2', 19, 'ดินถล่ม เป็นการเคลื่อนที่ของมวลดินหรือหินจำนวนมากลงตามลาดเขา เนื่องจากแรงโน้มถ่วงของโลกเป็นหลัก ซึ่งเกิดจากปัจจัยสำคัญ ได้แก่ความลาดชันของพื้นที่ สภาพธรณีวิทยา ปริมาณน้ำฝน พืชปกคลุมดิน และการใช้ประโยชน์พื้นที่'),
  ('ว 3.2', 'ม.2', 20, 'หลุมยุบ คือ แอ่งหรือหลุมบนแผ่นดินขนาดต่าง ๆ ที่อาจเกิดจากการถล่มของโพรงถ้ำหินปูนเกลือหินใต้ดิน หรือเกิดจากน้ำพัดพาตะกอนลงไปในโพรงถ้ำหรือธารน้ำใต้ดิน'),
  ('ว 3.2', 'ม.2', 21, 'แผ่นดินทรุดเกิดจากการยุบตัวของชั้นดิน หรือหินร่วน เมื่อมวลของแข็งหรือของเหลวปริมาณมากที่รองรับอยู่ใต้ชั้นดินบริเวณนั้นถูกเคลื่อนย้ายออกไปโดยธรรมชาติหรือโดยการกระทำของมนุษย์'),
  ('ว 3.2', 'ม.6', 1, 'การศึกษาโครงสร้างโลกใช้ข้อมูลหลายด้าน เช่นองค์ประกอบทางเคมีของหินและแร่ องค์ประกอบทางเคมีของอุกกาบาต ข้อมูลคลื่นไหวสะเทือนที่เคลื่อนที่ผ่านโลก จึงสามารถแบ่งชั้นโครงสร้างโลก ได้ 2 แบบ คือ โครงสร้างโลกตามองค์ประกอบทางเคมี แบ่งได้เป็น 3 ได้แก่ เปลือกโลกเนื้อโลก และแก่นโลก และโครงสร้างโลกตามสมบัติเชิงกล แบ่งได้เป็น 5 ได้แก่ ธรณีภาคฐานธรณีภาค มัชฌิมภาค แก่นโลกชั้นนอกและแก่นโลกชั้นใน'),
  ('ว 3.2', 'ม.6', 2, 'แผ่นธรณีต่าง ๆ เป็นส่วนประกอบของธรณีภาคการเปลี่ยนแปลงขนาดและตำแหน่งตั้งแต่อดีตจนถึงปัจจุบัน การเคลื่อนที่ของแผ่นธรณีดังกล่าวอธิบายได้ตามทฤษฎีธรณีแปรสัณฐาน ซึ่งมีรากฐานมาจากทฤษฎีทวีปเลื่อนและทฤษฎีการแผ่ขยายพื้นสมุทร โดยมีหลักฐานที่สนับสนุนได้แก่ รูปร่างของขอบทวีปที่สามารถเชื่อมต่อกันได้ความคล้ายคลึงกันของกลุ่มหินและแนวเทือกเขาซากดึกดำบรรพ์ ร่องรอยการเคลื่อนที่ของตะกอนธารน้ำแข็ง ภาวะแม่เหล็กโลกบรรพกาลอายุหินของพื้นมหาสมุทร รวมทั้งการค้นพบสันเขากลางสมุทร และร่องลึกก้นสมุทร'),
  ('ว 3.2', 'ม.6', 3, 'การพาความร้อนของแมกมาภายในโลก ทำให้เกิดการเคลื่อนที่ของแผ่นธรณี ตามทฤษฎีธรณีแปรสัณฐาน ซึ่งนักวิทยาศาสตร์ได้สำรวจพบหลักฐานทางธรณีวิทยา ได้แก่ ธรณีสัณฐานและธรณีโครงสร้าง ที่บริเวณแนวรอยต่อของแผ่นธรณี เช่น ร่องลึกก้นสมุทร หมู่เกาะภูเขาไฟรูปโค้ง แนวภูเขาไฟ แนวเทือกเขา หุบเขาทรุดและสันเขากลางสมุทร รอยเลื่อน นอกจากนี้ยังพบการเกิดธรณีพิบัติภัยที่บริเวณแนวรอยต่อของแผ่นธรณี เช่น แผ่นดินไหว ภูเขาไฟระเบิดสึนามิ ซึ่งหลักฐานดังกล่าวสัมพันธ์กับรูปแบบการเคลื่อนที่ของแผ่นธรณี นักวิทยาศาสตร์จึงสรุปได้ว่าแนวรอยต่อของแผ่นธรณีมี 3 รูปแบบได้แก่ แนวแผ่นธรณีแยกตัว แนวแผ่นธรณีเคลื่อนที่เข้าหากัน แนวแผ่นธรณีเคลื่อนที่ผ่านกันในแนวราบ'),
  ('ว 3.2', 'ม.6', 4, 'ภูเขาไฟระเบิด เกิดจากการแทรกดันของแมกมาขึ้นมาตามส่วนเปราะบาง หรือรอยแตกบนเปลือกโลกมักพบหนาแน่นบริเวณรอยต่อระหว่างแผ่นธรณีทำให้บริเวณดังกล่าวเป็นพื้นที่เสี่ยงภัย ผลจากการระเบิดของภูเขาไฟมีทั้งประโยชน์และโทษจึงต้องศึกษาแนวทางในการเฝ้าระวัง และการปฏิบัติตนให้ปลอดภัย'),
  ('ว 3.2', 'ม.6', 5, 'แผ่นดินไหวเกิดจากการปลดปล่อยพลังงานที่สะสมไว้ของเปลือกโลกในรูปของคลื่นไหวสะเทือนแผ่นดินไหวมีขนาดและความรุนแรงแตกต่างกันมักเกิดขึ้นบริเวณรอยต่อของแผ่นธรณี และพื้นที่ภายใต้อิทธิพลของการเคลื่อนของแผ่นธรณีทำให้บริเวณดังกล่าวเป็นพื้นที่เสี่ยงภัยแผ่นดินไหวซึ่งส่งผลให้สิ่งก่อสร้างเสียหาย เกิดอันตรายต่อชีวิตและทรัพย์สิน จึงต้องศึกษาแนวทางในการเฝ้าระวัง และการปฏิบัติตนให้ปลอดภัย'),
  ('ว 3.2', 'ม.6', 6, 'สึนามิ คือ คลื่นน้ำที่เกิดจากการแทนที่มวลน้ำในปริมาณมหาศาล ส่วนมากจะเกิดในทะเลหรือมหาสมุทร โดยคลื่นมีลักษณะเฉพาะ คือความยาวคลื่นมากและเคลื่อนที่ด้วยความเร็วสูงเมื่ออยู่กลางมหาสมุทรจะมีความสูงคลื่นน้อยและอาจเพิ่มความสูงขึ้นอย่างรวดเร็ว เมื่อคลื่นเคลื่อนที่ผ่านบริเวณน้ำตื้น จึงทำให้พื้นที่บริเวณชายฝั่งบางบริเวณเป็นพื้นที่เสี่ยงภัยสึนามิก่อให้เกิดอันตรายแก่มนุษย์และสิ่งก่อสร้างในบริเวณชายหาดนั้น จึงต้องศึกษาแนวทางในการเฝ้าระวัง และการปฏิบัติตนให้ปลอดภัย'),
  ('ว 3.2', 'ม.6', 7, 'พื้นผิวโลกแต่ละบริเวณได้รับพลังงานจากดวงอาทิตย์ในปริมาณที่แตกต่างกัน เนื่องจากปัจจัยสำคัญหลายประการ เช่น สัณฐานและการเอียงของแกนโลก ลักษณะของพื้นผิวละอองลอย และเมฆ ทำให้แต่ละบริเวณบนโลกมีอุณหภูมิไม่เท่ากัน ส่งผลให้มีความกดอากาศแตกต่างกัน และเกิดการถ่ายโอนพลังงานระหว่างกัน'),
  ('ว 3.2', 'ม.6', 8, 'การหมุนเวียนของอากาศเกิดขึ้นจากความกดอากาศที่แตกต่างกันระหว่างสองบริเวณโดยอากาศเคลื่อนที่จากบริเวณที่มีความกดอากาศสูงไปยังบริเวณที่มีความกดอากาศต่ำซึ่งจะเห็นได้ชัดเจน ในการเคลื่อนที่ของอากาศในแนวราบ และเมื่อพิจารณาการเคลื่อนที่ของอากาศในแนวดิ่งจะพบว่าอากาศเหนือบริเวณความกดอากาศต่ำจะมีการยกตัวขึ้นขณะที่อากาศเหนือบริเวณความกดอากาศสูง จะจมตัวลงโดยการเคลื่อนที่ของอากาศทั้งในแนวราบและแนวดิ่งนี้ ทำให้เกิดเป็นการหมุนเวียนของอากาศ'),
  ('ว 3.2', 'ม.6', 9, 'การหมุนรอบตัวเองของโลกทำให้เกิดแรงคอริออลิสส่งผลให้ทิศทางการเคลื่อนที่ของอากาศเบนไปโดยอากาศที่เคลื่อนที่ในบริเวณซีกโลกเหนือจะเบนไปทางขวาจากทิศทางเดิม ส่วนบริเวณซีกโลกใต้จะเบนไปทางซ้ายจากทิศทางเดิม'),
  ('ว 3.2', 'ม.6', 10, 'โลกมีความกดอากาศแตกต่างกันในแต่ละบริเวณรวมทั้งอิทธิพลจากการหมุนรอบตัวเองของโลกทำให้อากาศในแต่ละซีกโลกเกิดการหมุนเวียนของอากาศตามเขตละติจูด แบ่งออกเป็น 3 แถบโดยแต่ละแถบมีภูมิอากาศแตกต่างกัน ได้แก่การหมุนเวียนแถบขั้วโลกมีภูมิอากาศแบบหนาวเย็น การหมุนเวียนแถบละติจูดกลางมีภูมิอากาศแบบอบอุ่น และการหมุนเวียนแถบเขตร้อนมีภูมิอากาศแบบร้อนชื้น'),
  ('ว 3.2', 'ม.6', 11, 'นอกจากนี้บริเวณรอยต่อของการหมุนเวียนอากาศแต่ละแถบละติจูด จะมีลักษณะลมฟ้าอากาศ ที่แตกต่างกัน เช่น บริเวณใกล้ศูนย์สูตรมีปริมาณ หยาดน้ำฟ้าเฉลี่ยสูงกว่าบริเวณอื่นบริเวณละติจูด 30 องศา มีอากาศแห้งแล้งส่วนบริเวณละติจูด 60 องศา อากาศมีความแปรปรวนสูง'),
  ('ว 3.2', 'ม.6', 12, 'การหมุนเวียนของกระแสน้ำผิวหน้าในมหาสมุทรได้รับอิทธิพลจากการหมุนเวียนของอากาศในแต่ละแถบละติจูดเป็นปัจจัยหลักทำให้บริเวณซีกโลกเหนือมีการหมุนเวียนของกระแสน้ำผิวหน้าในทิศทางตามเข็มนาฬิกา และทวนเข็มนาฬิกาในซีกโลกใต้ ซึ่งกระแสน้ำผิวหน้าในมหาสมุทรมีทั้งกระแสน้ำอุ่น และกระแสน้ำเย็น'),
  ('ว 3.2', 'ม.6', 13, 'การหมุนเวียนอากาศและน้ำในมหาสมุทรส่งผลต่อภูมิอากาศ ลมฟ้าอากาศ สิ่งมีชีวิตและสิ่งแวดล้อม เช่น กระแสน้ำอุ่นกัลฟ์สตรีมที่ทำให้บางประเทศในทวีปยุโรปไม่หนาวเย็นเกินไป และเมื่อการหมุนเวียนอากาศและน้ำในมหาสมุทรแปรปรวน ทำให้เกิดผลกระทบต่อสภาพลมฟ้าอากาศ เช่น ปรากฏการณ์เอลนีโญและลานีญา ซึ่งเกิดจากความแปรปรวนของลมค้าและส่งผลต่อประเทศที่อยู่บริเวณมหาสมุทรแปซิฟิก'),
  ('ว 3.2', 'ม.6', 14, 'โลกได้รับพลังงานจากดวงอาทิตย์ โดยปริมาณพลังงานเฉลี่ยที่โลกได้รับเท่ากับพลังงานเฉลี่ยที่โลกปลดปล่อยกลับสู่อวกาศ ทำให้เกิดสมดุลพลังงานของโลก ส่งผลให้อุณหภูมิเฉลี่ยของโลกในแต่ละปีค่อนข้างคงที่และมีลักษณะภูมิอากาศที่ไม่เปลี่ยนแปลง หากสมดุลพลังงานของโลกเกิดการเปลี่ยนแปลงไปจะทำให้อุณหภูมิเฉลี่ยของโลกและภูมิอากาศเกิดการเปลี่ยนแปลงได้เนื่องจากปัจจัยหลายประการทั้งปัจจัยที่เกิดขึ้นตามธรรมชาติและการกระทำของมนุษย์ เช่นแก๊สเรือนกระจก ลักษณะผิวโลก และละอองลอย'),
  ('ว 3.2', 'ม.6', 15, 'มนุษย์มีส่วนช่วยในการชะลอการเปลี่ยนแปลงภูมิอากาศโลกได้โดยการลดกิจกรรมที่ทำให้เกิดการเปลี่ยนแปลงสมดุลพลังงาน เช่น ลดการปลดปล่อยแก๊สเรือนกระจกและละอองลอย'),
  ('ว 3.2', 'ม.6', 16, 'แผนที่อากาศผิวพื้นแสดงข้อมูลการตรวจอากาศในรูปแบบสัญลักษณ์หรือตัวเลข เช่น บริเวณความกดอากาศสูง หย่อมความกดอากาศต่ำพายุหมุนเขตร้อน ร่องความกดอากาศต่ำการแปลความหมายสัญลักษณ์ลมฟ้าอากาศทำให้ทราบลักษณะลมฟ้าอากาศ ณ บริเวณหนึ่ง'),
  ('ว 3.2', 'ม.6', 17, 'การแปลความหมายสัญลักษณ์ที่ปรากฏบนแผนที่อากาศ ร่วมกับข้อมูลสารสนเทศต่าง ๆ เช่นโปรแกรมประยุกต์เกี่ยวกับการพยากรณ์อากาศเรดาร์ตรวจอากาศ ภาพถ่ายดาวเทียม สามารถนำมาวางแผนการดำเนินชีวิตให้สอดคล้องกับสภาพลมฟ้าอากาศ เช่น การเลือกช่วงเวลาในการเพาะปลูกให้สอดคล้องกับฤดูกาลการเตรียมพร้อมรับมือสภาพอากาศแปรปรวน'),
  ('ว 4.1', 'ม.1', 1, 'เทคโนโลยี เป็นสิ่งที่มนุษย์สร้างหรือพัฒนาขึ้นซึ่งอาจเป็นได้ทั้งชิ้นงานหรือวิธีการ เพื่อใช้แก้ปัญหาสนองความต้องการ หรือเพิ่มความสามารถในการทำงานของมนุษย์'),
  ('ว 4.1', 'ม.1', 2, 'ระบบทางเทคโนโลยี เป็นกลุ่มของส่วนต่าง ๆ ตั้งแต่สองส่วนขึ้นไปประกอบเข้าด้วยกันและทำงานร่วมกันเพื่อให้บรรลุวัตถุประสงค์ โดยในการทำงานของระบบทางเทคโนโลยีจะประกอบไปด้วยตัวป้อน (input) กระบวนการ (process) และผลผลิต (output) ที่สัมพันธ์กัน นอกจากนี้ระบบทางเทคโนโลยีอาจมีข้อมูลย้อนกลับ (feedback) เพื่อใช้ปรับปรุงการทำงานได้ตามวัตถุประสงค์ ซึ่งการวิเคราะห์ระบบทางเทคโนโลยีช่วยให้เข้าใจองค์ประกอบและการทำงานของเทคโนโลยี รวมถึงสามารถปรับปรุงให้เทคโนโลยีทำงานได้ตามต้องการ'),
  ('ว 4.1', 'ม.1', 3, 'เทคโนโลยีมีการเปลี่ยนแปลงตลอดเวลาตั้งแต่อดีตจนถึงปัจจุบัน ซึ่งมีสาเหตุหรือปัจจัยมาจากหลายด้าน เช่น ปัญหา ความต้องการ ความก้าวหน้าของศาสตร์ต่าง ๆ เศรษฐกิจ สังคม'),
  ('ว 4.1', 'ม.1', 4, 'ปัญหาหรือความต้องการในชีวิตประจำวันพบได้จากหลายบริบทขึ้นกับสถานการณ์ที่ประสบเช่น การเกษตร การอาหาร'),
  ('ว 4.1', 'ม.1', 5, 'การแก้ปัญหาจำเป็นต้องสืบค้น รวบรวมข้อมูลความรู้จากศาสตร์ต่าง ๆ ที่เกี่ยวข้อง เพื่อนำไปสู่การออกแบบแนวทางการแก้ปัญหา'),
  ('ว 4.1', 'ม.1', 6, 'การวิเคราะห์ เปรียบเทียบ และตัดสินใจเลือกข้อมูลที่จำเป็น โดยคำนึงถึงเงื่อนไข และทรัพยากรที่มีอยู่ ช่วยให้ได้แนวทางการแก้ปัญหาที่เหมาะสม'),
  ('ว 4.1', 'ม.1', 7, 'การออกแบบแนวทางการแก้ปัญหาทำได้หลากหลายวิธี เช่น การร่างภาพ การเขียนแผนภาพการเขียนผังงาน'),
  ('ว 4.1', 'ม.1', 8, 'การกำหนดขั้นตอนและระยะเวลาในการทำงานก่อนดำเนินการแก้ปัญหาจะช่วยให้ทำงานสำเร็จได้ตามเป้าหมายและลดข้อผิดพลาดของการทำงานที่อาจเกิดขึ้น'),
  ('ว 4.1', 'ม.1', 9, 'การทดสอบ และประเมินผลเป็นการตรวจสอบชิ้นงานหรือวิธีการว่าสามารถแก้ปัญหาได้ตามวัตถุประสงค์ภายใต้กรอบของปัญหา เพื่อหาข้อบกพร่อง และดำเนินการปรับปรุง โดยอาจทดสอบซ้ำเพื่อให้สามารถแก้ปัญหาได้'),
  ('ว 4.1', 'ม.1', 10, 'การนำเสนอผลงานเป็นการถ่ายทอดแนวคิดเพื่อให้ผู้อื่นเข้าใจเกี่ยวกับกระบวนการทำงานและชิ้นงานหรือวิธีการที่ได้ ซึ่งสามารถทำได้หลายวิธี เช่น การเขียนรายงาน การทำแผ่นนำเสนอผลงาน การจัดนิทรรศการ การนำเสนอผ่านสื่อออนไลน์'),
  ('ว 4.1', 'ม.1', 11, 'วัสดุแต่ละประเภทมีสมบัติแตกต่างกัน เช่น ไม้โลหะ พลาสติก จึงต้องมีการวิเคราะห์สมบัติเพื่อเลือกใช้ให้เหมาะสมกับลักษณะของงาน'),
  ('ว 4.1', 'ม.1', 12, 'การสร้างชิ้นงานอาจใช้ความรู้ เรื่องกลไก ไฟฟ้าอิเล็กทรอนิกส์ เช่น LED บัซเซอร์ มอเตอร์วงจรไฟฟ้า'),
  ('ว 4.1', 'ม.1', 13, 'อุปกรณ์และเครื่องมือในการสร้างชิ้นงานหรือพัฒนาวิธีการมีหลายประเภท ต้องเลือกใช้ให้ถูกต้อง เหมาะสม และปลอดภัย รวมทั้งรู้จักเก็บรักษา'),
  ('ว 4.1', 'ม.2', 1, 'สาเหตุหรือปัจจัยต่าง ๆ เช่น ความก้าวหน้าของศาสตร์ต่าง ๆ การเปลี่ยนแปลงทางด้านเศรษฐกิจสังคม วัฒนธรรม ทำให้เทคโนโลยีมีการเปลี่ยนแปลงตลอดเวลา'),
  ('ว 4.1', 'ม.2', 2, 'เทคโนโลยีแต่ละประเภทมีผลกระทบต่อชีวิตสังคม และสิ่งแวดล้อมที่แตกต่างกัน จึงต้องวิเคราะห์เปรียบเทียบข้อดี ข้อเสีย และตัดสินใจเลือกใช้ให้เหมาะสม'),
  ('ว 4.1', 'ม.2', 3, 'ปัญหาหรือความต้องการในชุมชนหรือท้องถิ่นมีหลายอย่าง ขึ้นกับบริบทหรือสถานการณ์ที่ประสบ เช่น ด้านพลังงาน สิ่งแวดล้อมการเกษตร การอาหาร'),
  ('ว 4.1', 'ม.2', 4, 'การระบุปัญหาจำเป็นต้องมีการวิเคราะห์สถานการณ์ของปัญหาเพื่อสรุปกรอบของปัญหาแล้วดำเนินการสืบค้น รวบรวมข้อมูล ความรู้จากศาสตร์ต่าง ๆ ที่เกี่ยวข้อง เพื่อนำไปสู่การออกแบบแนวทางการแก้ปัญหา'),
  ('ว 4.1', 'ม.2', 5, 'การวิเคราะห์ เปรียบเทียบ และตัดสินใจเลือกข้อมูลที่จำเป็น โดยคำนึงถึงเงื่อนไขและทรัพยากร เช่น งบประมาณ เวลา ข้อมูลและสารสนเทศ วัสดุ เครื่องมือและอุปกรณ์ช่วยให้ได้แนวทางการแก้ปัญหาที่เหมาะสม'),
  ('ว 4.1', 'ม.2', 6, 'การออกแบบแนวทางการแก้ปัญหาทำได้หลากหลายวิธี เช่น การร่างภาพ การเขียนแผนภาพ การเขียนผังงาน'),
  ('ว 4.1', 'ม.2', 7, 'การกำหนดขั้นตอนระยะเวลาในการทำงานก่อนดำเนินการแก้ปัญหาจะช่วยให้การทำงานสำเร็จได้ตามเป้าหมาย และลดข้อผิดพลาดของการทำงานที่อาจเกิดขึ้น'),
  ('ว 4.1', 'ม.2', 8, 'การทดสอบและประเมินผลเป็นการตรวจสอบชิ้นงาน หรือวิธีการว่าสามารถแก้ปัญหาได้ตามวัตถุประสงค์ภายใต้กรอบของปัญหา เพื่อหาข้อบกพร่อง และดำเนินการปรับปรุงให้สามารถแก้ไขปัญหาได้'),
  ('ว 4.1', 'ม.2', 9, 'การนำเสนอผลงานเป็นการถ่ายทอดแนวคิดเพื่อให้ผู้อื่นเข้าใจเกี่ยวกับกระบวนการทำงานและชิ้นงานหรือวิธีการที่ได้ ซึ่งสามารถทำได้หลายวิธี เช่น การเขียนรายงานการทำแผ่นนำเสนอผลงาน การจัดนิทรรศการ'),
  ('ว 4.1', 'ม.2', 10, 'วัสดุแต่ละประเภทมีสมบัติแตกต่างกัน เช่น ไม้โลหะ พลาสติก จึงต้องมีการวิเคราะห์สมบัติเพื่อเลือกใช้ให้เหมาะสมกับลักษณะของงาน'),
  ('ว 4.1', 'ม.2', 11, 'การสร้างชิ้นงานอาจใช้ความรู้ เรื่องกลไก ไฟฟ้าอิเล็กทรอนิกส์ เช่น LED มอเตอร์ บัซเซอร์ เฟืองรอก ล้อ เพลา'),
  ('ว 4.1', 'ม.2', 12, 'อุปกรณ์และเครื่องมือในการสร้างชิ้นงานหรือพัฒนาวิธีการมีหลายประเภท ต้องเลือกใช้ให้ถูกต้อง เหมาะสม และปลอดภัย รวมทั้งรู้จักเก็บรักษา'),
  ('ว 4.1', 'ม.3', 1, 'เทคโนโลยีมีการเปลี่ยนแปลงตลอดเวลาตั้งแต่อดีตจนถึงปัจจุบัน ซึ่งมีสาเหตุหรือปัจจัยมาจากหลายด้าน เช่น ปัญหาหรือความต้องการของมนุษย์ความก้าวหน้าของศาสตร์ต่าง ๆ การเปลี่ยนแปลงทางด้านเศรษฐกิจ สังคม วัฒนธรรม สิ่งแวดล้อม'),
  ('ว 4.1', 'ม.3', 2, 'เทคโนโลยีมีความสัมพันธ์กับศาสตร์อื่น โดยเฉพาะวิทยาศาสตร์ โดยวิทยาศาสตร์เป็นพื้นฐานความรู้ที่นำไปสู่การพัฒนาเทคโนโลยี และเทคโนโลยีที่ได้สามารถเป็นเครื่องมือที่ใช้ในการศึกษา ค้นคว้าเพื่อให้ได้มาซึ่งองค์ความรู้ใหม่'),
  ('ว 4.1', 'ม.3', 3, 'ปัญหาหรือความต้องการอาจพบได้ในงานอาชีพของชุมชนหรือท้องถิ่น ซึ่งอาจมีหลายด้าน เช่นด้านการเกษตร อาหาร พลังงาน การขนส่ง'),
  ('ว 4.1', 'ม.3', 4, 'การวิเคราะห์สถานการณ์ปัญหาช่วยให้เข้าใจเงื่อนไขและกรอบของปัญหาได้ชัดเจน จากนั้นดำเนินการสืบค้น รวบรวมข้อมูล ความรู้จากศาสตร์ต่าง ๆ ที่เกี่ยวข้อง เพื่อนำไปสู่การออกแบบแนวทางการแก้ปัญหา'),
  ('ว 4.1', 'ม.3', 5, 'การวิเคราะห์ เปรียบเทียบ และตัดสินใจเลือกข้อมูลที่จำเป็น โดยคำนึงถึงทรัพย์สินทางปัญญาเงื่อนไขและทรัพยากร เช่น งบประมาณ เวลาข้อมูลและสารสนเทศ วัสดุ เครื่องมือและอุปกรณ์ช่วยให้ได้แนวทางการแก้ปัญหาที่เหมาะสม'),
  ('ว 4.1', 'ม.3', 6, 'การออกแบบแนวทางการแก้ปัญหาทำได้หลากหลายวิธี เช่น การร่างภาพ การเขียนแผนภาพการเขียนผังงาน'),
  ('ว 4.1', 'ม.3', 7, 'เทคนิคหรือวิธีการในการนำเสนอแนวทางการแก้ปัญหามีหลากหลาย เช่น การใช้แผนภูมิตาราง ภาพเคลื่อนไหว'),
  ('ว 4.1', 'ม.3', 8, 'การกำหนดขั้นตอนและระยะเวลาในการทำงานก่อนดำเนินการแก้ปัญหาจะช่วยให้การทำงานสำเร็จได้ตามเป้าหมาย และลดข้อผิดพลาดของการทำงานที่อาจเกิดขึ้น'),
  ('ว 4.1', 'ม.3', 9, 'การทดสอบและประเมินผลเป็นการตรวจสอบชิ้นงานหรือวิธีการว่า สามารถแก้ปัญหาได้ตามวัตถุประสงค์ภายใต้กรอบของปัญหา เพื่อหาข้อบกพร่อง และดำเนินการปรับปรุง โดยอาจทดสอบซ้ำเพื่อให้สามารถแก้ไขปัญหาได้'),
  ('ว 4.1', 'ม.3', 10, 'การนำเสนอผลงานเป็นการถ่ายทอดแนวคิดเพื่อให้ผู้อื่นเข้าใจเกี่ยวกับกระบวนการทำงานและชิ้นงานหรือวิธีการที่ได้ ซึ่งสามารถทำได้หลายวิธี เช่น การเขียนรายงาน การทำแผ่นนำเสนอผลงาน การจัดนิทรรศการ การนำเสนอผ่านสื่อออนไลน์'),
  ('ว 4.1', 'ม.3', 11, 'วัสดุแต่ละประเภทมีสมบัติแตกต่างกัน เช่น ไม้โลหะ พลาสติก เซรามิก จึงต้องมีการวิเคราะห์สมบัติเพื่อเลือกใช้ให้เหมาะสมกับลักษณะของงาน'),
  ('ว 4.1', 'ม.3', 12, 'การสร้างชิ้นงานอาจใช้ความรู้ เรื่องกลไก ไฟฟ้าอิเล็กทรอนิกส์ เช่น LED LDR มอเตอร์ เฟืองคาน รอก ล้อ เพลา'),
  ('ว 4.1', 'ม.3', 13, 'อุปกรณ์และเครื่องมือในการสร้างชิ้นงานหรือพัฒนาวิธีการมีหลายประเภท ต้องเลือกใช้ให้ถูกต้อง เหมาะสม และปลอดภัย รวมทั้งรู้จักเก็บรักษา'),
  ('ว 4.1', 'ม.4', 1, 'ระบบทางเทคโนโลยี เป็นกลุ่มของส่วนต่าง ๆ ตั้งแต่สองส่วนขึ้นไปประกอบเข้าด้วยกันและทำงานร่วมกันเพื่อให้บรรลุวัตถุประสงค์ โดยในการทำงานของระบบทางเทคโนโลยีจะประกอบไปด้วยตัวป้อน (input) กระบวนการ (process) และผลผลิต (output) ที่สัมพันธ์กันนอกจากนี้ระบบทางเทคโนโลยีอาจมีข้อมูลย้อนกลับ (feedback) เพื่อใช้ปรับปรุงการทำงานได้ตามวัตถุประสงค์ โดยระบบทางเทคโนโลยีอาจมีระบบย่อยหลายระบบ (sub-systems) ที่ทำงานสัมพันธ์กันอยู่ และหากระบบย่อยใดทำงานผิดพลาดจะส่งผลต่อการทำงานของระบบอื่นด้วย'),
  ('ว 4.1', 'ม.4', 2, 'เทคโนโลยีมีการเปลี่ยนแปลงตลอดเวลา ตั้งแต่อดีตจนถึงปัจจุบัน ซึ่งมีสาเหตุหรือปัจจัยมาจากหลายด้าน เช่น ปัญหา ความต้องการความก้าวหน้าของศาสตร์ต่าง ๆ เศรษฐกิจ สังคมวัฒนธรรม สิ่งแวดล้อม'),
  ('ว 4.1', 'ม.4', 3, 'ปัญหาหรือความต้องการที่มีผลกระทบต่อสังคมเช่น ปัญหาด้านการเกษตร อาหาร พลังงานการขนส่ง สุขภาพและการแพทย์ การบริการซึ่งแต่ละด้านอาจมีได้หลากหลายปัญหา'),
  ('ว 4.1', 'ม.4', 4, 'การวิเคราะห์สถานการณ์ปัญหาโดยอาจใช้เทคนิคหรือวิธีการวิเคราะห์ที่หลากหลาย ช่วยให้เข้าใจเงื่อนไขและกรอบของปัญหาได้ชัดเจน จากนั้นดำเนินการสืบค้น รวบรวมข้อมูล ความรู้จากศาสตร์ต่าง ๆ ที่เกี่ยวข้อง เพื่อนำไปสู่การออกแบบแนวทางการแก้ปัญหา'),
  ('ว 4.1', 'ม.4', 5, 'การวิเคราะห์ เปรียบเทียบ และตัดสินใจเลือกข้อมูลที่จำเป็น โดยคำนึงถึงทรัพย์สินทางปัญญาเงื่อนไขและทรัพยากร เช่น งบประมาณ เวลาข้อมูลและสารสนเทศ วัสดุ เครื่องมือและอุปกรณ์ช่วยให้ได้แนวทางการแก้ปัญหาที่เหมาะสม'),
  ('ว 4.1', 'ม.4', 6, 'การออกแบบแนวทางการแก้ปัญหาทำได้หลากหลายวิธี เช่น การร่างภาพ การเขียนแผนภาพการเขียนผังงาน'),
  ('ว 4.1', 'ม.4', 7, 'ซอฟต์แวร์ช่วยในการออกแบบและนำเสนอมีหลากหลายชนิดจึงต้องเลือกใช้ให้เหมาะกับงาน'),
  ('ว 4.1', 'ม.4', 8, 'การกำหนดขั้นตอนและระยะเวลาในการทำงานก่อนดำเนินการแก้ปัญหาจะช่วยให้การทำงานสำเร็จได้ตามเป้าหมาย และลดข้อผิดพลาดของการทำงานที่อาจเกิดขึ้น'),
  ('ว 4.1', 'ม.4', 9, 'การทดสอบและประเมินผลเป็นการตรวจสอบชิ้นงานหรือวิธีการว่าสามารถแก้ปัญหาได้ตามวัตถุประสงค์ภายใต้กรอบของปัญหา เพื่อหาข้อบกพร่อง และดำเนินการปรับปรุง โดยอาจทดสอบซ้ำเพื่อให้สามารถแก้ไขปัญหาได้อย่างมีประสิทธิภาพ'),
  ('ว 4.1', 'ม.4', 10, 'การนำเสนอผลงานเป็นการถ่ายทอดแนวคิดเพื่อให้ผู้อื่นเข้าใจเกี่ยวกับกระบวนการทำงานและชิ้นงานหรือวิธีการที่ได้ ซึ่งสามารถทำได้หลายวิธี เช่น การทำแผ่นนำเสนอผลงาน การจัดนิทรรศการ การนำเสนอผ่านสื่อออนไลน์ หรือการนำเสนอต่อภาคธุรกิจ เพื่อการพัฒนาต่อยอดสู่งานอาชีพ'),
  ('ว 4.1', 'ม.4', 11, 'วัสดุแต่ละประเภทมีสมบัติแตกต่างกัน เช่นไม้สังเคราะห์ โลหะ จึงต้องมีการวิเคราะห์สมบัติเพื่อเลือกใช้ให้เหมาะสมกับลักษณะของงาน'),
  ('ว 4.1', 'ม.4', 12, 'การสร้างชิ้นงานอาจใช้ความรู้ เรื่องกลไก ไฟฟ้าอิเล็กทรอนิกส์ เช่น LDR sensor เฟือง รอก คานวงจรสำเร็จรูป'),
  ('ว 4.1', 'ม.4', 13, 'อุปกรณ์และเครื่องมือในการสร้างชิ้นงาน หรือพัฒนาวิธีการมีหลายประเภท ต้องเลือกใช้ให้ถูกต้อง เหมาะสม และปลอดภัย รวมทั้งรู้จักเก็บรักษา'),
  ('ว 4.1', 'ม.5', 1, 'การทำโครงงาน เป็นการประยุกต์ใช้ความรู้และทักษะจากศาสตร์ต่าง ๆ รวมทั้งทรัพยากรในการสร้างหรือพัฒนาชิ้นงานหรือวิธีการ เพื่อแก้ปัญหาหรืออำนวยความสะดวกในการทำงาน'),
  ('ว 4.1', 'ม.5', 2, 'การทำโครงงานการออกแบบและเทคโนโลยีสามารถดำเนินการได้ โดยเริ่มจาก การสำรวจสถานการณ์ปัญหาที่สนใจ เพื่อกำหนดหัวข้อโครงงาน แล้วรวบรวมข้อมูลและแนวคิดที่เกี่ยวข้องกับปัญหา ออกแบบแนวทางการแก้ปัญหา วางแผนและดำเนินการแก้ปัญหา ทดสอบ ประเมินผลปรับปรุงแก้ไขวิธีการแก้ปัญหาหรือชิ้นงาน และนำเสนอวิธีการแก้ปัญหา'),
  ('ว 4.2', 'ป.1', 1, 'การแก้ปัญหาให้ประสบความสำเร็จทำได้โดยใช้ขั้นตอนการแก้ปัญหา'),
  ('ว 4.2', 'ป.1', 2, 'ปัญหาอย่างง่าย เช่น เกมเขาวงกต เกมหาจุดแตกต่างของภาพ การจัดหนังสือใส่กระเป๋า'),
  ('ว 4.2', 'ป.1', 3, 'การแสดงขั้นตอนการแก้ปัญหา ทำได้โดยการเขียน บอกเล่า วาดภาพ หรือใช้สัญลักษณ์'),
  ('ว 4.2', 'ป.1', 4, 'ปัญหาอย่างง่าย เช่น เกมเขาวงกต เกมหาจุดแตกต่างของภาพ การจัดหนังสือใส่กระเป๋า'),
  ('ว 4.2', 'ป.1', 5, 'การเขียนโปรแกรมเป็นการสร้างลำดับของคำสั่งให้คอมพิวเตอร์ทำงาน'),
  ('ว 4.2', 'ป.1', 6, 'ตัวอย่างโปรแกรม เช่น เขียนโปรแกรมสั่งให้ตัวละครย้ายตำแหน่ง ย่อขยายขนาด เปลี่ยนรูปร่าง'),
  ('ว 4.2', 'ป.1', 7, 'ซอฟต์แวร์หรือสื่อที่ใช้ในการเขียนโปรแกรม เช่นใช้บัตรคำสั่งแสดงการเขียนโปรแกรม, Code.org'),
  ('ว 4.2', 'ป.1', 8, 'การใช้งานอุปกรณ์เทคโนโลยีเบื้องต้น เช่น การใช้เมาส์ คีย์บอร์ด จอสัมผัส การเปิด-ปิด อุปกรณ์เทคโนโลยี'),
  ('ว 4.2', 'ป.1', 9, 'การใช้งานซอฟต์แวร์เบื้องต้น เช่น การเข้าและออกจากโปรแกรม การสร้างไฟล์ การจัดเก็บการเรียกใช้ไฟล์ ทำได้ในโปรแกรม เช่น โปรแกรมประมวลคำ โปรแกรมกราฟิก โปรแกรมนำเสนอ'),
  ('ว 4.2', 'ป.1', 10, 'การสร้างและจัดเก็บไฟล์อย่างเป็นระบบจะทำให้เรียกใช้ ค้นหาข้อมูลได้ง่ายและรวดเร็ว'),
  ('ว 4.2', 'ป.1', 11, 'การใช้เทคโนโลยีสารสนเทศอย่างปลอดภัย เช่นรู้จักข้อมูลส่วนตัว อันตรายจากการเผยแพร่ข้อมูลส่วนตัว และไม่บอกข้อมูลส่วนตัวกับบุคคลอื่นยกเว้นผู้ปกครองหรือครู แจ้งผู้เกี่ยวข้องเมื่อต้องการความช่วยเหลือเกี่ยวกับการใช้งาน'),
  ('ว 4.2', 'ป.1', 12, 'ข้อปฏิบัติในการใช้งานและการดูแลรักษาอุปกรณ์เช่น ไม่ขีดเขียนบนอุปกรณ์ ทำความสะอาดใช้อุปกรณ์อย่างถูกวิธี'),
  ('ว 4.2', 'ป.1', 13, 'การใช้งานอย่างเหมาะสม เช่น จัดท่านั่งให้ถูกต้องการพักสายตาเมื่อใช้อุปกรณ์เป็นเวลานานระมัดระวังอุบัติเหตุจากการใช้งาน'),
  ('ว 4.2', 'ป.2', 1, 'การแสดงขั้นตอนการแก้ปัญหา ทำได้โดยการเขียนบอกเล่า วาดภาพ หรือใช้สัญลักษณ์'),
  ('ว 4.2', 'ป.2', 2, 'ปัญหาอย่างง่าย เช่น เกมตัวต่อ 6-12 ชิ้นการแต่งตัวมาโรงเรียน'),
  ('ว 4.2', 'ป.2', 3, 'ตัวอย่างโปรแกรม เช่น เขียนโปรแกรมสั่งให้ตัวละครทำงานตามที่ต้องการ และตรวจสอบข้อผิดพลาด ปรับแก้ไขให้ได้ผลลัพธ์ตามที่กำหนด'),
  ('ว 4.2', 'ป.2', 4, 'การตรวจหาข้อผิดพลาด ทำได้โดยตรวจสอบคำสั่งที่แจ้งข้อผิดพลาด หรือหากผลลัพธ์ไม่เป็นไปตามที่ต้องการให้ตรวจสอบการทำงานทีละคำสั่ง'),
  ('ว 4.2', 'ป.2', 5, 'ซอฟต์แวร์หรือสื่อที่ใช้ในการเขียนโปรแกรม เช่นใช้บัตรคำสั่งแสดงการเขียนโปรแกรม, Code.org'),
  ('ว 4.2', 'ป.2', 6, 'การใช้งานซอฟต์แวร์เบื้องต้น เช่น การเข้าและออกจากโปรแกรม การสร้างไฟล์ การจัดเก็บการเรียกใช้ไฟล์ การแก้ไขตกแต่งเอกสาร ทำได้ในโปรแกรม เช่น โปรแกรมประมวลคำโปรแกรมกราฟิก โปรแกรมนำเสนอ'),
  ('ว 4.2', 'ป.2', 7, 'การสร้าง คัดลอก ย้าย ลบ เปลี่ยนชื่อ จัดหมวดหมู่ไฟล์ และโฟลเดอร์อย่างเป็นระบบจะทำให้เรียกใช้ ค้นหาข้อมูลได้ง่ายและรวดเร็ว'),
  ('ว 4.2', 'ป.2', 8, 'การใช้เทคโนโลยีสารสนเทศอย่างปลอดภัย เช่นรู้จักข้อมูลส่วนตัว อันตรายจากการเผยแพร่ข้อมูลส่วนตัว และไม่บอกข้อมูลส่วนตัวกับบุคคลอื่นยกเว้นผู้ปกครองหรือครู แจ้งผู้เกี่ยวข้องเมื่อต้องการความช่วยเหลือเกี่ยวกับการใช้งาน'),
  ('ว 4.2', 'ป.2', 9, 'ข้อปฏิบัติในการใช้งานและการดูแลรักษาอุปกรณ์เช่น ไม่ขีดเขียนบนอุปกรณ์ ทำความสะอาดใช้อุปกรณ์อย่างถูกวิธี'),
  ('ว 4.2', 'ป.2', 10, 'การใช้งานอย่างเหมาะสม เช่น จัดท่านั่งให้ถูกต้องการพักสายตาเมื่อใช้อุปกรณ์เป็นเวลานานระมัดระวังอุบัติเหตุจากการใช้งาน'),
  ('ว 4.2', 'ป.3', 1, 'อัลกอริทึมเป็นขั้นตอนที่ใช้ในการแก้ปัญหา'),
  ('ว 4.2', 'ป.3', 2, 'การแสดงอัลกอริทึม ทำได้โดยการเขียน บอกเล่าวาดภาพ หรือใช้สัญลักษณ์'),
  ('ว 4.2', 'ป.3', 3, 'ตัวอย่างปัญหา เช่น เกมเศรษฐี เกมบันไดงูเกม Tetris เกม OX การเดินไปโรงอาหารการทำความสะอาดห้องเรียน'),
  ('ว 4.2', 'ป.3', 4, 'การเขียนโปรแกรมเป็นการสร้างลำดับของคำสั่งให้คอมพิวเตอร์ทำงาน'),
  ('ว 4.2', 'ป.3', 5, 'ตัวอย่างโปรแกรม เช่น เขียนโปรแกรมที่สั่งให้ตัวละครทำงานซ้ำไม่สิ้นสุด'),
  ('ว 4.2', 'ป.3', 6, 'การตรวจหาข้อผิดพลาด ทำได้โดยตรวจสอบคำสั่งที่แจ้งข้อผิดพลาด หรือหากผลลัพธ์ไม่เป็นไปตามที่ต้องการให้ตรวจสอบการทำงานทีละคำสั่ง'),
  ('ว 4.2', 'ป.3', 7, 'ซอฟต์แวร์หรือสื่อที่ใช้ในการเขียนโปรแกรม เช่นใช้บัตรคำสั่งแสดงการเขียนโปรแกรม, Code.org'),
  ('ว 4.2', 'ป.3', 8, 'อินเทอร์เน็ตเป็นเครือข่ายขนาดใหญ่ช่วยให้การติดต่อสื่อสารทำได้สะดวกและรวดเร็วและเป็นแหล่งข้อมูลความรู้ที่ช่วยในการเรียนและการดำเนินชีวิต'),
  ('ว 4.2', 'ป.3', 9, 'เว็บเบราว์เซอร์เป็นโปรแกรมสำหรับอ่านเอกสารบนเว็บเพจ'),
  ('ว 4.2', 'ป.3', 10, 'การสืบค้นข้อมูลบนอินเทอร์เน็ต ทำได้โดยใช้เว็บไซต์สำหรับสืบค้น และต้องกำหนดคำค้นที่เหมาะสมจึงจะได้ข้อมูลตามต้องการ'),
  ('ว 4.2', 'ป.3', 11, 'ข้อมูลความรู้ เช่น วิธีทำอาหาร วิธีพับกระดาษเป็นรูปต่าง ๆ ข้อมูลประวัติศาสตร์ชาติไทย (อาจเป็นความรู้ในวิชาอื่น ๆ หรือเรื่องที่เป็นประเด็นที่สนใจในช่วงเวลานั้น)'),
  ('ว 4.2', 'ป.3', 12, 'การใช้อินเทอร์เน็ตอย่างปลอดภัยควรอยู่ในการดูแลของครู หรือผู้ปกครอง'),
  ('ว 4.2', 'ป.3', 13, 'การรวบรวมข้อมูล ทำได้โดยกำหนดหัวข้อที่ต้องการ เตรียมอุปกรณ์ในการจดบันทึก'),
  ('ว 4.2', 'ป.3', 14, 'การประมวลผลอย่างง่าย เช่น เปรียบเทียบจัดกลุ่ม เรียงลำดับ'),
  ('ว 4.2', 'ป.3', 15, 'การนำเสนอข้อมูลทำได้หลายลักษณะตามความเหมาะสม เช่น การบอกเล่า การทำเอกสารรายงาน การจัดทำป้ายประกาศ'),
  ('ว 4.2', 'ป.3', 16, 'การใช้ซอฟต์แวร์ทำงานตามวัตถุประสงค์ เช่นใช้ซอฟต์แวร์นำเสนอ หรือซอฟต์แวร์กราฟิกสร้างแผนภูมิรูปภาพ ใช้ซอฟต์แวร์ประมวลคำทำป้ายประกาศหรือเอกสารรายงาน ใช้ซอฟต์แวร์ตารางทำงานในการประมวลผลข้อมูล'),
  ('ว 4.2', 'ป.3', 17, 'การใช้เทคโนโลยีสารสนเทศอย่างปลอดภัย เช่นปกป้องข้อมูลส่วนตัว'),
  ('ว 4.2', 'ป.3', 18, 'ขอความช่วยเหลือจากครูหรือผู้ปกครอง เมื่อเกิดปัญหาจากการใช้งาน เมื่อพบข้อมูลหรือบุคคลที่ทำให้ไม่สบายใจ'),
  ('ว 4.2', 'ป.3', 19, 'การปฏิบัติตามข้อตกลงในการใช้อินเทอร์เน็ตจะทำให้ไม่เกิดความเสียหายต่อตนเองและผู้อื่นเช่น ไม่ใช้คำหยาบ ล้อเลียน ด่าทอ ทำให้ผู้อื่นเสียหายหรือเสียใจ'),
  ('ว 4.2', 'ป.3', 20, 'ข้อดีและข้อเสียในการใช้เทคโนโลยีสารสนเทศและการสื่อสาร'),
  ('ว 4.2', 'ป.4', 1, 'การใช้เหตุผลเชิงตรรกะเป็นการนำกฎเกณฑ์หรือเงื่อนไขที่ครอบคลุมทุกกรณีมาใช้พิจารณาในการแก้ปัญหา การอธิบายการทำงาน หรือการคาดการณ์ผลลัพธ์'),
  ('ว 4.2', 'ป.4', 2, 'สถานะเริ่มต้นของการทำงานที่แตกต่างกันจะให้ผลลัพธ์ที่แตกต่างกัน'),
  ('ว 4.2', 'ป.4', 3, 'ตัวอย่างปัญหา เช่น เกม OX โปรแกรมที่มีการคำนวณ โปรแกรมที่มีตัวละครหลายตัวและมีการสั่งงานที่แตกต่างหรือมีการสื่อสารระหว่างกัน การเดินทางไปโรงเรียน โดยวิธีการต่าง ๆ'),
  ('ว 4.2', 'ป.4', 4, 'การออกแบบโปรแกรมอย่างง่าย เช่น การออกแบบโดยใช้ storyboard หรือการออกแบบอัลกอริทึม'),
  ('ว 4.2', 'ป.4', 5, 'การเขียนโปรแกรมเป็นการสร้างลำดับของคำสั่งให้คอมพิวเตอร์ทำงาน เพื่อให้ได้ผลลัพธ์ตามความต้องการ หากมีข้อผิดพลาดให้ตรวจสอบการทำงานทีละคำสั่ง เมื่อพบจุดที่ทำให้ผลลััพธ์ไม่ถูกต้อง ให้ทำการแก้ไขจนกว่าจะได้ผลลัพธ์ที่ถูกต้อง'),
  ('ว 4.2', 'ป.4', 6, 'ตัวอย่างโปรแกรมที่มีเรื่องราว เช่น นิทานที่มีการโต้ตอบกับผู้ใช้ การ์ตูนสั้น เล่ากิจวัตรประจำวันภาพเคลื่อนไหว'),
  ('ว 4.2', 'ป.4', 7, 'การฝึกตรวจหาข้อผิดพลาดจากโปรแกรมของผู้อื่นจะช่วยพัฒนาทักษะการหาสาเหตุของปัญหาได้ดียิ่งขึ้น'),
  ('ว 4.2', 'ป.4', 8, 'ซอฟต์แวร์ที่ใช้ในการเขียนโปรแกรม เช่น Scratch, logo'),
  ('ว 4.2', 'ป.4', 9, 'การใช้คำค้นที่ตรงประเด็น กระชับ จะทำให้ได้ผลลัพธ์ที่รวดเร็วและตรงตามความต้องการ'),
  ('ว 4.2', 'ป.4', 10, 'การประเมินความน่าเชื่อถือของข้อมูล เช่นพิจารณาประเภทของเว็บไซต์ (หน่วยงานราชการสำนักข่าว องค์กร) ผู้เขียน วันที่เผยแพร่ข้อมูลการอ้างอิง'),
  ('ว 4.2', 'ป.4', 11, 'เมื่อได้ข้อมูลที่ต้องการจากเว็บไซต์ต่าง ๆ จะต้องนำเนื้อหามาพิจารณา เปรียบเทียบ แล้วเลือกข้อมูลที่มีความสอดคล้องและสัมพันธ์กัน'),
  ('ว 4.2', 'ป.4', 12, 'การทำรายงานหรือการนำเสนอข้อมูลจะต้องนำข้อมูลมาเรียบเรียง สรุป เป็นภาษาของตนเองที่เหมาะสมกับกลุ่มเป้าหมายและวิธีการนำเสนอ (บูรณาการกับวิชาภาษาไทย)'),
  ('ว 4.2', 'ป.4', 13, 'การรวบรวมข้อมูล ทำได้โดยกำหนดหัวข้อที่ต้องการ เตรียมอุปกรณ์ในการจดบันทึก'),
  ('ว 4.2', 'ป.4', 14, 'การประมวลผลอย่างง่าย เช่น เปรียบเทียบจัดกลุ่ม เรียงลำดับ การหาผลรวม'),
  ('ว 4.2', 'ป.4', 15, 'วิเคราะห์ผลและสร้างทางเลือกที่เป็นไปได้ประเมินทางเลือก (เปรียบเทียบ ตัดสิน)'),
  ('ว 4.2', 'ป.4', 16, 'การนำเสนอข้อมูลทำได้หลายลักษณะตามความเหมาะสม เช่น การบอกเล่า เอกสารรายงานโปสเตอร์ โปรแกรมนำเสนอ'),
  ('ว 4.2', 'ป.4', 17, 'การใช้ซอฟต์แวร์เพื่อแก้ปัญหาในชีวิตประจำวันเช่น การสำรวจเมนูอาหารกลางวันโดยใช้ซอฟต์แวร์สร้างแบบสอบถามและเก็บข้อมูล ใช้ซอฟต์แวร์ตารางทำงานเพื่อประมวลผลข้อมูลรวบรวมข้อมูลเกี่ยวกับคุณค่าทางโภชนาการและสร้างรายการอาหารสำหรับ 5 วัน ใช้ซอฟต์แวร์นำเสนอผลการสำรวจรายการอาหารที่เป็นทางเลือกและข้อมูลด้านโภชนาการ'),
  ('ว 4.2', 'ป.4', 18, 'การใช้เทคโนโลยีสารสนเทศอย่างปลอดภัย เข้าใจสิทธิและหน้าที่ของตน เคารพในสิทธิของผู้อื่นเช่น ไม่สร้างข้อความเท็จและส่งให้ผู้อื่น ไม่สร้างความเดือดร้อนต่อผู้อื่นโดยการส่งสแปมข้อความลูกโซ่ ส่งต่อโพสต์ที่มีข้อมูลส่วนตัวของผู้อื่นส่งคำเชิญเล่นเกม ไม่เข้าถึงข้อมูลส่วนตัวหรือการบ้านของบุคคลอื่นโดยไม่ได้รับอนุญาต ไม่ใช้เครื่องคอมพิวเตอร์/ชื่อบัญชีของผู้อื่น'),
  ('ว 4.2', 'ป.4', 19, 'การสื่อสารอย่างมีมารยาทและรู้กาลเทศะ'),
  ('ว 4.2', 'ป.4', 20, 'การปกป้องข้อมูลส่วนตัว เช่น การออกจากระบบเมื่อเลิกใช้งาน ไม่บอกรหัสผ่าน ไม่บอกเลขประจำตัวประชาชน'),
  ('ว 4.2', 'ป.5', 1, 'การใช้เหตุผลเชิงตรรกะเป็นการนำกฎเกณฑ์ หรือเงื่อนไขที่ครอบคลุมทุกกรณีมาใช้พิจารณาในการแก้ปัญหา การอธิบายการทำงาน หรือการคาดการณ์ผลลัพธ์'),
  ('ว 4.2', 'ป.5', 2, 'สถานะเริ่มต้นของการทำงานที่แตกต่างกันจะให้ผลลัพธ์ที่แตกต่างกัน'),
  ('ว 4.2', 'ป.5', 3, 'ตัวอย่างปัญหา เช่น เกม Sudoku โปรแกรมทำนายตัวเลข โปรแกรมสร้างรูปเรขาคณิตตามค่าข้อมูลเข้า การจัดลำดับการทำงานบ้านในช่วงวันหยุด จัดวางของในครัว'),
  ('ว 4.2', 'ป.5', 4, 'การออกแบบโปรแกรมสามารถทำได้โดยเขียนเป็นข้อความหรือผังงาน'),
  ('ว 4.2', 'ป.5', 5, 'การออกแบบและเขียนโปรแกรมที่มีการตรวจสอบเงื่อนไขที่ครอบคลุมทุกกรณีเพื่อให้ได้ผลลัพธ์ที่ถูกต้องตรงตามความต้องการ'),
  ('ว 4.2', 'ป.5', 6, 'หากมีข้อผิดพลาดให้ตรวจสอบการทำงานทีละคำสั่ง เมื่อพบจุดที่ทำให้ผลลััพธ์ไม่ถูกต้องให้ทำการแก้ไขจนกว่าจะได้ผลลัพธ์ที่ถูกต้อง'),
  ('ว 4.2', 'ป.5', 7, 'การฝึกตรวจหาข้อผิดพลาดจากโปรแกรมของผู้อื่น จะช่วยพัฒนาทักษะการหาสาเหตุของปัญหาได้ดียิ่งขึ้น'),
  ('ว 4.2', 'ป.5', 8, 'ตัวอย่างโปรแกรม เช่น โปรแกรมตรวจสอบเลขคู่เลขคี่ โปรแกรมรับข้อมูลน้ำหนักหรือส่วนสูงแล้วแสดงผลความสมส่วนของร่างกาย โปรแกรมสั่งให้ตัวละครทำตามเงื่อนไขที่กำหนด'),
  ('ว 4.2', 'ป.5', 9, 'ซอฟต์แวร์ที่ใช้ในการเขียนโปรแกรม เช่น Scratch, logo'),
  ('ว 4.2', 'ป.5', 10, 'การค้นหาข้อมูลในอินเทอร์เน็ต และการพิจารณาผลการค้นหา'),
  ('ว 4.2', 'ป.5', 11, 'การติดต่อสื่อสารผ่านอินเทอร์เน็ต เช่น อีเมลบล็อก โปรแกรมสนทนา'),
