  ('ว 4.2', 'ม.3', 11, 'เหตุผลวิบัติ (logical fallacy)'),
  ('ว 4.2', 'ม.3', 12, 'ผลกระทบจากข่าวสารที่ผิดพลาด'),
  ('ว 4.2', 'ม.3', 13, 'การรู้เท่าทันสื่อ เช่น การวิเคราะห์ถึงจุดประสงค์ของข้อมูลและผู้ให้ข้อมูล ตีความ แยกแยะเนื้อหาสาระของสื่อ เลือกแนวปฏิบัติได้อย่างเหมาะสมเมื่อพบข้อมูลต่าง ๆ'),
  ('ว 4.2', 'ม.3', 14, 'การใช้เทคโนโลยีสารสนเทศอย่างปลอดภัย เช่นการทำธุรกรรมออนไลน์ การซื้อสินค้าซื้อซอฟต์แวร์ ค่าบริการสมาชิก ซื้อไอเท็ม'),
  ('ว 4.2', 'ม.3', 15, 'การใช้เทคโนโลยีสารสนเทศอย่างมีความรับผิดชอบเช่น ไม่สร้างข่าวลวง ไม่แชร์ข้อมูลโดยไม่ตรวจสอบข้อเท็จจริง'),
  ('ว 4.2', 'ม.3', 16, 'กฎหมายเกี่ยวกับคอมพิวเตอร์'),
  ('ว 4.2', 'ม.3', 17, 'การใช้ลิขสิทธิ์ของผู้อื่นโดยชอบธรรม (fair use)'),
  ('ว 4.2', 'ม.4', 1, 'การพัฒนาโครงงาน'),
  ('ว 4.2', 'ม.4', 2, 'การนำแนวคิดเชิงคำนวณไปพัฒนาโครงงานที่เกี่ยวกับชีวิตประจำวัน เช่น การจัดการพลังงานอาหาร การเกษตร การตลาด การค้าขายการทำธุรกรรม สุขภาพ และสิ่งแวดล้อม'),
  ('ว 4.2', 'ม.4', 3, 'ตัวอย่างโครงงาน เช่น ระบบดูแลสุขภาพ ระบบอัตโนมัติควบคุมการปลูกพืช ระบบจัดเส้นทางการขนส่งผลผลิต ระบบแนะนำการใช้งานห้องสมุดที่มีการโต้ตอบกับผู้ใช้และเชื่อมต่อกับฐานข้อมูล'),
  ('ว 4.2', 'ม.5', 1, 'การนำความรู้ด้านวิทยาการคอมพิวเตอร์สื่อดิจิทัล และเทคโนโลยีสารสนเทศ มาใช้แก้ปัญหากับชีวิตจริง'),
  ('ว 4.2', 'ม.5', 2, 'การเพิ่มมูลค่าให้บริการหรือผลิตภัณฑ์'),
  ('ว 4.2', 'ม.5', 3, 'การเก็บข้อมูลและการจัดเตรียมข้อมูลให้พร้อมกับการประมวลผล'),
  ('ว 4.2', 'ม.5', 4, 'การวิเคราะห์ข้อมูลทางสถิติ'),
  ('ว 4.2', 'ม.5', 5, 'การประมวลผลข้อมูล และเครื่องมือ'),
  ('ว 4.2', 'ม.5', 6, 'การทำข้อมูลให้เป็นภาพ (data visualization) เช่น bar chart, scatter, histogram'),
  ('ว 4.2', 'ม.5', 7, 'การเลือกใช้แหล่งข้อมูล เช่น data.go.th, wolfram alpha, OECD.org, ตลาดหลักทรัพย์ , world economic forum'),
  ('ว 4.2', 'ม.5', 8, 'คุณค่าของข้อมูลและกรณีศึกษา'),
  ('ว 4.2', 'ม.5', 9, 'กรณีศึกษาและวิธีการแก้ปัญหา'),
  ('ว 4.2', 'ม.5', 10, 'ตัวอย่างปัญหา เช่น - รูปแบบของบรรจุภัณฑ์ที่ดึงดูดความสนใจ และตรงตามความต้องการผู้ใช้ในแต่ละประเภท - การกำหนดตำแหน่งป้ายรถเมล์เพื่อลดเวลาเดินทางและปัญหาการจราจร - สำรวจความต้องการรับประทานอาหารในชุมชน และเลือกขายอาหารที่จะได้กำไรสูงสุด - ออกแบบรายการอาหาร 7 วัน สำหรับผู้ป่วยเบาหวาน'),
  ('ว 4.2', 'ม.6', 1, 'การนำเสนอและแบ่งปันข้อมูล เช่น การเขียนบล็อก อัปโหลดวิดีโอ ภาพอินโฟกราฟิก'),
  ('ว 4.2', 'ม.6', 2, 'การนำเสนอและแบ่งปันข้อมูลอย่างปลอดภัยเช่น ระมัดระวังผลกระทบที่ตามมา เมื่อมีการแบ่งปันข้อมูลหรือเผยแพร่ข้อมูล ไม่สร้างความเดือดร้อนต่อตนเองและผู้อื่น'),
  ('ว 4.2', 'ม.6', 3, 'จริยธรรมในการใช้เทคโนโลยีสารสนเทศ'),
  ('ว 4.2', 'ม.6', 4, 'เทคโนโลยีเกิดใหม่ แนวโน้มในอนาคตการเปลี่ยนแปลงของเทคโนโลยี'),
  ('ว 4.2', 'ม.6', 5, 'นวัตกรรมหรือเทคโนโลยีด้านต่าง ๆ ที่เกี่ยวข้องกับชีวิตประจำวัน'),
  ('ว 4.2', 'ม.6', 6, 'อาชีพเกี่ยวกับเทคโนโลยีสารสนเทศ'),
  ('ว 4.2', 'ม.6', 7, 'ผลกระทบของเทคโนโลยีสารสนเทศต่อการดำเนินชีวิต อาชีพ สังคม และวัฒนธรรม')
INSERT INTO public.curriculum_learner_quality (learning_area, level_code, seq, description) VALUES
  ('วิทยาศาสตร์', 'ป.3', 1, 'เข้าใจลักษณะทั่วไปของสิ่งมีชีวิตและการดำรงชีวิตของสิ่งมีชีวิตรอบตัว'),
  ('วิทยาศาสตร์', 'ป.3', 2, 'เข้าใจลักษณะที่ปรากฏ ชนิดและสมบัติบางประการของวัสดุที่ใช้ทำวัตถุและการเปลี่ยนแปลงของวัสดุรอบตัว'),
  ('วิทยาศาสตร์', 'ป.3', 3, 'เข้าใจการดึง การผลัก แรงแม่เหล็ก และผลของแรงที่มีต่อการเปลี่ยนแปลงการเคลื่อนที่ของวัตถุ พลังงานไฟฟ้า และการผลิตไฟฟ้า การเกิดเสียง แสงและการมองเห็น'),
  ('วิทยาศาสตร์', 'ป.3', 4, 'เข้าใจการปรากฏของดวงอาทิตย์ ดวงจันทร์ และดาว ปรากฏการณ์การขึ้นและตกของดวงอาทิตย์ การเกิดกลางวันกลางคืน การกำหนดทิศ ลักษณะของหิน การจำแนกชนิดดินและการใช้ประโยชน์ ลักษณะและความสำคัญของอากาศ การเกิดลม ประโยชน์และโทษของลม'),
  ('วิทยาศาสตร์', 'ป.3', 5, 'ตั้งคำถามหรือกำหนดปัญหาเกี่ยวกับสิ่งที่จะเรียนรู้ตามที่กำหนดให้หรือตามความสนใจสังเกต สำรวจตรวจสอบโดยใช้เครื่องมืออย่างง่าย รวบรวมข้อมูล บันทึก และอธิบายผลการสำรวจตรวจสอบด้วยการเขียนหรือวาดภาพ และสื่อสารสิ่งที่เรียนรู้ด้วยการเล่าเรื่อง หรือด้วยการแสดงท่าทางเพื่อให้ผู้อื่นเข้าใจ'),
  ('วิทยาศาสตร์', 'ป.3', 6, 'แก้ปัญหาอย่างง่ายโดยใช้ขั้นตอนการแก้ปัญหา มีทักษะในการใช้เทคโนโลยีสารสนเทศและการสื่อสารเบื้องต้น รักษาข้อมูลส่วนตัว'),
  ('วิทยาศาสตร์', 'ป.3', 7, 'แสดงความกระตือรือร้น สนใจที่จะเรียนรู้ มีความคิดสร้างสรรค์เกี่ยวกับเรื่องที่จะศึกษาตามที่กำหนดให้หรือตามความสนใจ มีส่วนร่วมในการแสดงความคิดเห็น และยอมรับฟังความคิดเห็นผู้อื่น'),
  ('วิทยาศาสตร์', 'ป.3', 8, 'แสดงความรับผิดชอบด้วยการทำงานที่ได้รับมอบหมายอย่างมุ่งมั่น รอบคอบประหยัด ซื่อสัตย์ จนงานลุล่วงเป็นผลสำเร็จ และทำงานร่วมกับผู้อื่นอย่างมีความสุข'),
  ('วิทยาศาสตร์', 'ป.3', 9, 'ตระหนักถึงประโยชน์ของการใช้ความรู้และกระบวนการทางวิทยาศาสตร์ในการดำรงชีวิต ศึกษาหาความรู้เพิ่มเติม ทำโครงงานหรือชิ้นงานตามที่กำหนดให้หรือตามความสนใจ'),
  ('วิทยาศาสตร์', 'ป.6', 1, 'เข้าใจโครงสร้าง ลักษณะเฉพาะการปรับตัวของสิ่งมีชีวิต รวมทั้งความสัมพันธ์ของสิ่งมีชีวิตในแหล่งที่อยู่ การทำหน้าที่ของส่วนต่าง ๆ ของพืช และการทำงานของระบบย่อยอาหารของมนุษย์'),
  ('วิทยาศาสตร์', 'ป.6', 2, 'เข้าใจสมบัติและการจำแนกกลุ่มของวัสดุ สถานะและการเปลี่ยนสถานะของสสารการละลาย การเปลี่ยนแปลงทางเคมี การเปลี่ยนแปลงที่ผันกลับได้และผันกลับไม่ได้ และการแยกสารอย่างง่าย'),
  ('วิทยาศาสตร์', 'ป.6', 3, 'เข้าใจลักษณะของแรงโน้มถ่วงของโลก แรงลัพธ์ แรงเสียดทาน แรงไฟฟ้าและผลของแรงต่าง ๆ ผลที่เกิดจากแรงกระทำต่อวัตถุ ความดัน หลักการที่มีต่อวัตถุ วงจรไฟฟ้าอย่างง่ายปรากฏการณ์เบื้องต้นของเสียง และแสง'),
  ('วิทยาศาสตร์', 'ป.6', 4, 'เข้าใจปรากฏการณ์การขึ้นและตก รวมถึงการเปลี่ยนแปลงรูปร่างปรากฏของดวงจันทร์ องค์ประกอบของระบบสุริยะ คาบการโคจรของดาวเคราะห์ ความแตกต่างของดาวเคราะห์และดาวฤกษ์ การขึ้นและตกของกลุ่มดาวฤกษ์ การใช้แผนที่ดาว การเกิดอุปราคาพัฒนาการและประโยชน์ของเทคโนโลยีอวกาศ'),
  ('วิทยาศาสตร์', 'ป.6', 5, 'เข้าใจลักษณะของแหล่งน้ำ วัฏจักรน้ำ กระบวนการเกิดเมฆ หมอก น้ำค้างน้ำค้างแข็ง หยาดน้ำฟ้า กระบวนการเกิดหิน วัฏจักรหิน การใช้ประโยชน์หินและแร่ การเกิดซากดึกดำบรรพ์ การเกิดลมบก ลมทะเล มรสุม ลักษณะและผลกระทบของภัยธรรมชาติ ธรณีพิบัติภัยการเกิดและผลกระทบของปรากฏการณ์เรือนกระจก'),
  ('วิทยาศาสตร์', 'ป.6', 6, 'ค้นหาข้อมูลอย่างมีประสิทธิภาพและประเมินความน่าเชื่อถือ ตัดสินใจเลือกข้อมูลใช้เหตุผลเชิงตรรกะในการแก้ปัญหา ใช้เทคโนโลยีสารสนเทศและการสื่อสารในการทำงานร่วมกันเข้าใจสิทธิและหน้าที่ของตน เคารพสิทธิของผู้อื่น'),
  ('วิทยาศาสตร์', 'ป.6', 7, 'ตั้งคำถามหรือกำหนดปัญหาเกี่ยวกับสิ่งที่จะเรียนรู้ตามที่กำหนดให้หรือตามความสนใจ คาดคะเนคำตอบหลายแนวทาง สร้างสมมติฐานที่สอดคล้องกับคำถามหรือปัญหาที่จะสำรวจตรวจสอบ วางแผนและสำรวจตรวจสอบโดยใช้เครื่องมือ อุปกรณ์ และเทคโนโลยีสารสนเทศที่เหมาะสม ในการเก็บรวบรวมข้อมูลทั้งเชิงปริมาณและคุณภาพ'),
  ('วิทยาศาสตร์', 'ป.6', 8, 'วิเคราะห์ข้อมูล ลงความเห็น และสรุปความสัมพันธ์ของข้อมูลที่มาจากการสำรวจตรวจสอบในรูปแบบที่เหมาะสม เพื่อสื่อสารความรู้จากผลการสำรวจตรวจสอบได้อย่างมีเหตุผลและหลักฐานอ้างอิง'),
  ('วิทยาศาสตร์', 'ป.6', 9, 'แสดงถึงความสนใจ มุ่งมั่น ในสิ่งที่จะเรียนรู้ มีความคิดสร้างสรรค์เกี่ยวกับเรื่องที่จะศึกษาตามความสนใจของตนเอง แสดงความคิดเห็นของตนเอง ยอมรับในข้อมูลที่มีหลักฐานอ้างอิง และรับฟังความคิดเห็นผู้อื่น'),
  ('วิทยาศาสตร์', 'ป.6', 10, 'แสดงความรับผิดชอบด้วยการทำงานที่ได้รับมอบหมายอย่างมุ่งมั่นรอบคอบ ประหยัด ซื่อสัตย์ จนงานลุล่วงเป็นผลสำเร็จ และทำงานร่วมกับผู้อื่นอย่างสร้างสรรค์'),
  ('วิทยาศาสตร์', 'ป.6', 11, 'ตระหนักในคุณค่าของความรู้วิทยาศาสตร์และเทคโนโลยี ใช้ความรู้และกระบวนการทางวิทยาศาสตร์ในการดำรงชีวิต แสดงความชื่นชม ยกย่อง และเคารพสิทธิในผลงานของผู้คิดค้นและศึกษาหาความรู้เพิ่มเติม ทำโครงงานหรือชิ้นงานตามที่กำหนดให้หรือตามความสนใจ'),
  ('วิทยาศาสตร์', 'ป.6', 12, 'แสดงถึงความซาบซึ้ง ห่วงใย แสดงพฤติกรรมเกี่ยวกับการใช้ การดูแลรักษาทรัพยากรธรรมชาติและสิ่งแวดล้อมอย่างรู้คุณค่า'),
  ('วิทยาศาสตร์', 'ม.3', 1, 'เข้าใจลักษณะและองค์ประกอบที่สำคัญของเซลล์สิ่งมีชีวิต ความสัมพันธ์ของการทำงานของระบบต่าง ๆ ในร่างกายมนุษย์ การดำรงชีวิตของพืช การถ่ายทอดลักษณะทางพันธุกรรมการเปลี่ยนแปลงของยีนหรือโครโมโซม และตัวอย่างโรคที่เกิดจากการเปลี่ยนแปลงทางพันธุกรรมประโยชน์และผลกระทบของสิ่งมีชีวิตดัดแปรพันธุกรรม ความหลากหลายทางชีวภาพ ปฏิสัมพันธ์ขององค์ประกอบของระบบนิเวศและการถ่ายทอดพลังงานในสิ่งมีชีวิต'),
  ('วิทยาศาสตร์', 'ม.3', 2, 'เข้าใจองค์ประกอบและสมบัติของธาตุ สารละลาย สารบริสุทธิ์ สารผสมหลักการแยกสาร การเปลี่ยนแปลงของสารในรูปแบบของการเปลี่ยนสถานะ การเกิดสารละลายและการเกิดปฏิกิริยาเคมี และสมบัติทางกายภาพ และการใช้ประโยชน์ของวัสดุประเภทพอลิเมอร์เซรามิก และวัสดุผสม'),
  ('วิทยาศาสตร์', 'ม.3', 3, 'เข้าใจการเคลื่อนที่ แรงลัพธ์และผลของแรงลัพธ์กระทำต่อวัตถุ โมเมนต์ของแรงแรงที่ปรากฏในชีวิตประจำวัน สนามของแรง ความสัมพันธ์ของงาน พลังงานจลน์ พลังงานศักย์โน้มถ่วงกฎการอนุรักษ์พลังงาน การถ่ายโอนพลังงาน สมดุลความร้อน ความสัมพันธ์ของปริมาณทางไฟฟ้าการต่อวงจรไฟฟ้าในบ้าน พลังงานไฟฟ้า และหลักการเบื้องต้นของวงจรอิเล็กทรอนิกส์'),
  ('วิทยาศาสตร์', 'ม.3', 4, 'เข้าใจสมบัติของคลื่น และลักษณะของคลื่นแบบต่าง ๆ แสง การสะท้อนการหักเหของแสงและทัศนอุปกรณ์'),
  ('วิทยาศาสตร์', 'ม.3', 5, 'เข้าใจการโคจรของดาวเคราะห์รอบดวงอาทิตย์ การเกิดฤดู การเคลื่อนที่ปรากฏของดวงอาทิตย์ การเกิดข้างขึ้นข้างแรม การขึ้นและตกของดวงจันทร์ การเกิดน้ำขึ้นน้ำลงประโยชน์ของเทคโนโลยีอวกาศ และความก้าวหน้าของโครงการสำรวจอวกาศ'),
  ('วิทยาศาสตร์', 'ม.3', 6, 'เข้าใจลักษณะของชั้นบรรยากาศ องค์ประกอบและปัจจัยที่มีผลต่อลมฟ้าอากาศการเกิดและผลกระทบของพายุฟ้าคะนอง พายุหมุนเขตร้อน การพยากรณ์อากาศ สถานการณ์การเปลี่ยนแปลงภูมิอากาศโลก กระบวนการเกิดเชื้อเพลิงซากดึกดำบรรพ์และการใช้ประโยชน์พลังงานทดแทนและการใช้ประโยชน์ ลักษณะโครงสร้างภายในโลก กระบวนการเปลี่ยนแปลงทางธรณีวิทยาบนผิวโลก ลักษณะชั้นหน้าตัดดิน กระบวนการเกิดดิน แหล่งน้ำผิวดิน แหล่งน้ำใต้ดินกระบวนการเกิดและผลกระทบของภัยธรรมชาติ และธรณีพิบัติภัย'),
  ('วิทยาศาสตร์', 'ม.3', 7, 'เข้าใจแนวคิดหลักของเทคโนโลยี ได้แก่ ระบบทางเทคโนโลยี การเปลี่ยนแปลงของเทคโนโลยี ความสัมพันธ์ระหว่างเทคโนโลยีกับศาสตร์อื่น โดยเฉพาะวิทยาศาสตร์ หรือคณิตศาสตร์ วิเคราะห์ เปรียบเทียบ และตัดสินใจเพื่อเลือกใช้เทคโนโลยี โดยคำนึงถึงผลกระทบต่อชีวิต สังคม และสิ่งแวดล้อม ประยุกต์ใช้ความรู้ ทักษะ และทรัพยากรเพื่อออกแบบและสร้างผลงานสำหรับการแก้ปัญหาในชีวิตประจำวันหรือการประกอบอาชีพ โดยใช้กระบวนการออกแบบเชิงวิศวกรรม รวมทั้งเลือกใช้วัสดุ อุปกรณ์ และเครื่องมือได้อย่างถูกต้อง เหมาะสม ปลอดภัย รวมทั้งคำนึงถึงทรัพย์สินทางปัญญา'),
  ('วิทยาศาสตร์', 'ม.3', 8, 'นำข้อมูลปฐมภูมิเข้าสู่ระบบคอมพิวเตอร์ วิเคราะห์ ประเมิน นำเสนอข้อมูลและสารสนเทศได้ตามวัตถุประสงค์ ใช้ทักษะการคิดเชิงคำนวณในการแก้ปัญหาที่พบในชีวิตจริงและเขียนโปรแกรมอย่างง่ายเพื่อช่วยในการแก้ปัญหา ใช้เทคโนโลยีสารสนเทศและการสื่อสารอย่างรู้เท่าทันและรับผิดชอบต่อสังคม'),
  ('วิทยาศาสตร์', 'ม.3', 9, 'ตั้งคำถามหรือกำหนดปัญหาที่เชื่อมโยงกับพยานหลักฐาน หรือหลักการทางวิทยาศาสตร์ที่มีการกำหนดและควบคุมตัวแปร คิดคาดคะเนคำตอบหลายแนวทาง สร้างสมมติฐานที่สามารถนำไปสู่การสำรวจตรวจสอบ ออกแบบและลงมือสำรวจตรวจสอบโดยใช้วัสดุและเครื่องมือที่เหมาะสม เลือกใช้เครื่องมือและเทคโนโลยีสารสนเทศที่เหมาะสมในการเก็บรวบรวมข้อมูลทั้งในเชิงปริมาณและคุณภาพที่ได้ผลเที่ยงตรงและปลอดภัย'),
  ('วิทยาศาสตร์', 'ม.3', 10, 'วิเคราะห์และประเมินความสอดคล้องของข้อมูลที่ได้จากการสำรวจตรวจสอบจากพยานหลักฐาน โดยใช้ความรู้และหลักการทางวิทยาศาสตร์ในการแปลความหมายและลงข้อสรุปและสื่อสารความคิด ความรู้ จากผลการสำรวจตรวจสอบหลากหลายรูปแบบ หรือใช้เทคโนโลยีสารสนเทศเพื่อให้ผู้อื่นเข้าใจได้อย่างเหมาะสม'),
  ('วิทยาศาสตร์', 'ม.3', 11, 'แสดงถึงความสนใจ มุ่งมั่น รับผิดชอบ รอบคอบ และซื่อสัตย์ ในสิ่งที่จะเรียนรู้มีความคิดสร้างสรรค์เกี่ยวกับเรื่องที่จะศึกษาตามความสนใจของตนเอง โดยใช้เครื่องมือและวิธีการที่ให้ได้ผลถูกต้อง เชื่อถือได้ ศึกษาค้นคว้าเพิ่มเติมจากแหล่งความรู้ต่าง ๆ แสดงความคิดเห็นของตนเอง รับฟังความคิดเห็นผู้อื่น และยอมรับการเปลี่ยนแปลงความรู้ที่ค้นพบ เมื่อมีข้อมูลและประจักษ์พยานใหม่เพิ่มขึ้นหรือโต้แย้งจากเดิม'),
  ('วิทยาศาสตร์', 'ม.3', 12, 'ตระหนักในคุณค่าของความรู้วิทยาศาสตร์และเทคโนโลยีที่ใช้ในชีวิตประจำวันใช้ความรู้และกระบวนการทางวิทยาศาสตร์และเทคโนโลยีในการดำรงชีวิต และการประกอบอาชีพแสดงความชื่นชม ยกย่อง และเคารพสิทธิในผลงานของผู้คิดค้น เข้าใจผลกระทบทั้งด้านบวกและด้านลบของการพัฒนาทางวิทยาศาสตร์ต่อสิ่งแวดล้อมและต่อบริบทอื่น ๆ และศึกษาหาความรู้เพิ่มเติม ทำโครงงานหรือสร้างชิ้นงานตามความสนใจ'),
  ('วิทยาศาสตร์', 'ม.3', 13, 'แสดงถึงความซาบซึ้ง ห่วงใย มีพฤติกรรมเกี่ยวกับการดูแลรักษาความสมดุลของระบบนิเวศ และความหลากหลายทางชีวภาพ'),
  ('วิทยาศาสตร์', 'ม.6', 1, 'เข้าใจการลำเลียงสารเข้าและออกจากเซลล์ กลไกการรักษาดุลยภาพของมนุษย์ ภูมิคุ้มกันในร่างกายของมนุษย์และความผิดปกติของระบบภูมิคุ้มกัน การใช้ประโยชน์จากสารต่าง ๆ ที่พืชสร้างขึ้น การถ่ายทอดลักษณะทางพันธุกรรม การเปลี่ยนแปลงทางพันธุกรรม วิวัฒนาการที่ทำให้เกิดความหลากหลายของสิ่งมีชีวิต ความสำคัญและผลของเทคโนโลยีทางดีเอ็นเอต่อมนุษย์สิ่งมีชีวิต และสิ่งแวดล้อม'),
  ('วิทยาศาสตร์', 'ม.6', 2, 'เข้าใจความหลากหลายของไบโอมในเขตภูมิศาสตร์ต่าง ๆ ของโลก การเปลี่ยนแปลงแทนที่ในระบบนิเวศ ปัญหาและผลกระทบที่มีต่อทรัพยากรธรรมชาติและสิ่งแวดล้อม แนวทางในการอนุรักษ์ทรัพยากรธรรมชาติ และการแก้ไขปัญหาสิ่งแวดล้อม'),
  ('วิทยาศาสตร์', 'ม.6', 3, 'เข้าใจชนิดของอนุภาคสำคัญที่เป็นส่วนประกอบในโครงสร้างอะตอม สมบัติบางประการของธาตุ การจัดเรียงธาตุในตารางธาตุ ชนิดของแรงยึดเหนี่ยวระหว่างอนุภาคและสมบัติต่าง ๆ ของสารที่มีความสัมพันธ์กับแรงยึดเหนี่ยว พันธะเคมี โครงสร้างและสมบัติของพอลิเมอร์การเกิดปฏิกิริยาเคมี ปัจจัยที่มีผลต่ออัตราการเกิดปฏิกิริยาเคมี และการเขียนสมการเคมี'),
  ('วิทยาศาสตร์', 'ม.6', 4, 'เข้าใจปริมาณที่เกี่ยวกับการเคลื่อนที่ ความสัมพันธ์ระหว่างแรง มวลและความเร่งผลของความเร่งที่มีต่อการเคลื่อนที่แบบต่าง ๆ ของวัตถุ แรงโน้มถ่วง แรงแม่เหล็ก ความสัมพันธ์ระหว่างสนามแม่เหล็กและกระแสไฟฟ้า และแรงภายในนิวเคลียส'),
  ('วิทยาศาสตร์', 'ม.6', 5, 'เข้าใจพลังงานนิวเคลียร์ ความสัมพันธ์ระหว่างมวลและพลังงาน การเปลี่ยนพลังงานทดแทนเป็นพลังงานไฟฟ้า เทคโนโลยีด้านพลังงาน การสะท้อน การหักเห การเลี้ยวเบนและการรวมคลื่น การได้ยิน ปรากฏการณ์ที่เกี่ยวข้องกับเสียง สีกับการมองเห็นสี คลื่นแม่เหล็กไฟฟ้าและประโยชน์ของคลื่นแม่เหล็กไฟฟ้า'),
  ('วิทยาศาสตร์', 'ม.6', 6, 'เข้าใจการแบ่งชั้นและสมบัติของโครงสร้างโลก สาเหตุ และรูปแบบการเคลื่อนที่ของแผ่นธรณีที่สัมพันธ์กับการเกิดลักษณะธรณีสัณฐาน สาเหตุ กระบวนการเกิดแผ่นดินไหว ภูเขาไฟระเบิด สึนามิ ผลกระทบ แนวทางการเฝ้าระวัง และการปฏิบัติตนให้ปลอดภัย'),
  ('วิทยาศาสตร์', 'ม.6', 7, 'เข้าใจผลของแรงเนื่องจากความแตกต่างของความกดอากาศ แรงคอริออลิส ที่มีต่อการหมุนเวียนของอากาศ การหมุนเวียนของอากาศตามเขตละติจูด และผลที่มีต่อภูมิอากาศความสัมพันธ์ของการหมุนเวียนของอากาศ และการหมุนเวียนของกระแสน้ำผิวหน้าในมหาสมุทรและผลต่อลักษณะลมฟ้าอากาศ สิ่งมีชีวิตและสิ่งแวดล้อม ปัจจัยต่าง ๆ ที่มีผลต่อการเปลี่ยนแปลงภูมิอากาศโลก และแนวปฏิบัติเพื่อลดกิจกรรมของมนุษย์ที่ส่งผลต่อการเปลี่ยนแปลงภูมิอากาศโลกรวมทั้งการแปลความหมายสัญลักษณ์ลมฟ้าอากาศที่สำคัญจากแผนที่อากาศ และข้อมูลสารสนเทศ'),
  ('วิทยาศาสตร์', 'ม.6', 8, 'เข้าใจการกำเนิดและการเปลี่ยนแปลงพลังงาน สสาร ขนาด อุณหภูมิของเอกภพ หลักฐานที่สนับสนุนทฤษฎีบิกแบง ประเภทของกาแล็กซี โครงสร้างและองค์ประกอบของกาแล็กซีทางช้างเผือก กระบวนการเกิดและการสร้างพลังงาน ปัจจัยที่ส่งผลต่อความส่องสว่างของดาวฤกษ์ และความสัมพันธ์ระหว่างความส่องสว่างกับโชติมาตรของดาวฤกษ์ ความสัมพันธ์ระหว่างสีอุณหภูมิผิว และสเปกตรัมของดาวฤกษ์ วิวัฒนาการและการเปลี่ยนแปลงสมบัติบางประการของดาวฤกษ์ กระบวนการเกิดระบบสุริยะ การแบ่งเขตบริวารของดวงอาทิตย์ ลักษณะของดาวเคราะห์ที่เอื้อต่อการดำรงชีวิต การเกิดลมสุริยะ พายุสุริยะและผลที่มีต่อโลก รวมทั้งการสำรวจอวกาศและการประยุกต์ใช้เทคโนโลยีอวกาศ'),
  ('วิทยาศาสตร์', 'ม.6', 9, 'ระบุปัญหา ตั้งคำถามที่จะสำรวจตรวจสอบ โดยมีการกำหนดความสัมพันธ์ระหว่างตัวแปรต่าง ๆ สืบค้นข้อมูลจากหลายแหล่ง ตั้งสมมติฐานที่เป็นไปได้หลายแนวทาง ตัดสินใจเลือกตรวจสอบสมมติฐานที่เป็นไปได้'),
  ('วิทยาศาสตร์', 'ม.6', 10, 'ตั้งคำถามหรือกำหนดปัญหาที่อยู่บนพื้นฐานของความรู้และความเข้าใจทางวิทยาศาสตร์ ที่แสดงให้เห็นถึงการใช้ความคิดระดับสูงที่สามารถสำรวจตรวจสอบหรือศึกษาค้นคว้าได้อย่างครอบคลุมและเชื่อถือได้ สร้างสมมติฐานที่มีทฤษฎีรองรับหรือคาดการณ์สิ่งที่จะพบ เพื่อนำไปสู่การสำรวจตรวจสอบ ออกแบบวิธีการสำรวจตรวจสอบตามสมมติฐานที่กำหนดไว้ได้อย่างเหมาะสมมีหลักฐานเชิงประจักษ์ เลือกวัสดุ อุปกรณ์ รวมทั้งวิธีการในการสำรวจตรวจสอบอย่างถูกต้องทั้งในเชิงปริมาณและคุณภาพ และบันทึกผลการสำรวจตรวจสอบอย่างเป็นระบบ'),
  ('วิทยาศาสตร์', 'ม.6', 11, 'วิเคราะห์ แปลความหมายข้อมูล และประเมินความสอดคล้องของข้อสรุปเพื่อตรวจสอบกับสมมติฐานที่ตั้งไว้ ให้ข้อเสนอแนะเพื่อปรับปรุงวิธีการสำรวจตรวจสอบ จัดกระทำข้อมูลและนำเสนอข้อมูลด้วยเทคนิควิธีที่เหมาะสม สื่อสารแนวคิด ความรู้จากผลการสำรวจตรวจสอบโดยการพูด เขียน จัดแสดงหรือใช้เทคโนโลยีสารสนเทศเพื่อให้ผู้อื่นเข้าใจโดยมีหลักฐานอ้างอิงหรือมีทฤษฎีรองรับ'),
  ('วิทยาศาสตร์', 'ม.6', 12, 'แสดงถึงความสนใจ มุ่งมั่น รับผิดชอบ รอบคอบ และซื่อสัตย์ ในการสืบเสาะหาความรู้ โดยใช้เครื่องมือและวิธีการที่ให้ได้ผลถูกต้อง เชื่อถือได้ มีเหตุผลและยอมรับได้ว่าความรู้ทางวิทยาศาสตร์อาจมีการเปลี่ยนแปลงได้'),
  ('วิทยาศาสตร์', 'ม.6', 13, 'แสดงถึงความพอใจและเห็นคุณค่าในการค้นพบความรู้ พบคำตอบ หรือแก้ปัญหาได้ทำงานร่วมกับผู้อื่นอย่างสร้างสรรค์ แสดงความคิดเห็นโดยมีข้อมูลอ้างอิงและเหตุผลประกอบเกี่ยวกับผลของการพัฒนาและการใช้วิทยาศาสตร์และเทคโนโลยีอย่างมีคุณธรรมต่อสังคมและสิ่งแวดล้อม และยอมรับฟังความคิดเห็นของผู้อื่น'),
  ('วิทยาศาสตร์', 'ม.6', 14, 'เข้าใจความสัมพันธ์ของความรู้วิทยาศาสตร์ที่มีผลต่อการพัฒนาเทคโนโลยีประเภทต่าง ๆ และการพัฒนาเทคโนโลยีที่ส่งผลให้มีการคิดค้นความรู้ทางวิทยาศาสตร์ที่ก้าวหน้าผลของเทคโนโลยีต่อชีวิต สังคม และสิ่งแวดล้อม'),
  ('วิทยาศาสตร์', 'ม.6', 15, 'ตระหนักถึงความสำคัญและเห็นคุณค่าของความรู้วิทยาศาสตร์และเทคโนโลยีที่ใช้ในชีวิตประจำวัน ใช้ความรู้และกระบวนการทางวิทยาศาสตร์และเทคโนโลยีในการดำรงชีวิตและการประกอบอาชีพ แสดงความชื่นชม ภูมิใจ ยกย่อง อ้างอิงผลงาน ชิ้นงานที่เป็นผลมาจากภูมิปัญญาท้องถิ่น และการพัฒนาเทคโนโลยีที่ทันสมัย ศึกษาหาความรู้เพิ่มเติม ทำโครงงานหรือสร้างชิ้นงานตามความสนใจ'),
  ('วิทยาศาสตร์', 'ม.6', 16, 'แสดงความซาบซึ้ง ห่วงใย มีพฤติกรรมเกี่ยวกับการใช้และรักษาทรัพยากรธรรมชาติและสิ่งแวดล้อมอย่างรู้คุณค่า เสนอตัวเองร่วมมือปฏิบัติกับชุมชนในการป้องกัน ดูแลทรัพยากรธรรมชาติและสิ่งแวดล้อมของท้องถิ่น'),
  ('วิทยาศาสตร์', 'ม.6', 17, 'วิเคราะห์แนวคิดหลักของเทคโนโลยี ได้แก่ ระบบทางเทคโนโลยีที่ซับซ้อนการเปลี่ยนแปลงของเทคโนโลยี ความสัมพันธ์ระหว่างเทคโนโลยีกับศาสตร์อื่น โดยเฉพาะวิทยาศาสตร์หรือคณิตศาสตร์ วิเคราะห์ เปรียบเทียบ และตัดสินใจเพื่อเลือกใช้เทคโนโลยี โดยคำนึงถึงผลกระทบต่อชีวิต สังคม เศรษฐกิจ และสิ่งแวดล้อม ประยุกต์ใช้ความรู้ ทักษะ ทรัพยากรเพื่อออกแบบสร้างหรือพัฒนาผลงาน สำหรับแก้ปัญหาที่มีผลกระทบต่อสังคม โดยใช้กระบวนการออกแบบเชิงวิศวกรรม ใช้ซอฟต์แวร์ช่วยในการออกแบบและนำเสนอผลงาน เลือกใช้วัสดุ อุปกรณ์ และเครื่องมือได้อย่างถูกต้อง เหมาะสม ปลอดภัย รวมทั้งคำนึงถึงทรัพย์สินทางปัญญา'),
  ('วิทยาศาสตร์', 'ม.6', 18, 'ใช้ความรู้ทางด้านวิทยาการคอมพิวเตอร์ สื่อดิจิทัล เทคโนโลยีสารสนเทศและการสื่อสาร เพื่อรวบรวมข้อมูลในชีวิตจริงจากแหล่งต่าง ๆ และความรู้จากศาสตร์อื่น มาประยุกต์ใช้สร้างความรู้ใหม่ เข้าใจการเปลี่ยนแปลงของเทคโนโลยีที่มีผลต่อการดำเนินชีวิต อาชีพ สังคมวัฒนธรรม และใช้อย่างปลอดภัย มีจริยธรรม')
