-- หลักสูตรแกนกลาง กลุ่มสาระการเรียนรู้วิทยาศาสตร์ (ฉบับปรับปรุง พ.ศ. 2560) — มาตรฐาน ตัวชี้วัด สาระการเรียนรู้แกนกลาง คุณภาพผู้เรียน
-- ที่มา: ไฟล์ "SciCurriculum_2560.pdf" (สสวท./สพฐ.) ถอดเป็นตาราง · ตัวเลขไทยแปลงเป็นเลขอารบิก (เช่น ว ๑.๑ ป.๑/๑ → ว 1.1 ป.1/1)
--
-- ตาราง:
--   curriculum_standards       มาตรฐานการเรียนรู้ (ว 1.1 ... ว 4.2) พร้อมสาระและคำอธิบาย
--   curriculum_indicators      ตัวชี้วัด (ตารางเดิม ใช้ร่วมกับรายวิชาการงานอาชีพ) — เพิ่มคอลัมน์ learning_area, indicator_no
--   curriculum_core_content    สาระการเรียนรู้แกนกลาง แยกตามมาตรฐาน/ชั้น
--   curriculum_learner_quality คุณภาพผู้เรียนเมื่อจบ ป.3 ป.6 ม.3 ม.6
-- ไม่รวม: "ผลการเรียนรู้และสาระการเรียนรู้เพิ่มเติม" ม.4–6 (วิชาเพิ่มเติม ชีววิทยา เคมี ฟิสิกส์ โลกฯ) ในหน้า 134–277 ของไฟล์
--
-- สิทธิ์: ทุกบัญชีเจ้าหน้าที่ที่เข้าแดชบอร์ดได้ อ่านได้ · เพิ่ม/แก้/ลบ ได้เฉพาะแอดมิน · anon เข้าไม่ได้
-- รันซ้ำได้ · ต้องรัน 20261013100000_curriculum_work_career.sql มาก่อน (ตาราง curriculum_indicators)

ALTER TABLE public.curriculum_indicators
  ADD COLUMN IF NOT EXISTS learning_area text,
  ADD COLUMN IF NOT EXISTS indicator_no integer;
UPDATE public.curriculum_indicators SET learning_area = 'การงานอาชีพ' WHERE learning_area IS NULL AND standard LIKE 'ง %';

CREATE TABLE IF NOT EXISTS public.curriculum_standards (
  standard_code text PRIMARY KEY,            -- เช่น ว 1.1
  learning_area text NOT NULL,               -- กลุ่มสาระการเรียนรู้
  strand_no     smallint,                    -- สาระที่
  strand_name   text,                        -- เช่น วิทยาศาสตร์ชีวภาพ
  description   text NOT NULL                -- คำอธิบายมาตรฐาน
);

CREATE TABLE IF NOT EXISTS public.curriculum_core_content (
  standard_code text NOT NULL REFERENCES public.curriculum_standards (standard_code) ON DELETE CASCADE ON UPDATE CASCADE,
  grade         text NOT NULL,               -- ป.1 ... ม.6
  seq           integer NOT NULL,
  content       text NOT NULL,               -- สาระการเรียนรู้แกนกลาง (หัวข้อละ 1 แถว)
  PRIMARY KEY (standard_code, grade, seq)
);

CREATE TABLE IF NOT EXISTS public.curriculum_learner_quality (
  learning_area text NOT NULL,
  level_code    text NOT NULL,               -- ป.3 / ป.6 / ม.3 / ม.6 (คุณภาพผู้เรียนเมื่อจบชั้น)
  seq           integer NOT NULL,
  description   text NOT NULL,
  PRIMARY KEY (learning_area, level_code, seq)
);

-- สิทธิ์: อ่านได้ทุกบัญชีเจ้าหน้าที่ · แก้ได้เฉพาะแอดมิน
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['curriculum_standards', 'curriculum_core_content', 'curriculum_learner_quality']
  LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('REVOKE ALL ON public.%I FROM anon', t);
    EXECUTE format('REVOKE ALL ON public.%I FROM public', t);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('DROP POLICY IF EXISTS "Staff reads %1$s" ON public.%1$I', t);
    EXECUTE format('CREATE POLICY "Staff reads %1$s" ON public.%1$I FOR SELECT USING (public.can_access_dashboard())', t);
    EXECUTE format('DROP POLICY IF EXISTS "Admin writes %1$s" ON public.%1$I', t);
    EXECUTE format('CREATE POLICY "Admin writes %1$s" ON public.%1$I FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin())', t);
  END LOOP;
END $$;

-- ───────── ข้อมูล ─────────
ON CONFLICT (standard_code) DO UPDATE SET learning_area = EXCLUDED.learning_area, strand_no = EXCLUDED.strand_no, strand_name = EXCLUDED.strand_name, description = EXCLUDED.description;

ON CONFLICT (indicator_code) DO UPDATE SET grade = EXCLUDED.grade, standard = EXCLUDED.standard, description = EXCLUDED.description, learning_area = EXCLUDED.learning_area, indicator_no = EXCLUDED.indicator_no;

ON CONFLICT (standard_code, grade, seq) DO UPDATE SET content = EXCLUDED.content;

ON CONFLICT (learning_area, level_code, seq) DO UPDATE SET description = EXCLUDED.description;

NOTIFY pgrst, 'reload schema';

-- ผลตรวจหลังนำเข้า: ตัวชี้วัดวิทยาศาสตร์แยกตามชั้น (รวม 415) · มาตรฐาน 10 · สาระแกนกลาง 672 แถว · คุณภาพผู้เรียน 52 ข้อ
SELECT grade AS "ชั้น", count(*) AS "จำนวนตัวชี้วัด"
FROM public.curriculum_indicators
WHERE learning_area = 'วิทยาศาสตร์'
GROUP BY grade
ORDER BY CASE left(grade, 1) WHEN 'ป' THEN 0 ELSE 1 END, grade;
